# --- WebSocket 状态管理器 ---
COLLAB_MEMBER_MAX_NAME = 32
COLLAB_MEMBER_MAX_SELECTION = 24
COLLAB_HEARTBEAT_TIMEOUT_MS = 22 * 1000
COLLAB_LOCK_TTL_MS = 16 * 1000
COLLAB_MEMBER_COLORS = (
    "#2563eb", "#db2777", "#059669", "#d97706", "#7c3aed",
    "#0891b2", "#dc2626", "#4f46e5", "#65a30d", "#c026d3",
)


def _collab_clean_name(value: Any, fallback: str = "协作者") -> str:
    text = re.sub(r"[\x00-\x1f\x7f]", "", str(value or ""))
    text = re.sub(r"\s+", " ", text).strip()[:COLLAB_MEMBER_MAX_NAME]
    return text or fallback


def _collab_clean_id(value: Any, fallback: str = "") -> str:
    text = re.sub(r"[^a-zA-Z0-9_-]", "", str(value or ""))[:80]
    return text or fallback


def _collab_clean_color(value: Any, member_id: str = "") -> str:
    text = str(value or "").strip().lower()
    if re.fullmatch(r"#[0-9a-f]{6}", text):
        return text
    seed = sum((index + 1) * ord(char) for index, char in enumerate(str(member_id or "")))
    return COLLAB_MEMBER_COLORS[seed % len(COLLAB_MEMBER_COLORS)]


def _collab_public_member(member: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    member = member or {}
    return {
        "id": str(member.get("id") or ""),
        "name": _collab_clean_name(member.get("name")),
        "color": _collab_clean_color(member.get("color"), str(member.get("id") or "")),
        "role": str(member.get("role") or "viewer"),
        "host": bool(member.get("host")),
        "x": float(member.get("x") or 0),
        "y": float(member.get("y") or 0),
        "selected_ids": list(member.get("selected_ids") or [])[:COLLAB_MEMBER_MAX_SELECTION],
        "active_node_id": str(member.get("active_node_id") or ""),
        "last_seen": int(member.get("last_seen") or 0),
    }


class ConnectionManager:
    def __init__(self):
        self.collab_connections: Dict[str, Dict[WebSocket, Dict[str, Any]]] = {}
        self.collab_connection_meta: Dict[WebSocket, Dict[str, Any]] = {}
        self.collab_locks: Dict[str, Dict[str, Dict[str, Any]]] = {}

    def _prune_collab_stale(self, canvas_id: str) -> List[Dict[str, Any]]:
        """Remove abandoned browser tabs before returning a presence snapshot."""
        now = now_ms()
        connections = self.collab_connections.get(str(canvas_id or ""), {})
        removed = []
        for websocket, member in list(connections.items()):
            if now - int(member.get("last_seen") or 0) <= COLLAB_HEARTBEAT_TIMEOUT_MS:
                continue
            removed.append(dict(member))
            connections.pop(websocket, None)
            self.collab_connection_meta.pop(websocket, None)
            self._release_collab_locks(str(canvas_id or ""), str(member.get("id") or ""))
        locks = self.collab_locks.get(str(canvas_id or ""), {})
        for node_id, lock in list(locks.items()):
            if int(lock.get("expires_at") or 0) <= now:
                locks.pop(node_id, None)
        return removed

    def _collab_members(self, canvas_id: str) -> List[Dict[str, Any]]:
        self._prune_collab_stale(canvas_id)
        return [dict(member) for member in self.collab_connections.get(str(canvas_id or ""), {}).values()]

    def _collab_public_locks(self, canvas_id: str) -> List[Dict[str, Any]]:
        self._prune_collab_stale(canvas_id)
        result = []
        for node_id, lock in self.collab_locks.get(str(canvas_id or ""), {}).items():
            owner = self.collab_connection_meta.get(lock.get("websocket"))
            if not owner:
                continue
            result.append({
                "node_id": str(node_id),
                "member": _collab_public_member(owner),
                "expires_at": int(lock.get("expires_at") or 0),
            })
        return result

    async def _send_collab(self, websocket: WebSocket, message: Dict[str, Any]) -> bool:
        try:
            await websocket.send_text(json.dumps(message, ensure_ascii=False))
            return True
        except Exception as exc:
            print(f"Collaboration message error: {exc}")
            return False

    async def broadcast_collab(self, canvas_id: str, message: Dict[str, Any], exclude: Optional[WebSocket] = None):
        canvas_id = str(canvas_id or "")
        stale = self._prune_collab_stale(canvas_id)
        if stale:
            for member in stale:
                message_to_send = {
                    "type": "collab_leave",
                    "member_id": str(member.get("id") or ""),
                    "released_node_ids": [],
                }
                for websocket in list(self.collab_connections.get(canvas_id, {}).keys()):
                    if websocket is exclude:
                        continue
                    await self._send_collab(websocket, message_to_send)
        for websocket in list(self.collab_connections.get(canvas_id, {}).keys()):
            if websocket is exclude:
                continue
            if not await self._send_collab(websocket, message):
                await self.disconnect_collab(websocket, notify=True)

    async def connect_collab(self, websocket: WebSocket, canvas_id: str, member: Dict[str, Any]):
        canvas_id = str(canvas_id or "")
        member = dict(member or {})
        member["id"] = _collab_clean_id(member.get("id"), f"guest-{uuid.uuid4().hex[:10]}")
        member["name"] = _collab_clean_name(member.get("name"), "协作者")
        member["color"] = _collab_clean_color(member.get("color"), member["id"])
        member["canvas_id"] = canvas_id
        member["selected_ids"] = []
        member["active_node_id"] = ""
        member["x"] = 0.0
        member["y"] = 0.0
        member["last_seen"] = now_ms()
        # 浏览器重连时，旧连接不能继续占用同一个成员身份。
        for old_socket, old_member in list(self.collab_connections.get(canvas_id, {}).items()):
            if old_member.get("id") == member["id"]:
                await self.disconnect_collab(old_socket, notify=False)
        await websocket.accept()
        self.collab_connections.setdefault(canvas_id, {})[websocket] = member
        self.collab_connection_meta[websocket] = member
        await self._send_collab(websocket, {
            "type": "collab_snapshot",
            "self_id": member["id"],
            "members": [_collab_public_member(item) for item in self._collab_members(canvas_id)],
            "locks": self._collab_public_locks(canvas_id),
        })
        await self.broadcast_collab(canvas_id, {"type": "collab_join", "member": _collab_public_member(member)}, exclude=websocket)

    def _release_collab_locks(self, canvas_id: str, member_id: str, node_id: str = "") -> List[str]:
        released = []
        locks = self.collab_locks.get(str(canvas_id or ""), {})
        for target_id, lock in list(locks.items()):
            if node_id and str(target_id) != str(node_id):
                continue
            owner = self.collab_connection_meta.get(lock.get("websocket"))
            if owner and str(owner.get("id") or "") != str(member_id or ""):
                continue
            locks.pop(target_id, None)
            released.append(str(target_id))
        return released

    async def disconnect_collab(self, websocket: WebSocket, notify: bool = True):
        member = self.collab_connection_meta.pop(websocket, None)
        if not member:
            return
        canvas_id = str(member.get("canvas_id") or "")
        connections = self.collab_connections.get(canvas_id, {})
        connections.pop(websocket, None)
        released = self._release_collab_locks(canvas_id, str(member.get("id") or ""))
        if notify:
            await self.broadcast_collab(canvas_id, {
                "type": "collab_leave",
                "member_id": str(member.get("id") or ""),
                "released_node_ids": released,
            })
            for node_id in released:
                await self.broadcast_collab(canvas_id, {"type": "collab_lock_changed", "node_id": node_id, "member": None})
        if not connections:
            self.collab_connections.pop(canvas_id, None)
            self.collab_locks.pop(canvas_id, None)

    def collab_lock_conflicts(self, canvas_id: str, client_id: str, node_ids: List[str]) -> List[Dict[str, Any]]:
        self._prune_collab_stale(canvas_id)
        wanted = {str(item or "") for item in (node_ids or []) if str(item or "")}
        conflicts = []
        for node_id in wanted:
            lock = self.collab_locks.get(str(canvas_id or ""), {}).get(node_id)
            if not lock:
                continue
            owner = self.collab_connection_meta.get(lock.get("websocket"))
            if not owner or str(owner.get("id") or "") == str(client_id or ""):
                continue
            conflicts.append({"node_id": node_id, "member": _collab_public_member(owner)})
        return conflicts

    async def handle_collab_message(self, websocket: WebSocket, payload: Dict[str, Any]):
        member = self.collab_connection_meta.get(websocket)
        if not member or not isinstance(payload, dict):
            return
        canvas_id = str(member.get("canvas_id") or "")
        member["last_seen"] = now_ms()
        message_type = str(payload.get("type") or "").strip().lower()
        if message_type in {"heartbeat", "ping"}:
            owned = payload.get("locks") if isinstance(payload.get("locks"), list) else []
            for node_id in owned:
                lock = self.collab_locks.get(canvas_id, {}).get(str(node_id or ""))
                if lock and lock.get("websocket") is websocket:
                    lock["expires_at"] = now_ms() + COLLAB_LOCK_TTL_MS
            await self._send_collab(websocket, {"type": "collab_pong", "at": now_ms()})
            return
        if message_type in {"hello", "rename"}:
            name = _collab_clean_name(payload.get("name"), member.get("name") or "协作者")
            if name != member.get("name"):
                member["name"] = name
                await self.broadcast_collab(canvas_id, {"type": "collab_presence", "member": _collab_public_member(member)})
            return
        if message_type == "cursor":
            try:
                x = float(payload.get("x"))
                y = float(payload.get("y"))
                if not math.isfinite(x) or not math.isfinite(y):
                    return
                member["x"] = max(-1000000.0, min(1000000.0, x))
                member["y"] = max(-1000000.0, min(1000000.0, y))
            except (TypeError, ValueError):
                return
            await self.broadcast_collab(canvas_id, {
                "type": "collab_cursor",
                "member_id": member["id"],
                "x": member["x"],
                "y": member["y"],
            }, exclude=websocket)
            return
        if message_type == "selection":
            raw_ids = payload.get("node_ids") if isinstance(payload.get("node_ids"), list) else []
            member["selected_ids"] = [_collab_clean_id(value) for value in raw_ids if _collab_clean_id(value)][:COLLAB_MEMBER_MAX_SELECTION]
            member["active_node_id"] = _collab_clean_id(payload.get("active_node_id"))
            await self.broadcast_collab(canvas_id, {"type": "collab_selection", "member_id": member["id"], "node_ids": member["selected_ids"], "active_node_id": member["active_node_id"]}, exclude=websocket)
            return
        if message_type == "lock":
            node_id = _collab_clean_id(payload.get("node_id"))
            if not node_id:
                return
            action = str(payload.get("action") or "acquire").lower()
            if action not in {"release", "unlock"} and str(member.get("role") or "viewer") != "editor":
                await self._send_collab(websocket, {"type": "collab_lock", "ok": False, "node_id": node_id, "reason": "readonly"})
                return
            locks = self.collab_locks.setdefault(canvas_id, {})
            if action in {"release", "unlock"}:
                released = self._release_collab_locks(canvas_id, member["id"], node_id)
                if released:
                    await self._send_collab(websocket, {"type": "collab_lock", "ok": True, "action": "release", "node_id": node_id})
                    await self.broadcast_collab(canvas_id, {"type": "collab_lock_changed", "node_id": node_id, "member": None})
                return
            current = locks.get(node_id)
            current_owner = self.collab_connection_meta.get(current.get("websocket")) if current else None
            if current and int(current.get("expires_at") or 0) > now_ms() and current_owner and current.get("websocket") is not websocket:
                await self._send_collab(websocket, {"type": "collab_lock", "ok": False, "node_id": node_id, "member": _collab_public_member(current_owner)})
                return
            locks[node_id] = {"websocket": websocket, "expires_at": now_ms() + COLLAB_LOCK_TTL_MS}
            await self._send_collab(websocket, {"type": "collab_lock", "ok": True, "node_id": node_id, "member": _collab_public_member(member)})
            await self.broadcast_collab(canvas_id, {"type": "collab_lock_changed", "node_id": node_id, "member": _collab_public_member(member)}, exclude=websocket)
            return
        if message_type == "kick":
            if not member.get("host"):
                return
            target_id = _collab_clean_id(payload.get("member_id"))
            if not target_id or target_id == member.get("id"):
                return
            target_socket = next((socket for socket, item in self.collab_connections.get(canvas_id, {}).items() if item.get("id") == target_id), None)
            if target_socket:
                await self._send_collab(target_socket, {"type": "collab_kicked"})
                await self.disconnect_collab(target_socket, notify=True)

