def _default_image_storage_preferences():
    return {
        "mode": "local",
        "provider": "qiniu",
        "providers": {
            "qiniu": {
                "bucket": "",
                "region": "",
                "domain": "",
            },
        },
    }


def _normalize_image_storage_preferences(raw, *, strict=False):
    raw = raw if isinstance(raw, dict) else {}
    requested_mode = str(raw.get("mode") or "local").strip().lower()
    if strict and requested_mode not in {"local", "cloud"}:
        raise ValueError("图片存储模式必须是 local 或 cloud")
    mode = requested_mode
    if mode not in {"local", "cloud"}:
        mode = "local"
    requested_provider = str(raw.get("provider") or "qiniu").strip().lower()
    if strict and requested_provider != "qiniu":
        raise ValueError("当前仅支持七牛云 Kodo")
    provider = requested_provider
    if provider != "qiniu":
        provider = "qiniu"
    raw_providers = raw.get("providers") if isinstance(raw.get("providers"), dict) else {}
    raw_qiniu = raw_providers.get("qiniu") if isinstance(raw_providers.get("qiniu"), dict) else {}
    return {
        "mode": mode,
        "provider": provider,
        "providers": {
            "qiniu": {
                "bucket": str(raw_qiniu.get("bucket") or "").strip()[:256],
                "region": str(raw_qiniu.get("region") or "").strip()[:128],
                "domain": str(raw_qiniu.get("domain") or "").strip()[:512],
            },
        },
    }


def load_image_storage_preferences():
    if not os.path.exists(IMAGE_STORAGE_PREFERENCES_FILE):
        return _default_image_storage_preferences()
    try:
        with open(IMAGE_STORAGE_PREFERENCES_FILE, "r", encoding="utf-8-sig") as handle:
            raw = json.load(handle)
    except Exception as exc:
        try:
            _backup_unreadable_data_file(IMAGE_STORAGE_PREFERENCES_FILE, "图片存储偏好无法解析")
        except Exception:
            pass
        raise RuntimeError(f"加载图片存储偏好失败：{exc}") from exc
    return _normalize_image_storage_preferences(raw)


def save_image_storage_preferences(payload):
    normalized = _normalize_image_storage_preferences(payload, strict=True)
    _atomic_write_json_file(IMAGE_STORAGE_PREFERENCES_FILE, normalized)
    return normalized


def _browser_agent_node_executable():
    """Find the existing Node runtime used by the commerce analysis tools."""
    configured = str(os.getenv("XIAOMEI_NODE", "")).strip()
    candidates = [configured, shutil.which("node"), shutil.which("node.exe")]
    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            return os.path.abspath(candidate)
    return ""


def _browser_agent_process_alive():
    process = BROWSER_AGENT_PROCESS
    return bool(process is not None and process.poll() is None)


def _browser_agent_free_port():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.bind(("127.0.0.1", 0))
        return int(sock.getsockname()[1])


def _browser_agent_start():
    """Start the local browser bridge lazily, without opening a browser on app startup."""
    global BROWSER_AGENT_PROCESS, BROWSER_AGENT_PORT, BROWSER_AGENT_TOKEN
    with BROWSER_AGENT_LOCK:
        if _browser_agent_process_alive():
            return
        node = _browser_agent_node_executable()
        if not node:
            raise RuntimeError("未找到 Node.js，无法启动浏览器技能。请先安装 Node.js。")
        if not os.path.isfile(BROWSER_AGENT_SCRIPT):
            raise RuntimeError("小美画布浏览器桥接文件不存在，请检查 tools/commerce-analysis/browser-session.mjs")
        os.makedirs(BROWSER_AGENT_PROFILE_DIR, exist_ok=True)
        os.makedirs(BROWSER_AGENT_OUTPUT_DIR, exist_ok=True)
        BROWSER_AGENT_PORT = _browser_agent_free_port()
        BROWSER_AGENT_TOKEN = uuid.uuid4().hex
        command = [
            node,
            BROWSER_AGENT_SCRIPT,
            "--port", str(BROWSER_AGENT_PORT),
            "--token", BROWSER_AGENT_TOKEN,
            "--profile-dir", BROWSER_AGENT_PROFILE_DIR,
            "--output-dir", BROWSER_AGENT_OUTPUT_DIR,
        ]
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
        try:
            BROWSER_AGENT_PROCESS = subprocess.Popen(
                command,
                cwd=os.path.dirname(BROWSER_AGENT_SCRIPT),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=creationflags,
            )
        except Exception:
            BROWSER_AGENT_PROCESS = None
            BROWSER_AGENT_PORT = 0
            BROWSER_AGENT_TOKEN = ""
            raise


def _browser_agent_stop():
    global BROWSER_AGENT_PROCESS, BROWSER_AGENT_PORT, BROWSER_AGENT_TOKEN
    with BROWSER_AGENT_LOCK:
        process = BROWSER_AGENT_PROCESS
        BROWSER_AGENT_PROCESS = None
        BROWSER_AGENT_PORT = 0
        BROWSER_AGENT_TOKEN = ""
        if process is None:
            return
        try:
            process.terminate()
            process.wait(timeout=4)
        except Exception:
            try:
                process.kill()
                process.wait(timeout=2)
            except Exception:
                pass


def _browser_agent_public_url(file_path):
    """Expose only files created below /output, never an absolute local path."""
    if not file_path:
        return ""
    try:
        output_root = os.path.realpath(OUTPUT_DIR)
        target = os.path.realpath(str(file_path))
        if os.path.commonpath([output_root, target]) != output_root:
            return ""
        relative = os.path.relpath(target, output_root).replace(os.sep, "/")
        if relative in ("", ".") or relative.startswith("../"):
            return ""
        return "/output/" + urllib.parse.quote(relative, safe="/")
    except (OSError, ValueError):
        return ""


def _browser_agent_public_result(value):
    result = dict(value or {}) if isinstance(value, dict) else {"ok": False, "error": str(value)}
    local_path = result.pop("path", "")
    public_url = _browser_agent_public_url(local_path)
    if public_url:
        result["file_url"] = public_url
        if result.get("status") == "screenshot":
            result["screenshot_url"] = public_url
    return result


async def _browser_agent_call(payload, start=True):
    """Proxy one browser action through the authenticated loopback bridge."""
    if start:
        await asyncio.to_thread(_browser_agent_start)
    if not _browser_agent_process_alive() or not BROWSER_AGENT_PORT:
        raise RuntimeError("浏览器技能服务没有运行")
    endpoint = f"http://127.0.0.1:{BROWSER_AGENT_PORT}/action"
    headers = {"X-Xiaomei-Browser-Token": BROWSER_AGENT_TOKEN}
    timeout = httpx.Timeout(65.0, connect=2.0)
    last_error = None
    async with httpx.AsyncClient(timeout=timeout) as client:
        for attempt in range(40):
            try:
                response = await client.post(endpoint, headers=headers, json=payload or {})
                data = response.json()
                if response.status_code >= 400:
                    detail = data.get("error") or data.get("message") or f"浏览器服务 HTTP {response.status_code}"
                    error = RuntimeError(str(detail))
                    setattr(error, "browser_result", _browser_agent_public_result(data))
                    raise error
                result = _browser_agent_public_result(data)
                if str(payload.get("action") or "").lower() == "close":
                    await asyncio.to_thread(_browser_agent_stop)
                return result
            except RuntimeError:
                raise
            except (httpx.ConnectError, httpx.ConnectTimeout, httpx.ReadError, httpx.RemoteProtocolError) as exc:
                last_error = exc
                if attempt >= 39 or not _browser_agent_process_alive():
                    break
                await asyncio.sleep(0.15)
    raise RuntimeError(f"浏览器技能服务未能响应：{last_error or '未知错误'}")

def _decode_storage_settings(raw):
    return storage_migration.decode(raw, DEFAULT_STORAGE_DIRS, IMAGE_SPACE_FOLDER_NAMES, DEFAULT_IMAGE_SPACE_DIR, BASE_DIR)


def load_storage_settings():
    try:
        return _decode_storage_settings(storage_migration.read_config(STORAGE_SETTINGS_FILE))
    except (ValueError, OSError) as exc:
        print(f"加载存储目录设置失败 {type(exc).__name__}")
        return _decode_storage_settings({})


def save_storage_settings(payload):
    with STORAGE_SETTINGS_LOCK:
        try:
            raw = storage_migration.read_config(STORAGE_SETTINGS_FILE)
            previous = _decode_storage_settings(raw)
        except (OSError, ValueError) as exc:
            raise HTTPException(status_code=409, detail="无法读取原存储配置。请修复配置文件后重试。") from exc
        try:
            requested = storage_migration.change(
                previous, payload if isinstance(payload, dict) else {},
                IMAGE_SPACE_FOLDER_NAMES, DEFAULT_IMAGE_SPACE_DIR, BASE_DIR,
            )
        except (OSError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="图片空间路径无效") from exc
        migration = {"moved": 0, "failed": 0, "performed": False, "retained": 0}
        if requested is None:
            return {**previous, "migration": migration}
        dirs = requested["dirs"]
        copies = []
        written = set()
        perform = requested["unified"] and bool(payload.get("migrate_legacy"))
        migration["performed"] = perform
        try:
            for key, destination in dirs.items():
                same_target = storage_migration.path_key(previous["dirs"][key]) == storage_migration.path_key(destination)
                old_roots = requested["legacy_roots"].get(key, [])
                if not same_target:
                    storage_migration.check_shadowing(old_roots, destination)
                if perform:
                    files, skipped = storage_migration.migration_files(
                        old_roots, destination, target_already_active=same_target,
                    )
                    copies.extend(files)
                    migration["retained"] += skipped
            for folder in dirs.values():
                os.makedirs(folder, exist_ok=True)
            for old, new in copies:
                if storage_migration.copy_into_space(old, new):
                    written.add(new)
            persisted = {
                **raw, **dirs, "version": 3, "image_space": requested["image_space"],
                "legacy_dirs": requested["legacy_dirs"], "legacy_roots": requested["legacy_roots"],
            }
            _atomic_write_json_file(STORAGE_SETTINGS_FILE, persisted)
        except storage_migration.StorageConflict as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        except (OSError, ValueError) as exc:
            raise HTTPException(status_code=500, detail="图片空间保存失败。原目录仍可使用，请检查目标目录后重试。") from exc

        apply_storage_settings(dirs)
        for old, new in copies:
            try:
                removed = storage_migration.remove_migrated_copy(old, new, (ASSETS_DIR, OUTPUT_DIR))
                if removed:
                    written.add(new)
                else:
                    migration["retained"] += 1
            except OSError:
                migration["failed"] += 1
        migration["moved"] = len(written)
        return {**requested, "migration": migration}


def apply_storage_settings(dirs=None):
    global OUTPUT_INPUT_DIR, OUTPUT_OUTPUT_DIR, LOCAL_UPLOAD_DIR
    dirs = dirs or load_storage_settings().get("dirs") or {}
    OUTPUT_INPUT_DIR = dirs.get("upload") or OUTPUT_INPUT_DIR
    OUTPUT_OUTPUT_DIR = dirs.get("generated") or OUTPUT_OUTPUT_DIR
    LOCAL_UPLOAD_DIR = dirs.get("local") or LOCAL_UPLOAD_DIR
    # 三个素材目录固定带 图片/视频/音频 子目录，切换图片空间后立即建好。
    for folder in (OUTPUT_INPUT_DIR, OUTPUT_OUTPUT_DIR, LOCAL_UPLOAD_DIR):
        for folder_name in media_paths.MEDIA_TYPE_FOLDERS.values():
            try:
                os.makedirs(os.path.join(folder, folder_name), exist_ok=True)
            except OSError:
                continue

apply_storage_settings()

