def ensure_runtime_config_files():
    """首次运行时提前创建配置目录，避免第一次保存 API Key 时才创建目录/文件。"""
    try:
        os.makedirs(os.path.dirname(API_ENV_FILE), exist_ok=True)
        os.makedirs(DATA_DIR, exist_ok=True)
        if not os.path.exists(API_ENV_FILE):
            with open(API_ENV_FILE, "a", encoding="utf-8"):
                pass
    except Exception as e:
        print(f"初始化 API 配置目录失败: {e}")

def load_env_file():
    if not os.path.exists(API_ENV_FILE):
        return
    try:
        with open(API_ENV_FILE, 'r', encoding='utf-8-sig') as f:
            for raw_line in f.read().splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip().strip('"').strip("'")
                os.environ.setdefault(key, value)
    except Exception as e:
        print(f"加载 API/.env 失败: {e}")

def normalize_httpx_no_proxy():
    # httpx 0.28 treats an IPv6 /128 entry as a hostname, then builds an
    # invalid URL from it. A /128 network names one host, so keep the proxy
    # exclusion by writing that host in the form httpx accepts.
    for key in ("NO_PROXY", "no_proxy"):
        value = os.environ.get(key)
        if not value:
            continue
        entries = value.split(",")
        changed = False
        for index, entry in enumerate(entries):
            host = entry.strip()
            if not host.endswith("/128") or "://" in host:
                continue
            try:
                network = ipaddress.IPv6Network(host, strict=False)
            except ValueError:
                continue
            entries[index] = str(network.network_address)
            changed = True
        if changed:
            os.environ[key] = ",".join(entries)

ensure_runtime_config_files()
load_env_file()
normalize_httpx_no_proxy()

