class ProjectStaticFiles(StaticFiles):
    async def get_response(self, path, scope):
        if re.fullmatch(r"runninghub/thumbnails/(?:workflow-|app-)?[\w-]+\.(?:jpe?g|png|webp)", path.replace("\\", "/"), re.I):
            response = await super().get_response("runninghub/entry-placeholder.svg", scope)
            response.headers["Cache-Control"] = "no-cache"
            return response
        comfy_web = os.path.join(BASE_DIR, "ComfyUI", "web")
        candidate = os.path.abspath(os.path.join(comfy_web, path))
        if os.path.commonpath([candidate, comfy_web]) == comfy_web and os.path.isfile(candidate):
            response = await StaticFiles(directory=comfy_web).get_response(path, scope)
        else:
            response = await super().get_response(path, scope)
        if path.lower().endswith(".html"):
            response.headers["Cache-Control"] = "no-cache"
        # 内置 PhotoCraft（static/photocraft/）缓存规则来自上游 HOSTING.md：
        # 入口页与加载器 no-cache，hashed 资源 immutable；part-* 是已 gzip 的分块，保持原样返回。
        normalized = path.replace("\\", "/")
        if normalized.startswith("photocraft/"):
            rel = normalized[len("photocraft/"):]
            if rel in ("index.html", "app/photocraft-web.js", "app/parts.txt"):
                response.headers["Cache-Control"] = "no-cache"
            elif rel:
                response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
        return response

class LegacyOutputFiles(StaticFiles):
    def lookup_path(self, path):
        candidate = media_paths.first_file((OUTPUT_DIR, OUTPUT_OUTPUT_DIR), path)
        if candidate:
            try:
                return candidate, os.stat(candidate)
            except FileNotFoundError:
                pass
        return "", None


