@app.get("/api/canvas-agent/runtime-config")
def canvas_agent_runtime_config():
    """Expose only the browser timeout that must stay ahead of canvas-llm.

    Keeping this separate from provider settings lets API/.env tune the server
    timeout without leaving the browser on an obsolete hard-coded deadline.
    """
    server_timeout_ms = max(30_000, int(math.ceil(CANVAS_LLM_TIMEOUT * 1000)))
    grace_ms = max(5_000, int(math.ceil(CANVAS_AGENT_CLIENT_GRACE_SECONDS * 1000)))
    return {
        "request_timeout_ms": server_timeout_ms + grace_ms,
        "server_timeout_ms": server_timeout_ms,
        "harness_enabled": _canvas_harness_enabled(),
        "harness_available": bool(_canvas_harness_command()),
    }

