    prompt: str = Field(default="", max_length=ONLINE_IMAGE_PROMPT_MAX_LENGTH)
    provider_id: str = "comfly"
    model: str = ""
    # Browser-side task creation can lose the HTTP response even though the
    # server has already persisted and started the task.  Keep a short-lived
    # client correlation ID so the browser can recover that task without
    # submitting the image request a second time.
    client_request_id: str = Field(default="", max_length=120)
    # 本次画布详情页批量任务的并发屏数；0 沿用普通生图的共享限制。
    canvas_batch_concurrency: int = Field(default=0, ge=0, le=100)
    # 用于历史记录区分在线生图、画布和电商工作台；不会发送给上游模型。
    history_source: str = ""
    # 记录所属的画布项目，不会发送给上游模型。
    project_id: str = ""
    size: str = "1024x1024"
    # Optional final pixel dimensions for canvas batch output.
    output_size: str = Field(default="", pattern=r"^(?:[1-9][0-9]{0,3}x[1-9][0-9]{0,3})?$")
    # 与画布的画质选项一致，独立于提示词和像素尺寸。
    resolution: str = ""
    # 可选的画幅语义。像素尺寸仍由 size 提供；source/adaptive 表示
    # 原生 Gemini 在有参考图时应沿用输入图比例，而不是把近似像素比硬转成枚举。
    # 聚合网关的 Gemini 兼容路由不保证该语义，后台会按 size 显式提交最近比例。
    aspect_ratio: str = ""
    quality: str = "auto"
    # GPT Image 2.5 支持 auto/opaque/transparent；其它模型保持默认值，
    # generate_ai_image 只会把该字段发给明确支持它的 GPT Image 2.5。
    background: str = "auto"
    output_format: Literal["", "gif", "svg"] = ""
    n: int = 1
    reference_images: List[AIReference] = []
    # operation="upscale" 走即梦 image_upscale；resolution_type 支持 2k/4k/8k。
    operation: str = ""
    resolution_type: str = ""
    # 只有扩图操作会显式打开此标记；普通生图忽略旧浏览器误带的定位信息。
    outpaint_mode: bool = False
    # 扩图底图的定位信息，用于校验输入和判断结果是否重绘原图；不发送给上游模型。
    outpaint_preserve: Dict[str, Any] = Field(default_factory=dict)
    product_fidelity: Dict[str, Any] = Field(default_factory=dict)
    product_retouch: Dict[str, Any] = Field(default_factory=dict)
    # Agent Skill metadata is carried through to history/task records so a
    # generated image can be audited back to the exact Skill that shaped the
    # prompt.  It does not affect the upstream image API request.
    skill_id: str = ""
    skill_name: str = ""
    skill_applied: bool = False
    # 设计大脑执行记录关联：只写入任务与历史，不参与上游请求。
    design_run_id: str = Field(default="", max_length=60)

    @model_validator(mode="after")
    def validate_image_prompt(self):
        if self.prompt and (self.output_format != "svg" or self.prompt.strip()):
            return self
        if self.output_format == "svg" and any(ref.url.strip() for ref in self.reference_images):
            return self
        raise ValueError("请输入提示词")

    @field_validator("output_size")
    @classmethod
    def validate_output_size(cls, value):
        if value and max(map(int, value.split("x"))) > 8192:
            raise ValueError("自定义宽高请填写 1 到 8192 之间的整数")
        return value

