# --- 本地定时任务 ---
#
# 小美画布把任务持久化到
# data/scheduled_tasks.json。任务调度器只负责按时触发并记录消息，不会擅自调用
# 外部平台或生成图片；后续若接入 Agent，可直接复用 payload/sessionTarget 字段。
SCHEDULED_TASKS: Dict[str, Dict[str, Any]] = {}
SCHEDULED_TASK_LOCK = Lock()
SCHEDULED_TASK_LOOP: Optional[asyncio.Task] = None
SCHEDULED_TASK_RUNS: Dict[str, asyncio.Task] = {}
SCHEDULED_TASK_STORE_VERSION = 1
SCHEDULED_TASK_TICK_SECONDS = 1.0


def _scheduled_now_ms() -> int:
    return int(time.time() * 1000)


def _scheduled_timezone(name: str = ""):
    """Resolve a task timezone without adding a third-party dependency."""
    value = str(name or "").strip()
    if not value:
        return datetime.datetime.now().astimezone().tzinfo or datetime.timezone.utc
    if value in {"Asia/Shanghai", "Asia/Chongqing", "PRC", "China/Beijing"}:
        return datetime.timezone(datetime.timedelta(hours=8), name="Asia/Shanghai")
    try:
        from zoneinfo import ZoneInfo

        return ZoneInfo(value)
    except Exception as exc:
        raise ValueError(f"无法识别时区：{value}") from exc


def _scheduled_parse_datetime(value: str, timezone_name: str = "") -> datetime.datetime:
    text = str(value or "").strip()
    if not text:
        raise ValueError("一次性触发时间不能为空")
    if text.endswith("Z") or text.endswith("z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValueError("一次性触发时间必须是 ISO 日期时间") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=_scheduled_timezone(timezone_name))
    return parsed


def _scheduled_parse_cron_field(raw: str, minimum: int, maximum: int) -> Tuple[set, bool]:
    text = str(raw or "").strip()
    if not text:
        raise ValueError("Cron 表达式包含空字段")
    values = set()
    wildcard = text in {"*", "?"}
    for item in text.split(","):
        token = item.strip()
        if not token:
            raise ValueError("Cron 表达式包含空字段")
        pieces = token.split("/", 1)
        if len(pieces) == 2:
            try:
                step = int(pieces[1])
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Cron 步长无效：{token}") from exc
            if step <= 0:
                raise ValueError(f"Cron 步长必须大于 0：{token}")
        else:
            step = 1
        base = pieces[0].strip()
        if base in {"", "*", "?"}:
            start, end = minimum, maximum
            wildcard = True
        elif "-" in base:
            bounds = base.split("-", 1)
            try:
                start, end = int(bounds[0]), int(bounds[1])
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Cron 范围无效：{token}") from exc
        else:
            try:
                start = end = int(base)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Cron 数值无效：{token}") from exc
            if len(pieces) == 2:
                end = maximum
        if start < minimum or end > maximum or start > end:
            raise ValueError(f"Cron 数值超出范围：{token}")
        values.update(range(start, end + 1, step))
    if not values:
        raise ValueError("Cron 表达式没有匹配值")
    return values, wildcard


def _scheduled_parse_cron(expr: str) -> Dict[str, Any]:
    fields = str(expr or "").strip().split()
    if len(fields) != 5:
        raise ValueError("Cron 表达式需要 5 个字段：分 时 日 月 周")
    minute, minute_wild = _scheduled_parse_cron_field(fields[0], 0, 59)
    hour, hour_wild = _scheduled_parse_cron_field(fields[1], 0, 23)
    day, day_wild = _scheduled_parse_cron_field(fields[2], 1, 31)
    month, month_wild = _scheduled_parse_cron_field(fields[3], 1, 12)
    weekday, weekday_wild = _scheduled_parse_cron_field(fields[4], 0, 7)
    # Cron 的周日既可以写 0 也可以写 7，Python datetime 的周一是 0。
    if 7 in weekday:
        weekday.add(0)
        weekday.discard(7)
    return {
        "minute": minute,
        "hour": hour,
        "day": day,
        "month": month,
        "weekday": weekday,
        "day_wild": day_wild,
        "weekday_wild": weekday_wild,
        "minute_wild": minute_wild,
        "hour_wild": hour_wild,
        "month_wild": month_wild,
    }


def _scheduled_next_cron_ms(expr: str, timezone_name: str = "", after_ms: Optional[int] = None) -> int:
    parsed = _scheduled_parse_cron(expr)
    tz = _scheduled_timezone(timezone_name)
    base_ms = _scheduled_now_ms() if after_ms is None else int(after_ms)
    cursor = datetime.datetime.fromtimestamp(base_ms / 1000, tz=tz).replace(second=0, microsecond=0)
    if int(cursor.timestamp() * 1000) <= base_ms:
        cursor += datetime.timedelta(minutes=1)
    # 两年窗口足以覆盖常见的月/周计划，同时避免错误表达式造成无限循环。
    for _ in range(2 * 366 * 24 * 60):
        cron_weekday = (cursor.weekday() + 1) % 7
        month_ok = cursor.month in parsed["month"]
        minute_ok = cursor.minute in parsed["minute"]
        hour_ok = cursor.hour in parsed["hour"]
        day_ok = cursor.day in parsed["day"]
        weekday_ok = cron_weekday in parsed["weekday"]
        if not (parsed["day_wild"] or parsed["weekday_wild"]):
            calendar_day_ok = day_ok or weekday_ok
        else:
            calendar_day_ok = day_ok and weekday_ok
            if parsed["day_wild"]:
                calendar_day_ok = weekday_ok
            if parsed["weekday_wild"]:
                calendar_day_ok = day_ok
        if month_ok and hour_ok and minute_ok and calendar_day_ok:
            return int(cursor.timestamp() * 1000)
        cursor += datetime.timedelta(minutes=1)
    raise ValueError("Cron 表达式在两年内没有可执行时间")


def _scheduled_normalize_schedule(schedule: Any, now_ms: Optional[int] = None) -> Tuple[Dict[str, Any], Optional[int]]:
    if not isinstance(schedule, dict):
        raise ValueError("执行计划格式无效")
    kind = str(schedule.get("kind") or schedule.get("type") or "cron").strip().lower()
    current_ms = _scheduled_now_ms() if now_ms is None else int(now_ms)
    if kind == "cron":
        expr = str(schedule.get("expr") or "").strip()
        timezone_name = str(schedule.get("tz") or schedule.get("timezone") or "").strip()
        _scheduled_parse_cron(expr)
        next_ms = _scheduled_next_cron_ms(expr, timezone_name, current_ms)
        result = {"kind": "cron", "expr": expr}
        if timezone_name:
            result["tz"] = timezone_name
        return result, next_ms
    if kind == "every":
        raw_every = schedule.get("everyMs", schedule.get("every_ms"))
        try:
            every_ms = int(raw_every)
        except (TypeError, ValueError) as exc:
            raise ValueError("间隔必须是毫秒数") from exc
        if every_ms < 1000:
            raise ValueError("间隔不能小于 1 秒")
        if every_ms > 366 * 24 * 60 * 60 * 1000:
            raise ValueError("间隔不能超过 366 天")
        return {"kind": "every", "everyMs": every_ms}, current_ms + every_ms
    if kind == "at":
        value = str(schedule.get("at") or "").strip()
        timezone_name = str(schedule.get("tz") or "").strip()
        parsed = _scheduled_parse_datetime(value, timezone_name)
        result = {"kind": "at", "at": value}
        if timezone_name:
            result["tz"] = timezone_name
        return result, int(parsed.timestamp() * 1000)
    raise ValueError("执行计划必须是 cron、every 或 at")


def _scheduled_next_run_for_task(task: Dict[str, Any], after_ms: int) -> Optional[int]:
    schedule = task.get("schedule") or {}
    kind = schedule.get("kind")
    if kind == "every":
        return int(after_ms) + int(schedule.get("everyMs") or 0)
    if kind == "cron":
        return _scheduled_next_cron_ms(str(schedule.get("expr") or ""), str(schedule.get("tz") or ""), after_ms)
    return None


def _scheduled_normalize_payload(payload: Any, agent_id: str = "") -> Tuple[Dict[str, Any], str]:
    data = payload if isinstance(payload, dict) else {}
    kind = str(data.get("kind") or "systemEvent").strip()
    if kind not in {"systemEvent", "agentTurn"}:
        raise ValueError("运行模式必须是 systemEvent 或 agentTurn")
    message_key = "text" if kind == "systemEvent" else "message"
    message = str(data.get(message_key) or data.get("message") or data.get("text") or "").strip()
    if not message:
        raise ValueError("任务内容不能为空")
    if len(message) > 5000:
        raise ValueError("任务内容不能超过 5000 个字符")
    result = {"kind": kind, message_key: message}
    if kind == "agentTurn":
        normalized_agent = str(agent_id or data.get("agentId") or "").strip()
        if not normalized_agent:
            raise ValueError("独立对话模式需要填写 Agent ID")
        result["agentId"] = normalized_agent
        return result, normalized_agent
    return result, ""


def _scheduled_public_task(task: Dict[str, Any]) -> Dict[str, Any]:
    # 数据只由 JSON 可序列化字段组成，深拷贝避免接口响应修改内存中的嵌套 state。
    return json.loads(json.dumps(task, ensure_ascii=False))


def _scheduled_write_store_locked() -> None:
    os.makedirs(DATA_DIR, exist_ok=True)
    temp_path = f"{SCHEDULED_TASKS_FILE}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    payload = {
        "version": SCHEDULED_TASK_STORE_VERSION,
        "updatedAtMs": _scheduled_now_ms(),
        "tasks": SCHEDULED_TASKS,
    }
    try:
        with open(temp_path, "w", encoding="utf-8", newline="") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
        os.replace(temp_path, SCHEDULED_TASKS_FILE)
    finally:
        if os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass


def _scheduled_task_from_raw(raw: Dict[str, Any], task_id: str = "") -> Dict[str, Any]:
    now = _scheduled_now_ms()
    normalized_id = str(raw.get("id") or task_id or f"task_{uuid.uuid4().hex[:12]}").strip()
    name = str(raw.get("name") or "未命名任务").strip()[:120] or "未命名任务"
    schedule, next_ms = _scheduled_normalize_schedule(raw.get("schedule") or {}, now)
    payload, normalized_agent = _scheduled_normalize_payload(raw.get("payload") or {}, str(raw.get("agentId") or ""))
    enabled = bool(raw.get("enabled", True))
    state = raw.get("state") if isinstance(raw.get("state"), dict) else {}
    state = dict(state)
    # 服务重启时，之前正在执行的本地任务不会伪造成功结果。
    if state.get("runningAtMs"):
        state.pop("runningAtMs", None)
        state["lastStatus"] = "error"
        state["lastError"] = "服务重启时任务被中断"
        state["lastResult"] = "服务重启时任务被中断"
    if not enabled:
        state["nextRunAtMs"] = None
    elif not state.get("nextRunAtMs"):
        state["nextRunAtMs"] = next_ms
    return {
        "id": normalized_id,
        "name": name,
        "enabled": enabled,
        "schedule": schedule,
        "sessionTarget": str(raw.get("sessionTarget") or ("isolated" if payload["kind"] == "agentTurn" else "main")),
        "wakeMode": str(raw.get("wakeMode") or "now"),
        "payload": payload,
        "agentId": normalized_agent,
        "createdAtMs": int(raw.get("createdAtMs") or raw.get("created_at_ms") or now),
        "updatedAtMs": int(raw.get("updatedAtMs") or raw.get("updated_at_ms") or now),
        "state": state,
    }


def load_scheduled_task_store() -> None:
    global SCHEDULED_TASKS
    loaded: Dict[str, Dict[str, Any]] = {}
    if os.path.isfile(SCHEDULED_TASKS_FILE):
        try:
            with open(SCHEDULED_TASKS_FILE, "r", encoding="utf-8-sig") as handle:
                raw = json.load(handle)
            entries = raw.get("tasks") if isinstance(raw, dict) else raw
            if isinstance(entries, dict):
                for task_id, item in entries.items():
                    if not isinstance(item, dict):
                        continue
                    try:
                        task = _scheduled_task_from_raw(item, str(task_id))
                    except Exception as exc:
                        # 保留损坏任务，用户仍可在页面看到并删除；不让一条任务阻塞服务启动。
                        task = {
                            "id": str(task_id),
                            "name": str(item.get("name") or "无效任务")[:120],
                            "enabled": False,
                            "schedule": item.get("schedule") or {"kind": "cron", "expr": ""},
                            "sessionTarget": str(item.get("sessionTarget") or "main"),
                            "wakeMode": str(item.get("wakeMode") or "now"),
                            "payload": item.get("payload") or {"kind": "systemEvent", "text": ""},
                            "agentId": str(item.get("agentId") or ""),
                            "createdAtMs": int(item.get("createdAtMs") or _scheduled_now_ms()),
                            "updatedAtMs": _scheduled_now_ms(),
                            "state": {
                                "nextRunAtMs": None,
                                "lastStatus": "error",
                                "lastError": f"任务计划无效：{exc}",
                                "lastResult": f"任务计划无效：{exc}",
                            },
                        }
                    loaded[task["id"]] = task
        except (OSError, ValueError, TypeError) as exc:
            print(f"读取定时任务记录失败，将以空列表启动: {exc}")
    with SCHEDULED_TASK_LOCK:
        SCHEDULED_TASKS = loaded


def _scheduled_trigger_task(task_id: str, force: bool = False) -> Tuple[bool, Dict[str, Any]]:
    with SCHEDULED_TASK_LOCK:
        task = SCHEDULED_TASKS.get(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="未找到定时任务")
        state = task.setdefault("state", {})
        existing = SCHEDULED_TASK_RUNS.get(task_id)
        if state.get("runningAtMs") or (existing and not existing.done()):
            return False, _scheduled_public_task(task)
        if not force and not task.get("enabled"):
            return False, _scheduled_public_task(task)
        started_ms = _scheduled_now_ms()
        state["runningAtMs"] = started_ms
        state["lastRunAtMs"] = started_ms
        task["updatedAtMs"] = started_ms
        _scheduled_write_store_locked()
        try:
            run = asyncio.create_task(_run_scheduled_task(task_id, force=force))
        except Exception:
            state.pop("runningAtMs", None)
            _scheduled_write_store_locked()
            raise
        SCHEDULED_TASK_RUNS[task_id] = run
        return True, _scheduled_public_task(task)


async def _run_scheduled_task(task_id: str, force: bool = False) -> None:
    with SCHEDULED_TASK_LOCK:
        task = SCHEDULED_TASKS.get(task_id)
        if not task:
            return
        task_snapshot = _scheduled_public_task(task)
        started_ms = int((task.get("state") or {}).get("runningAtMs") or _scheduled_now_ms())
    status = "ok"
    result_message = ""
    error_message = ""
    try:
        # 这里刻意不调用图片模型或第三方 Agent：当前项目没有外部网关，
        # 先完成可恢复的定时触发和审计记录。payload 保留了后续接入 Agent 的协议形状。
        await asyncio.sleep(0)
        payload = task_snapshot.get("payload") or {}
        if payload.get("kind") == "agentTurn":
            result_message = f"已触发独立对话任务：{payload.get('message') or ''}"
        else:
            result_message = f"已触发系统事件：{payload.get('text') or ''}"
    except Exception as exc:
        status = "error"
        error_message = str(exc)
        result_message = error_message
    finished_ms = _scheduled_now_ms()
    with SCHEDULED_TASK_LOCK:
        task = SCHEDULED_TASKS.get(task_id)
        if task:
            state = task.setdefault("state", {})
            state.pop("runningAtMs", None)
            state["lastStatus"] = status
            state["lastDurationMs"] = max(0, finished_ms - started_ms)
            state["lastResult"] = result_message
            state["lastError"] = error_message
            schedule_kind = (task.get("schedule") or {}).get("kind")
            if schedule_kind == "at":
                task["enabled"] = False
                state["nextRunAtMs"] = None
            elif task.get("enabled"):
                try:
                    state["nextRunAtMs"] = _scheduled_next_run_for_task(task, finished_ms)
                except Exception as exc:
                    task["enabled"] = False
                    state["nextRunAtMs"] = None
                    state["lastStatus"] = "error"
                    state["lastError"] = f"无法计算下次执行时间：{exc}"
                    state["lastResult"] = state["lastError"]
            else:
                state["nextRunAtMs"] = None
            task["updatedAtMs"] = finished_ms
            _scheduled_write_store_locked()
        SCHEDULED_TASK_RUNS.pop(task_id, None)


async def _scheduled_task_scheduler_loop() -> None:
    while True:
        now = _scheduled_now_ms()
        due_ids: List[str] = []
        with SCHEDULED_TASK_LOCK:
            for task_id, task in SCHEDULED_TASKS.items():
                state = task.get("state") if isinstance(task.get("state"), dict) else {}
                next_ms = state.get("nextRunAtMs")
                if task.get("enabled") and isinstance(next_ms, (int, float)) and next_ms <= now:
                    if not state.get("runningAtMs"):
                        due_ids.append(task_id)
        for task_id in due_ids:
            try:
                _scheduled_trigger_task(task_id, force=False)
            except Exception as exc:
                print(f"触发定时任务失败({task_id}): {exc}")
        await asyncio.sleep(SCHEDULED_TASK_TICK_SECONDS)


def start_scheduled_task_scheduler() -> None:
    global SCHEDULED_TASK_LOOP
    if SCHEDULED_TASK_LOOP and not SCHEDULED_TASK_LOOP.done():
        return
    try:
        SCHEDULED_TASK_LOOP = asyncio.create_task(_scheduled_task_scheduler_loop())
    except RuntimeError:
        SCHEDULED_TASK_LOOP = None


async def stop_scheduled_task_scheduler() -> None:
    global SCHEDULED_TASK_LOOP
    scheduler = SCHEDULED_TASK_LOOP
    SCHEDULED_TASK_LOOP = None
    if scheduler and not scheduler.done():
        scheduler.cancel()
        try:
            await scheduler
        except asyncio.CancelledError:
            pass
    for run in list(SCHEDULED_TASK_RUNS.values()):
        if run and not run.done():
            run.cancel()
    SCHEDULED_TASK_RUNS.clear()


class ScheduledTaskCreateRequest(BaseModel):
    name: str = Field(min_length=1, max_length=120)
    enabled: bool = True
    schedule: Dict[str, Any] = Field(default_factory=dict)
    sessionTarget: str = "main"
    wakeMode: str = "now"
    payload: Dict[str, Any] = Field(default_factory=dict)
    agentId: str = ""


class ScheduledTaskPatchRequest(BaseModel):
    name: Optional[str] = Field(default=None, min_length=1, max_length=120)
    enabled: Optional[bool] = None
    schedule: Optional[Dict[str, Any]] = None
    sessionTarget: Optional[str] = None
    wakeMode: Optional[str] = None
    payload: Optional[Dict[str, Any]] = None
    agentId: Optional[str] = None


class ScheduledTaskRunRequest(BaseModel):
    mode: str = "force"


def _build_scheduled_task(payload: ScheduledTaskCreateRequest, task_id: str = "") -> Dict[str, Any]:
    now = _scheduled_now_ms()
    schedule, next_ms = _scheduled_normalize_schedule(payload.schedule, now)
    normalized_payload, normalized_agent = _scheduled_normalize_payload(payload.payload, payload.agentId)
    enabled = bool(payload.enabled)
    return {
        "id": task_id or f"task_{uuid.uuid4().hex[:12]}",
        "name": str(payload.name).strip(),
        "enabled": enabled,
        "schedule": schedule,
        "sessionTarget": str(payload.sessionTarget or ("isolated" if normalized_payload["kind"] == "agentTurn" else "main")),
        "wakeMode": str(payload.wakeMode or "now"),
        "payload": normalized_payload,
        "agentId": normalized_agent,
        "createdAtMs": now,
        "updatedAtMs": now,
        "state": {
            "nextRunAtMs": next_ms if enabled else None,
            "lastStatus": "idle",
            "lastDurationMs": 0,
            "lastResult": "",
            "lastError": "",
        },
    }


@app.get("/api/scheduled-tasks")
@app.get("/api/tasks")
async def list_scheduled_tasks(includeDisabled: bool = True):
    with SCHEDULED_TASK_LOCK:
        jobs = [
            _scheduled_public_task(task)
            for task in SCHEDULED_TASKS.values()
            if includeDisabled or bool(task.get("enabled"))
        ]
    jobs.sort(key=lambda item: (not bool(item.get("enabled")), -int(item.get("updatedAtMs") or 0)))
    return {"jobs": jobs, "generatedAtMs": _scheduled_now_ms()}


@app.post("/api/scheduled-tasks")
@app.post("/api/tasks")
async def create_scheduled_task(payload: ScheduledTaskCreateRequest):
    try:
        task = _build_scheduled_task(payload)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    with SCHEDULED_TASK_LOCK:
        SCHEDULED_TASKS[task["id"]] = task
        _scheduled_write_store_locked()
    return {"job": _scheduled_public_task(task), "task": _scheduled_public_task(task)}


@app.get("/api/scheduled-tasks/{task_id}")
@app.get("/api/tasks/{task_id}")
async def get_scheduled_task(task_id: str):
    with SCHEDULED_TASK_LOCK:
        task = SCHEDULED_TASKS.get(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="未找到定时任务")
        return _scheduled_public_task(task)


@app.patch("/api/scheduled-tasks/{task_id}")
@app.patch("/api/tasks/{task_id}")
async def patch_scheduled_task(task_id: str, payload: ScheduledTaskPatchRequest):
    updates = payload.model_dump(exclude_unset=True) if hasattr(payload, "model_dump") else payload.dict(exclude_unset=True)
    with SCHEDULED_TASK_LOCK:
        task = SCHEDULED_TASKS.get(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="未找到定时任务")
        candidate = _scheduled_public_task(task)
        if "name" in updates:
            candidate["name"] = str(updates["name"] or "").strip()
        if "schedule" in updates and updates["schedule"] is not None:
            candidate["schedule"] = updates["schedule"]
        if "payload" in updates and updates["payload"] is not None:
            candidate["payload"] = updates["payload"]
        if "agentId" in updates and updates["agentId"] is not None:
            candidate["agentId"] = updates["agentId"]
        if "sessionTarget" in updates and updates["sessionTarget"] is not None:
            candidate["sessionTarget"] = updates["sessionTarget"]
        if "wakeMode" in updates and updates["wakeMode"] is not None:
            candidate["wakeMode"] = updates["wakeMode"]
        if "enabled" in updates and updates["enabled"] is not None:
            candidate["enabled"] = bool(updates["enabled"])
        try:
            normalized_schedule, computed_next_ms = _scheduled_normalize_schedule(candidate.get("schedule") or {})
            normalized_payload, normalized_agent = _scheduled_normalize_payload(candidate.get("payload") or {}, str(candidate.get("agentId") or ""))
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        candidate["name"] = str(candidate.get("name") or "").strip()[:120]
        if not candidate["name"]:
            raise HTTPException(status_code=400, detail="任务名不能为空")
        candidate["schedule"] = normalized_schedule
        candidate["payload"] = normalized_payload
        candidate["agentId"] = normalized_agent
        candidate["updatedAtMs"] = _scheduled_now_ms()
        state = candidate.setdefault("state", {})
        if not candidate.get("enabled"):
            state["nextRunAtMs"] = None
        elif "schedule" in updates or not state.get("nextRunAtMs"):
            state["nextRunAtMs"] = computed_next_ms
        SCHEDULED_TASKS[task_id] = candidate
        _scheduled_write_store_locked()
        return _scheduled_public_task(candidate)


@app.post("/api/scheduled-tasks/{task_id}/run")
@app.post("/api/tasks/{task_id}/run")
async def run_scheduled_task(task_id: str, payload: ScheduledTaskRunRequest):
    force = str(payload.mode or "force").strip().lower() == "force"
    accepted, task = _scheduled_trigger_task(task_id, force=force)
    return {"ok": True, "started": accepted, "status": "running" if accepted else "idle", "job": task}


@app.delete("/api/scheduled-tasks/{task_id}")
@app.delete("/api/tasks/{task_id}")
async def delete_scheduled_task(task_id: str):
    with SCHEDULED_TASK_LOCK:
        if task_id not in SCHEDULED_TASKS:
            raise HTTPException(status_code=404, detail="未找到定时任务")
        run = SCHEDULED_TASK_RUNS.get(task_id)
        if run and not run.done():
            run.cancel()
        SCHEDULED_TASK_RUNS.pop(task_id, None)
        SCHEDULED_TASKS.pop(task_id, None)
        _scheduled_write_store_locked()
    return {"ok": True, "id": task_id}


CANVAS_TASKS: Dict[str, Dict[str, Any]] = {}
CANVAS_TASK_LOCK = Lock()
CANVAS_TASK_STORE_VERSION = 1
CANVAS_TASK_TERMINAL_STATUSES = {"succeeded", "failed", "cancelled"}
CANVAS_IMAGE_BACKGROUND_TASKS: Dict[str, asyncio.Task] = {}
# 视频生成是一个同步长轮询请求；用浏览器生成的不透明请求 ID 关联当前处理任务，
# 让画布上的“取消视频”能立即停止本地等待，而不是只能等平台超时。
CANVAS_VIDEO_RUNS: Dict[str, asyncio.Task] = {}
CANVAS_COMFY_CANCEL_EVENTS: Dict[str, threading.Event] = {}
try:
    CANVAS_TASK_RETENTION_SECONDS = max(
        24 * 60 * 60,
        float(os.getenv("CANVAS_TASK_RETENTION_SECONDS", str(7 * 24 * 60 * 60))),
    )
except (TypeError, ValueError):
    CANVAS_TASK_RETENTION_SECONDS = 7 * 24 * 60 * 60
try:
    CANVAS_TASK_MAX_RECORDS = max(100, int(os.getenv("CANVAS_TASK_MAX_RECORDS", "500")))
except (TypeError, ValueError):
    CANVAS_TASK_MAX_RECORDS = 500

# 画布批量生图会在同一个事件循环中启动多个后台任务。保持适度并发，避免四张图
# 被人为拆成“两张运行、两张排队”；上游若有自己的限流，仍可通过环境变量调低。
try:
    CANVAS_IMAGE_TASK_CONCURRENCY = max(
        1,
        min(8, int(os.getenv("CANVAS_IMAGE_TASK_CONCURRENCY", "4"))),
    )
except (TypeError, ValueError):
    CANVAS_IMAGE_TASK_CONCURRENCY = 4
CANVAS_IMAGE_BATCH_CONCURRENCY = contextvars.ContextVar("canvas_image_batch_concurrency", default=0)
CANVAS_IMAGE_TASK_SEMAPHORES: Dict[Tuple[int, int], asyncio.Semaphore] = {}
CANVAS_IMAGE_TASK_SEMAPHORES_LOCK = Lock()


def canvas_image_task_semaphore():
    """Return the background image-task limiter for the current event loop."""
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return None
    concurrency = CANVAS_IMAGE_BATCH_CONCURRENCY.get() or CANVAS_IMAGE_TASK_CONCURRENCY
    key = (id(loop), concurrency)
    with CANVAS_IMAGE_TASK_SEMAPHORES_LOCK:
        semaphore = CANVAS_IMAGE_TASK_SEMAPHORES.get(key)
        if semaphore is None:
            semaphore = asyncio.Semaphore(concurrency)
            CANVAS_IMAGE_TASK_SEMAPHORES[key] = semaphore
        return semaphore

def _canvas_task_timestamp(task):
    try:
        return float(task.get("updated_at") or task.get("created_at") or 0)
    except (TypeError, ValueError, AttributeError):
        return 0.0

def _prune_canvas_tasks_locked(now=None):
    """Keep the local task journal bounded without removing active tasks."""
    now = float(now or time.time())
    changed = False
    cutoff = now - CANVAS_TASK_RETENTION_SECONDS
    for task_id, task in list(CANVAS_TASKS.items()):
        if not isinstance(task, dict):
            CANVAS_TASKS.pop(task_id, None)
            changed = True
            continue
        status = str(task.get("status") or "").lower()
        if status in CANVAS_TASK_TERMINAL_STATUSES and _canvas_task_timestamp(task) < cutoff:
            CANVAS_TASKS.pop(task_id, None)
            changed = True
    if len(CANVAS_TASKS) > CANVAS_TASK_MAX_RECORDS:
        active = []
        terminal = []
        for task_id, task in CANVAS_TASKS.items():
            status = str(task.get("status") or "").lower()
            item = (task_id, task)
            (terminal if status in CANVAS_TASK_TERMINAL_STATUSES else active).append(item)
        terminal.sort(key=lambda item: _canvas_task_timestamp(item[1]), reverse=True)
        keep_ids = {task_id for task_id, _task in active}
        keep_ids.update(task_id for task_id, _task in terminal[:max(0, CANVAS_TASK_MAX_RECORDS - len(active))])
        for task_id in list(CANVAS_TASKS):
            if task_id not in keep_ids:
                CANVAS_TASKS.pop(task_id, None)
                changed = True
    return changed

def _write_canvas_task_store_locked():
    """Atomically persist the task journal; caller must hold CANVAS_TASK_LOCK."""
    os.makedirs(DATA_DIR, exist_ok=True)
    temp_path = f"{CANVAS_TASKS_FILE}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    payload = {
        "version": CANVAS_TASK_STORE_VERSION,
        "updated_at": time.time(),
        "tasks": CANVAS_TASKS,
    }
    try:
        with open(temp_path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False, indent=2, default=str)
            fh.flush()
            try:
                os.fsync(fh.fileno())
            except OSError:
                pass
        os.replace(temp_path, CANVAS_TASKS_FILE)
    finally:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass

def _read_canvas_task_store_entries():
    with open(CANVAS_TASKS_FILE, "r", encoding="utf-8-sig") as fh:
        raw = json.load(fh)
    entries = raw.get("tasks") if isinstance(raw, dict) and isinstance(raw.get("tasks"), dict) else raw
    return entries if isinstance(entries, dict) else {}

def load_canvas_task_store():
    """Restore task records after a process restart.

    An asyncio task cannot survive a Python process restart, so queued/running
    records are converted to an explicit failure instead of being left as a
    forever-running card or disappearing as a 404. Completed records remain
    queryable and can still be finalized by the browser after it reconnects.
    """
    if not os.path.isfile(CANVAS_TASKS_FILE):
        return
    try:
        entries = _read_canvas_task_store_entries()
    except (OSError, ValueError, TypeError) as exc:
        # The next add/update rewrites the journal from memory, so keep a copy
        # of an unparsable file instead of silently losing finished results.
        print(f"加载画布任务记录失败: {exc}")
        if not isinstance(exc, OSError):
            try:
                _backup_unreadable_data_file(CANVAS_TASKS_FILE, exc)
            except RuntimeError as backup_error:
                print(backup_error)
        return
    restored = {}
    interrupted = False
    now = time.time()
    for key, value in entries.items():
        if not isinstance(value, dict):
            continue
        task = dict(value)
        task_id = str(task.get("id") or key or "").strip()
        if not task_id:
            continue
        status = str(task.get("status") or "").lower()
        if status in {"queued", "running"}:
            task.update({
                "status": "failed",
                "error": (
                    "服务在生图任务进行中重启，本地等待已中断。平台任务编号已保存，可查询原任务结果，请勿重复生成。"
                    if task.get("upstream_task_id")
                    else "服务在生图任务进行中重启，后台任务已中断，请重新生成。"
                ),
                "status_code": 503,
                "restart_interrupted": True,
                "updated_at": now,
                "finished_at": now,
            })
            interrupted = True
        restored[task_id] = task
    with CANVAS_TASK_LOCK:
        CANVAS_TASKS.clear()
        CANVAS_TASKS.update(restored)
        pruned = _prune_canvas_tasks_locked(now)
        if interrupted or pruned:
            try:
                _write_canvas_task_store_locked()
            except OSError as exc:
                print(f"保存重启后的画布任务状态失败: {exc}")

def update_canvas_task(task_id, changes):
    """Update and persist one task without raising if it was pruned."""
    with CANVAS_TASK_LOCK:
        task = CANVAS_TASKS.get(task_id)
        if not isinstance(task, dict):
            return False
        if task.get("status") == "cancelled" and (changes or {}).get("status") != "cancelled":
            return False
        task.update(changes or {})
        task["updated_at"] = time.time()
        if task.get("status") in CANVAS_TASK_TERMINAL_STATUSES and not task.get("finished_at"):
            task["finished_at"] = task["updated_at"]
        _prune_canvas_tasks_locked(task["updated_at"])
        try:
            _write_canvas_task_store_locked()
        except OSError as exc:
            print(f"保存画布任务状态失败({task_id}): {exc}")
        return True

def add_canvas_task(task_id, task):
    """Insert and persist a new task before returning its ID to the browser."""
    with CANVAS_TASK_LOCK:
        CANVAS_TASKS[task_id] = dict(task or {})
        _prune_canvas_tasks_locked()
        try:
            _write_canvas_task_store_locked()
        except OSError as exc:
            # 任务日志是恢复能力，不能因为磁盘暂时不可写而阻止一次正常生图。
            print(f"保存新建画布任务失败({task_id}): {exc}")


def _normalize_canvas_client_request_id(value):
    """Keep recovery lookups bounded to opaque browser-generated IDs."""
    raw = str(value or "").strip()
    if not raw or len(raw) > 120 or not re.fullmatch(r"[A-Za-z0-9._:-]+", raw):
        return ""
    return raw


def _find_canvas_task_by_client_request_id(client_request_id, task_type=None):
    """Find a task after a create response was lost by the browser.

    The in-memory lookup covers the normal path.  Reading the persisted task
    journal as a fallback also handles a brief process restart between the
    POST and the browser's recovery GET.
    """
    request_id = _normalize_canvas_client_request_id(client_request_id)
    if not request_id:
        return None
    with CANVAS_TASK_LOCK:
        for task in CANVAS_TASKS.values():
            if not isinstance(task, dict):
                continue
            if str(task.get("client_request_id") or "").strip() == request_id and (not task_type or task.get("type") == task_type):
                return dict(task)
    try:
        persisted = _read_canvas_task_store_entries()
    except (OSError, ValueError, TypeError):
        return None
    for task in persisted.values() if isinstance(persisted, dict) else []:
        if not isinstance(task, dict):
            continue
        if str(task.get("client_request_id") or "").strip() == request_id and (not task_type or task.get("type") == task_type):
            return dict(task)
    return None


def _find_canvas_task_by_upstream_task_id(upstream_task_id, provider_id):
    """Find the local binding ID needed to resume a SoonStudio task poll."""
    wanted = str(upstream_task_id or "").strip()
    if not wanted or len(wanted) > 240:
        return ""
    sources = []
    with CANVAS_TASK_LOCK:
        sources.extend(CANVAS_TASKS.values())
    try:
        persisted = _read_canvas_task_store_entries()
        if isinstance(persisted, dict):
            sources.extend(persisted.values())
    except (OSError, ValueError, TypeError):
        pass
    provider_id = str(provider_id or "").strip().lower()
    legacy_bindings = set()
    for task in sources:
        if not isinstance(task, dict) or task.get("type") not in (None, "", "online-image"):
            continue
        ids = [task.get("upstream_task_id"), *(task.get("upstream_task_ids") or [])]
        if not any(str(item or "").strip() == wanted for item in ids):
            continue
        binding = _normalize_canvas_client_request_id(task.get("client_request_id"))
        if not binding:
            continue
        saved_provider = str(task.get("provider_id") or "").strip().lower()
        if saved_provider and saved_provider == provider_id:
            return binding
        if not saved_provider:
            legacy_bindings.add(binding)
    return next(iter(legacy_bindings)) if len(legacy_bindings) == 1 else ""

