# --- 负载均衡 ---

MEDIA_INPUT_KEYS = ("image", "video", "audio", "mask", "filename", "file")
MEDIA_INPUT_EXT_RE = re.compile(r"\.(png|jpe?g|webp|gif|bmp|tiff?|mp4|webm|mov|m4v|avi|mkv|mp3|wav|m4a|aac|ogg|flac)(?:\?|$)", re.I)

def is_comfy_input_media_value(input_name: str, value: Any) -> bool:
    if not isinstance(value, str) or not value.strip():
        return False
    key = str(input_name or "").lower()
    if any(token in key for token in MEDIA_INPUT_KEYS):
        return True
    return bool(MEDIA_INPUT_EXT_RE.search(value))

def collect_required_comfy_media(params: Dict[str, Any]) -> List[str]:
    required = []
    for node_inputs in (params or {}).values():
        if not isinstance(node_inputs, dict):
            continue
        for input_name, value in node_inputs.items():
            if is_comfy_input_media_value(input_name, value):
                required.append(value)
    return list(dict.fromkeys(required))

def reserve_best_backend(required_images=None):
    from ComfyUI.integration.comfy_execution import backend_capacity

    status = {}
    for address in tuple(COMFYUI_INSTANCES):
        try:
            status[address] = backend_capacity(address, required_images or ())
        except (requests.RequestException, ValueError) as error:
            print(f"Backend {address} unreachable: {error}")

    with LOAD_LOCK:
        addresses = COMFYUI_INSTANCES
        if not addresses:
            raise RuntimeError("请先配置 ComfyUI 服务")

        def capacity(address):
            remote_load, has_media = status[address]
            return max(remote_load, BACKEND_LOCAL_LOAD.get(address, 0)), not has_media

        reachable = (address for address in addresses if address in status)
        backend = min(reachable, key=capacity, default=addresses[0])
        BACKEND_LOCAL_LOAD[backend] = BACKEND_LOCAL_LOAD.get(backend, 0) + 1
        return backend


# --- 辅助工具 ---

def comfyui_input_directory():
    """Resolve the input folder belonging to the local ComfyUI installation."""
    candidates = []
    configured_base = str(os.getenv("XIAOMEI_COMFY_BASE", "")).strip()
    if configured_base:
        candidates.append(configured_base)

    runtime = getattr(globals().get("COMFY_APPS"), "runtime", None)
    managed_base = getattr(runtime, "base", None)
    if managed_base:
        candidates.append(managed_base)

    # The project-local installation is the default used by the desktop app.
    candidates.append(os.path.join(BASE_DIR, "ComfyUI"))
    # Keep the documented fallback for installations kept in Documents.
    candidates.append(os.path.join(os.path.expanduser("~"), "Documents", "ComfyUI"))

    seen = set()
    for candidate in candidates:
        try:
            base = os.path.abspath(os.path.expandvars(os.path.expanduser(os.fspath(candidate))))
            if base in seen:
                continue
            seen.add(base)
            input_dir = os.path.join(base, "input")
            if os.path.isdir(input_dir):
                return input_dir
        except (OSError, TypeError, ValueError):
            continue
    return ""

def download_comfy_output(comfy_address, item, prefix="studio_"):
    from http.client import HTTPException as HTTPTransportError

    from ComfyUI.integration.comfy_outputs import output_format, view_query

    kind, extension = output_format(item)
    query = view_query(item)
    try:
        with urllib.request.urlopen(f"http://{comfy_address}/view?{query}", timeout=COMFYUI_DOWNLOAD_TIMEOUT) as response:
            content = response.read()
            content_type = response.headers.get("Content-Type", "")
        if kind == "image":
            url, _ = save_generated_image_bytes(
                content, prefix=prefix, fallback_extension=image_fallback_extension(item["filename"], content_type),
            )
            return url
        filename = generated_output_filename(prefix, extension)
        media_storage.write_media_snapshot(media_write_path(filename, "output"), content, deduplicate=False)
        return output_url_for(filename, "output")
    except (OSError, ValueError, HTTPTransportError) as error:
        print(f"下载 ComfyUI 输出失败: {error}")
        return f"/api/view?{query}"


def save_comfy_text_output(text, prefix="studio_", name=""):
    from ComfyUI.integration.comfy_outputs import SUFFIXES

    fallback = "comfy_text.txt"
    name = sanitize_export_filename(name or fallback, fallback)
    if os.path.splitext(name)[1].lower() not in SUFFIXES["text"]:
        name += ".txt"
    filename = f"{prefix}{uuid.uuid4().hex[:10]}_{name}"
    media_storage.write_media_snapshot(
        media_write_path(filename, "output"), text.encode("utf-8"), deduplicate=False,
    )
    return output_url_for(filename, "output")


