async def responses_input_image_url(ref, require_public_url=False):
    raw = ref.get("url", "") if isinstance(ref, dict) else ref
    text = str(raw or "").strip()
    if not text or (text.startswith("data:image/") and not require_public_url):
        return text
    path, local = media_cloud.reference_location(text)
    if not local:
        return path
    if not path or not output_file_from_url(path):
        if require_public_url:
            raise HTTPException(status_code=400, detail=f"RS 参考图不是公网 URL，无法传给上游：{text[:160]}")
        return ""
    if require_public_url:
        return await openai_video_proxy_public_reference_url(path)
    try:
        uploaded = await upload_local_video_to_cloud(path)
        public = str((uploaded or {}).get("url") or "")
        if public.startswith(("http://", "https://")):
            return public
    except Exception as exc:
        print(f"RS 参考图上传失败，使用内联图片：{getattr(exc, 'detail', str(exc))}")
    inline = reference_to_data_url({"url": path}, max_size=1536)
    return inline if inline.startswith("data:") else ""


