def provider_protocol(provider):
    return str((provider or {}).get("protocol") or "openai").strip().lower()

# 单模型可覆盖的协议（仅 OpenAI / Gemini，二者可共用同一站点的 Base URL + Key）
PER_MODEL_PROTOCOL_OPTIONS = {"openai", "gemini"}
# 协议固定、不支持单模型覆盖的内置平台
FIXED_PROTOCOL_PROVIDER_IDS = {"volcengine", "jimeng", "runninghub"}

def normalize_model_protocols(value):
    """规整 {模型名: 协议} 覆盖表，仅保留 openai/gemini。"""
    out = {}
    if isinstance(value, dict):
        for raw_name, raw_proto in value.items():
            name = str(raw_name or "").strip()
            proto = str(raw_proto or "").strip().lower()
            if name and proto in PER_MODEL_PROTOCOL_OPTIONS:
                out[name] = proto
    return out

def normalize_model_name_map(value):
    """规整 {模型ID: 展示名}，只保存真正有意义的显示标签。"""
    normalized = {}
    if isinstance(value, dict):
        for raw_model, raw_label in value.items():
            model = str(raw_model or "").strip()
            label = re.sub(r"\s+", " ", str(raw_label or "").strip())[:160]
            if model and label and label != model:
                normalized[model] = label
    return normalized

def is_soonstudio_provider(provider):
    """SoonStudio 只暴露 OpenAI 兼容图片接口，没有 Google 原生 /v1beta 路由。"""
    base_url = str((provider or {}).get("base_url") or "").strip().lower()
    try:
        host = urllib.parse.urlsplit(base_url).netloc.lower()
    except Exception:
        host = ""
    return host == "soonstudio.ai" or host.endswith(".soonstudio.ai")

def effective_protocol(provider, model=""):
    """返回某模型实际生效的协议：优先单模型覆盖，否则用平台全局协议。"""
    base = provider_protocol(provider)
    pid = str((provider or {}).get("id") or "").strip().lower()
    if pid in FIXED_PROTOCOL_PROVIDER_IDS:
        return base
    # SoonStudio 的图片模型（含 nano-banana）只接 OpenAI Images 接口。
    # 它没有 /v1beta/models/...:generateContent；误走 Gemini 原生路由会得到
    # {"detail":"Application \"v1beta\" not found"}。
    if is_soonstudio_provider(provider):
        return "openai"
    overrides = (provider or {}).get("model_protocols")
    if isinstance(overrides, dict):
        val = str(overrides.get(str(model or "").strip()) or "").strip().lower()
        if val in PER_MODEL_PROTOCOL_OPTIONS:
            return val
    # 混合聚合平台通常同时提供 OpenAI 图片模型和 Google/Nano Banana 图片模型。
    # 拉取模型后即使还没有保存单模型覆盖，也要按模型 ID 自动选择正确协议。
    model_id = str(model or "").strip().lower()
    if model_id.startswith(("nano-banana", "gemini-nano-banana")) or (
        model_id.startswith("gemini-") and "image" in model_id
    ):
        return "gemini"
    return base

def is_apimart_provider(provider):
    base_url = str((provider or {}).get("base_url") or "").lower()
    return provider_protocol(provider) == "apimart" or "apimart.ai" in base_url

detect_image_request_mode = provider_discovery.image_mode_hint

def effective_image_request_mode(provider, model=""):
    detected = detect_image_request_mode((provider or {}).get("base_url"), [model])
    if detected:
        return detected
    return normalize_image_request_mode((provider or {}).get("image_request_mode"))

def is_gemini_provider(provider):
    return provider_protocol(provider) == "gemini"

def is_volcengine_provider(provider):
    return provider_protocol(provider) == "volcengine"

def is_runninghub_provider(provider):
    return provider_protocol(provider) == "runninghub" or str((provider or {}).get("id") or "").strip().lower() == "runninghub"

def is_jimeng_provider(provider):
    return provider_protocol(provider) == "jimeng" or str((provider or {}).get("id") or "").strip().lower() == "jimeng"

def is_codex_provider(provider):
    return provider_protocol(provider) == "codex"

def is_gemini_cli_provider(provider):
    return provider_protocol(provider) == "gemini-cli"

def codex_env_value(key):
    return os.getenv(key, "") or read_api_env_value(key)

def codex_cli_executable():
    configured = str(codex_env_value("CODEX_BIN") or "").strip()
    if configured:
        return configured
    if os.name == "nt":
        # 安装器修改的用户 PATH 不会传回已经运行的桌面服务。
        candidates = [
            os.path.join(os.environ.get("LOCALAPPDATA", os.path.expanduser("~/AppData/Local")), "Programs", "OpenAI", "Codex", "bin", "codex.exe"),
            os.path.join(os.environ.get("APPDATA", os.path.expanduser("~/AppData/Roaming")), "npm", "codex.cmd"),
        ]
        for candidate in candidates:
            if os.path.isfile(candidate):
                return candidate
    return shutil.which("codex") or shutil.which("codex.exe") or shutil.which("codex.cmd") or ""

def codex_timeout(default=CODEX_DEFAULT_TIMEOUT):
    try:
        return max(30, min(3600, int(os.getenv("CODEX_CLI_TIMEOUT", str(default)) or default)))
    except Exception:
        return default


def codex_chat_timeout(default=CODEX_CHAT_TIMEOUT):
    """Return the bounded timeout used by GPT text chat."""
    try:
        raw = os.getenv("CODEX_CHAT_TIMEOUT", "") or read_api_env_value("CODEX_CHAT_TIMEOUT") or str(default)
        return max(45, min(1800, int(raw or default)))
    except Exception:
        return default


def codex_chat_reasoning_effort(default="low"):
    """Return a safe, overridable reasoning level for text-only CLI chat."""
    value = str(
        os.getenv("CODEX_CHAT_REASONING_EFFORT", "")
        or read_api_env_value("CODEX_CHAT_REASONING_EFFORT")
        or default
    ).strip().lower()
    return value if value in {"minimal", "low", "medium", "high", "xhigh"} else default


def codex_chat_base_url(default="https://chatgpt.com/backend-api/codex"):
    """Return the HTTPS Responses endpoint used by the ChatGPT CLI login."""
    value = str(
        os.getenv("CODEX_CHAT_BASE_URL", "")
        or read_api_env_value("CODEX_CHAT_BASE_URL")
        or default
    ).strip().rstrip("/")
    try:
        parsed = urllib.parse.urlsplit(value)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc or parsed.query or parsed.fragment:
            return default
    except Exception:
        return default
    return value


def codex_chat_force_https(default=True):
    """Whether GPT text chat should bypass the CLI WebSocket transport."""
    value = str(
        os.getenv("CODEX_CHAT_FORCE_HTTPS", "")
        or read_api_env_value("CODEX_CHAT_FORCE_HTTPS")
        or ("1" if default else "0")
    ).strip().lower()
    return value not in {"0", "false", "no", "off"}

def codex_decode_output(stdout, stderr):
    out_text = (stdout or b"").decode("utf-8", errors="replace").strip()
    err_text = (stderr or b"").decode("utf-8", errors="replace").strip()
    return out_text, err_text

async def run_codex_cli(
    prompt,
    model="",
    image_paths=None,
    timeout=None,
    output_last_message=True,
    sandbox="workspace-write",
    ephemeral=False,
    reasoning_effort="",
    force_https=False,
    https_base_url="",
):
    exe = codex_cli_executable()
    if not exe:
        raise HTTPException(status_code=400, detail="未找到 OpenAI Codex CLI。请先运行 CLI/windows/openai/install_openai_codex_cli.bat，并完成 codex 登录。")
    https_url = codex_chat_base_url(https_base_url or "https://chatgpt.com/backend-api/codex") if force_https else ""
    try:
        code, stdout, stderr, last = await codex_exec.execute(
            exe, BASE_DIR, prompt,
            timeout=timeout or codex_timeout(), output_last_message=output_last_message,
            sandbox=sandbox, model=model, images=image_paths, ephemeral=ephemeral,
            reasoning=reasoning_effort, https_url=https_url,
        )
    except asyncio.TimeoutError as exc:
        raise HTTPException(504, "OpenAI Codex CLI 执行超时。可设置 CODEX_CLI_TIMEOUT 增大等待时间。") from exc
    except FileNotFoundError as exc:
        raise HTTPException(400, f"未找到 OpenAI Codex CLI：{exe}") from exc
    out, err = codex_decode_output(stdout, stderr)
    if code:
        detail = err or out or last or f"exit={code}"
        raise HTTPException(502, f"OpenAI Codex CLI 调用失败：{detail[:1200]}")
    return {"text": last or out, "_stdout": out, "_stderr": err}


def codex_output_image_files(since_time=0):
    exts = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
    root = os.path.abspath(OUTPUT_OUTPUT_DIR)
    files = []
    try:
        # 新素材落在 图片 子目录，旧素材仍在根目录；两处都要扫到。
        for dirpath, dirnames, names in os.walk(root):
            dirnames[:] = [name for name in dirnames if name in media_paths.MEDIA_TYPE_FOLDER_NAMES]
            for name in names:
                if os.path.splitext(name)[1].lower() not in exts:
                    continue
                path = os.path.join(dirpath, name)
                if not os.path.isfile(path):
                    continue
                mtime = os.path.getmtime(path)
                if mtime + 1 < float(since_time or 0):
                    continue
                files.append((mtime, path))
    except Exception:
        return []
    return [path for _mtime, path in sorted(files, reverse=True)]

def codex_generated_image_files(since_time=0):
    """Return images written by the Codex CLI built-in image tool.

    The CLI stores built-in image-tool results under CODEX_HOME rather than
    the canvas output directory.  Keep this scan separate from
    ``codex_output_image_files`` so existing canvas assets are never mistaken
    for a new fallback result.
    """
    configured_home = str(os.getenv("CODEX_HOME") or "").strip()
    user_profile = str(os.getenv("USERPROFILE") or os.path.expanduser("~") or "").strip()
    roots = [
        os.path.join(configured_home, "generated_images") if configured_home else "",
        os.path.join(user_profile, ".codex", "generated_images") if user_profile else "",
    ]
    files = []
    seen = set()
    for root in roots:
        root = os.path.abspath(root) if root else ""
        if not root or root in seen or not os.path.isdir(root):
            continue
        seen.add(root)
        try:
            for dirpath, _dirnames, names in os.walk(root):
                for name in names:
                    path = os.path.join(dirpath, name)
                    if os.path.splitext(name)[1].lower() not in {".png", ".jpg", ".jpeg", ".webp", ".gif"}:
                        continue
                    try:
                        mtime = os.path.getmtime(path)
                    except OSError:
                        continue
                    if mtime + 1 < float(since_time or 0):
                        continue
                    files.append((mtime, path))
        except OSError:
            continue
    return [path for _mtime, path in sorted(files, reverse=True)]

def codex_output_url_from_path(path):
    if not path:
        return ""
    try:
        relative = os.path.relpath(os.path.realpath(path), os.path.realpath(OUTPUT_OUTPUT_DIR))
    except (OSError, TypeError, ValueError):
        return ""
    if not media_paths.path_under(OUTPUT_OUTPUT_DIR, relative):
        return ""
    return output_url_for(relative, "output")


ANTIGRAVITY_CLI_IMAGE_EXTENSIONS = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
ANTIGRAVITY_CLI_IMAGE_SKIP_DIRS = {".tempmediastorage", ".user_uploaded", ".system_generated"}


def gemini_cli_image_storage_roots():
    """Return Antigravity's local artifact roots for native image-tool output."""
    user_profile = str(os.getenv("USERPROFILE") or os.path.expanduser("~") or "").strip()
    if not user_profile:
        return []
    cli_home = os.path.join(user_profile, ".gemini", "antigravity-cli")
    return [os.path.join(cli_home, "brain"), os.path.join(cli_home, "scratch")]


def gemini_cli_image_path_is_owned(path):
    path = os.path.abspath(str(path or ""))
    if not os.path.isfile(path):
        return False
    for root in gemini_cli_image_storage_roots():
        root = os.path.abspath(root)
        try:
            if os.path.commonpath([os.path.normcase(root), os.path.normcase(path)]) == os.path.normcase(root):
                return True
        except (OSError, ValueError):
            continue
    return False


def gemini_cli_generated_image_files(since_time=0, name_hint=""):
    """Find native ``generate_image`` artifacts written by the Antigravity CLI."""
    hint = str(name_hint or "").strip().lower()
    files = []
    seen = set()
    for root in gemini_cli_image_storage_roots():
        root = os.path.abspath(root)
        if root in seen or not os.path.isdir(root):
            continue
        seen.add(root)
        try:
            for dirpath, dirnames, names in os.walk(root):
                dirnames[:] = [name for name in dirnames if name.lower() not in ANTIGRAVITY_CLI_IMAGE_SKIP_DIRS]
                for name in names:
                    if os.path.splitext(name)[1].lower() not in ANTIGRAVITY_CLI_IMAGE_EXTENSIONS:
                        continue
                    path = os.path.abspath(os.path.join(dirpath, name))
                    try:
                        mtime = os.path.getmtime(path)
                    except OSError:
                        continue
                    if mtime + 1 < float(since_time or 0):
                        continue
                    matching_hint = bool(hint and hint in os.path.splitext(name)[0].lower())
                    files.append((matching_hint, mtime, path))
        except OSError:
            continue
    return [path for _matching_hint, _mtime, path in sorted(files, key=lambda item: (item[0], item[1]), reverse=True)]


def gemini_cli_materialize_image(source_path, image_name=""):
    """Copy a native Antigravity artifact into the app's served output folder."""
    source_path = os.path.abspath(str(source_path or ""))
    if not os.path.isfile(source_path):
        return ""
    extension = os.path.splitext(source_path)[1].lower()
    if extension not in ANTIGRAVITY_CLI_IMAGE_EXTENSIONS:
        return ""
    in_output = bool(codex_output_url_from_path(source_path))
    if in_output and extension == ".png":
        try:
            with Image.open(source_path) as image:
                if str(image.format or "").upper() == "PNG":
                    return source_path
        except Exception:
            pass
    if not in_output and not gemini_cli_image_path_is_owned(source_path):
        return ""
    safe_name = re.sub(r"[^a-z0-9_]+", "_", str(image_name or "").lower()).strip("_")
    safe_name = "_".join(part for part in safe_name.split("_") if part)[:60] or "image"
    os.makedirs(OUTPUT_OUTPUT_DIR, exist_ok=True)
    try:
        _url, destination = save_generated_image_file(
            source_path,
            prefix=f"{safe_name}_",
            category="output",
            # Each native CLI request is an immutable user-visible result,
            # even when two requests happen to produce byte-identical images.
            # Global media deduplication is still used by ordinary providers.
            deduplicate=False,
        )
        return destination
    except (OSError, ValueError):
        return ""

def gpt_image_2_skill_executable():
    configured = str(codex_env_value("GPT_IMAGE_2_SKILL_BIN") or "").strip()
    if configured:
        return configured
    native_executable = shutil.which("gpt-image-2-skill.exe")
    if native_executable:
        return native_executable

    launchers = [
        shutil.which("gpt-image-2-skill"),
        shutil.which("gpt-image-2-skill.cmd"),
        shutil.which("gpt-image-2-skill.ps1"),
    ]
    if os.name == "nt":
        npm_launcher = os.path.join(os.environ.get("APPDATA", os.path.expanduser("~/AppData/Roaming")), "npm", "gpt-image-2-skill.cmd")
        if os.path.isfile(npm_launcher):
            launchers.append(npm_launcher)
    for launcher in launchers:
        if not launcher:
            continue
        # On Windows, the npm command shim forwards argv through cmd.exe. That
        # loses arguments after non-ACP characters such as emoji in a long
        # prompt, which can make the helper report that --out/--ref-image are
        # missing. Prefer the platform package's native binary when the shim
        # exposes the standard global npm layout.
        launcher_dir = os.path.dirname(os.path.abspath(launcher))
        package_root = os.path.join(launcher_dir, "node_modules", "gpt-image-2-skill", "node_modules")
        native_candidates = glob.glob(
            os.path.join(package_root, "gpt-image-2-skill-*", "bin", "gpt-image-2-skill.exe")
        )
        for candidate in sorted(native_candidates):
            if os.path.isfile(candidate):
                return candidate

    return next((launcher for launcher in launchers if launcher), "")

def gpt_image_2_skill_auth_file():
    configured = str(codex_env_value("GPT_IMAGE_2_SKILL_AUTH_FILE") or codex_env_value("CODEX_AUTH_FILE") or "").strip()
    if configured:
        return configured
    project_auth = os.path.join(RUNTIME_ROOT, "API", "openai-gpt-account-auth.json")
    user_profile = os.getenv("USERPROFILE", "").strip()
    codex_home = str(codex_env_value("CODEX_HOME") or "").strip()
    candidates = [
        project_auth,
        os.path.join(codex_home, "auth.json") if codex_home else "",
        os.path.join(user_profile, ".codex", "auth.json") if user_profile else "",
        os.path.join(os.path.expanduser("~"), ".codex", "auth.json"),
    ]
    for path in candidates:
        if path and os.path.isfile(path):
            return path
    return candidates[0] if candidates and candidates[0] else ""

def gpt_image_2_skill_auth_json(auth_file=""):
    path = str(auth_file or "").strip()
    if not path or not os.path.isfile(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8-sig") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def gpt_image_2_skill_access_token(auth_data):
    if not isinstance(auth_data, dict):
        return ""
    for key in ("access_token", "accessToken"):
        value = str(auth_data.get(key) or "").strip()
        if value:
            return value
    tokens = auth_data.get("tokens")
    if isinstance(tokens, dict):
        for key in ("access_token", "accessToken"):
            value = str(tokens.get(key) or "").strip()
            if value:
                return value
    return ""

def gpt_image_2_skill_api_key(auth_data=None):
    for key in ("GPT_IMAGE_2_SKILL_API_KEY", "OPENAI_API_KEY"):
        value = str(codex_env_value(key) or "").strip()
        if value:
            return value
    if isinstance(auth_data, dict):
        value = str(auth_data.get("OPENAI_API_KEY") or auth_data.get("api_key") or auth_data.get("apiKey") or "").strip()
        if value:
            return value
    user_profile = os.getenv("USERPROFILE", "").strip()
    codex_home = str(codex_env_value("CODEX_HOME") or "").strip()
    user_auth = os.path.join(codex_home, "auth.json") if codex_home else (os.path.join(user_profile, ".codex", "auth.json") if user_profile else "")
    if user_auth:
        user_data = gpt_image_2_skill_auth_json(user_auth)
        value = str(user_data.get("OPENAI_API_KEY") or user_data.get("api_key") or user_data.get("apiKey") or "").strip()
        if value:
            return value
    return ""

def gpt_image_2_skill_openai_args(auth_data=None):
    """Keep an API-key login paired with its configured OpenAI-compatible base."""
    api_key = gpt_image_2_skill_api_key(auth_data)
    explicit_key = any(str(codex_env_value(key) or "").strip() for key in ("GPT_IMAGE_2_SKILL_API_KEY", "OPENAI_API_KEY"))
    base_url = str(codex_env_value("GPT_IMAGE_2_SKILL_OPENAI_API_BASE") or codex_env_value("OPENAI_BASE_URL") or "").strip()
    if not explicit_key:
        codex_home = str(codex_env_value("CODEX_HOME") or "").strip() or os.path.join(os.path.expanduser("~"), ".codex")
        config_path = os.path.join(codex_home, "config.toml")
        if os.path.isfile(config_path):
            try:
                try:
                    import tomllib
                except ModuleNotFoundError:
                    import tomli as tomllib
                with open(config_path, "r", encoding="utf-8-sig") as config_file:
                    config = tomllib.loads(config_file.read())
                provider_id = str(config.get("model_provider") or "openai").strip()
                selected = config.get("model_providers", {}).get(provider_id, {})
                configured_base = str(selected.get("base_url") or "").strip()
                if provider_id != "openai" and not (base_url or configured_base):
                    raise HTTPException(status_code=400, detail=f"Codex 配置中的平台 {provider_id} 缺少 base_url，请补全中转服务地址后重试。")
                base_url = base_url or configured_base
                env_key = str(selected.get("env_key") or "").strip()
                if env_key:
                    api_key = str(codex_env_value(env_key) or "").strip()
                    if not api_key:
                        raise HTTPException(status_code=400, detail=f"Codex 中转服务所需的环境变量 {env_key} 未设置，请配置 API Key 后重试。")
                else:
                    api_key = str(selected.get("experimental_bearer_token") or api_key or "").strip()
            except HTTPException:
                raise
            except (OSError, ValueError, TypeError, AttributeError, ImportError) as exc:
                raise HTTPException(status_code=400, detail=f"无法读取 Codex 配置 {config_path}，请检查 TOML 格式及 Python 的 tomli 依赖后重试。") from exc
    if not api_key:
        return []
    base_url = (base_url or "https://api.openai.com/v1").rstrip("/")
    try:
        parsed = urllib.parse.urlparse(base_url)
        valid_base = parsed.scheme in {"http", "https"} and parsed.hostname and not (parsed.username or parsed.password or parsed.query or parsed.fragment)
    except ValueError:
        valid_base = False
    if not valid_base:
        raise HTTPException(status_code=400, detail="GPT CLI 生图的请求地址无效，请配置不含账号、密码或查询参数的 HTTP(S) API 根地址。")
    return ["--provider", "openai", "--api-key", api_key, "--openai-api-base", base_url]


def gpt_image_2_skill_provider_args(auth_file=""):
    auth_data = gpt_image_2_skill_auth_json(auth_file)
    if gpt_image_2_skill_access_token(auth_data):
        return ["--provider", "codex", "--auth-file", auth_file] if auth_file else ["--provider", "codex"], "codex"
    openai_args = gpt_image_2_skill_openai_args(auth_data)
    if openai_args:
        return openai_args, "openai"
    return (["--provider", "codex", "--auth-file", auth_file] if auth_file else ["--provider", "codex"]), "codex"

def is_codex_gpt_image_25_model(model=""):
    value = str(model or "").strip().lower()
    if value in CODEX_GPT_IMAGE_25_MODELS:
        return True
    return bool(re.fullmatch(r"gpt-image-2\.5-(?:flare|sunburst)-\d{4}-\d{2}-\d{2}", value))

def codex_image_model_family(model=""):
    value = str(model or "").strip().lower()
    return re.sub(r"-\d{4}-\d{2}-\d{2}$", "", value)

def codex_image_model_supported(model="", supported_models=None):
    """Check a model against the image models advertised by Codex."""
    if not is_codex_gpt_image_25_model(model):
        return True
    target = codex_image_model_family(model)
    return any(
        is_codex_gpt_image_25_model(candidate)
        and codex_image_model_family(candidate) == target
        for candidate in (supported_models or [])
    )

def gpt_image_2_skill_command(executable, *args):
    """Build a subprocess command for native binaries and Windows shims."""
    executable = str(executable or "").strip()
    lower = executable.lower()
    if lower.endswith(".ps1"):
        return ["powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", executable, *args]
    if lower.endswith((".cmd", ".bat")):
        return ["cmd.exe", "/d", "/c", executable, *args]
    return [executable, *args]

def parse_codex_capability_payload(stdout_text="", stderr_text=""):
    """Parse the JSON object emitted by `gpt-image-2-skill models list`."""
    candidates = []
    for text in (stdout_text, stderr_text):
        text = str(text or "").strip()
        if not text:
            continue
        candidates.append(text)
        candidates.extend(line.strip() for line in text.splitlines() if line.strip())
    for candidate in reversed(candidates):
        try:
            value = json.loads(candidate)
        except Exception:
            continue
        if isinstance(value, dict):
            return value
    return {}

def codex_image_generation_tool(raw):
    """Return only the Codex provider's image-generation capability object."""
    if not isinstance(raw, dict):
        return {}
    providers = raw.get("providers")
    codex = providers.get("codex") if isinstance(providers, dict) else None
    if not isinstance(codex, dict):
        codex = raw.get("codex") if isinstance(raw.get("codex"), dict) else None
    if not isinstance(codex, dict):
        return {}
    tool = codex.get("image_generation_tool")
    return tool if isinstance(tool, dict) else {}

def codex_image_models_from_capability(raw):
    """Extract image model IDs from the Codex image tool declaration only."""
    tool = codex_image_generation_tool(raw)
    detected = []

    def collect(value, model_context=False):
        if isinstance(value, dict):
            for key, child in value.items():
                key_text = str(key or "").strip().lower().replace("-", "_")
                child_context = model_context or (
                    "model" in key_text
                    or key_text in {"id", "ids", "name", "names"}
                )
                collect(child, child_context)
            return
        if isinstance(value, (list, tuple, set)):
            for child in value:
                collect(child, model_context)
            return
        if not model_context:
            return
        candidate = str(value or "").strip()
        if candidate == "gpt-image-2" or is_codex_gpt_image_25_model(candidate):
            detected.append(candidate)

    collect(tool)
    return model_list_from_values([*CODEX_DEFAULT_IMAGE_MODELS, *detected])

def codex_capability_message(capabilities):
    if not capabilities.get("helper_installed"):
        return "未找到 GPT Image helper；当前不会显示 GPT Image 2.5。"
    if not capabilities.get("probe_ok"):
        return "暂时无法读取本机 Codex image_generation 能力；当前不会显示 GPT Image 2.5。"
    if capabilities.get("has_gpt_image_25"):
        return "已检测到本机 Codex image_generation 能力声明支持 GPT Image 2.5。"
    return "本机 Codex image_generation 当前只声明支持 GPT Image 2；未检测到 GPT Image 2.5。"

async def detect_codex_image_capabilities(force=False):
    """Probe the installed helper and cache its Codex image capability list."""
    now = time.monotonic()
    cached = CODEX_IMAGE_CAPABILITY_CACHE.get("result")
    if not force and cached and float(CODEX_IMAGE_CAPABILITY_CACHE.get("expires_at") or 0) > now:
        return cached
    async with CODEX_IMAGE_CAPABILITY_LOCK:
        now = time.monotonic()
        cached = CODEX_IMAGE_CAPABILITY_CACHE.get("result")
        if not force and cached and float(CODEX_IMAGE_CAPABILITY_CACHE.get("expires_at") or 0) > now:
            return cached
        executable = gpt_image_2_skill_executable()
        base = {
            "helper_installed": bool(executable),
            "helper_path": executable,
            "probe_ok": False,
            "image_models": list(CODEX_DEFAULT_IMAGE_MODELS),
            "has_gpt_image_25": False,
            "raw": {},
        }
        if not executable:
            base["message"] = codex_capability_message(base)
            CODEX_IMAGE_CAPABILITY_CACHE.update({"expires_at": now + CODEX_IMAGE_CAPABILITY_TTL, "result": base})
            return base
        auth_file = gpt_image_2_skill_auth_file()
        args = gpt_image_2_skill_command(
            executable,
            "--json",
            "--provider",
            "codex",
            *( ["--auth-file", auth_file] if auth_file else [] ),
            "models",
            "list",
        )
        try:
            code, stdout, stderr = await cli_process.run(args, BASE_DIR, timeout=20)
            out_text, err_text = codex_decode_output(stdout, stderr)
            raw = parse_codex_capability_payload(out_text, err_text)
            base["raw"] = raw
            base["probe_ok"] = code == 0 and bool(raw)
            if base["probe_ok"]:
                base["image_models"] = codex_image_models_from_capability(raw)
                base["has_gpt_image_25"] = any(
                    is_codex_gpt_image_25_model(model)
                    for model in base["image_models"]
                )
            else:
                base["error"] = gpt_image_2_skill_failure_message(out_text, err_text, code)
        except asyncio.TimeoutError:
            base["error"] = "能力探测超时"
        except Exception as exc:
            base["error"] = str(exc)[:500]
        base["message"] = codex_capability_message(base)
        CODEX_IMAGE_CAPABILITY_CACHE.update({"expires_at": time.monotonic() + CODEX_IMAGE_CAPABILITY_TTL, "result": base})
        return base

def gpt_image_2_skill_model_arg(model="", provider="openai"):
    value = str(model or "").strip()
    low = value.lower()
    provider = str(provider or "").strip().lower()
    if provider == "codex":
        # This is the top-level Responses model used by the Codex transport.
        # The selected GPT Image model is passed separately in the
        # image_generation tool for the 2.5 raw-Responses path below.
        supported = {"gpt-5.4", "gpt-5.4-mini", "gpt-5.4-pro"}
        return value if low in supported else "gpt-5.4"
    if not value or low.startswith("$imagegen"):
        return "gpt-image-2"
    return value

def codex_local_image_data_url(path="", max_size=1536):
    """Create a bounded data URL for a local Codex Responses input image."""
    source_path = os.path.abspath(str(path or "").strip())
    if not source_path or not os.path.isfile(source_path):
        return ""
    try:
        with Image.open(source_path) as source:
            source.load()
            image = ImageOps.exif_transpose(source).copy()
        try:
            if max_size and max(image.size) > int(max_size):
                image.thumbnail((int(max_size), int(max_size)), Image.LANCZOS)
            has_alpha = image_has_alpha(image)
            buffer = BytesIO()
            if has_alpha:
                image.convert("RGBA").save(buffer, format="PNG", optimize=True)
                mime = "image/png"
            else:
                image.convert("RGB").save(buffer, format="JPEG", quality=88, optimize=True)
                mime = "image/jpeg"
            encoded = base64.b64encode(buffer.getvalue()).decode("ascii")
            return f"data:{mime};base64,{encoded}"
        finally:
            image.close()
    except Exception as exc:
        print(f"Codex 参考图预处理失败，回退原文件：{exc}")
        try:
            with open(source_path, "rb") as f:
                encoded = base64.b64encode(f.read()).decode("ascii")
            return f"data:{content_type_for_path(source_path)};base64,{encoded}"
        except OSError:
            return ""

def codex_gpt_image_25_request_body(prompt="", size="", model="", ref_paths=None):
    image_model = str(model or "").strip()
    if not is_codex_gpt_image_25_model(image_model):
        image_model = "gpt-image-2.5-flare"
    ref_paths = [str(path) for path in (ref_paths or []) if path and os.path.isfile(str(path))]
    content = []
    for path in ref_paths[:ONLINE_IMAGE_REFERENCE_MAX]:
        data_url = codex_local_image_data_url(path)
        if not data_url:
            raise HTTPException(status_code=400, detail=f"Codex 参考图读取失败：{os.path.basename(path)}")
        content.append({"type": "input_image", "image_url": data_url})
    content.append({
        "type": "input_text",
        "text": gpt_image_2_skill_prompt_arg(prompt, size, "codex"),
    })
    tool = {
        "type": "image_generation",
        "model": image_model,
        "action": "edit" if ref_paths else "generate",
        "background": "auto",
        "size": gpt_image_2_skill_size_arg(size, model, prompt, "codex"),
        "quality": "high",
        "output_format": "png",
    }
    return {
        "model": gpt_image_2_skill_model_arg(model, "codex"),
        "instructions": "Generate the requested image with the image_generation tool. Do not return only a text description.",
        "store": False,
        "stream": True,
        "input": [{"role": "user", "content": content}],
        "tools": [tool],
    }

async def generate_codex_provider_image_via_codex_responses(prompt, size, model, ref_paths=None):
    """Use Codex OAuth with a selectable GPT Image 2.5 tool model.

    The installed helper's high-level Codex command intentionally delegates
    to GPT Image 2. Its raw Responses command still owns the Codex auth,
    refresh, SSE parsing, and image materialization, so this adapter only
    supplies the image_generation request body needed by 2.5.
    """
    exe = gpt_image_2_skill_executable()
    if not exe:
        return None
    ref_paths = [str(path) for path in (ref_paths or []) if path and os.path.isfile(str(path))]
    image_model = str(model or "").strip()
    if not is_codex_gpt_image_25_model(image_model):
        return None
    body = codex_gpt_image_25_request_body(prompt, size, image_model, ref_paths)
    auth_file = gpt_image_2_skill_auth_file()
    body_fd, body_path = tempfile.mkstemp(prefix="codex_image25_", suffix=".json")
    os.close(body_fd)
    out_path = media_write_path(generated_output_filename("gpt_image_25_", ".png"), "output")
    try:
        with open(body_path, "w", encoding="utf-8") as f:
            json.dump(body, f, ensure_ascii=False, separators=(",", ":"))
        args = [exe, "--json", "--provider", "codex"]
        if auth_file:
            args.extend(["--auth-file", auth_file])
        args.extend([
            "request",
            "create",
            "--request-operation",
            "responses",
            "--body-file",
            body_path,
            "--out-image",
            out_path,
            "--expect-image",
        ])
        try:
            execution = await gpt_image_cli.run_helper(args, BASE_DIR, codex_timeout())
        except asyncio.TimeoutError as exc:
            raise HTTPException(status_code=504, detail="Codex 登录态调用 GPT Image 2.5 超时。可设置 CODEX_CLI_TIMEOUT 增大等待时间。") from exc
        if execution is None:
            return None
        returncode, stdout, stderr = execution
        out_text, err_text = codex_decode_output(stdout, stderr)
        if returncode:
            message = gpt_image_2_skill_failure_message(out_text, err_text, returncode)
            raise HTTPException(
                status_code=502,
                detail=f"Codex 登录态调用 GPT Image 2.5 失败（{image_model}）：{message[:1200]}",
            )
        parsed, reported_paths = parse_gpt_image_2_skill_output(out_text, err_text)
        candidate_paths = gpt_image_cli.output_files(
            out_path, reported_paths, OUTPUT_OUTPUT_DIR, working_dir=BASE_DIR,
        )
        urls = []
        for path in candidate_paths:
            processed_path = codex_postprocess_image_to_requested_size(path, size, "codex")
            url = codex_output_url_from_path(processed_path or path)
            if url and url not in urls:
                urls.append(url)
        if not urls:
            status_text = (out_text or err_text or "")[:1200]
            raise HTTPException(status_code=502, detail=f"Codex 已返回 GPT Image 2.5 响应，但没有在输出目录发现图片：{status_text}")
        return {"type": "url", "value": urls[0]}, {
            "images": urls,
            "text": out_text,
            "provider": "codex",
            "tool": "gpt-image-2-skill",
            "tool_mode": "raw-responses",
            "tool_provider": "codex",
            "image_model": image_model,
            "raw": parsed or {"stdout": out_text, "stderr": err_text},
        }
    finally:
        try:
            os.remove(body_path)
        except OSError:
            pass

async def generate_codex_provider_image_via_gpt_image_2_skill(prompt, size, model, ref_paths=None):
    exe = gpt_image_2_skill_executable()
    if not exe:
        return None
    ref_paths = [str(path) for path in (ref_paths or []) if path and os.path.isfile(str(path))]
    auth_file = gpt_image_2_skill_auth_file()
    auth_data = gpt_image_2_skill_auth_json(auth_file)
    provider_args, tool_provider = gpt_image_2_skill_provider_args(auth_file)
    attempts = [(provider_args, tool_provider)]
    if tool_provider == "codex" and gpt_image_2_skill_api_key(auth_data):
        attempts.append((gpt_image_2_skill_openai_args(auth_data), "openai"))
    for attempt_index, (options, attempt_provider) in enumerate(attempts):
        output_name = generated_output_filename("gpt_image_2_", ".png")
        out_path = os.path.join(OUTPUT_OUTPUT_DIR, output_name)
        args = gpt_image_cli.image_command(
            exe, options, ref_paths, destination=out_path,
            prompt=gpt_image_2_skill_prompt_arg(prompt, size, attempt_provider),
            model=gpt_image_2_skill_model_arg(model, attempt_provider),
            size=gpt_image_2_skill_size_arg(size, model, prompt, attempt_provider),
        )
        try:
            execution = await gpt_image_cli.run_helper(args, BASE_DIR, codex_timeout())
        except asyncio.TimeoutError as exc:
            raise HTTPException(status_code=504, detail="GPT Image 2 Skill 执行超时。可设置 CODEX_CLI_TIMEOUT 增大等待时间。") from exc
        if execution is None:
            return None
        returncode, stdout, stderr = execution
        out_text, err_text = codex_decode_output(stdout, stderr)
        if returncode:
            reason = gpt_image_2_skill_failure_message(out_text, err_text, returncode)
            rejected = gpt_image_cli.authentication_error(reason)
            label = gpt_image_cli.redact_provider_arguments(reason, options)
            detail = f"{attempt_provider}: {label}"[:1200]
            if rejected:
                if attempt_provider == "codex" and attempt_index + 1 < len(attempts):
                    continue
                action = (
                    "请重新执行 codex login 完成账号登录后重试。" if attempt_provider == "codex"
                    else "请检查 Codex 中转服务的 API Key、请求地址和生图权限后重试。"
                )
                raise HTTPException(401, f"GPT CLI 生图鉴权失败：{detail}。{action}")
            raise HTTPException(502, f"GPT Image 2 Skill 调用失败：{detail}")
        parsed, reported_paths = parse_gpt_image_2_skill_output(out_text, err_text)
        candidate_paths = gpt_image_cli.output_files(
            out_path, reported_paths, OUTPUT_OUTPUT_DIR, working_dir=BASE_DIR,
        )
        urls = []
        for path in candidate_paths:
            processed_path = codex_postprocess_image_to_requested_size(path, size, attempt_provider)
            url = codex_output_url_from_path(processed_path or path)
            if url:
                urls.append(url)
        if not urls:
            status_text = (out_text or err_text or "")[:1200]
            raise HTTPException(status_code=502, detail=f"GPT Image 2 Skill 已返回，但没有在输出目录发现图片：{status_text}")
        return {"type": "url", "value": urls[0]}, {
            "images": urls,
            "text": out_text,
            "provider": "codex",
            "tool": "gpt-image-2-skill",
            "tool_provider": attempt_provider,
            "raw": parsed or {"stdout": out_text, "stderr": err_text},
        }


async def codex_prepare_local_media(ref_url):
    return await cli_references.prepare(ref_url, output_file_from_url)


async def codex_reference_paths(reference_images=None, max_images=ONLINE_IMAGE_REFERENCE_MAX):
    paths = []
    temp_paths = []
    try:
        for ref in (reference_images or [])[:max_images]:
            url = ref.get("url") if isinstance(ref, dict) else getattr(ref, "url", "")
            if not url:
                continue
            path, created = await codex_prepare_local_media(url)
            if path:
                paths.append(path)
            temp_paths.extend(created)
        return paths, temp_paths
    except (Exception, asyncio.CancelledError):
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass
        raise

def codex_chat_models_from_app_server(data):
    """Use the executable model IDs advertised by the local Codex account."""
    models = []
    names = {}
    for item in data or []:
        if not isinstance(item, dict) or item.get("hidden"):
            continue
        model = str(item.get("model") or item.get("id") or "").strip()
        if not model or model.lower().startswith("gpt-image") or model in models:
            continue
        models.append(model)
        name = str(item.get("displayName") or "").strip()
        if name and name != model:
            names[model] = name
    return models, names


async def fetch_codex_cli_chat_models():
    """Read the account-visible chat models from Codex's app-server."""
    command = _canvas_harness_command()
    if not command:
        raise HTTPException(status_code=400, detail="未找到 Codex CLI，请先安装并登录后重试。")
    kwargs = {
        "cwd": BASE_DIR,
        "stdin": asyncio.subprocess.PIPE,
        "stdout": asyncio.subprocess.PIPE,
        "stderr": asyncio.subprocess.DEVNULL,
    }
    if os.name == "nt":
        kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    proc = None
    deadline = time.monotonic() + 30

    async def send(message):
        proc.stdin.write((json.dumps(message, ensure_ascii=False) + "\n").encode("utf-8"))
        await proc.stdin.drain()

    async def receive(request_id):
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise asyncio.TimeoutError()
            line = await asyncio.wait_for(proc.stdout.readline(), timeout=remaining)
            if not line:
                raise RuntimeError("Codex App Server 提前退出")
            message = json.loads(line)
            if message.get("id") != request_id:
                continue
            if message.get("error"):
                error = message["error"]
                raise RuntimeError(str(error.get("message") if isinstance(error, dict) else error))
            return message.get("result")

    try:
        proc = await asyncio.create_subprocess_exec(*command, **kwargs)
        await send({
            "method": "initialize", "id": 1,
            "params": {"clientInfo": {"name": "xiaomei_canvas", "title": "小美画布", "version": APP_VERSION}},
        })
        await receive(1)
        await send({"method": "initialized", "params": {}})
        data = []
        cursor = None
        seen_cursors = set()
        for page in range(20):
            params = {"includeHidden": False}
            if cursor:
                params["cursor"] = cursor
            request_id = page + 2
            await send({"method": "model/list", "id": request_id, "params": params})
            result = await receive(request_id)
            if not isinstance(result, dict) or not isinstance(result.get("data"), list):
                raise RuntimeError("Codex App Server 返回了无效模型列表")
            data.extend(result["data"])
            cursor = result.get("nextCursor")
            if not cursor:
                break
            if cursor in seen_cursors:
                raise RuntimeError("Codex App Server 模型分页游标重复")
            seen_cursors.add(cursor)
        else:
            raise RuntimeError("Codex App Server 模型列表分页过多")
        models, names = codex_chat_models_from_app_server(data)
        if not models:
            raise RuntimeError("Codex App Server 没有返回可选聊天模型")
        return models, names
    except asyncio.TimeoutError as exc:
        raise HTTPException(status_code=504, detail="读取 Codex CLI 模型列表超时，请检查网络和登录状态后重试。") from exc
    except (OSError, ValueError, RuntimeError) as exc:
        raise HTTPException(status_code=502, detail=f"读取 Codex CLI 模型列表失败：{str(exc)[:200]}。请更新 Codex CLI 或重新登录后重试。") from exc
    finally:
        if proc:
            if proc.stdin:
                proc.stdin.close()
            if proc.returncode is None:
                try:
                    proc.terminate()
                except ProcessLookupError:
                    pass
            try:
                await asyncio.wait_for(proc.wait(), timeout=3)
            except asyncio.TimeoutError:
                try:
                    proc.kill()
                except ProcessLookupError:
                    pass
                await proc.wait()


def codex_models_payload(chat_models, raw=None, image_models=None, model_names=None):
    image_models = model_list_from_values(
        image_models if image_models is not None else CODEX_DEFAULT_IMAGE_MODELS
    )
    chat_models = model_list_from_values(chat_models)
    all_models = [*image_models, *chat_models]
    has_image_25 = any(is_codex_gpt_image_25_model(model) for model in image_models)
    return {
        "ok": True,
        "protocol": "codex",
        "status": 200,
        "message": (
            "OpenAI Codex CLI 可用，已检测到 GPT Image 2.5 官方能力。"
            if has_image_25
            else "OpenAI Codex CLI 可用，当前只检测到 GPT Image 2。"
        ),
        "model_count": len(all_models),
        "total": len(all_models),
        "image_models": image_models,
        "chat_models": chat_models,
        "video_models": [],
        "model_names": model_names or {},
        "model_source": "codex app-server model/list",
        "all": all_models,
        "raw": raw or {},
    }


async def codex_live_models_payload():
    status = await codex_status()
    if not status.get("installed"):
        raise HTTPException(status_code=400, detail="未找到可用的 Codex CLI，请先安装或更新后重试。")
    chat_models, model_names = await fetch_codex_cli_chat_models()
    return codex_models_payload(
        chat_models,
        raw={"status": status},
        image_models=status.get("image_models"),
        model_names=model_names,
    )

async def generate_codex_provider_image_via_codex_cli(prompt, size, model, ref_paths=None):
    """Generate through Codex CLI's built-in image tool.

    This is a network-transport fallback for gpt-image-2-skill.  The CLI can
    fall back from WebSockets to HTTPS on Windows, and its built-in image tool
    writes results below CODEX_HOME/generated_images.  Copy only newly-created
    images into the canvas output directory so the rest of the app can serve
    them through its normal /output URL.
    """
    if not codex_cli_executable():
        return None
    ref_paths = [str(path) for path in (ref_paths or []) if path and os.path.isfile(str(path))]
    since = time.time()
    size_arg = gpt_image_2_skill_size_arg(size, model, prompt, "codex")
    reference_text = ""
    if ref_paths:
        reference_text = (
            "\n已附加参考图片。请把它们作为本次生成/编辑的参考，尽量保持商品主体、包装结构、颜色和文字布局一致。"
            "不要修改项目源代码。"
        )
    image_prompt = (
        "请使用当前 Codex 内置的 image_gen/GPT Image 2 图像工具，实际生成一张图片；不要只用文字描述。\n"
        f"用户的生图要求：{str(prompt or '').strip()}\n"
        f"输出尺寸要求：{size_arg}。\n"
        f"生成完成后不要把图片只留在工具缓存中；请确认工具已生成最终图片。{reference_text}\n"
        "不要修改项目代码、配置或数据文件；完成后用一句话说明已生成。"
    )
    raw = await run_codex_cli(
        image_prompt,
        # gpt-image-2-skill's Codex presets identify gpt-5.4 as the validated
        # model for the delegated image-generation tool.
        model="gpt-5.4",
        image_paths=ref_paths,
        timeout=codex_timeout(),
        output_last_message=True,
    )
    source_paths = codex_generated_image_files(since)
    source_paths.extend(codex_output_image_files(since))
    urls = []
    copied_paths = []
    os.makedirs(OUTPUT_OUTPUT_DIR, exist_ok=True)
    for source_path in source_paths:
        if not source_path or not os.path.isfile(source_path):
            continue
        try:
            _url, target_path = save_generated_image_file(
                source_path,
                prefix="gpt_image_2_codex_",
                category="output",
            )
        except (OSError, ValueError):
            continue
        copied_paths.append(target_path)
        processed_path = codex_postprocess_image_to_requested_size(target_path, size, "codex")
        url = codex_output_url_from_path(processed_path or target_path)
        if url and url not in urls:
            urls.append(url)
        if urls:
            break
    if not urls:
        status_text = "\n".join(
            str(raw.get(key) or "") for key in ("text", "_stdout", "_stderr")
        ).strip()[:1200]
        raise HTTPException(status_code=502, detail=f"Codex CLI 已完成请求，但没有找到新生成的图片：{status_text}")
    return {"type": "url", "value": urls[0]}, {
        "images": urls,
        "text": raw.get("text"),
        "provider": "codex",
        "tool": "codex-cli-imagegen",
        "tool_provider": "codex",
        "raw": raw,
    }

async def generate_codex_provider_image(prompt, size, model, reference_images=None, provider=None):
    ref_paths, temp_paths = await codex_reference_paths(reference_images)
    try:
        if is_codex_gpt_image_25_model(model):
            capabilities = await detect_codex_image_capabilities()
            if not codex_image_model_supported(model, capabilities.get("image_models")):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"当前 Codex image_generation 未声明支持 {str(model).strip()}，"
                        "已隐藏该模型。请在 API 设置中重新验证/拉取模型。"
                    ),
                )
            skill_result = await generate_codex_provider_image_via_codex_responses(prompt, size, model, ref_paths)
            if skill_result:
                return skill_result
            raise HTTPException(
                status_code=400,
                detail="未找到 GPT Image helper。Codex 登录态下的 GPT Image 2.5 需要先安装 gpt-image-2-skill。",
            )
        try:
            skill_result = await generate_codex_provider_image_via_gpt_image_2_skill(prompt, size, model, ref_paths)
            if skill_result:
                return skill_result
        except HTTPException as exc:
            # gpt-image-2-skill uses a direct HTTP request to the Codex
            # endpoint.  On some Windows networks that endpoint is blocked,
            # while the regular Codex CLI can recover by switching from
            # WebSockets to HTTPS.  In that case use the CLI's built-in
            # image_gen tool, which has the same signed-in account.
            detail = str(getattr(exc, "detail", "") or "")
            network_failure = bool(re.search(
                r"codex request failed|network[_ -]?error|backend-api/codex/responses|error sending request",
                detail,
                re.I,
            ))
            if not network_failure:
                raise
            _provider_args, tool_provider = gpt_image_2_skill_provider_args(gpt_image_2_skill_auth_file())
            if tool_provider != "codex":
                raise
            fallback = await generate_codex_provider_image_via_codex_cli(prompt, size, model, ref_paths)
            if fallback:
                return fallback
            raise
        raise HTTPException(status_code=400, detail="GPT CLI 生图组件未安装或路径已失效。请在“API 设置 → GPT CLI”点击“安装 / 更新”，完成后重试。")
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def codex_chat_prompt(payload, history_messages=None):
    parts = []
    system_prompt = chat_system_prompt(payload)
    if system_prompt:
        parts.append(f"系统要求：\n{system_prompt}")
    for item in (history_messages or [])[-MAX_HISTORY_MESSAGES:]:
        role = str(item.get("role") or "").strip()
        content = item.get("content")
        if role == "user" and item.get("link_context"):
            content = f"{content}\n\n{item.get('link_context')}"
        if role in {"user", "assistant"} and content:
            label = "用户" if role == "user" else "助手"
            parts.append(f"{label}：\n{content}")
    message = str(getattr(payload, "message", "") or "").strip()
    parts.append(f"用户：\n{message}")
    image_count = len([item for item in (getattr(payload, "images", None) or []) if item])
    if image_count:
        labels = "、".join(f"图{i}" for i in range(1, image_count + 1))
        parts.append(
            f"本次随请求附带 {image_count} 张视觉参考图，按提交顺序对应 {labels}。"
            "请严格按该顺序理解用户提到的图1、图2等编号。"
        )
    parts.append("请直接回答用户，输出纯文本，不要修改项目文件。")
    return "\n\n".join(part for part in parts if part).strip()

async def codex_chat_text(payload, history_messages=None):
    image_paths = []
    temp_paths = []
    try:
        image_values = []
        if hasattr(payload, "images"):
            image_values.extend([{"url": item} for item in (getattr(payload, "images", None) or []) if item])
        if hasattr(payload, "reference_images"):
            image_values.extend([ref.dict() for ref in (getattr(payload, "reference_images", None) or []) if getattr(ref, "url", "")])
        for item in (history_messages or [])[-MAX_HISTORY_MESSAGES:]:
            image_values.extend(
                {"url": value, "name": "商品链接参考图", "role": "link"}
                for value in _commerce_analysis_link_images_from_record(item)
            )
        image_paths, temp_paths = await codex_reference_paths(
            image_values,
            max_images=None if isinstance(payload, CanvasLLMRequest) else ONLINE_IMAGE_REFERENCE_MAX,
        )
        raw = await run_codex_cli(
            codex_chat_prompt(payload, history_messages),
            model=getattr(payload, "model", "") or CODEX_DEFAULT_CHAT_MODELS[0],
            image_paths=image_paths,
            timeout=getattr(payload, "cli_timeout", 0) or codex_chat_timeout(),
            output_last_message=True,
            sandbox="read-only",
            ephemeral=True,
            reasoning_effort=codex_chat_reasoning_effort(),
            force_https=codex_chat_force_https(),
            https_base_url=codex_chat_base_url(),
        )
        text = str(raw.get("text") or "").strip()
        return text or "Codex CLI 返回了空回复。", raw
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def gemini_cli_env_value(key):
    return os.getenv(key, "") or read_api_env_value(key)

def antigravity_cli_winget_candidates():
    patterns = [
        os.path.join(os.path.expanduser("~"), "AppData", "Local", "Microsoft", "WinGet", "Packages", "Google.AntigravityCLI_*", "agy.exe"),
        os.path.join(os.getenv("LOCALAPPDATA", ""), "Microsoft", "WinGet", "Packages", "Google.AntigravityCLI_*", "agy.exe"),
    ]
    candidates = []
    for pattern in patterns:
        if not pattern:
            continue
        candidates.extend(glob.glob(pattern))
    return sorted(dict.fromkeys(path for path in candidates if os.path.exists(path)), reverse=True)

def gemini_cli_executable():
    for key in ("ANTIGRAVITY_BIN", "AGY_BIN", "GEMINI_BIN"):
        configured = str(gemini_cli_env_value(key) or "").strip().strip('"')
        if configured:
            configured = os.path.expandvars(os.path.expanduser(configured))
            resolved = shutil.which(configured)
            if resolved and os.path.isfile(resolved):
                return resolved
    for name in ("agy", "agy.exe"):
        found = shutil.which(name)
        if found:
            return found
    for candidate in antigravity_cli_winget_candidates():
        return candidate
    return shutil.which("gemini") or shutil.which("gemini.exe") or shutil.which("gemini.cmd") or ""

def is_antigravity_cli(exe):
    text = str(exe or "").lower()
    return os.path.basename(text).startswith("agy") or "antigravity" in text

def gemini_cli_display_name(exe=None):
    return "Antigravity CLI" if is_antigravity_cli(exe or gemini_cli_executable()) else "Gemini CLI"

def gemini_cli_command(exe, prompt, model="", allow_tools=False, timeout=None):
    """Build the command from the executable resolved immediately before launch."""
    if is_antigravity_cli(exe):
        # Antigravity's default text mode can exit successfully without writing
        # the final turn to stdout (especially when the turn uses a tool).  The
        # JSON print format always includes the final ``response`` field and
        # still keeps native tool artifacts on disk.
        args = [
            exe,
            "--print-timeout",
            f"{int(timeout or gemini_cli_timeout())}s",
            "--output-format",
            "json",
        ]
        selected = gemini_cli_model(model)
        if selected and selected != "auto":
            args.extend(["--model", selected])
        if allow_tools:
            args.append("--dangerously-skip-permissions")
        args.extend(["-p", str(prompt or "")])
        return args
    args = [
        exe,
        "--model",
        gemini_cli_model(model),
        "--output-format",
        "json",
        "--skip-trust",
    ]
    if allow_tools:
        args.extend(["--approval-mode", "yolo"])
    args.extend(["--prompt", str(prompt or "")])
    return args

def gemini_cli_timeout(default=GEMINI_CLI_DEFAULT_TIMEOUT):
    try:
        return max(30, min(3600, int(os.getenv("GEMINI_CLI_TIMEOUT", str(default)) or default)))
    except Exception:
        return default

def gemini_cli_image_timeout():
    return GEMINI_CLI_IMAGE_TIMEOUT_SECONDS

def gemini_cli_model(model="", fallback=""):
    value = str(model or fallback or "").strip()
    return value or "auto"

def gemini_cli_image_failure_detail(raw=None, exe=None, model=""):
    """Turn an Antigravity native image-tool failure into an actionable error."""
    if isinstance(raw, dict):
        response_parts = [
            str(raw.get(key) or "").strip()
            for key in ("text", "_stdout", "_stderr", "raw")
            if str(raw.get(key) or "").strip()
        ]
        response_text = "\n".join(response_parts)
    else:
        response_text = str(raw or "").strip()
    lowered = response_text.lower()
    quota_markers = (
        "resource_exhausted",
        "quota",
        "rate limit",
        "429",
        "配额",
        "额度",
        "限额",
    )
    if any(marker in lowered or marker in response_text for marker in quota_markers):
        return (
            f"{gemini_cli_display_name(exe)} 的原生 generate_image 工具被账号图片配额限制，未生成图片文件。"
            "请等待 Antigravity 图片配额恢复后重试。"
        )
    if "generate_image" in lowered or "图片" in response_text or "image" in lowered:
        return (
            f"{gemini_cli_display_name(exe)} 已调用原生 generate_image，但未发现图片文件。"
            f"已检查 Antigravity 结果目录和应用输出目录：{OUTPUT_OUTPUT_DIR}。"
            "请查看 CLI 返回的具体错误后重试。"
        )
    return (
        f"{gemini_cli_display_name(exe)} 已返回，但未发现原生 generate_image 生成的图片文件。"
        f"已检查 Antigravity 结果目录和应用输出目录：{OUTPUT_OUTPUT_DIR}。"
    )


def gemini_cli_failure_detail(message, exe=None):
    """将 CLI 的常见上游错误转换为用户可执行的排查提示。

    Antigravity 会把账号/出口地区限制作为 FAILED_PRECONDITION(400) 写到
    stderr。这个错误与画布参数、参考图和 API Key 无关，直接展示英文原文
    会让用户误以为需要修改项目配置。
    """
    text = str(message or "").strip()
    lowered = text.lower()
    location_error = (
        "user location is not supported" in lowered
        or "failed_precondition" in lowered and "location" in lowered
        or "user location" in lowered and "not supported" in lowered
    )
    if location_error:
        raw = re.sub(r"\s+", " ", text).strip()
        raw_suffix = f" 原始错误：{raw[:600]}" if raw else ""
        return (
            f"{gemini_cli_display_name(exe)} 被上游拒绝：当前网络出口或账号地区不支持 API。"
            "请先开启能访问 Google/Antigravity 的 TUN 或全局代理，并切换到受支持的地区节点（例如美国）；"
            "然后在新终端运行 `agy` 确认登录成功，再回到小美画布重试。"
            "这不是参考图、提示词或画布连线问题，也不需要在 API 设置中填写 Key。"
            f"{raw_suffix}"
        )
    return f"{gemini_cli_display_name(exe)} 调用失败：{text[:1200]}"

def gemini_cli_text_from_raw(raw, fallback_text=""):
    if isinstance(raw, str):
        return raw.strip()
    if isinstance(raw, dict):
        for key in ("response", "text", "content", "message", "output"):
            value = raw.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        candidates = []
        for value in raw.values():
            if isinstance(value, str) and value.strip():
                candidates.append(value.strip())
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        text = gemini_cli_text_from_raw(item)
                        if text:
                            candidates.append(text)
                    elif isinstance(item, str) and item.strip():
                        candidates.append(item.strip())
        if candidates:
            return "\n".join(candidates).strip()
    if isinstance(raw, list):
        parts = [gemini_cli_text_from_raw(item) for item in raw]
        return "\n".join(part for part in parts if part).strip()
    return str(fallback_text or "").strip()


def gemini_cli_envelope_text(raw, fallback_text=""):
    """Extract assistant text without exposing Antigravity envelope metadata."""
    if not isinstance(raw, dict):
        return str(fallback_text or "").strip()
    # An explicit empty response means the CLI produced no assistant text.
    # Never fall back to conversation IDs, status values, or tool names.
    for key in ("response", "text", "content", "message", "output"):
        if key not in raw:
            continue
        value = raw.get(key)
        if isinstance(value, str):
            return value.strip()
        if value is not None:
            return gemini_cli_text_from_raw(value).strip()
        return ""
    return str(fallback_text or "").strip()

def gemini_cli_parse_stdout(out_text, unwrap_envelope=True):
    text = str(out_text or "").strip().lstrip("\ufeff")
    if not text:
        return {}, ""
    try:
        raw = json.loads(text)
        # A user may explicitly ask the model to return a JSON object.  Only
        # unwrap a CLI response envelope; otherwise preserve that JSON verbatim
        # so structured-output callers do not lose fields such as ``text``.
        is_envelope = isinstance(raw, dict) and (
            (isinstance(raw.get("response"), str) and any(
                key in raw for key in ("status", "conversation_id", "duration_seconds", "usage", "stats")
            ))
            or raw.get("status") in {"SUCCESS", "ERROR", "FAILED"}
        )
        parsed_text = gemini_cli_envelope_text(raw, text) if (unwrap_envelope and is_envelope) else text
        return raw, parsed_text
    except Exception:
        # Some Windows builds prepend a short diagnostic line or ANSI marker
        # before the JSON envelope.  Recover the first complete JSON object so
        # that a valid response is not shown verbatim as CLI metadata.
        start = text.find("{")
        if start >= 0:
            try:
                raw, _end = json.JSONDecoder().raw_decode(text[start:])
                is_envelope = isinstance(raw, dict) and (
                    (isinstance(raw.get("response"), str) and any(
                        key in raw for key in ("status", "conversation_id", "duration_seconds", "usage", "stats")
                    ))
                    or raw.get("status") in {"SUCCESS", "ERROR", "FAILED"}
                )
                if is_envelope:
                    parsed_text = gemini_cli_envelope_text(raw, text) if unwrap_envelope else text
                    return raw, parsed_text
            except Exception:
                pass
    parsed = jimeng_cli.parse_reply(text)
    if isinstance(parsed, (dict, list)) and parsed != {"text": text}:
        return parsed, gemini_cli_text_from_raw(parsed, text) if unwrap_envelope else text
    return {"text": text}, text

async def run_gemini_cli(prompt, model="", timeout=None, allow_tools=False, task_kind="chat"):
    exe = gemini_cli_executable()
    if not exe:
        raise HTTPException(status_code=400, detail="未找到 Antigravity CLI。请先安装 Google Antigravity CLI，并完成 agy 登录。")
    timeout_seconds = timeout or gemini_cli_timeout()
    args = gemini_cli_command(exe, prompt, model=model, allow_tools=allow_tools, timeout=timeout_seconds)
    try:
        try:
            proc = await cli_process.start(args, BASE_DIR)
        except (FileNotFoundError, OSError) as first_error:
            # WinGet can replace agy.exe while the desktop app stays open.
            # Re-resolve once so a stale path cannot strand the current task.
            refreshed_exe = gemini_cli_executable()
            same_exe = refreshed_exe and os.path.normcase(os.path.abspath(refreshed_exe)) == os.path.normcase(os.path.abspath(exe))
            if not refreshed_exe or same_exe:
                raise first_error
            exe = refreshed_exe
            args = gemini_cli_command(exe, prompt, model=model, allow_tools=allow_tools, timeout=timeout_seconds)
            proc = await cli_process.start(args, BASE_DIR)
        code, stdout, stderr = await cli_process.collect(proc, timeout_seconds)
    except asyncio.TimeoutError as exc:
        if task_kind == "image" and is_antigravity_cli(exe):
            detail = (
                f"{gemini_cli_display_name(exe)} 图片任务执行超时（固定上限 {GEMINI_CLI_IMAGE_TIMEOUT_SECONDS} 秒）。"
                "原生 generate_image 工具未在时限内完成；已停止任务，且不会改走其他生图平台。"
            )
        else:
            detail = f"{gemini_cli_display_name(exe)} 执行超时（已等待 {int(timeout_seconds)} 秒）。可设置 GEMINI_CLI_TIMEOUT 增大聊天等待时间。"
        raise HTTPException(status_code=504, detail=detail) from exc
    except (FileNotFoundError, OSError) as exc:
        raise HTTPException(
            status_code=400,
            detail=f"{gemini_cli_display_name(exe)} 启动失败（当前路径：{exe}）。请在 API 设置中重新检测 CLI；若未安装，请点击“安装 / 更新”后重试。",
        ) from exc
    out_text, err_text = codex_decode_output(stdout, stderr)
    # Antigravity is invoked with ``--output-format json`` above.  Unwrap only
    # its response envelope; model-returned JSON remains intact.
    raw, text = gemini_cli_parse_stdout(out_text, unwrap_envelope=True)
    if code != 0:
        message = err_text or out_text or f"exit={code}"
        raise HTTPException(status_code=502, detail=gemini_cli_failure_detail(message, exe))
    # Keep an actually empty response empty.  Returning the JSON envelope here
    # would make the chat layer mistake metadata for the model's answer.
    return {"text": text, "raw": raw, "_stdout": out_text, "_stderr": err_text}

def parse_antigravity_cli_models(output):
    """Parse the tab-separated model list printed by ``agy models``.

    Antigravity exposes model discovery as a CLI subcommand rather than an
    HTTP ``/models`` endpoint.  Keep the parser deliberately strict so a
    status/help line can never become a selectable model by accident.
    """
    ansi = re.compile(r"\x1b(?:[@-_]|\[[0-?]*[ -/]*[@-~])")
    model_ids = []
    model_names = {}
    for raw_line in str(output or "").splitlines():
        line = ansi.sub("", raw_line).strip()
        if not line or re.match(r"^(fetching available models|usage:|flags:|list available models)$", line, re.I):
            continue
        columns = re.split(r"\t+", line, maxsplit=1)
        model_id = columns[0].strip()
        label = columns[1].strip() if len(columns) > 1 else ""
        if not label:
            # A future CLI may align columns with spaces instead of tabs.
            columns = re.split(r"\s{2,}", line, maxsplit=1)
            if len(columns) > 1:
                model_id, label = columns[0].strip(), columns[1].strip()
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]*", model_id or ""):
            continue
        if not label and not re.match(r"^(gemini|claude|gpt|codex|gemma|mistral|llama)", model_id, re.I):
            continue
        model_ids.append(model_id)
        if label and label != model_id:
            model_names[model_id] = re.sub(r"\s+", " ", label)[:160]
    return model_list_from_values(model_ids), model_names


async def fetch_antigravity_cli_models(exe=None):
    """Ask the installed Antigravity CLI for its account-visible models."""
    executable = exe or gemini_cli_executable()
    if not executable or not is_antigravity_cli(executable):
        return [], {}
    proc = None
    try:
        proc = await asyncio.create_subprocess_exec(
            executable,
            "models",
            cwd=BASE_DIR,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
    except (asyncio.TimeoutError, FileNotFoundError, OSError):
        if proc and proc.returncode is None:
            try:
                proc.kill()
                await proc.wait()
            except Exception:
                pass
        return [], {}
    out_text, err_text = codex_decode_output(stdout, stderr)
    if proc.returncode != 0:
        return [], {}
    return parse_antigravity_cli_models("\n".join(part for part in (out_text, err_text) if part))


async def gemini_cli_models_payload(raw=None, exe=None):
    discovered, model_names = await fetch_antigravity_cli_models(exe)
    model_names = dict(model_names or {})
    model_names.setdefault("auto", "auto（调用 Antigravity 原生 generate_image）")
    if discovered:
        # ``agy models`` supplies the agent/chat model selector. Image tasks
        # use the CLI session's native generate_image tool independently.
        image_models = model_list_from_values(GEMINI_CLI_DEFAULT_IMAGE_MODELS)
        chat_models = model_list_from_values(discovered)
        all_models = model_list_from_values([*image_models, *chat_models])
        message = "Antigravity CLI 可用；图片任务会调用当前会话的原生 generate_image 工具。"
        source = "agy models"
    else:
        image_models = model_list_from_values(GEMINI_CLI_DEFAULT_IMAGE_MODELS)
        chat_models = model_list_from_values(GEMINI_CLI_DEFAULT_CHAT_MODELS)
        all_models = model_list_from_values([*image_models, *chat_models])
        message = "Antigravity CLI 可用，但未能拉取具体聊天模型；图片任务仍会调用原生 generate_image 工具。"
        source = "default models"
    return {
        "ok": True,
        "protocol": "gemini-cli",
        "status": 200,
        "message": message,
        "model_source": source,
        "model_count": len(all_models),
        "total": len(all_models),
        "image_models": image_models,
        "chat_models": chat_models,
        "video_models": [],
        "model_names": model_names,
        "all": all_models,
        "raw": raw or {},
    }

def gemini_cli_reference_note(reference_images=None):
    refs = []
    temp_paths = []
    for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
        url = ref.get("url") if isinstance(ref, dict) else getattr(ref, "url", "")
        if not url:
            continue
        refs.append(url)
    return refs, temp_paths

async def gemini_cli_reference_paths(reference_images=None, max_images=ONLINE_IMAGE_REFERENCE_MAX):
    return await codex_reference_paths(reference_images, max_images=max_images)

def gemini_cli_image_size_instruction(size="", model=""):
    size_text = str(size or "").strip()
    model_text = str(model or "").strip()
    match = re.match(r"^\s*(\d{2,5})\s*[xX*]\s*(\d{2,5})\s*$", size_text)
    if match:
        width, height = int(match.group(1)), int(match.group(2))
        if width > 0 and height > 0:
            orientation = "正方形" if width == height else ("横版" if width > height else "竖版")
            return (
                f"目标输出分辨率：{width}x{height} 像素（宽 x 高），画面方向：{orientation}。"
                f"请将这个分辨率要求写入原生 generate_image 的 Prompt，并按工具能力输出最接近的结果。"
            )
    combined = f"{size_text} {model_text}".lower()
    if "4k" in combined:
        return "目标输出为 4K 高分辨率图片；请将 4K 要求交给原生 generate_image 工具处理。"
    if "2k" in combined:
        return "目标输出为 2K 高分辨率图片；请将 2K 要求交给原生 generate_image 工具处理。"
    return f"尺寸/比例参考：{size_text or 'auto'}；请由原生 generate_image 工具决定最终输出尺寸。"


def gemini_cli_tool_aspect_ratio(size="", aspect_ratio=""):
    allowed = {"1:1", "2:3", "3:2", "3:4", "4:3", "9:16", "16:9"}
    requested = str(aspect_ratio or "").strip().lower().replace(" ", "")
    if requested in allowed:
        return requested
    if requested in {"adaptive", "source", "auto"}:
        return ""
    match = re.match(r"^\s*(\d{2,5})\s*[xX*]\s*(\d{2,5})\s*$", str(size or ""))
    if match:
        width, height = int(match.group(1)), int(match.group(2))
        if width > 0 and height > 0:
            ratio = width / height
            candidates = []
            for value in allowed:
                numerator, denominator = (int(part) for part in value.split(":"))
                candidates.append((abs(ratio - numerator / denominator), value))
            return min(candidates, key=lambda item: item[0])[1]
    return ""


def gemini_cli_path_from_text(value):
    path = str(value or "").strip().strip("`'\".,;:)]}")
    if path.lower().startswith("file://"):
        parsed = urllib.parse.urlparse(path)
        path = urllib.parse.unquote(parsed.path or "")
        if re.match(r"^/[A-Za-z]:[\\/]", path):
            path = path[1:]
        elif parsed.netloc:
            path = f"//{parsed.netloc}{path}"
    return path


def gemini_cli_seedvr2_backend_status():
    """Return a local ComfyUI backend only when SeedVR2 is actually exposed."""
    try:
        capability = (_local_upscale_comfy_capabilities(force=True) or {}).get("seedvr2") or {}
    except Exception as exc:
        capability = {"ready": False, "message": str(exc)}
    if capability.get("ready") and capability.get("address"):
        return str(capability["address"]), ""

    detail = str(capability.get("message") or "未检测到可用的本地 ComfyUI")
    return "", f"本地 AI 超分未执行：{detail}。已保留 CLI 原图，未进行普通插值放大。"


def gemini_cli_upload_image_to_comfy(comfy_address, source_path):
    extension = os.path.splitext(source_path)[1].lower() or ".png"
    upload_name = f"gemini_cli_upscale_{uuid.uuid4().hex[:12]}{extension}"
    content_type = mimetypes.guess_type(source_path)[0] or "application/octet-stream"
    with open(source_path, "rb") as source_file:
        response = requests.post(
            f"http://{comfy_address}/upload/image",
            files={"image": (upload_name, source_file, content_type)},
            timeout=60,
        )
    response.raise_for_status()
    payload = response.json()
    uploaded_name = str(payload.get("name") or upload_name).strip()
    if not uploaded_name:
        raise RuntimeError("ComfyUI 未返回上传图片名称")
    return uploaded_name


def gemini_cli_local_ai_upscale_sync(source_path, requested_size, comfy_address):
    width, height = parse_size_pair(requested_size)
    target_long_edge = max(width, height, 2048)
    target_long_edge = min(4096, target_long_edge)
    target_width = width or target_long_edge
    target_height = height or target_long_edge
    try:
        uploaded_name = gemini_cli_upload_image_to_comfy(comfy_address, source_path)
        capability = (_local_upscale_comfy_capabilities(force=True) or {}).get("seedvr2") or {}
        official_node = str(capability.get("node") or "official") != "legacy"
        if official_node:
            workflow_name = GEMINI_CLI_LOCAL_AI_UPSCALE_WORKFLOW
            params = {
                "1": {"image": uploaded_name},
                "2": {
                    "tiled_vae": True,
                    "vae_tile_size": 512,
                    "vae_tile_overlap": 64,
                    "preserve_vram": True,
                    "cache_model": False,
                    "enable_debug": False,
                    "device": "cuda:0",
                },
                "3": {"blocks_to_swap": 32, "offload_io_components": True},
                "4": {
                    "model": "seedvr2_ema_3b_fp8_e4m3fn.safetensors",
                    "new_resolution": max(16, min(4320, min(target_width, target_height))),
                    "batch_size": 1,
                    "color_correction": "wavelet",
                    "input_noise_scale": 0.0,
                    "latent_noise_scale": 0.0,
                },
                "5": {"width": target_width, "height": target_height},
            }
        else:
            workflow_name = "upscale.json"
            params = {
                "15": {"image": uploaded_name},
                "172": {
                    "resolution": target_long_edge,
                    "max_resolution": 4096,
                    "batch_size": 1,
                    "input_noise_scale": 0,
                    "latent_noise_scale": 0,
                },
            }
        result = generate(GenerateRequest(
            prompt="Antigravity CLI 图片 AI 超分",
            width=target_width,
            height=target_height,
            workflow_json=workflow_name,
            params=params,
            type="gemini-cli-upscale",
            record_history=False,
            preferred_backend=comfy_address,
            timeout_seconds=GEMINI_CLI_LOCAL_AI_UPSCALE_TIMEOUT_SECONDS,
        ))
        if not isinstance(result, dict) or result.get("error"):
            detail = str((result or {}).get("error") or "ComfyUI 未返回超分结果")[:800]
            return source_path, {
                "status": "failed",
                "engine": "SeedVR2",
                "message": f"本地 AI 超分失败：{detail}。已保留 CLI 原图，未进行普通插值放大。",
            }
        image_url = next((str(item) for item in (result.get("images") or []) if item), "")
        result_path = output_file_from_url(image_url)
        if not result_path or not os.path.isfile(result_path):
            return source_path, {
                "status": "failed",
                "engine": "SeedVR2",
                "message": "本地 AI 超分没有返回可用图片。已保留 CLI 原图，未进行普通插值放大。",
            }
        return result_path, {
            "status": "succeeded",
            "engine": "SeedVR2",
            "backend": comfy_address,
            "target_long_edge": target_long_edge,
            "message": f"已使用本地 SeedVR2 AI 超分（目标长边 {target_long_edge}px）。",
        }
    except Exception as exc:
        return source_path, {
            "status": "failed",
            "engine": "SeedVR2",
            "message": f"本地 AI 超分失败：{str(exc)[:800]}。已保留 CLI 原图，未进行普通插值放大。",
        }


async def gemini_cli_local_ai_upscale_image(source_path, requested_size):
    source_path = os.path.abspath(str(source_path or ""))
    if not source_path or not os.path.isfile(source_path):
        return source_path, {
            "status": "skipped",
            "engine": "SeedVR2",
            "message": "本地 AI 超分未执行：找不到 CLI 生成的原图。",
        }
    comfy_address, unavailable_message = await asyncio.to_thread(gemini_cli_seedvr2_backend_status)
    if not comfy_address:
        return source_path, {
            "status": "skipped",
            "engine": "SeedVR2",
            "message": unavailable_message,
        }
    return await asyncio.to_thread(
        gemini_cli_local_ai_upscale_sync,
        source_path,
        requested_size,
        comfy_address,
    )

async def generate_gemini_cli_provider_image(prompt, size, model, reference_images=None, provider=None, aspect_ratio=""):
    cli_exe = gemini_cli_executable()
    if not is_antigravity_cli(cli_exe):
        raise HTTPException(
            status_code=400,
            detail="当前图片任务仅支持已安装并登录的 Antigravity CLI（agy），不会改用其他 CLI 或生图平台。",
        )
    ref_paths, temp_paths = await gemini_cli_reference_paths(reference_images)
    image_name = f"canvas_image_{uuid.uuid4().hex[:10]}"
    tool_aspect_ratio = gemini_cli_tool_aspect_ratio(size, aspect_ratio)
    try:
        reference_argument = json.dumps(ref_paths[:3], ensure_ascii=False)
        aspect_argument = f"AspectRatio: {tool_aspect_ratio}\n" if tool_aspect_ratio else ""
        size_context = f"{model or ''} {prompt or ''}"
        image_prompt = (
            "这是一个必须完成的图片生成任务，不是文字问答。\n"
            "你必须调用当前 Antigravity CLI 会话提供的原生 `generate_image` 工具恰好一次；"
            "不要只返回图片描述、计划或 Markdown，也不要调用 shell、Python、HTML/canvas、其他 API、其他平台或其他生图工具。\n"
            "请按下面的字段名传给原生工具（字段名大小写保持一致）：\n"
            f"Prompt: {json.dumps(str(prompt or ''), ensure_ascii=False)}\n"
            f"ImageName: {image_name}\n"
            "toolAction: Generate canvas image\n"
            "toolSummary: Generate canvas image\n"
            f"ImagePaths: {reference_argument}\n"
            f"{aspect_argument}"
            f"{gemini_cli_image_size_instruction(size, size_context)}\n"
            "只生成 1 张最终图片。图片必须由原生 generate_image 工具产生并由该工具保存；"
            "应用会自动回收工具生成的文件，不要自行创建、复制或移动文件。完成工具调用后只需简短说明结果。"
        )
        async with GEMINI_CLI_IMAGE_LOCK:
            existing_files = {os.path.abspath(path) for path in codex_output_image_files()}
            existing_cli_files = {os.path.abspath(path) for path in gemini_cli_generated_image_files()}
            since = time.time()
            raw = await run_gemini_cli(
                image_prompt,
                model=model or GEMINI_CLI_DEFAULT_IMAGE_MODELS[0],
                timeout=gemini_cli_image_timeout(),
                allow_tools=True,
                task_kind="image",
            )
            output_files = [
                path for path in codex_output_image_files(since)
                if os.path.abspath(path) not in existing_files
            ]
            cli_files = [
                path for path in gemini_cli_generated_image_files(since, image_name)
                if os.path.abspath(path) not in existing_cli_files
            ]
            files = []
            for path in [*cli_files, *output_files]:
                path = os.path.abspath(path)
                if path not in files:
                    files.append(path)
            urls = []
            postprocess = {
                "status": "skipped",
                "engine": "SeedVR2",
                "message": "本地 AI 超分未执行：未找到 CLI 输出图片。",
            }
            for path in files:
                materialized_path = gemini_cli_materialize_image(path, image_name)
                if not materialized_path:
                    continue
                processed_path, postprocess = await gemini_cli_local_ai_upscale_image(materialized_path, size)
                url = codex_output_url_from_path(processed_path or materialized_path)
                if url and url not in urls:
                    urls.append(url)
                if urls:
                    break
            if not urls:
                text_parts = []
                if isinstance(raw, dict):
                    for key in ("text", "_stdout", "_stderr"):
                        value = str(raw.get(key) or "").strip()
                        if value:
                            text_parts.append(value)
                    nested_raw = raw.get("raw")
                    if nested_raw:
                        text_parts.append(json.dumps(nested_raw, ensure_ascii=False))
                text = "\n".join(text_parts)
                pattern = r"(file://[^\r\n\"'<>]+\.(?:png|jpe?g|webp|gif)|[A-Za-z]:[\\/][^\r\n\"'<>]+\.(?:png|jpe?g|webp|gif)|/[^\r\n\"'<>]+\.(?:png|jpe?g|webp|gif))"
                for match in re.findall(pattern, text, flags=re.I):
                    match_path = gemini_cli_path_from_text(match)
                    if os.path.abspath(match_path) in existing_cli_files or os.path.abspath(match_path) in existing_files:
                        continue
                    materialized_path = gemini_cli_materialize_image(match_path, image_name)
                    if not materialized_path:
                        continue
                    processed_path, postprocess = await gemini_cli_local_ai_upscale_image(materialized_path, size)
                    url = codex_output_url_from_path(processed_path or materialized_path)
                    if url and url not in urls:
                        urls.append(url)
                    if urls:
                        break
        if not urls:
            raise HTTPException(
                status_code=502,
                detail=gemini_cli_image_failure_detail(raw, cli_exe, model),
            )
        raw_text = str(raw.get("text") or "").strip()
        postprocess_message = str(postprocess.get("message") or "").strip()
        if postprocess_message:
            raw_text = f"{raw_text}\n{postprocess_message}".strip()
        transport = "agy-cli+seedvr2" if postprocess.get("status") == "succeeded" else "agy-cli"
        return {"type": "url", "value": urls[0]}, {
            "images": urls,
            "text": raw_text,
            "provider": "gemini-cli",
            "transport": transport,
            "postprocess": postprocess,
            "raw": raw.get("raw"),
        }
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def gemini_cli_chat_prompt(payload, history_messages=None):
    parts = []
    system_prompt = chat_system_prompt(payload)
    if system_prompt:
        parts.append(f"系统要求：\n{system_prompt}")
    for item in (history_messages or [])[-MAX_HISTORY_MESSAGES:]:
        role = str(item.get("role") or "").strip()
        content = item.get("content")
        # Do not feed the pre-fix CLI metadata artifact back to the model as if
        # it were an assistant answer.
        if role == "assistant" and re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f-]{27}\s+SUCCESS\s+read_file\s+ViewFile",
            str(content or "").strip(),
            flags=re.IGNORECASE,
        ):
            continue
        if role == "user" and item.get("link_context"):
            content = f"{content}\n\n{item.get('link_context')}"
        if role in {"user", "assistant"} and content:
            label = "用户" if role == "user" else "助手"
            parts.append(f"{label}：\n{content}")
    message = str(getattr(payload, "message", "") or "").strip()
    parts.append(f"用户：\n{message}")
    image_values = []
    if hasattr(payload, "images"):
        image_values.extend([{"url": item} for item in (getattr(payload, "images", None) or []) if item])
    if hasattr(payload, "reference_images"):
        image_values.extend([ref.dict() for ref in (getattr(payload, "reference_images", None) or []) if getattr(ref, "url", "")])
    for item in (history_messages or [])[-MAX_HISTORY_MESSAGES:]:
        image_values.extend(
            {"url": value, "name": "商品链接参考图", "role": "link"}
            for value in _commerce_analysis_link_images_from_record(item)
        )
    refs = []
    temp_paths = []
    return "\n\n".join(part for part in parts if part).strip(), image_values

async def gemini_cli_chat_text(payload, history_messages=None):
    temp_paths = []
    try:
        prompt, image_values = gemini_cli_chat_prompt(payload, history_messages)
        image_paths, temp_paths = await gemini_cli_reference_paths(
            image_values,
            max_images=None if isinstance(payload, CanvasLLMRequest) else ONLINE_IMAGE_REFERENCE_MAX,
        )
        if image_paths:
            numbered_paths = "\n".join(
                f"图{index}（第 {index} 张参考图）：{path}"
                for index, path in enumerate(image_paths, start=1)
            )
            prompt = f"{prompt}\n\n可参考的本地图片路径（按编号对应）：\n" + numbered_paths
        prompt = (
            f"{prompt}\n\n请直接回答用户，输出纯文本。"
            "如需查看参考图片，只读取上面列出的图片路径；不要访问其它文件，"
            "不要创建、修改或删除任何文件。"
        )
        cli_timeout = getattr(payload, "cli_timeout", 0) or gemini_cli_timeout()
        raw = await run_gemini_cli(
            prompt,
            model=getattr(payload, "model", "") or GEMINI_CLI_DEFAULT_CHAT_MODELS[0],
            timeout=cli_timeout,
            # Antigravity reads local reference images through its native
            # read_file tool. Text-only chats keep the no-tools path.
            allow_tools=bool(image_paths),
        )
        text = str(raw.get("text") or "").strip()
        if not text and not getattr(payload, "cli_single_attempt", False):
            # ``agy`` can occasionally finish with a successful process status
            # but no final response (for example after a transient transport
            # reconnect).  A single chat retry is safe and prevents the UI from
            # surfacing the misleading “空回复” message.  OCR 类一次性任务通过
            # cli_single_attempt 跳过重试，避免把弹窗等待时间翻倍。
            raw = await run_gemini_cli(
                prompt,
                model=getattr(payload, "model", "") or GEMINI_CLI_DEFAULT_CHAT_MODELS[0],
                timeout=cli_timeout,
                allow_tools=bool(image_paths),
            )
            text = str(raw.get("text") or "").strip()
        if text:
            return text, raw
        # Keep CLI diagnostics out of the conversation body while still
        # telling the user what can be retried.
        stderr = str(raw.get("_stderr") or "") if isinstance(raw, dict) else ""
        if "read_file" in stderr.lower() or "permission" in stderr.lower() or "denied" in stderr.lower():
            return "附件读取失败，Antigravity CLI 没有完成图片读取。请重新发送附件后重试。", raw
        return f"{gemini_cli_display_name()} 返回了空回复，请重试。", raw
    finally:
        for path in temp_paths:
            try:
                os.remove(path)
            except Exception:
                pass

def is_yuli_provider(provider):
    # 玉玉API（yuli.host）的视频接口走自有格式（/v1/video/create + /v1/video/query），
    # 与通用 OpenAI /v1/videos/generations 不同，需单独识别。
    base_url = str((provider or {}).get("base_url") or "").lower()
    return "yuli.host" in base_url

def is_lingjing_provider(provider):
    base_url = str((provider or {}).get("base_url") or "").lower()
    provider_id = str((provider or {}).get("id") or "").strip().lower()
    return provider_id == "lingjing" or "apistudio.vip" in base_url

def is_agnes_provider(provider, model=""):
    base_url = str((provider or {}).get("base_url") or "").lower()
    model_id = str(model or "").strip().lower()
    return "apihub.agnes-ai.com" in base_url or model_id.startswith("agnes-video-")

is_6789_provider = api6789_video.is_provider

# ---- 数字人/真人认证：平台无关分发 ----
# 认证是一个跨平台功能。每个平台用不同的资产 API 实现，但对外是统一入口。
# 新增平台时：在 avatar_platform_for_provider 里加一条识别，并把平台键加进
# AVATAR_SUPPORTED_PLATFORMS，再在 register/avatar-status 端点里补一个分发分支即可。
AVATAR_SUPPORTED_PLATFORMS = {"apimart", "volcengine"}  # 已接入官方资产 API 的平台

def avatar_platform_for_provider(provider) -> str:
    if not provider:
        return ""
    if is_apimart_provider(provider):
        return "apimart"
    if is_volcengine_provider(provider):
        return "volcengine"
    return ""

def provider_supports_avatar(provider) -> bool:
    return avatar_platform_for_provider(provider) in AVATAR_SUPPORTED_PLATFORMS

