def _publish_jimeng_file(filename, kind):
    path = Path(filename)
    if not jimeng_media.matches_kind(path, kind):
        return ""
    relative = jimeng_media.relative_output_file(path, OUTPUT_OUTPUT_DIR)
    if kind == "image":
        try:
            if relative and path.suffix.lower() == ".png":
                with Image.open(path) as image:
                    if image.format == "PNG":
                        image.verify()
                        return output_url_for(relative, "output")
            url, _ = save_generated_image_bytes(
                path.read_bytes(), prefix="jimeng_", category="output",
                fallback_extension=media_formats.image_extension(path), require_decodable=True,
            )
            return url
        except (OSError, ValueError):
            return ""

    if relative:
        return output_url_for(relative, "output")
    name = generated_output_filename(f"jimeng_{kind}_", path.suffix.lower())
    target = media_write_path(name, "output")
    with path.open("rb") as handle:
        _replace_file_durably(target, lambda destination: shutil.copyfileobj(handle, destination), binary=True)
    return output_url_for(name, "output")


async def jimeng_store_output_value(value, kind="image"):
    address = str(value or "").strip()
    if jimeng_media.managed_address(address):
        path = output_file_from_url(address)
        if not path or not jimeng_media.matches_kind(path, kind):
            return ""
        if kind != "image":
            return address
        return await asyncio.to_thread(_publish_jimeng_file, path, kind)
    if address.startswith(("http://", "https://")):
        if not jimeng_media.matches_kind(address, kind, remote=True):
            return ""
        if kind == "video":
            return await save_remote_video_to_output(address, prefix="jimeng_video_")
        if kind == "image":
            return await save_ai_image_to_output({"type": "url", "value": address}, prefix="jimeng_")
        with jimeng_media.ReferenceFiles(output_file_from_url, os.fspath) as files:
            try:
                path = await files.stage(address, "audio")
            except HTTPException:
                return address
            return await asyncio.to_thread(_publish_jimeng_file, path, kind)
    path = jimeng_media.local_file(address, wsl=jimeng_use_wsl())
    return await asyncio.to_thread(_publish_jimeng_file, path, kind) if path else ""


async def jimeng_query_result(submit_id, kind="image"):
    # CLI 只会把结果直接写进给定目录，这里提前落到 图片/视频 子目录。
    download_dir = os.path.join(OUTPUT_OUTPUT_DIR, media_paths.MEDIA_TYPE_FOLDERS.get(kind, ""))
    os.makedirs(download_dir, exist_ok=True)
    args = [
        "query_result",
        f"--submit_id={submit_id}",
        f"--download_dir={jimeng_cli_path_arg(download_dir)}",
    ]
    return await run_jimeng_cli(args, timeout=min(300, jimeng_poll_seconds() + 60))

async def jimeng_store_outputs(raw, kind="image", allow_query=True, *, queried_id=""):
    return await jimeng_results.resolve_outputs(
        raw, kind, jimeng_store_output_value,
        query=jimeng_query_result if allow_query else None, queried_id=queried_id,
    )


async def _run_jimeng_image(args, poll):
    raw = await run_jimeng_cli(args, timeout=poll + 120)
    urls = await jimeng_store_outputs(raw, "image")
    return {"type": "url", "value": urls[0]}, raw


async def generate_jimeng_provider_image(prompt, size, model, reference_images=None, provider=None):
    references = [url for ref in reference_images or () if (url := jimeng_requests.reference_url(ref))]
    poll = jimeng_poll_seconds()
    with jimeng_media.ReferenceFiles(output_file_from_url, jimeng_cli_path_arg) as files:
        paths = [await files.stage(url) for url in references[:10]]
        return await _run_jimeng_image(jimeng_requests.image_command(prompt, size, model, paths, poll), poll)


async def generate_jimeng_upscale_image(reference_images, resolution_type):
    address = next((url for ref in reference_images or () if (url := jimeng_requests.reference_url(ref))), "")
    if not address:
        raise HTTPException(400, "请先选择要放大的图片")
    poll = jimeng_poll_seconds()
    with jimeng_media.ReferenceFiles(output_file_from_url, jimeng_cli_path_arg) as files:
        path = await files.stage(address)
        return await _run_jimeng_image(jimeng_requests.upscale_command(path, resolution_type, poll), poll)


async def generate_jimeng_video(payload: CanvasVideoRequest, provider):
    poll = jimeng_poll_seconds()
    with jimeng_media.ReferenceFiles(output_file_from_url, jimeng_cli_path_arg) as files:
        args = await jimeng_requests.video_command(payload, files.stage, poll)
        raw = await run_jimeng_cli(args, timeout=poll + 180)
        urls = await jimeng_store_outputs(raw, "video")
    return {"videos": urls, "task_id": jimeng_submit_id(raw) or None, "raw": raw}


async def httpx_request_with_transient_retries(client, method, url, attempts=2, retry_delay=1.2, **kwargs):
    from multi_agent_runtime import PAID_REQUEST_SCOPE
    if str(method).upper() == "POST" and PAID_REQUEST_SCOPE.get():
        attempts = 1
    attempts = max(1, int(attempts or 1))
    last_exc = None
    retry_statuses = {502, 503, 504, 520, 522, 524}
    for attempt in range(attempts):
        try:
            response = await client.request(method, url, **kwargs)
            if response.status_code in retry_statuses and attempt + 1 < attempts:
                await asyncio.sleep(retry_delay * (attempt + 1))
                continue
            return response
        except (httpx.RemoteProtocolError, httpx.ReadError, httpx.ConnectError, httpx.ConnectTimeout, httpx.ReadTimeout, httpx.PoolTimeout) as exc:
            last_exc = exc
            if attempt + 1 >= attempts:
                raise
            print(f"[HTTPX-RETRY] {method} {url} transient error: {exc}; retry {attempt + 2}/{attempts}", flush=True)
            await asyncio.sleep(retry_delay * (attempt + 1))
    if last_exc:
        raise last_exc
    raise httpx.HTTPError(f"请求失败：{method} {url}")

async def fetch_image_task_payload(client, task_id, provider=None):
    addresses = image_task_queries.endpoints(
        provider, task_id, apimart=is_apimart_provider(provider), fallback_base=AI_BASE_URL,
    )
    headers = api_headers(provider=provider)

    async def get(address):
        return await httpx_request_with_transient_retries(client, "GET", address, attempts=3, headers=headers)

    return await image_task_queries.fetch(task_id, addresses, get)


IMAGE_TASK_UPSTREAM_CALLBACK = contextvars.ContextVar("image_task_upstream_callback", default=None)
# SoonStudio requires the client task ID used at submission to be echoed in
# ``x-studio-task-id`` while polling.  Keep it in request-local context so
# concurrent canvas tasks never leak one another's binding.
IMAGE_TASK_BINDING_ID = contextvars.ContextVar("image_task_binding_id", default="")


async def wait_for_image_task(client, task_id, provider=None):
    apimart = is_apimart_provider(provider)
    return await image_task_queries.wait(
        task_id, functools.partial(fetch_image_task_payload, client, task_id, provider),
        timeout=APIMART_IMAGE_TASK_TIMEOUT if apimart else IMAGE_TASK_TIMEOUT,
        interval=APIMART_IMAGE_POLL_INTERVAL if apimart else IMAGE_POLL_INTERVAL,
        initial_delay=APIMART_IMAGE_INITIAL_POLL_DELAY if apimart else 0,
        on_receipt=IMAGE_TASK_UPSTREAM_CALLBACK.get(),
    )


def output_storage(category="output"):
    return (OUTPUT_INPUT_DIR, "input") if category == "input" else (OUTPUT_OUTPUT_DIR, "output")

def media_type_folder_for(name):
    return media_paths.media_type_folder(name)

def media_type_rel(rel):
    return media_paths.typed_relative(rel)

def media_path_in(root, rel):
    """素材写入路径：按类型落到 图片/视频/音频 子目录，并建好父目录。"""
    return media_paths.write_path(root, rel)

def media_write_path(filename, category="output"):
    folder, _ = output_storage(category)
    return media_path_in(folder, filename)

def output_rel_from_path(path, category="output"):
    """把已落盘的绝对路径还原成相对素材目录的地址片段。"""
    folder, _ = output_storage(category)
    try:
        return os.path.relpath(os.path.abspath(str(path or "")), os.path.abspath(folder)).replace("\\", "/")
    except (OSError, TypeError, ValueError):
        return os.path.basename(str(path or ""))

def ensure_media_type_dirs(root):
    """在素材根目录（或某个素材文件夹）下建好 图片/视频/音频 子目录。"""
    base = str(root or "")
    if not base:
        return
    for folder_name in media_paths.MEDIA_TYPE_FOLDERS.values():
        try:
            os.makedirs(os.path.join(base, folder_name), exist_ok=True)
        except OSError:
            continue

def generated_output_stem(prefix="generated_"):
    """Return a human-sortable stem for newly generated media.

    Windows Explorer commonly opens the generated-media folder sorted by name.
    Putting the local generation timestamp first keeps new files in generation
    order without changing the URL/path compatibility of existing files.
    """
    safe_prefix = str(prefix or "generated_")
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    return f"{timestamp}_{safe_prefix}{uuid.uuid4().hex[:10]}"

def generated_output_filename(prefix="generated_", extension=".png", suffix=""):
    extension = str(extension or "")
    if extension and not extension.startswith("."):
        extension = f".{extension}"
    return f"{generated_output_stem(prefix)}{str(suffix or '')}{extension}"

def output_url_for(filename, category="output"):
    folder, _ = output_storage(category)
    return media_paths.output_url(folder, ASSETS_DIR, filename, category)


def output_path_for(filename, category="output"):
    folder, _ = output_storage(category)
    relative = str(filename or "").replace("\\", "/").lstrip("/")
    if not relative:
        return folder
    direct = media_paths.path_under(folder, relative)
    if direct and os.path.exists(direct):
        return direct
    path = media_paths.path_under(folder, media_paths.typed_relative(relative))
    if path is None:
        raise ValueError("生成文件路径不在存储目录内")
    return path


def storage_kind_dir(kind):
    bucket = asset_kernel.storage_bucket(kind)
    if bucket.get("error"):
        raise HTTPException(status_code=int(bucket.get("status") or 404), detail=bucket["error"])
    kind = bucket["bucket"]
    kind = str(kind or "").strip().lower()
    if kind == "upload":
        return os.path.abspath(OUTPUT_INPUT_DIR)
    if kind == "generated":
        return os.path.abspath(OUTPUT_OUTPUT_DIR)
    if kind == "local":
        return os.path.abspath(LOCAL_UPLOAD_DIR)
    raise HTTPException(status_code=404, detail="未知存储目录")


def storage_kind_roots(kind):
    current = storage_kind_dir(kind)
    settings = load_storage_settings()
    key = str(kind or "").strip().lower()
    roots = [current, *((settings.get("legacy_roots") or {}).get(key) or [])]
    legacy = (settings.get("legacy_dirs") or {}).get(key)
    if legacy:
        roots.append(legacy)
    unique = {}
    for root in roots:
        unique.setdefault(storage_migration.path_key(root), root)
    return list(unique.values())


def storage_file_path(kind, rel, *, allow_alias=False):
    bucket = asset_kernel.storage_bucket(kind)
    if bucket.get("error"):
        raise HTTPException(status_code=int(bucket.get("status") or 404), detail=bucket["error"])
    checked = asset_kernel.relative_path(rel)
    if checked.get("error") or not checked.get("rel"):
        raise HTTPException(status_code=400, detail="非法文件路径")
    roots = storage_kind_roots(bucket["bucket"])
    relative = checked["rel"]
    # 旧地址是平铺相对路径，新素材带 图片/视频/音频 子目录；两种写法都能读到。
    path = media_paths.first_file(roots, relative)
    if not path:
        typed = media_paths.typed_relative(relative)
        if typed != relative:
            path = media_paths.first_file(roots, typed)
    if path or not allow_alias or bucket["bucket"] != "local":
        return path
    record = ASSET_REGISTRY.find_by_url(_local_upload_media_url(relative), include_deleted=False)
    target = media_paths.parse_address((record or {}).get("canonical_url"))
    if target and target[0] == "local" and target[1] != relative:
        return media_paths.first_file(roots, target[1])
    return None


def _resolve_local_media_address(value, *, allow_loopback):
    parsed = media_paths.parse_address(value, allow_loopback=allow_loopback)
    if parsed is None:
        return None
    kind, relative = parsed
    if kind == "/assets":
        return media_paths.first_file((ASSETS_DIR,), relative)
    if kind == "/output":
        return media_paths.first_file((OUTPUT_OUTPUT_DIR, OUTPUT_DIR), relative)
    return storage_file_path(kind, relative, allow_alias=True)


def output_file_from_url(url):
    return _resolve_local_media_address(url, allow_loopback=True)


image_has_alpha = media_formats.has_alpha
GENERATED_IMAGE_EXTENSIONS = media_formats.IMAGE_EXTENSIONS


def image_fallback_extension(value="", content_type=""):
    return media_formats.image_extension(value, content_type)


def _write_generated_snapshot(content, filename, category, *, deduplicate):
    folder, _ = output_storage(category)
    path = media_paths.write_path(folder, filename)
    stored = media_storage.write_media_snapshot(path, content, deduplicate=deduplicate)
    url = media_paths.output_url(folder, ASSETS_DIR, output_rel_from_path(stored, category), category)
    return url, stored


def save_generated_image_bytes(content, prefix="generated_", category="output", fallback_extension=".png", deduplicate=True, *, require_decodable=False):
    extension, payload = media_formats.image_snapshot(content, fallback_extension, require_decodable=require_decodable)
    filename = generated_output_filename(prefix, extension)
    return _write_generated_snapshot(payload, filename, category, deduplicate=deduplicate)


def save_generated_image_file(source_path, prefix="generated_", category="output", deduplicate=True):
    """Copy a generated image into storage while normalizing it to PNG."""
    with open(source_path, "rb") as source_file:
        content = source_file.read()
    return save_generated_image_bytes(
        content,
        prefix=prefix,
        category=category,
        fallback_extension=image_fallback_extension(source_path),
        deduplicate=deduplicate,
    )


# 参考图上传本身仍保持 50MiB 的保护上限；超过时只生成内存中的上传副本，
# 不会改写用户在桌面、素材库或外部磁盘中的原始文件。
AI_REFERENCE_UPLOAD_MAX_BYTES = 50 * 1024 * 1024

def _auto_compress_oversize_reference_image(content, original_name="", max_bytes=AI_REFERENCE_UPLOAD_MAX_BYTES):
    """将超限静态图片压成受控的上传副本。

    透明 PNG/WebP 始终输出 PNG 以保留透明通道；普通 PNG 也保留为 PNG，避免
    图文素材被 JPEG 有损压缩。非透明照片则输出高质量 JPEG。返回
    ``(result, reason)``，其中 result 为 None 表示不能安全地自动处理。
    """
    original_bytes = len(content or b"")
    max_bytes = max(1, int(max_bytes or AI_REFERENCE_UPLOAD_MAX_BYTES))
    if original_bytes <= max_bytes:
        return None, ""

    # 给 multipart 写入和后续平台留出一点余量，避免刚好卡在上限边缘。
    target_bytes = max(256 * 1024, max_bytes - min(2 * 1024 * 1024, max(256 * 1024, max_bytes // 25)))
    image = None
    try:
        with Image.open(BytesIO(content)) as source:
            if getattr(source, "is_animated", False):
                return None, "为保留动画内容，动态 GIF/WebP 不会自动转码"
            source.load()
            source_format = str(source.format or "").upper()
            icc_profile = source.info.get("icc_profile")
            oriented = ImageOps.exif_transpose(source)
            try:
                has_alpha = image_has_alpha(oriented)
                preserve_png = has_alpha or source_format == "PNG"
                image = oriented.convert("RGBA" if has_alpha else "RGB")
            finally:
                if oriented is not source:
                    oriented.close()
    except Exception as exc:
        print(f"参考图自动压缩失败：{os.path.basename(str(original_name or 'image'))} ({exc})")
        return None, "图片无法被安全读取"

    try:
        output_format = "PNG" if preserve_png else "JPEG"
        output_extension = ".png" if output_format == "PNG" else ".jpg"
        output_mime = "image/png" if output_format == "PNG" else "image/jpeg"
        resample = getattr(Image, "Resampling", Image).LANCZOS
        scale = 0.90

        for _ in range(8):
            width = max(1, round(image.width * scale))
            height = max(1, round(image.height * scale))
            working = image.resize((width, height), resample) if (width, height) != image.size else image.copy()
            try:
                best_candidate = None
                qualities = (92, 88, 84) if output_format == "JPEG" else (None,)
                for quality in qualities:
                    buffer = BytesIO()
                    save_kwargs = {"format": output_format, "optimize": True}
                    if icc_profile:
                        save_kwargs["icc_profile"] = icc_profile
                    if output_format == "JPEG":
                        working.save(buffer, quality=quality, progressive=True, **save_kwargs)
                    else:
                        working.save(buffer, compress_level=9, **save_kwargs)
                    candidate = buffer.getvalue()
                    if len(candidate) <= max_bytes:
                        return {
                            "content": candidate,
                            "extension": output_extension,
                            "content_type": output_mime,
                            "original_bytes": original_bytes,
                            "uploaded_bytes": len(candidate),
                            "width": width,
                            "height": height,
                        }, ""
                    if best_candidate is None or len(candidate) < len(best_candidate):
                        best_candidate = candidate
            finally:
                working.close()

            if not best_candidate or scale <= 0.05:
                break
            ratio = math.sqrt(target_bytes / max(1, len(best_candidate)))
            factor = max(0.35, min(0.82, ratio * 0.94))
            next_scale = max(0.05, scale * factor)
            if next_scale >= scale:
                next_scale = max(0.05, scale * 0.75)
            if abs(next_scale - scale) < 0.001:
                break
            scale = next_scale
    except Exception as exc:
        print(f"参考图自动压缩失败：{os.path.basename(str(original_name or 'image'))} ({exc})")
        return None, "图片压缩过程失败"
    finally:
        if image is not None:
            try:
                image.close()
            except Exception:
                pass

    limit_mb = max_bytes / (1024 * 1024)
    return None, f"自动压缩后仍无法降至 {limit_mb:.0f}MB 以内"

def _compressed_reference_upload_name(filename, extension):
    base = os.path.splitext(os.path.basename(str(filename or "image")))[0].strip() or "image"
    return f"{base}-上传版{extension}"

def _auto_compressed_reference_upload_meta(result, original_name=""):
    return {
        "original_name": os.path.basename(str(original_name or "")),
        "original_bytes": int(result.get("original_bytes") or 0),
        "uploaded_bytes": int(result.get("uploaded_bytes") or 0),
        "width": int(result.get("width") or 0),
        "height": int(result.get("height") or 0),
    }

def _image_size_metadata_from_bytes(content):
    """读取上传图片的显示尺寸，不解码整张图片。"""
    try:
        from svg_media import generated_svg_meta
        svg_meta = generated_svg_meta(content or b"")
        if svg_meta:
            return {**svg_meta, "width": svg_meta["natural_w"], "height": svg_meta["natural_h"]}
        with Image.open(BytesIO(content or b"")) as source:
            width, height = int(source.width or 0), int(source.height or 0)
            try:
                orientation = int(source.getexif().get(274, 1) or 1)
            except Exception:
                orientation = 1
        if orientation in {5, 6, 7, 8}:
            width, height = height, width
        if width <= 0 or height <= 0:
            return {}
        return {
            "natural_w": width,
            "natural_h": height,
            "width": width,
            "height": height,
        }
    except Exception:
        return {}

STORAGE_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".bmp", ".avif"}
STORAGE_VIDEO_EXTS = {".mp4", ".webm", ".mov", ".m4v", ".avi", ".mkv", ".flv"}
STORAGE_AUDIO_EXTS = {".mp3", ".wav", ".flac", ".ogg", ".m4a", ".aac"}
STORAGE_MEDIA_EXTS = STORAGE_IMAGE_EXTS | STORAGE_VIDEO_EXTS | STORAGE_AUDIO_EXTS

def storage_file_item(kind, root, path, include_dimensions=True, register_asset=True, registry_record=None):
    rel = os.path.relpath(path, root).replace("\\", "/")
    try:
        stat = os.stat(path)
    except OSError:
        return None
    item = {
        "id": f"{kind}:{rel}",
        "kind": kind,
        "rel": rel,
        "name": os.path.basename(path),
        "folder": os.path.dirname(rel).replace("\\", "/"),
        "url": f"/api/storage-files/{kind}/{urllib.parse.quote(rel, safe='/')}",
        "size": stat.st_size,
        "created_at": stat.st_mtime,
    }
    if include_dimensions and kind in {"upload", "generated"}:
        caption_path = path + ".caption.txt"
        if os.path.isfile(caption_path):
            try:
                with open(caption_path, encoding="utf-8-sig") as handle:
                    item["caption"] = handle.read()
            except OSError:
                pass
    if include_dimensions:
        try:
            if os.path.splitext(path)[1].lower() == ".svg":
                from svg_media import generated_svg_meta
                with open(path, "rb") as stream:
                    svg_meta = generated_svg_meta(stream.read())
                if svg_meta:
                    item["width"], item["height"] = svg_meta["natural_w"], svg_meta["natural_h"]
            else:
                with Image.open(path) as img:
                    item["width"], item["height"] = img.size
        except Exception:
            pass
    source = "generated" if kind == "generated" else ("upload" if kind == "upload" else "local_upload")
    record = registry_record
    if register_asset and record is None:
        record = asset_registry_register_media(
            item["url"],
            name=item["name"],
            kind=asset_library_media_kind(path),
            source=source,
            created_at=item["created_at"],
        )
    if record and registry_is_asset_id(record.get("id")):
        item["asset_id"] = record["id"]
        if kind == "upload":
            metadata = record.get("metadata") or {}
            item["name"] = metadata.get("upload_name") or item["name"]
            item["upload_project_id"] = metadata.get("upload_project_id") or ""
            item["upload_canvas_id"] = metadata.get("upload_canvas_id") or ""
    return item


_UPLOAD_CANVAS_CACHE = {}
_UPLOAD_CANVAS_CACHE_LOCK = RLock()


def upload_media_key(url):
    """Match current upload URLs and the aliases saved before directory migration."""
    text = str(url or "").replace("\\", "/")
    parsed = urllib.parse.urlsplit(text)
    if parsed.netloc and parsed.hostname not in {"localhost", "127.0.0.1", "::1"}:
        return ""
    path = urllib.parse.unquote(parsed.path)
    for prefix in ("/api/storage-files/upload/", "/assets/input/", "/output/input/", "/input/"):
        if path.startswith(prefix):
            rel = os.path.normpath(path[len(prefix):]).replace("\\", "/")
            if rel not in {"", ".", ".."} and not rel.startswith("../") and not os.path.isabs(rel):
                return os.path.normcase(rel)
    return ""


def upload_canvas_index():
    """Read project membership without indexing, moving or rewriting user media."""
    projects = [project_record(p) for p in load_projects() if not p.get("deleted_at")]
    if not any(p["id"] == DEFAULT_PROJECT_ID for p in projects):
        projects.insert(0, {"id": DEFAULT_PROJECT_ID, "name": "默认项目", "order": 0})
    projects.sort(key=lambda p: (p.get("order", 0), p.get("created_at", 0)))
    project_ids = {str(p["id"]) for p in projects}
    canvases = []
    by_file = {}
    with _UPLOAD_CANVAS_CACHE_LOCK:
        present = set()
        for filename in os.listdir(CANVAS_DIR) if os.path.isdir(CANVAS_DIR) else []:
            if not filename.endswith(".json") or filename.startswith("."):
                continue
            path = os.path.join(CANVAS_DIR, filename)
            present.add(path)
            try:
                stat = os.stat(path)
                stamp = (stat.st_mtime_ns, stat.st_size)
                cached = _UPLOAD_CANVAS_CACHE.get(path)
                if not cached or cached[0] != stamp:
                    with open(path, encoding="utf-8-sig") as handle:
                        canvas = json.load(handle)
                    if not isinstance(canvas, dict):
                        continue
                    record = canvas_record(canvas)
                    keys = {upload_media_key(url) for _, _, url in canvas_media.walk(canvas.get("nodes") or [])}
                    cached = (stamp, record, keys - {""})
                    _UPLOAD_CANVAS_CACHE[path] = cached
                _, record, keys = cached
                if record.get("deleted_at") or record.get("project") not in project_ids:
                    continue
                canvases.append(record)
                ref = {"project_id": record["project"], "canvas_id": record["id"], "canvas_title": record["title"]}
                for key in keys:
                    by_file.setdefault(key, []).append(ref)
            except (OSError, ValueError, TypeError):
                continue
        for path in set(_UPLOAD_CANVAS_CACHE) - present:
            _UPLOAD_CANVAS_CACHE.pop(path, None)
    return {"projects": projects, "canvases": canvases, "by_file": by_file}


def upload_registry_records():
    """Return saved upload metadata once per directory listing.

    Upload folders can contain thousands of files; looking up the registry for
    every file would turn a read-only listing into thousands of JSON writes.
    """
    records = {}
    try:
        for record in ASSET_REGISTRY.records():
            key = upload_media_key(record.get("canonical_url") or record.get("url"))
            if key:
                records[key] = record
    except Exception:
        return {}
    return records


def prepare_upload_scopes(items, index):
    projects = {str(p["id"]): dict(p, count=0) for p in index["projects"]}
    canvases = {str(c["id"]): dict(c, count=0) for c in index["canvases"]}
    unassigned = 0
    for item in items:
        refs = list(index["by_file"].get(upload_media_key(item["url"]), []))
        assigned_canvas = canvases.get(item.get("upload_canvas_id"))
        assigned_project = assigned_canvas.get("project") if assigned_canvas else item.get("upload_project_id")
        if assigned_project in projects:
            ref = {"project_id": assigned_project, "canvas_id": assigned_canvas["id"] if assigned_canvas else "", "canvas_title": assigned_canvas["title"] if assigned_canvas else ""}
            if ref not in refs:
                refs.append(ref)
        item["references"] = refs
        item["project_ids"] = sorted({ref["project_id"] for ref in refs})
        item["canvas_ids"] = sorted({ref["canvas_id"] for ref in refs if ref["canvas_id"]})
        for project_id in item["project_ids"]:
            projects[project_id]["count"] += 1
        for canvas_id in item["canvas_ids"]:
            canvases[canvas_id]["count"] += 1
        if not item["project_ids"]:
            unassigned += 1
    return {"projects": list(projects.values()), "canvases": list(canvases.values()), "unassigned_count": unassigned}

