async def background_removal_model_catalog(force=False, include_remote=False):
    now = time.time()
    if not force and BACKGROUND_REMOVAL_CATALOG_CACHE.get("expires_at", 0) > now:
        return list(BACKGROUND_REMOVAL_CATALOG_CACHE.get("models") or [])
    models = []
    for raw in _background_removal_builtin_catalog():
        model = _background_removal_model_from_catalog_item(raw)
        if model:
            models.append(model)
    # 远程目录只用于补充旧版 BEN2 等模型；默认 RMBG-2.0 不依赖网络目录。
    if include_remote and BACKGROUND_REMOVAL_MODEL_CATALOG_URL:
        try:
            async with httpx.AsyncClient(timeout=12, follow_redirects=True) as client:
                response = await client.get(
                    BACKGROUND_REMOVAL_MODEL_CATALOG_URL,
                    headers={"Accept": "application/json"},
                )
            if response.status_code >= 400:
                raise RuntimeError(f"模型目录连接失败（HTTP {response.status_code}）")
            body = response.json()
            raw_models = body.get("models") if isinstance(body, dict) else []
            known_ids = {item.get("id") for item in models}
            for raw in raw_models or []:
                model = _background_removal_model_from_catalog_item(raw)
                if model and model.get("id") not in known_ids:
                    models.append(model)
                    known_ids.add(model.get("id"))
        except Exception as exc:
            # 内置模型可离线使用，远程目录失败不应阻断默认模型。
            print(f"本地抠图扩展模型目录暂不可用：{exc}")
    if not models:
        raise RuntimeError("没有可用的本地抠图模型")
    BACKGROUND_REMOVAL_CATALOG_CACHE["expires_at"] = now + 5 * 60
    BACKGROUND_REMOVAL_CATALOG_CACHE["models"] = models
    return list(models)


async def background_removal_model_definition(model_id=BACKGROUND_REMOVAL_MODEL_ID, force=False):
    requested = str(model_id or "").strip().lower()
    if requested in {AIARTY_BACKGROUND_REMOVAL_MODEL_ID, "solidmat", "solidmat-v2"}:
        requested = BACKGROUND_REMOVAL_MODEL_ID
    elif requested in {"birefnet", "birefnet-general-lite"}:
        requested = BACKGROUND_REMOVAL_FALLBACK_MODEL_ID
    elif requested == "ben2":
        requested = BACKGROUND_REMOVAL_LEGACY_MODEL_ID
    supported_ids = {
        BACKGROUND_REMOVAL_MODEL_ID,
        BACKGROUND_REMOVAL_FALLBACK_MODEL_ID,
        BACKGROUND_REMOVAL_LEGACY_MODEL_ID,
    }
    if requested not in supported_ids:
        raise RuntimeError("不支持的本地抠图模型")
    models = await background_removal_model_catalog(force=force, include_remote=requested == BACKGROUND_REMOVAL_LEGACY_MODEL_ID)
    model = next((item for item in models if item.get("id") == requested), None)
    if not model:
        raise RuntimeError(f"模型目录未提供 {requested}")
    return model


def _background_removal_model_paths(model):
    filename = str(model.get("filename") or "")
    if not filename or os.path.basename(filename) != filename:
        raise RuntimeError("模型文件名非法")
    os.makedirs(BACKGROUND_REMOVAL_MODEL_DIR, exist_ok=True)
    path = os.path.abspath(os.path.join(BACKGROUND_REMOVAL_MODEL_DIR, filename))
    root = os.path.abspath(BACKGROUND_REMOVAL_MODEL_DIR)
    if os.path.commonpath([root, path]) != root:
        raise RuntimeError("模型路径非法")
    return path, f"{path}.json"


def _background_removal_local_model_path(model):
    try:
        path, metadata_path = _background_removal_model_paths(model)
        if not os.path.isfile(path) or os.path.getsize(path) != int(model.get("size") or 0):
            return ""
        with open(metadata_path, "r", encoding="utf-8") as handle:
            metadata = json.load(handle)
        if (
            metadata.get("version") != model.get("version")
            or str(metadata.get("sha256") or "").lower() != str(model.get("sha256") or "").lower()
            or int(metadata.get("size") or 0) != int(model.get("size") or 0)
        ):
            return ""
        return path
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return ""


def _background_removal_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _background_removal_public_state(model, downloaded=False):
    state = BACKGROUND_REMOVAL_DOWNLOADS.get(model.get("id"), {})
    status = str(state.get("status") or ("downloaded" if downloaded else "not_downloaded"))
    if downloaded:
        status = "downloaded"
    return {
        "id": model.get("id"),
        "name": model.get("name"),
        "version": model.get("version"),
        "size": int(model.get("size") or 0),
        "downloaded": bool(downloaded),
        "downloading": status == "downloading",
        "status": status,
        "downloaded_bytes": int(state.get("downloaded_bytes") or (model.get("size") if downloaded else 0)),
        "total_bytes": int(state.get("total_bytes") or model.get("size") or 0),
        "error": str(state.get("error") or "")[:500],
        "available": True,
        "backend": "onnx",
        "license": str(model.get("license") or "")[:120],
        "source_url": str(model.get("source_url") or "")[:500],
    }


async def _download_background_removal_model(model, state):
    model_id = model.get("id")
    partial = ""
    try:
        path, metadata_path = _background_removal_model_paths(model)
        existing = await asyncio.to_thread(_background_removal_local_model_path, model)
        if existing:
            state.update({"status": "downloaded", "downloaded_bytes": model.get("size", 0), "error": ""})
            return
        partial = f"{path}.download"
        state.update({"status": "downloading", "downloaded_bytes": 0, "error": ""})
        timeout = httpx.Timeout(connect=20, read=60, write=60, pool=20)
        async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
            async with client.stream("GET", model.get("download_url"), headers={"Accept": "application/octet-stream"}) as response:
                if response.status_code >= 400:
                    raise RuntimeError(f"{model.get('name') or model_id} 下载失败（HTTP {response.status_code}）")
                with open(partial, "wb") as handle:
                    async for chunk in response.aiter_bytes(1024 * 1024):
                        if not chunk:
                            continue
                        handle.write(chunk)
                        state["downloaded_bytes"] = int(state.get("downloaded_bytes") or 0) + len(chunk)
        actual_size = os.path.getsize(partial)
        expected_size = int(model.get("size") or 0)
        if actual_size != expected_size:
            raise RuntimeError(f"{model.get('name') or model_id} 下载不完整（{actual_size} / {expected_size} 字节）")
        actual_hash = await asyncio.to_thread(_background_removal_sha256, partial)
        if actual_hash.lower() != str(model.get("sha256") or "").lower():
            raise RuntimeError(f"{model.get('name') or model_id} 文件校验失败，未使用不完整文件")
        os.replace(partial, path)
        metadata_tmp = f"{metadata_path}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
        try:
            with open(metadata_tmp, "w", encoding="utf-8") as handle:
                json.dump({"version": model.get("version"), "sha256": model.get("sha256"), "size": expected_size}, handle, ensure_ascii=False)
            os.replace(metadata_tmp, metadata_path)
        finally:
            if os.path.exists(metadata_tmp):
                try:
                    os.remove(metadata_tmp)
                except OSError:
                    pass
        state.update({"status": "downloaded", "downloaded_bytes": expected_size, "error": ""})
    except Exception as exc:
        if partial and os.path.exists(partial):
            try:
                os.remove(partial)
            except OSError:
                pass
        state.update({"status": "failed", "error": str(exc)[:500]})
    finally:
        state["task"] = None


def _local_upscale_path(*parts):
    root = os.path.abspath(LOCAL_UPSCALE_MODEL_DIR)
    path = os.path.abspath(os.path.join(root, *[str(part) for part in parts]))
    try:
        if os.path.commonpath([root, path]) != root:
            raise RuntimeError("高清模型路径越界")
    except ValueError as exc:
        raise RuntimeError("高清模型路径非法") from exc
    return path


def _local_upscale_realesrgan_paths():
    package = LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE
    install_dir = _local_upscale_path(package["install_dir"])
    return {
        "archive": _local_upscale_path(package["archive_name"]),
        "install_dir": install_dir,
        "executable": os.path.join(install_dir, "realesrgan-ncnn-vulkan.exe"),
        "metadata": os.path.join(install_dir, ".xiaomei-install.json"),
    }


def _local_upscale_realesrgan_override():
    value = os.path.abspath(os.path.expandvars(str(os.getenv("XIAOMEI_REALESRGAN_BIN", "")).strip())) if str(os.getenv("XIAOMEI_REALESRGAN_BIN", "")).strip() else ""
    return value if value and os.path.isfile(value) else ""


def _local_upscale_realesrgan_executable():
    override = _local_upscale_realesrgan_override()
    if override:
        return override
    package = LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE
    paths = _local_upscale_realesrgan_paths()
    try:
        with open(paths["metadata"], "r", encoding="utf-8") as handle:
            metadata = json.load(handle)
        if (
            metadata.get("version") != package.get("version")
            or metadata.get("sha256") != package.get("sha256")
            or int(metadata.get("size") or 0) != int(package.get("size") or 0)
        ):
            return ""
        for relative, expected_size in (package.get("required_files") or {}).items():
            candidate = os.path.abspath(os.path.join(paths["install_dir"], *str(relative).split("/")))
            if os.path.commonpath([paths["install_dir"], candidate]) != paths["install_dir"]:
                return ""
            if not os.path.isfile(candidate) or os.path.getsize(candidate) != int(expected_size):
                return ""
        return paths["executable"]
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return ""


def _local_upscale_validate_realesrgan_archive(path):
    package = LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE
    if not os.path.isfile(path) or os.path.getsize(path) != int(package["size"]):
        return False
    return _background_removal_sha256(path).lower() == str(package["sha256"]).lower()


def _local_upscale_safe_rmtree(path):
    root = os.path.abspath(LOCAL_UPSCALE_MODEL_DIR)
    target = os.path.abspath(str(path or ""))
    if not target or target == root or os.path.commonpath([root, target]) != root:
        raise RuntimeError("拒绝清理越界的高清模型目录")
    if os.path.isdir(target):
        shutil.rmtree(target)


def _local_upscale_extract_realesrgan(archive_path):
    package = LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE
    paths = _local_upscale_realesrgan_paths()
    os.makedirs(LOCAL_UPSCALE_MODEL_DIR, exist_ok=True)
    staging = _local_upscale_path(f".{package['install_dir']}.installing-{uuid.uuid4().hex}")
    backup = _local_upscale_path(f".{package['install_dir']}.previous-{uuid.uuid4().hex}")
    os.makedirs(staging, exist_ok=False)
    installed = False
    try:
        staging_root = os.path.abspath(staging)
        with zipfile.ZipFile(archive_path) as archive:
            for entry in archive.infolist():
                name = str(entry.filename or "").replace("\\", "/")
                parts = [part for part in name.split("/") if part not in {"", "."}]
                if not parts:
                    continue
                if name.startswith("/") or re.match(r"^[A-Za-z]:", name) or ".." in parts:
                    raise RuntimeError("Real-ESRGAN 压缩包包含非法路径")
                if ((entry.external_attr >> 16) & 0o170000) == 0o120000:
                    raise RuntimeError("Real-ESRGAN 压缩包包含不支持的符号链接")
                target = os.path.abspath(os.path.join(staging_root, *parts))
                if os.path.commonpath([staging_root, target]) != staging_root:
                    raise RuntimeError("Real-ESRGAN 解压路径越界")
                if entry.is_dir():
                    os.makedirs(target, exist_ok=True)
                    continue
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with archive.open(entry, "r") as source, open(target, "wb") as output:
                    shutil.copyfileobj(source, output, length=1024 * 1024)

        for relative, expected_size in (package.get("required_files") or {}).items():
            candidate = os.path.abspath(os.path.join(staging, *str(relative).split("/")))
            if os.path.commonpath([staging, candidate]) != staging:
                raise RuntimeError("Real-ESRGAN 必需文件路径越界")
            if not os.path.isfile(candidate) or os.path.getsize(candidate) != int(expected_size):
                raise RuntimeError(f"Real-ESRGAN 安装包缺少必需文件：{relative}")

        with open(os.path.join(staging, ".xiaomei-install.json"), "w", encoding="utf-8") as handle:
            json.dump({
                "version": package["version"],
                "sha256": package["sha256"],
                "size": package["size"],
                "source_url": package["source_url"],
                "installed_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            }, handle, ensure_ascii=False, indent=2)

        if os.path.isdir(paths["install_dir"]):
            os.replace(paths["install_dir"], backup)
        try:
            os.replace(staging, paths["install_dir"])
            installed = True
        except Exception:
            if os.path.isdir(backup) and not os.path.exists(paths["install_dir"]):
                os.replace(backup, paths["install_dir"])
            raise
        if os.path.isdir(backup):
            _local_upscale_safe_rmtree(backup)
    finally:
        if os.path.isdir(staging):
            _local_upscale_safe_rmtree(staging)
        if installed and os.path.isdir(backup):
            _local_upscale_safe_rmtree(backup)


async def _download_local_upscale_realesrgan(state):
    package = LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE
    paths = _local_upscale_realesrgan_paths()
    partial = f"{paths['archive']}.download"
    try:
        existing = await asyncio.to_thread(_local_upscale_realesrgan_executable)
        if existing:
            state.update({"status": "downloaded", "phase": "ready", "downloaded_bytes": package["size"], "error": ""})
            return
        os.makedirs(LOCAL_UPSCALE_MODEL_DIR, exist_ok=True)
        archive_ready = await asyncio.to_thread(_local_upscale_validate_realesrgan_archive, paths["archive"])
        if not archive_ready:
            if os.path.exists(paths["archive"]):
                os.remove(paths["archive"])
            if os.path.exists(partial):
                os.remove(partial)
            state.update({"status": "downloading", "phase": "downloading", "downloaded_bytes": 0, "error": ""})
            timeout = httpx.Timeout(connect=20, read=90, write=60, pool=20)
            async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
                async with client.stream("GET", package["download_url"], headers={"Accept": "application/octet-stream"}) as response:
                    if response.status_code >= 400:
                        raise RuntimeError(f"Real-ESRGAN 下载失败（HTTP {response.status_code}）")
                    with open(partial, "wb") as handle:
                        async for chunk in response.aiter_bytes(1024 * 1024):
                            if not chunk:
                                continue
                            handle.write(chunk)
                            state["downloaded_bytes"] = int(state.get("downloaded_bytes") or 0) + len(chunk)
            actual_size = os.path.getsize(partial)
            if actual_size != int(package["size"]):
                raise RuntimeError(f"Real-ESRGAN 下载不完整（{actual_size} / {package['size']} 字节）")
            actual_hash = await asyncio.to_thread(_background_removal_sha256, partial)
            if actual_hash.lower() != str(package["sha256"]).lower():
                raise RuntimeError("Real-ESRGAN 文件校验失败，未安装不完整文件")
            os.replace(partial, paths["archive"])
        else:
            state["downloaded_bytes"] = int(package["size"])

        state.update({"status": "downloading", "phase": "installing", "error": ""})
        await asyncio.to_thread(_local_upscale_extract_realesrgan, paths["archive"])
        executable = await asyncio.to_thread(_local_upscale_realesrgan_executable)
        if not executable:
            raise RuntimeError("Real-ESRGAN 已解压，但完整性检查未通过")
        if os.path.exists(paths["archive"]):
            os.remove(paths["archive"])
        state.update({"status": "downloaded", "phase": "ready", "downloaded_bytes": package["size"], "error": ""})
    except Exception as exc:
        if os.path.exists(partial):
            try:
                os.remove(partial)
            except OSError:
                pass
        state.update({"status": "failed", "phase": "failed", "error": str(exc)[:500]})
    finally:
        state["task"] = None


def _local_upscale_comfy_choices(node_info, input_name):
    try:
        spec = ((node_info.get("input") or {}).get("required") or {}).get(input_name) or []
        values = spec[0] if isinstance(spec, list) and spec else []
        if values == "COMBO" and isinstance(spec, list) and len(spec) > 1 and isinstance(spec[1], dict):
            values = spec[1].get("options") or spec[1].get("values") or []
        return [str(item) for item in values if str(item).strip()] if isinstance(values, list) else []
    except (AttributeError, TypeError):
        return []


def _local_upscale_comfy_capabilities(force=False):
    now = time.time()
    cached = LOCAL_UPSCALE_COMFY_CACHE.get("value")
    if not force and cached is not None and float(LOCAL_UPSCALE_COMFY_CACHE.get("expires_at") or 0) > now:
        return cached
    capabilities = {
        "swinir": {"ready": False, "address": "", "models": [], "message": "未检测到运行中的 ComfyUI 或 SwinIR 权重"},
        "seedvr2": {
            "ready": False,
            "address": "",
            "node": "",
            "workflow": "seedvr2-official-upscale.json",
            "dit_model": "",
            "vae_model": "",
            "message": "未检测到运行中的 ComfyUI 或 SeedVR2 3B FP8 权重",
        },
    }
    details = []
    for address in COMFYUI_INSTANCES:
        base_url = f"http://{address}"
        try:
            response = requests.get(f"{base_url}/object_info", timeout=3.5)
            if response.status_code != 200:
                details.append(f"{address} 返回 HTTP {response.status_code}")
                continue
            object_info = response.json()
            if not isinstance(object_info, dict):
                details.append(f"{address} 节点信息不可读")
                continue
        except (ValueError, requests.RequestException) as exc:
            details.append(f"{address} 未启动（{str(exc)[:120]}）")
            continue

        if not capabilities["swinir"]["ready"]:
            loader = object_info.get("UpscaleModelLoader") or {}
            has_upscaler = isinstance(object_info.get("ImageUpscaleWithModel"), dict)
            models = [name for name in _local_upscale_comfy_choices(loader, "model_name") if "swinir" in name.lower()]
            if has_upscaler and models:
                capabilities["swinir"] = {
                    "ready": True,
                    "address": address,
                    "models": models,
                    "message": f"ComfyUI {address} 已就绪",
                }

        if not capabilities["seedvr2"]["ready"]:
            official_node = object_info.get("SeedVR2") or {}
            official_models = _local_upscale_comfy_choices(official_node, "model")
            official_model = next(
                (
                    name
                    for name in official_models
                    if str(name).strip().lower() == "seedvr2_ema_3b_fp8_e4m3fn.safetensors"
                ),
                "",
            )
            official_helpers_ready = all(
                isinstance(object_info.get(node_name), dict)
                for node_name in ("SeedVR2ExtraArgs", "SeedVR2BlockSwap")
            )
            if isinstance(official_node, dict) and official_model and official_helpers_ready:
                capabilities["seedvr2"] = {
                    "ready": True,
                    "address": address,
                    "node": "official",
                    "workflow": "seedvr2-official-upscale.json",
                    "dit_model": official_model,
                    "vae_model": "ema_vae_fp16.safetensors",
                    "models": official_models,
                    "message": f"ComfyUI {address} · SeedVR2 3B FP8 已就绪",
                }
            else:
                dit_loader = object_info.get("SeedVR2LoadDiTModel") or {}
                vae_loader = object_info.get("SeedVR2LoadVAEModel") or {}
                has_upscaler = isinstance(object_info.get("SeedVR2VideoUpscaler"), dict)
                dit_models = _local_upscale_comfy_choices(dit_loader, "model")
                vae_models = _local_upscale_comfy_choices(vae_loader, "model")
                fp8_models = [name for name in dit_models if all(token in name.lower() for token in ("seedvr2", "3b", "fp8"))]
                vae_model = next((name for name in vae_models if "vae" in name.lower() and "fp16" in name.lower()), "")
                if has_upscaler and fp8_models and vae_model:
                    capabilities["seedvr2"] = {
                        "ready": True,
                        "address": address,
                        "node": "legacy",
                        "workflow": "upscale.json",
                        "dit_model": fp8_models[0],
                        "vae_model": vae_model,
                        "message": f"ComfyUI {address} · SeedVR2 旧版节点已就绪",
                    }

    detail = "；".join(details)
    if detail:
        for key in ("swinir", "seedvr2"):
            if not capabilities[key]["ready"]:
                capabilities[key]["message"] = detail[:500]
    LOCAL_UPSCALE_COMFY_CACHE["value"] = capabilities
    LOCAL_UPSCALE_COMFY_CACHE["expires_at"] = now + 5
    return capabilities


def _local_upscale_realesrgan_state():
    package = LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE
    state = LOCAL_UPSCALE_DOWNLOADS.get(LOCAL_UPSCALE_REAL_ESRGAN_ID, {})
    executable = _local_upscale_realesrgan_executable()
    supported = os.name == "nt" or bool(_local_upscale_realesrgan_override())
    status = str(state.get("status") or ("downloaded" if executable else "not_downloaded"))
    if executable:
        status = "downloaded"
    message = "本地 Vulkan 推理，不调用付费 API"
    if not supported:
        message = "内置便携包仅支持 Windows；可通过 XIAOMEI_REALESRGAN_BIN 指定本机可执行文件"
    return {
        "id": LOCAL_UPSCALE_REAL_ESRGAN_ID,
        "name": "Real-ESRGAN",
        "tagline": "快速通用",
        "available": supported,
        "ready": bool(executable),
        "downloaded": bool(executable),
        "downloading": status == "downloading",
        "status": status,
        "phase": str(state.get("phase") or ""),
        "downloaded_bytes": int(state.get("downloaded_bytes") or (package["size"] if executable else 0)),
        "total_bytes": int(package["size"]),
        "size": int(package["size"]),
        "error": str(state.get("error") or "")[:500],
        "message": message,
        "backend": "ncnn-vulkan",
        "device": "GPU · Vulkan",
        "max_long_edge": LOCAL_UPSCALE_MAX_LONG_EDGE,
        "license": package["license"],
        "source_url": package["source_url"],
    }


