def _background_removal_session(model, model_path, ort, force_cpu=False):
    _available, providers = _background_removal_provider_candidates(ort)
    if force_cpu:
        providers = ["CPUExecutionProvider"] if "CPUExecutionProvider" in _available else []
    if not providers:
        raise RuntimeError("当前 ONNX Runtime 没有可用的推理设备")
    key = f"{model.get('id')}:{model.get('version')}:{','.join(providers)}"
    session = BACKGROUND_REMOVAL_SESSIONS.get(key)
    if session is not None:
        return session
    with BACKGROUND_REMOVAL_SESSION_LOCK:
        session = BACKGROUND_REMOVAL_SESSIONS.get(key)
        if session is None:
            try:
                session = ort.InferenceSession(model_path, providers=providers)
            except Exception as exc:
                if not force_cpu and "CPUExecutionProvider" in _available and len(providers) > 1:
                    print(f"本地抠图 GPU 会话不可用，回退 CPU：{exc}")
                    providers = ["CPUExecutionProvider"]
                    key = f"{model.get('id')}:{model.get('version')}:CPUExecutionProvider"
                    session = ort.InferenceSession(model_path, providers=providers)
                else:
                    raise
            BACKGROUND_REMOVAL_SESSIONS[key] = session
            active = list(session.get_providers() or [])
            actual = next((item for item in ("CUDAExecutionProvider", "DmlExecutionProvider", "CPUExecutionProvider") if item in active), "CPUExecutionProvider")
            BACKGROUND_REMOVAL_RUNTIME_STATUS.update({
                "provider": actual,
                "provider_verified": True,
                "device": _background_removal_device_label(actual),
                "message": "" if actual != "CPUExecutionProvider" else BACKGROUND_REMOVAL_RUNTIME_STATUS.get("message") or "",
            })
    return session


def _background_removal_run(model, model_path, ort, values):
    session = _background_removal_session(model, model_path, ort)
    input_name = session.get_inputs()[0].name
    output_names = [item.name for item in session.get_outputs()]
    try:
        return session, session.run(output_names or None, {input_name: values})
    except Exception as exc:
        active = set(session.get_providers() or [])
        if not active.intersection({"CUDAExecutionProvider", "DmlExecutionProvider"}):
            raise
        print(f"本地抠图 GPU 推理失败，回退 CPU：{exc}")
        cpu_session = _background_removal_session(model, model_path, ort, force_cpu=True)
        cpu_input_name = cpu_session.get_inputs()[0].name
        cpu_output_names = [item.name for item in cpu_session.get_outputs()]
        return cpu_session, cpu_session.run(cpu_output_names or None, {cpu_input_name: values})


def _background_removal_mask(output, model, np):
    mask = np.asarray(output)
    while mask.ndim > 2 and mask.shape[0] == 1:
        mask = mask[0]
    expected = int(model.get("input_width") or 0) * int(model.get("input_height") or 0)
    if mask.ndim != 2:
        if mask.size != expected:
            raise RuntimeError(f"{model.get('name') or '本地抠图模型'} 返回了无法识别的遮罩尺寸")
        mask = mask.reshape((int(model.get("input_height")), int(model.get("input_width"))))
    mask = mask.astype(np.float32, copy=False)
    if model.get("sigmoid"):
        mask = 1.0 / (1.0 + np.exp(-mask))
    mask = np.nan_to_num(mask, nan=0.0, posinf=1.0, neginf=0.0)
    low = float(mask.min())
    high = float(mask.max())
    span = max(1e-6, high - low)
    mask = np.clip((mask - low) / span, 0.0, 1.0)
    return (mask * 255.0).round().astype(np.uint8)


def _background_removal_center_subject(image):
    """在保留原始画布尺寸的前提下，把透明图主体尽量移到画布中心。"""
    alpha = image.getchannel("A")
    visible = alpha.point(lambda value: 255 if value > 12 else 0)
    bbox = visible.getbbox()
    if not bbox:
        return image, {"auto_centered": False, "subject_bbox": None, "offset": {"x": 0, "y": 0}}
    width, height = image.size
    left, top, right, bottom = bbox
    target_x = int(round(width / 2 - (left + right) / 2))
    target_y = int(round(height / 2 - (top + bottom) / 2))
    padding = max(4, int(round(min(width, height) * 0.02)))

    min_x, max_x = padding - left, width - padding - right
    min_y, max_y = padding - top, height - padding - bottom
    offset_x = max(min_x, min(max_x, target_x)) if min_x <= max_x else 0
    offset_y = max(min_y, min(max_y, target_y)) if min_y <= max_y else 0
    offset_x, offset_y = int(offset_x), int(offset_y)
    if offset_x == 0 and offset_y == 0:
        return image, {"auto_centered": False, "subject_bbox": [left, top, right, bottom], "offset": {"x": 0, "y": 0}}

    centered = Image.new("RGBA", (width, height), (0, 0, 0, 0))
    source_left = max(0, -offset_x)
    source_top = max(0, -offset_y)
    source_right = min(width, width - offset_x)
    source_bottom = min(height, height - offset_y)
    if source_right > source_left and source_bottom > source_top:
        cropped = image.crop((source_left, source_top, source_right, source_bottom))
        centered.paste(cropped, (max(0, offset_x), max(0, offset_y)), cropped)
        cropped.close()
    return centered, {
        "auto_centered": True,
        "subject_bbox": [left, top, right, bottom],
        "offset": {"x": offset_x, "y": offset_y},
    }


def _remove_background_image_from_path(source_path, model, model_path, auto_center=True):
    np, ort = _background_removal_runtime()
    with Image.open(source_path) as opened:
        opened.load()
        oriented = ImageOps.exif_transpose(opened)
        try:
            image = oriented.convert("RGBA")
        finally:
            if oriented is not opened:
                oriented.close()
    width, height = image.size
    max_pixels = max(1, int(BACKGROUND_REMOVAL_MAX_PIXELS or 1))
    if width * height > max_pixels:
        image.close()
        raise RuntimeError(f"图片尺寸过大（{width}×{height}），本地抠图最多处理 {max_pixels:,} 像素")

    resampling = getattr(Image, "Resampling", Image)
    input_image = image.convert("RGB").resize(
        (int(model.get("input_width")), int(model.get("input_height"))),
        resampling.BILINEAR,
    )
    try:
        values = np.asarray(input_image, dtype=np.float32)
        if model.get("normalize") == "imagenet-max":
            values = values / max(float(values.max()), 1e-6)
        else:
            values = values / 255.0
    finally:
        input_image.close()
    if model.get("normalize") == "imagenet":
        values = (values - np.asarray([0.485, 0.456, 0.406], dtype=np.float32)) / np.asarray([0.229, 0.224, 0.225], dtype=np.float32)
    values = np.transpose(values, (2, 0, 1))[None, ...]
    _session, outputs = _background_removal_run(model, model_path, ort, values)
    if not outputs:
        image.close()
        raise RuntimeError(f"{model.get('name') or '本地抠图模型'} 没有返回遮罩")
    mask_values = _background_removal_mask(outputs[0], model, np)
    mask = Image.fromarray(mask_values, mode="L").resize((width, height), resampling.LANCZOS)
    image.putalpha(mask)
    mask.close()
    if auto_center:
        centered, center_meta = _background_removal_center_subject(image)
        if centered is not image:
            image.close()
        image = centered
    else:
        center_meta = {"auto_centered": False, "subject_bbox": None, "offset": {"x": 0, "y": 0}}
    return image, {"width": width, "height": height, **center_meta}


def _local_upscale_source_size(source_path):
    with Image.open(source_path) as opened:
        opened.load()
        oriented = ImageOps.exif_transpose(opened)
        try:
            return int(oriented.width), int(oriented.height)
        finally:
            if oriented is not opened:
                oriented.close()


def _local_upscale_size_for_long_edge(width, height, long_edge):
    width, height, long_edge = int(width), int(height), int(long_edge)
    if width >= height:
        return long_edge, max(1, int(round(height * long_edge / max(1, width))))
    return max(1, int(round(width * long_edge / max(1, height)))), long_edge


def local_upscale_plan(width, height, mode="scale", scale=2, target_resolution="4k", model_id=LOCAL_UPSCALE_REAL_ESRGAN_ID):
    try:
        width, height = int(width), int(height)
    except (TypeError, ValueError) as exc:
        raise ValueError("无法读取原图尺寸") from exc
    if width < 1 or height < 1:
        raise ValueError("原图尺寸无效")
    mode = str(mode or "scale").strip().lower()
    model_id = str(model_id or LOCAL_UPSCALE_REAL_ESRGAN_ID).strip().lower()
    if mode not in {"scale", "target"}:
        raise ValueError("放大模式仅支持倍率或目标分辨率")
    try:
        scale = int(scale)
    except (TypeError, ValueError) as exc:
        raise ValueError("放大倍率无效") from exc
    if scale not in {2, 4}:
        raise ValueError("放大倍率仅支持 2x 或 4x")
    target_key = str(target_resolution or "4k").strip().lower()
    target_edges = {"2k": 2048, "4k": 4096, "8k": 8192}
    if target_key not in target_edges:
        raise ValueError("目标分辨率仅支持 2K、4K 或 8K")

    source_long_edge = max(width, height)
    if mode == "scale":
        target_width, target_height = width * scale, height * scale
        target_long_edge = max(target_width, target_height)
        inference_scale = scale
        input_width, input_height = width, height
        repair_mode = False
    else:
        target_long_edge = target_edges[target_key]
        target_width, target_height = _local_upscale_size_for_long_edge(width, height, target_long_edge)
        factor = target_long_edge / max(1, source_long_edge)
        if factor > 4.0001:
            raise ValueError(
                f"从 {width}×{height} 到 {target_width}×{target_height} 超过单次 4x；"
                "请先选择 4x 生成新节点，再对新节点继续放大"
            )
        inference_scale = 2 if factor <= 2 else 4
        repair_mode = factor <= 1
        predicted_long_edge = source_long_edge * inference_scale
        if repair_mode or predicted_long_edge > LOCAL_UPSCALE_MAX_LONG_EDGE:
            input_width = max(1, int(round(target_width / inference_scale)))
            input_height = max(1, int(round(target_height / inference_scale)))
        else:
            input_width, input_height = width, height

    model_max_edge = 4096 if model_id == LOCAL_UPSCALE_SEEDVR2_ID else LOCAL_UPSCALE_MAX_LONG_EDGE
    if target_long_edge > model_max_edge:
        model_name = "SeedVR2 3B FP8" if model_id == LOCAL_UPSCALE_SEEDVR2_ID else "当前模型"
        raise ValueError(f"{model_name} 当前最多输出长边 {model_max_edge}px，请降低倍率或目标分辨率")
    if target_width * target_height > LOCAL_UPSCALE_MAX_PIXELS:
        raise ValueError(
            f"目标尺寸 {target_width}×{target_height} 超过本地高清上限；"
            "请降低倍率或目标分辨率"
        )
    return {
        "mode": mode,
        "scale": scale,
        "target_resolution": target_key,
        "source_size": (width, height),
        "source_long_edge": source_long_edge,
        "target_size": (target_width, target_height),
        "target_long_edge": target_long_edge,
        "inference_scale": inference_scale,
        "input_size": (input_width, input_height),
        "repair_mode": repair_mode,
    }


def _local_upscale_load_image(path):
    with Image.open(path) as opened:
        opened.load()
        oriented = ImageOps.exif_transpose(opened)
        try:
            return oriented.copy()
        finally:
            if oriented is not opened:
                oriented.close()


def _local_upscale_prepare_input(source_path, destination, input_size=None):
    image = _local_upscale_load_image(source_path)
    try:
        if tuple(input_size or ()) and image.size != tuple(input_size):
            resampling = getattr(Image, "Resampling", Image)
            resized = image.resize(tuple(input_size), resampling.LANCZOS)
            image.close()
            image = resized
        if image_has_alpha(image):
            converted = image.convert("RGBA")
            image.close()
            image = converted
        elif image.mode not in {"RGB", "L"}:
            converted = image.convert("RGB")
            image.close()
            image = converted
        image.save(destination, "PNG", compress_level=2)
        return destination
    finally:
        image.close()


def _local_upscale_run_realesrgan(source_path, plan, job_dir):
    executable = _local_upscale_realesrgan_executable()
    if not executable:
        raise FileNotFoundError("Real-ESRGAN 尚未下载，请先完成首次模型下载")
    input_path = os.path.join(job_dir, "input.png")
    output_path = os.path.join(job_dir, "enhanced.png")
    native_scale = LOCAL_UPSCALE_REAL_ESRGAN_NATIVE_SCALE
    input_size = tuple(plan["input_size"])
    max_native_input_long_edge = max(1, LOCAL_UPSCALE_MAX_LONG_EDGE // native_scale)
    if max(input_size) > max_native_input_long_edge:
        input_size = _local_upscale_size_for_long_edge(
            input_size[0], input_size[1], max_native_input_long_edge,
        )
    _local_upscale_prepare_input(source_path, input_path, input_size)
    model_dir = os.path.join(os.path.dirname(executable), "models")
    if not os.path.isdir(model_dir):
        raise RuntimeError("Real-ESRGAN 模型目录缺失，请重新下载本地高清模型")
    try:
        tile_size = int(os.getenv("XIAOMEI_REALESRGAN_TILE_SIZE", "256"))
    except ValueError:
        tile_size = 256
    if 0 < tile_size < 32:
        tile_size = 32
    tile_size = min(2048, max(0, tile_size))
    command = [
        executable,
        "-i", input_path,
        "-o", output_path,
        "-m", model_dir,
        "-n", "realesrgan-x4plus",
        "-s", str(native_scale),
        "-t", str(tile_size),
        "-j", "1:1:1",
        "-f", "png",
        "-v",
    ]
    creationflags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    try:
        completed = subprocess.run(
            command,
            cwd=os.path.dirname(executable),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=LOCAL_UPSCALE_TIMEOUT_SECONDS,
            creationflags=creationflags,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(f"Real-ESRGAN 处理超时（已等待 {LOCAL_UPSCALE_TIMEOUT_SECONDS} 秒）") from exc
    if completed.returncode != 0 or not os.path.isfile(output_path):
        output = (completed.stderr or completed.stdout or b"").decode("utf-8", errors="replace").strip()
        raise RuntimeError(f"Real-ESRGAN 运行失败：{output[-800:] or f'退出码 {completed.returncode}'}")
    return output_path, {
        "backend": "ncnn-vulkan",
        "model_name": "Real-ESRGAN",
        "native_scale": native_scale,
        "device": "GPU · Vulkan",
    }


def _local_upscale_model_scale(name):
    matches = re.findall(r"(?:^|[^a-z0-9])x([2348])(?:[^0-9]|$)", str(name or "").lower())
    return int(matches[-1]) if matches else 4


def _local_upscale_select_swinir_model(models, plan):
    candidates = [(name, _local_upscale_model_scale(name)) for name in models]
    desired = int(plan["scale"] if plan["mode"] == "scale" else plan["inference_scale"])
    exact = next((item for item in candidates if item[1] == desired), None)
    if exact:
        return exact
    sufficient = sorted((item for item in candidates if item[1] >= desired), key=lambda item: item[1])
    if sufficient:
        return sufficient[0]
    raise RuntimeError(f"ComfyUI 中没有可完成 {desired}x 的 SwinIR 权重")


def _local_upscale_comfy_output(result, model_name):
    if not isinstance(result, dict) or result.get("error"):
        detail = str((result or {}).get("error") or "ComfyUI 没有返回结果")[:800]
        raise RuntimeError(f"{model_name} 处理失败：{detail}")
    image_url = next((str(item) for item in (result.get("images") or []) if item), "")
    result_path = output_file_from_url(image_url)
    if not result_path or not os.path.isfile(result_path):
        raise RuntimeError(f"{model_name} 没有返回可用图片")
    return result_path


def _local_upscale_run_swinir(source_path, plan, job_dir, capability):
    model_name, native_scale = _local_upscale_select_swinir_model(capability.get("models") or [], plan)
    source_width, source_height = plan["source_size"]
    target_width, target_height = plan["target_size"]
    if plan["mode"] == "target" or native_scale != int(plan["scale"]):
        input_size = (
            max(1, int(round(target_width / native_scale))),
            max(1, int(round(target_height / native_scale))),
        )
    else:
        input_size = (source_width, source_height)
    prepared_path = os.path.join(job_dir, "input.png")
    _local_upscale_prepare_input(source_path, prepared_path, input_size)
    uploaded_name = gemini_cli_upload_image_to_comfy(capability["address"], prepared_path)
    result = generate(GenerateRequest(
        prompt="小美画布 SwinIR 高清修复",
        width=target_width,
        height=target_height,
        workflow_json="swinir-upscale.json",
        params={
            "1": {"image": uploaded_name},
            "2": {"model_name": model_name},
            "4": {"width": target_width, "height": target_height},
        },
        type="local-upscale-swinir",
        record_history=False,
        preferred_backend=capability["address"],
        timeout_seconds=LOCAL_UPSCALE_TIMEOUT_SECONDS,
    ))
    return _local_upscale_comfy_output(result, "SwinIR"), {
        "backend": "comfyui",
        "model_name": "SwinIR",
        "model_file": model_name,
        "native_scale": native_scale,
        "device": f"ComfyUI · {capability['address']}",
    }


def _local_upscale_run_seedvr2(source_path, plan, job_dir, capability, strength):
    target_width, target_height = plan["target_size"]
    prepared_path = os.path.join(job_dir, "input.png")
    _local_upscale_prepare_input(source_path, prepared_path, None)
    uploaded_name = gemini_cli_upload_image_to_comfy(capability["address"], prepared_path)
    noise = {"low": 0.0, "medium": 0.03, "high": 0.08}[strength]
    official_node = str(capability.get("node") or "official") != "legacy"
    if official_node:
        workflow_name = "seedvr2-official-upscale.json"
        params = {
            "1": {"image": uploaded_name},
            "2": {
                "tiled_vae": True,
                "vae_tile_size": 512,
                "vae_tile_overlap": 64,
                "preserve_vram": True,
                "cache_model": False,
                "enable_debug": False,
                "device": "cuda:0",
            },
            "3": {"blocks_to_swap": 32, "offload_io_components": True},
            "4": {
                "model": capability.get("dit_model") or "seedvr2_ema_3b_fp8_e4m3fn.safetensors",
                "new_resolution": max(16, min(4320, min(target_width, target_height))),
                "batch_size": 1,
                "color_correction": "wavelet",
                "input_noise_scale": noise,
                "latent_noise_scale": noise,
            },
            "5": {"width": target_width, "height": target_height},
        }
    else:
        workflow_name = "upscale.json"
        params = {
            "15": {"image": uploaded_name},
            "169": {"model": capability["dit_model"]},
            "170": {"model": capability["vae_model"]},
            "172": {
                "resolution": max(target_width, target_height),
                "max_resolution": 4096,
                "batch_size": 1,
                "input_noise_scale": noise,
                "latent_noise_scale": noise,
            },
        }
    result = generate(GenerateRequest(
        prompt="小美画布 SeedVR2 生成式高清",
        width=target_width,
        height=target_height,
        workflow_json=workflow_name,
        params=params,
        type="local-upscale-seedvr2",
        record_history=False,
        preferred_backend=capability["address"],
        timeout_seconds=LOCAL_UPSCALE_TIMEOUT_SECONDS,
    ))
    return _local_upscale_comfy_output(result, "SeedVR2 3B FP8"), {
        "backend": "comfyui",
        "model_name": "SeedVR2 3B FP8",
        "model_file": capability.get("dit_model") or "seedvr2_ema_3b_fp8_e4m3fn.safetensors",
        "native_scale": 0,
        "device": f"ComfyUI · {capability['address']}",
        "noise_scale": noise,
    }


def _local_upscale_flatten_rgb(image):
    if image_has_alpha(image):
        rgba = image.convert("RGBA")
        background = Image.new("RGBA", rgba.size, (255, 255, 255, 255))
        background.alpha_composite(rgba)
        rgba.close()
        rgb = background.convert("RGB")
        background.close()
        return rgb
    return image.convert("RGB")


def _local_upscale_save_result(ai_path, source_path, output_path, target_size, strength, output_format):
    enhanced = _local_upscale_load_image(ai_path)
    original = _local_upscale_load_image(source_path)
    resampling = getattr(Image, "Resampling", Image)
    final_fit = enhanced.size != tuple(target_size)
    try:
        if final_fit:
            resized = enhanced.resize(tuple(target_size), resampling.LANCZOS)
            enhanced.close()
            enhanced = resized
        if original.size != tuple(target_size):
            resized = original.resize(tuple(target_size), resampling.LANCZOS)
            original.close()
            original = resized

        ai_weight = {"low": 0.58, "medium": 0.8, "high": 1.0}[strength]
        preserve_alpha = output_format != "jpg" and (image_has_alpha(enhanced) or image_has_alpha(original))
        if preserve_alpha:
            enhanced_ready = enhanced.convert("RGBA")
            original_ready = original.convert("RGBA")
        else:
            enhanced_ready = _local_upscale_flatten_rgb(enhanced)
            original_ready = _local_upscale_flatten_rgb(original)
        try:
            result = enhanced_ready if ai_weight >= 1 else Image.blend(original_ready, enhanced_ready, ai_weight)
            try:
                os.makedirs(os.path.dirname(output_path), exist_ok=True)
                if output_format == "jpg":
                    result.save(output_path, "JPEG", quality=95, subsampling=0, optimize=True)
                elif output_format == "webp":
                    result.save(output_path, "WEBP", quality=95, method=4)
                else:
                    result.save(output_path, "PNG", compress_level=4)
            finally:
                if result is not enhanced_ready:
                    result.close()
        finally:
            enhanced_ready.close()
            original_ready.close()
    finally:
        enhanced.close()
        original.close()
    return {"width": int(target_size[0]), "height": int(target_size[1]), "ai_weight": ai_weight, "final_fit": final_fit}


def _local_upscale_remove_comfy_intermediate(path):
    target = os.path.abspath(str(path or ""))
    root = os.path.abspath(OUTPUT_OUTPUT_DIR)
    try:
        inside = os.path.commonpath([root, target]) == root
    except ValueError:
        inside = False
    name = os.path.basename(target).lower()
    if inside and os.path.isfile(target) and "local-upscale-" in name:
        try:
            os.remove(target)
        except OSError:
            pass


def _local_upscale_process(source_path, source_url, requested_name, payload):
    model_id = str(payload.model_id or LOCAL_UPSCALE_REAL_ESRGAN_ID).strip().lower()
    if model_id not in {LOCAL_UPSCALE_REAL_ESRGAN_ID, LOCAL_UPSCALE_SWINIR_ID, LOCAL_UPSCALE_SEEDVR2_ID}:
        raise ValueError("不支持的本地高清模型")
    strength = str(payload.strength or "medium").strip().lower()
    if strength not in {"low", "medium", "high"}:
        raise ValueError("增强强度仅支持低、中、高")
    output_format = str(payload.output_format or "png").strip().lower()
    if output_format == "jpeg":
        output_format = "jpg"
    if output_format not in {"png", "jpg", "webp"}:
        raise ValueError("输出格式仅支持 PNG、JPG 或 WebP")

    source_size = _local_upscale_source_size(source_path)
    plan = local_upscale_plan(
        source_size[0], source_size[1],
        payload.mode, payload.scale, payload.target_resolution, model_id,
    )
    capabilities = None
    if model_id == LOCAL_UPSCALE_REAL_ESRGAN_ID:
        if not _local_upscale_realesrgan_executable():
            raise FileNotFoundError("Real-ESRGAN 尚未下载，请先完成首次模型下载")
    else:
        capabilities = _local_upscale_comfy_capabilities(force=True)
        capability_key = "swinir" if model_id == LOCAL_UPSCALE_SWINIR_ID else "seedvr2"
        if not capabilities[capability_key]["ready"]:
            raise FileNotFoundError(
                "SwinIR 本地环境未就绪" if model_id == LOCAL_UPSCALE_SWINIR_ID
                else "SeedVR2 3B FP8 本地环境未就绪"
            )

    job_root = _local_upscale_path("jobs")
    os.makedirs(job_root, exist_ok=True)
    job_dir = tempfile.mkdtemp(prefix="upscale-", dir=job_root)
    ai_path = ""
    started_at = time.time()
    try:
        if model_id == LOCAL_UPSCALE_REAL_ESRGAN_ID:
            ai_path, engine_meta = _local_upscale_run_realesrgan(source_path, plan, job_dir)
        elif model_id == LOCAL_UPSCALE_SWINIR_ID:
            ai_path, engine_meta = _local_upscale_run_swinir(source_path, plan, job_dir, capabilities["swinir"])
        else:
            ai_path, engine_meta = _local_upscale_run_seedvr2(source_path, plan, job_dir, capabilities["seedvr2"], strength)

        extension = ".jpg" if output_format == "jpg" else f".{output_format}"
        filename = generated_output_filename("upscale_", extension)
        output_path = media_write_path(filename, "output")
        save_meta = _local_upscale_save_result(
            ai_path,
            source_path,
            output_path,
            plan["target_size"],
            strength,
            output_format,
        )
        duration = round(time.time() - started_at, 3)
        base = _background_removal_name(source_path, requested_name)
        mode_label = f"{plan['scale']}x" if plan["mode"] == "scale" else plan["target_resolution"].upper()
        display_name = f"{base}_高清_{mode_label}{extension}"
        metadata = {
            "model_id": model_id,
            "model_name": engine_meta["model_name"],
            "backend": engine_meta["backend"],
            "device": engine_meta.get("device") or "",
            "model_file": engine_meta.get("model_file") or "",
            "mode": plan["mode"],
            "scale": plan["scale"],
            "target_resolution": plan["target_resolution"],
            "strength": strength,
            "output_format": output_format,
            "source_width": source_size[0],
            "source_height": source_size[1],
            "width": save_meta["width"],
            "height": save_meta["height"],
            "native_scale": engine_meta.get("native_scale") or 0,
            "repair_mode": bool(plan["repair_mode"]),
            "ai_weight": save_meta["ai_weight"],
            "final_fit": bool(save_meta["final_fit"]),
            "duration_seconds": duration,
            "paid_api": False,
        }
        return {
            "url": output_url_for(filename, "output"),
            "name": display_name,
            "kind": "image",
            "width": save_meta["width"],
            "height": save_meta["height"],
            "upscale": metadata,
            "derived_from": {"url": source_url, "operation": "local-upscale"},
        }
    finally:
        if ai_path and model_id in {LOCAL_UPSCALE_SWINIR_ID, LOCAL_UPSCALE_SEEDVR2_ID}:
            _local_upscale_remove_comfy_intermediate(ai_path)
        if os.path.isdir(job_dir):
            _local_upscale_safe_rmtree(job_dir)

