def prepare_asset_library_folders():
    with ASSET_LIBRARY_IO_LOCK:
        catalog = load_asset_library()
        created = asset_library_storage.provision_category_folders(ASSET_LIBRARY_DIR, catalog)
        if created:
            try:
                save_asset_library(catalog)
            except Exception:
                for folder in created:
                    asset_library_storage.remove_empty_folder(folder)
                raise


def _publish_asset_library_workflows(items, library_id, category_id, *, strict=False):
    with ASSET_LIBRARY_IO_LOCK:
        catalog = load_asset_library()
        asset_library_workflows.add_items(catalog, library_id, category_id, items, strict=strict)
        save_asset_library(catalog)
    return catalog


def _merge_asset_library_additions(current, incoming, additions):
    """Merge additions produced from an older snapshot into the latest library."""
    current = normalize_asset_library(current or {})
    incoming = normalize_asset_library(incoming or {})
    added_ids = {str(item.get("id") or "") for item in additions}
    existing_ids = {
        str(item.get("id") or "")
        for library in current.get("libraries", [])
        for category in library.get("categories", [])
        for item in category.get("items", [])
    }
    current_libs = {str(item.get("id") or ""): item for item in current.get("libraries", [])}
    for incoming_lib in incoming.get("libraries", []):
        library_id = str(incoming_lib.get("id") or "")
        target_lib = current_libs.get(library_id)
        if not target_lib:
            continue
        target_cats = {str(item.get("id") or ""): item for item in target_lib.get("categories", [])}
        for incoming_cat in incoming_lib.get("categories", []):
            category_id = str(incoming_cat.get("id") or "")
            target_cat = target_cats.get(category_id)
            if not target_cat:
                continue
            for item in incoming_cat.get("items", []):
                item_id = str(item.get("id") or "")
                if item_id and item_id in added_ids and item_id not in existing_ids:
                    target_cat.setdefault("items", []).append(item)
                    existing_ids.add(item_id)
    return current


def save_asset_library(lib, merge_items=None):
    lib = normalize_asset_library(lib)
    sort_asset_library_items(lib)
    lib["updated_at"] = now_ms()
    with ASSET_LIBRARY_IO_LOCK:
        if merge_items is not None:
            latest = load_asset_library()
            merged = _merge_asset_library_additions(latest, lib, merge_items)
            lib.clear()
            lib.update(merged)
            lib["updated_at"] = now_ms()
            sort_asset_library_items(lib)
        _atomic_write_json_file(ASSET_LIBRARY_PATH, lib)
    if GLOBAL_LOOP:
        asyncio.run_coroutine_threadsafe(workspace_events.broadcast_asset_library_updated(int(lib["updated_at"])), GLOBAL_LOOP)

def find_asset_category(lib, category_id):
    for cat in lib.get("categories", []):
        if cat.get("id") == category_id:
            return cat
    return None

def find_asset_library(lib, library_id=""):
    lib = normalize_asset_library(lib)
    library_id = str(library_id or lib.get("active_library_id") or "").strip()
    return next((item for item in lib.get("libraries", []) if item.get("id") == library_id), None) or (lib.get("libraries") or [None])[0]

def find_asset_category_in_library(lib, category_id, library_id=""):
    library = find_asset_library(lib, library_id)
    if not library:
        return None
    for cat in library.get("categories", []):
        if cat.get("id") == category_id:
            return cat
    return None

def find_asset_category_with_library(lib, category_id, library_id=""):
    lib = normalize_asset_library(lib)
    preferred = str(library_id or "").strip()
    libraries = lib.get("libraries", []) or []
    if preferred:
        libraries = [item for item in libraries if item.get("id") == preferred]
    for library in libraries:
        for cat in library.get("categories", []) or []:
            if cat.get("id") == category_id:
                return library, cat
    return None, None


def _asset_library_item_registry_record(item: Dict[str, Any]) -> Dict[str, Any]:
    url = registry_url_key(_asset_registry_trackable_url(item.get("url")))
    requested = item.get("asset_ref_id") or item.get("id")
    existing = ASSET_REGISTRY.get(requested) if registry_is_asset_id(requested) else None
    if existing:
        addresses = [existing.get("canonical_url"), *(existing.get("aliases") or [])]
        if url not in {registry_url_key(value) for value in addresses}:
            requested = ""
    record = asset_registry_register_media(
        item.get("url"),
        asset_id=requested,
        name=item.get("name"),
        kind=item.get("kind") or item.get("type"),
        source="asset_library",
        derived_from=item.get("derived_from") or item.get("derivedFrom"),
        created_at=item.get("created_at"),
    )
    if not record or not registry_is_asset_id(record.get("id")):
        raise HTTPException(status_code=500, detail="素材索引登记失败")
    item["asset_ref_id"] = record["id"]
    return record


def _asset_library_restore_context(library: Dict[str, Any], category: Dict[str, Any], item: Dict[str, Any]) -> Dict[str, Any]:
    try:
        saved_item = json.loads(json.dumps(item, ensure_ascii=False))
    except (TypeError, ValueError):
        saved_item = dict(item)
    return {
        "asset_library": {
            "library_id": str(library.get("id") or ""),
            "category_id": str(category.get("id") or ""),
            "category": {
                "id": str(category.get("id") or ""),
                "name": str(category.get("name") or "已恢复素材")[:120],
                "type": str(category.get("type") or "image"),
                "dir": str(category.get("dir") or "").strip("/\\"),
            },
            "item": saved_item,
        }
    }


def _trash_asset_library_item(
    library: Dict[str, Any],
    category: Dict[str, Any],
    item: Dict[str, Any],
    *,
    reason: str,
    reference_scan_cache: Optional[Dict[str, Any]] = None,
) -> str:
    record = _asset_library_item_registry_record(item)
    asset_id = str(record.get("id") or "")
    asset_registry_require_unreferenced(asset_id, reference_scan_cache)
    _asset_registry_trash_media(
        asset_id,
        reason=reason,
        restore_context=_asset_library_restore_context(library, category, item),
    )
    return asset_id

