def content_type_for_path(path):
    return media_formats.content_type(path)


def _reference_kind(value):
    if not isinstance(value, str) or not value:
        return ""
    if value.startswith("data:"):
        mime = value[5:].partition(";")[0].partition(",")[0]
        kind, separator, _ = mime.partition("/")
        return kind if separator else ""
    if media_paths.parse_address(value, allow_loopback=True):
        try:
            path = output_file_from_url(value)
        except (HTTPException, OSError, ValueError):
            path = None
        return content_type_for_path(path).partition("/")[0] if path else ""
    mime = content_type_for_path("reference" + media_formats.url_extension(value))
    kind = mime.partition("/")[0]
    return kind if kind in {"video", "audio"} else "image"


def is_image_reference_value(value):
    return _reference_kind(value) == "image"


def is_video_reference_value(value):
    return _reference_kind(value) == "video"


def reference_to_data_url(ref, max_size=None):
    value = ref.get("url", "")
    path = output_file_from_url(value)
    if not path:
        return value
    return media_formats.reference_data_url(path, max_size, content_type_for_path(path))


def is_image_reference(ref):
    if not isinstance(ref, dict):
        return False
    kind = str(ref.get("kind") or "").strip().lower()
    mime = str(ref.get("mime") or "").strip().lower()
    url = str(ref.get("url") or "").strip().lower()
    if kind:
        return kind == "image"
    if mime:
        return mime.startswith("image/")
    return bool(re.search(r"\.(png|jpe?g|webp|gif|bmp|tiff?)(\?|#|$)", url))

def image_references(refs):
    return [ref for ref in (refs or []) if is_image_reference(ref)]

def attachment_embedded_image_data_urls(refs, max_images=4):
    urls = []
    for ref in (refs or []):
        if not isinstance(ref, dict) or is_image_reference(ref):
            continue
        path = output_file_from_url(ref.get("url", ""))
        if not path or os.path.splitext(path)[1].lower() != ".xlsx":
            continue
        urls.extend(workbook_image_data_urls(path, max_images=max(0, max_images - len(urls))))
        if len(urls) >= max_images:
            break
    return urls[:max_images]

def canvas_document_details(path, include_images=False):
    if not path or not os.path.isfile(path):
        return {"status": "error", "message": "文件不存在或已移走，请重新上传", "text": ""}
    ext = os.path.splitext(path)[1].lower()
    if ext not in TEXT_ATTACHMENT_EXTS | DOCUMENT_EXTS | set(LEGACY_DOCUMENT_EXTS) | {".xlsx"}:
        return {"status": "unsupported", "message": "该格式暂不能读取文字，请另存为 DOCX、XLSX、PPTX、PDF 或 TXT 后上传", "text": ""}
    try:
        text = read_text_attachment(path, MAX_ATTACHMENT_TEXT_CHARS + 1, strict=True)
        if not text.strip():
            raise ValueError("未读取到文字，请检查文件内容；扫描文档请先识字或上传页面图片")
        truncated = len(text) > MAX_ATTACHMENT_TEXT_CHARS or "已截断" in text
        text = text[:MAX_ATTACHMENT_TEXT_CHARS]
        message = f"已读取 {len(text)} 字"
        if truncated:
            message += "，内容较长，仅使用已读取的部分；可拆分文件后上传"
        if ext == ".xlsx":
            message += f"；最多读取 {EXCEL_MAX_SHEETS} 个工作表，每表 {EXCEL_MAX_ROWS_PER_SHEET} 行、{EXCEL_MAX_COLS_PER_ROW} 列"
        details = {"status": "ready", "message": message, "text": text, "chars": len(text), "truncated": truncated}
        if include_images:
            entries, images_truncated = document_preview_images(path)
            details["images"] = [{"index": index, "title": entry["title"], **({"after_char": entry["after_char"]} if "after_char" in entry else {})} for index, entry in enumerate(entries)]
            details["images_truncated"] = images_truncated
            if entries:
                message += f"；可预览 {len(entries)} 张内嵌图片"
            if images_truncated:
                message += "（仅显示前 40 张）"
        if ext in DOCUMENT_EXTS | {".xlsx"}:
            message += "；Agent 识图需将文档内图片另行上传"
        details["message"] = message
        return details
    except ValueError as exc:
        if include_images and ext in {".xmind", ".docx", ".pptx", ".xlsx"}:
            try:
                entries, images_truncated = document_preview_images(path)
                if entries:
                    message = f"{exc}；可预览 {len(entries)} 张内嵌图片"
                    if images_truncated:
                        message += "（仅显示前 40 张）"
                    return {"status": "error", "message": message, "text": "", "images": [{"index": index, "title": entry["title"], **({"after_char": entry["after_char"]} if "after_char" in entry else {})} for index, entry in enumerate(entries)], "images_truncated": images_truncated}
            except Exception:
                pass
        return {"status": "error", "message": str(exc), "text": ""}
    except Exception:
        return {"status": "error", "message": "文件无法解析，请检查是否损坏或加密，并重新保存后上传", "text": ""}


