def media_reference_to_url(value, max_image_size=None):
    if not isinstance(value, str) or not value:
        return ""
    value = value.strip()
    if not value:
        return ""

    # 聊天/视觉模型通常只接受 data URL 或公网 HTTPS URL。画布里的图片还
    # 可能来自 /output、/assets、/api/storage-files，或者以上地址的
    # localhost 绝对 URL；这些地址对上游服务不可见，必须先读取本地文件并
    # 转为 data URL，不能把相对路径原样交给 Comfly 等 OpenAI 兼容接口。
    local_value = value
    parsed = urllib.parse.urlparse(value)
    if parsed.scheme in {"http", "https"} and (parsed.hostname or "").lower() in {"127.0.0.1", "localhost", "::1"}:
        local_value = parsed.path or ""
        if parsed.query:
            local_value += f"?{parsed.query}"
    if output_file_from_url(local_value):
        return reference_to_data_url({"url": local_value}, max_size=max_image_size)
    return value

