def vision_image_data_url(source, max_size=VISION_INPUT_MAX_EDGE, max_bytes=VISION_INPUT_MAX_BYTES):
    """把视觉聊天参考图压成受控大小的 JPEG data URL。

    透明通道仅服务于显示，发送给视觉模型时统一铺白后转 JPEG；这能避免一张
    1024px 的 RGBA PNG 因无损编码仍有数 MB，触发部分上游的“image too large”。
    返回空字符串表示无法安全地生成受控副本，调用方应跳过该图而不是回退原图。
    """
    working = None
    try:
        with Image.open(source) as original, ImageOps.exif_transpose(original) as oriented:
            working = media_formats.rgb_on_white(oriented)

        max_size = max(128, int(max_size or VISION_INPUT_MAX_EDGE))
        max_bytes = max(0, int(max_bytes or 0))
        min_edge = min(max_size, VISION_INPUT_MIN_EDGE)
        resampling = getattr(Image, "Resampling", Image).LANCZOS
        if max(working.size) > max_size:
            working.thumbnail((max_size, max_size), resampling)
        if not working.size[0] or not working.size[1]:
            return ""

        # 先通过质量压缩，仍超限时再等比降边；全程只处理内存副本。
        for _ in range(8):
            for quality in (86, 78, 70, 62, 54, 46):
                buffer = BytesIO()
                working.save(buffer, format="JPEG", quality=quality, optimize=True, progressive=True)
                encoded = buffer.getvalue()
                if not max_bytes or len(encoded) <= max_bytes:
                    return f"data:image/jpeg;base64,{base64.b64encode(encoded).decode('ascii')}"
            edge = max(working.size)
            if edge <= min_edge:
                break
            next_edge = max(min_edge, int(edge * 0.72))
            if next_edge >= edge:
                break
            width = max(1, round(working.width * next_edge / edge))
            height = max(1, round(working.height * next_edge / edge))
            resized = working.resize((width, height), resampling)
            working.close()
            working = resized

        print(f"[vision] 参考图压缩后仍超过 {max_bytes} bytes，已跳过")
        return ""
    except Exception as exc:
        print(f"[vision] 参考图压缩失败，已跳过：{exc}")
        return ""
    finally:
        if working is not None:
            try:
                working.close()
            except Exception:
                pass

def vision_image_reference_url(value, max_size=VISION_INPUT_MAX_EDGE, max_bytes=VISION_INPUT_MAX_BYTES):
    """将本地或 data URL 参考图转成视觉聊天可安全提交的内联 JPEG。"""
    text = str(value or "").strip()
    if not text:
        return ""
    if text.startswith("data:image/"):
        if ";base64," not in text:
            return ""
        try:
            _header, encoded = text.split(";base64,", 1)
            return vision_image_data_url(BytesIO(base64.b64decode(encoded)), max_size, max_bytes)
        except Exception as exc:
            print(f"[vision] 无法读取 data URL 参考图，已跳过：{exc}")
            return ""
    if text.startswith("data:"):
        return ""

    local_value = text
    parsed = urllib.parse.urlparse(text)
    if parsed.scheme in {"http", "https"} and (parsed.hostname or "").lower() in {"127.0.0.1", "localhost", "::1"}:
        local_value = parsed.path or ""
        if parsed.query:
            local_value += f"?{parsed.query}"
    path = output_file_from_url(local_value)
    if path:
        return vision_image_data_url(path, max_size, max_bytes)
    return text

async def canvas_vision_image_url(value, client: httpx.AsyncClient):
    """为画布 Agent 规范化本地、data URL 和可安全读取的公网参考图。"""
    text = str(value or "").strip()
    normalized = vision_image_reference_url(text)
    if not text or normalized != text or not text.startswith(("http://", "https://")):
        return normalized
    try:
        raw, _content_type, _final_url = await _request_public_link_document(
            client,
            text,
            max_bytes=VISION_INPUT_SOURCE_MAX_BYTES,
        )
        compressed = vision_image_data_url(BytesIO(raw))
        if compressed:
            return compressed
        print("[vision] 公网参考图不是可读取图片，保留原始 URL 交由上游处理")
    except ValueError as exc:
        # 源文件本身超过安全下载上限时，绝不能把原 URL 原样交给上游，否则仍会
        # 触发同一个 image too large 错误；跳过并由前端显示计数即可。
        if "过大" in str(exc):
            print(f"[vision] 公网参考图源文件过大，已跳过：{exc}")
            return ""
        print(f"[vision] 公网参考图本地压缩失败，保留原始 URL：{exc}")
    except Exception as exc:
        # CDN 防盗链等场景本机可能读不到，而上游仍可能能读取；保留原行为作为兼容兜底。
        print(f"[vision] 公网参考图本地压缩失败，保留原始 URL：{exc}")
    return text

async def prepare_canvas_vision_images(values, max_images=None):
    """为 Canvas LLM（含计划模式和 CLI 模式）统一准备受控的视觉输入。"""
    candidates = [item for item in (values or []) if is_image_reference_value(item)][:max_images]
    prepared = []
    normalized_count = 0
    skipped_indices = []
    async with httpx.AsyncClient(
        timeout=httpx.Timeout(connect=10.0, read=max(30.0, LINK_CONTEXT_TIMEOUT), write=30.0, pool=20.0),
        headers={"User-Agent": "XiaomeiCanvas/1.0", "Accept": "image/avif,image/webp,image/apng,image/*,*/*;q=0.8"},
        follow_redirects=False,
    ) as client:
        for index, item in enumerate(candidates, start=1):
            original = str(item or "").strip()
            safe_url = await canvas_vision_image_url(original, client)
            if not safe_url:
                skipped_indices.append(index)
                continue
            if safe_url != original:
                normalized_count += 1
            prepared.append(safe_url)
    return prepared, {
        "requested": len(candidates),
        "submitted": len(prepared),
        "normalized": normalized_count,
        "skipped": max(0, len(candidates) - len(prepared)),
        "skipped_indices": skipped_indices,
    }


def valid_video_image_input(value: str) -> bool:
    if not isinstance(value, str):
        return False
    value = value.strip()
    return (
        value.startswith("http://") or
        value.startswith("https://") or
        value.startswith("asset://") or
        (value.startswith("data:image/") and ";base64," in value)
    )

