async def openai_video_proxy_public_reference_url(ref):
    raw = ref.get("url") if isinstance(ref, dict) else ref
    text = str(raw or "").strip()
    if not text:
        return ""
    address, local = media_cloud.reference_location(text)
    if not local:
        return address
    if not address or not output_file_from_url(address):
        raise HTTPException(status_code=400, detail=f"参考图不是公网 URL，无法传给上游：{text[:160]}")
    problem = "未知错误"
    try:
        uploaded = await upload_local_video_to_cloud(address)
        public = str((uploaded or {}).get("url") or "")
        if media_cloud.is_public_media_url(public):
            return public
    except HTTPException as exc:
        problem = str(exc.detail)
    public = local_asset_public_url(address)
    if public:
        return public
    raise HTTPException(status_code=400, detail=f"参考图上传图床失败，无法转成公网 URL：{problem[:200]}。请检查网络后重试。")


