async def _submit_avatar_review(platform, provider, media, project, group):
    kind = str(media.get("kind") or "image").lower()
    if kind not in ("image", "video", "audio"):
        kind = "image"
    name = media.get("name") or "asset"
    if platform == "apimart":
        async with httpx.AsyncClient(timeout=VIDEO_POLL_TIMEOUT) as client:
            url = await apimart_reference_uploader(client, provider).prepare(media.get("url"), kind)
        if not media_cloud.is_public_media_url(url):
            reason = url[4:] if isinstance(url, str) and url.startswith("ERR:") else "无法获取公网可访问地址"
            raise HTTPException(status_code=400, detail=f"素材无法提交到 APIMart：{reason}\n请配置 PUBLIC_BASE_URL，或确认本地文件存在。")
        root = apimart_avatar_root(provider)
        async with httpx.AsyncClient(timeout=120) as client:
            return await apimart_media.submit_avatar(client, root, api_headers(provider=provider), url, name, kind, project, group)

    address, local = media_cloud.reference_location(media.get("url"))
    url = local_asset_public_url(address) if local else address
    if not url:
        raise HTTPException(status_code=400, detail="火山要求素材使用公网 http/https URL。可为本地素材配置 PUBLIC_BASE_URL 或 PUBLIC_MEDIA_BASE_URL。")
    async with httpx.AsyncClient(timeout=120) as client:
        return await _ark_assets(client).submit(url, name, kind, project, group)


async def _query_avatar_review(platform, provider, task_id, stored_provider, project):
    if stored_provider and stored_provider != provider.get("id"):
        provider = get_api_provider_exact(stored_provider)
        if avatar_platform_for_provider(provider) != platform:
            raise HTTPException(status_code=409, detail="提交审核的 API 平台已变更，请核对平台配置")
    async with httpx.AsyncClient(timeout=60) as client:
        if platform == "apimart":
            return await apimart_media.avatar_status(
                client, apimart_avatar_root(provider), api_headers(provider=provider), task_id,
            )
        return await _ark_assets(client).status(task_id, project)


