async def upload_local_video_to_cloud(ref_url: str, service: str = "auto") -> Dict[str, str]:
    address = str(ref_url or "").strip()
    if address.startswith(("https://", "http://")):
        return {"url": address, "source": address, "service": "existing"}
    path = local_media_path_for_cloud_upload(address)
    hosts = media_cloud.select_hosts(service)
    uploaders = {"litterbox": upload_video_to_litterbox, "temp.sh": upload_video_to_temp_sh}
    if len(hosts) == 1:
        return await uploaders[hosts[0]](path, address)
    failures = []
    for host in hosts:
        try:
            return await uploaders[host](path, address)
        except HTTPException as exc:
            failures.append(str(exc.detail))
    raise HTTPException(status_code=502, detail="云端上传失败。" + "；".join(failures))


