def save_canvas_video_to_history(payload: CanvasVideoRequest, provider, result):
    """把画布视频成功结果写入共享历史记录。"""
    if not isinstance(result, dict):
        return result
    raw_items = result.get("video_items")
    if not isinstance(raw_items, list) or not raw_items:
        raw_items = result.get("videos")
    if not isinstance(raw_items, list):
        raw_items = [raw_items] if raw_items else []

    videos = []
    video_items = []
    seen = set()
    for raw_item in raw_items:
        if isinstance(raw_item, dict):
            url = str(
                raw_item.get("url")
                or raw_item.get("src")
                or raw_item.get("path")
                or raw_item.get("uri")
                or ""
            ).strip()
            item = dict(raw_item)
        else:
            url = str(raw_item or "").strip()
            item = {}
        if not url or url in seen:
            continue
        seen.add(url)
        name = os.path.basename(urllib.parse.urlparse(url).path) or f"video-{len(videos) + 1}.mp4"
        item.update({"url": url, "kind": "video", "name": str(item.get("name") or name)})
        videos.append(url)
        video_items.append(item)
    if not videos:
        return result

    provider = provider if isinstance(provider, dict) else {}
    provider_id = str(provider.get("id") or getattr(payload, "provider_id", "") or "")
    provider_name = str(provider.get("name") or provider_id)
    model = str(getattr(payload, "model", "") or "")
    try:
        duration = max(1, min(60, int(getattr(payload, "duration", 5) or 5)))
    except (TypeError, ValueError):
        duration = 5
    record = {
        "prompt": str(getattr(payload, "prompt", "") or ""),
        "images": [],
        "videos": videos,
        "video_items": video_items,
        "timestamp": time.time(),
        "type": "video",
        "history_source": "canvas",
        "project_id": str(getattr(payload, "project_id", "") or "").strip(),
        "model": model,
        "provider_id": provider_id,
        "provider_name": provider_name,
        "task_id": result.get("task_id") or result.get("video_id") or None,
        "params": {
            "source": "canvas_video",
            "history_source": "canvas",
            "project_id": str(getattr(payload, "project_id", "") or "").strip(),
            "provider_id": provider_id,
            "model": model,
            "duration": duration,
            "aspect_ratio": str(getattr(payload, "aspect_ratio", "") or ""),
            "resolution": str(getattr(payload, "resolution", "") or ""),
            "size": str(getattr(payload, "size", "") or ""),
            "watermark": bool(getattr(payload, "watermark", False)),
            "generate_audio": bool(getattr(payload, "generate_audio", False)),
        },
    }
    save_to_history(record)
    return result

def snap_size_to_multiple(size, multiple=16):
    width, height = parse_size_pair(size)
    if not width or not height:
        return size
    step = max(1, int(multiple or 16))
    snapped_w = max(step, int(math.ceil(width / step) * step))
    snapped_h = max(step, int(math.ceil(height / step) * step))
    return f"{snapped_w}x{snapped_h}"

