    GPT_IMAGE2_EDIT_WRITE_TIMEOUT = max(10.0, min(600.0, float(os.getenv("GPT_IMAGE2_EDIT_WRITE_TIMEOUT", "") or read_api_env_value("GPT_IMAGE2_EDIT_WRITE_TIMEOUT") or "120")))
