@app.post("/api/comfyui/upload-base64")
async def upload_comfyui_base64(payload: Base64UploadRequest):
    """base64 方式把图片传到 ComfyUI 各后端的 input 目录，返回 comfy 用文件名（供 UXP 做 ComfyUI 图生图）。"""
    raw = (payload.data or "").strip()
    ct = (payload.content_type or "").split(";", 1)[0].strip().lower()
    if raw.startswith("data:"):
        header, _, raw = raw.partition(",")
        if not ct:
            ct = header[5:].split(";", 1)[0].strip().lower()
    try:
        content = base64.b64decode(raw, validate=False)
    except Exception:
        raise HTTPException(status_code=400, detail="数据无法解码")
    if not content:
        raise HTTPException(status_code=400, detail="内容为空")
    _, ext = _local_upload_kind_ext(payload.name or "", ct or "image/png")
    filename = f"dx_{uuid.uuid4().hex[:12]}{ext or '.png'}"
    comfy_name = None

    def push_to_backends():
        """逐个后端上传；每台最长 10 秒超时，必须离开事件循环执行。"""
        name = None
        for addr in COMFYUI_INSTANCES:
            try:
                resp = requests.post(f"http://{addr}/upload/image",
                                     files={'image': (filename, content, ct or 'image/png')}, timeout=10)
                if resp.status_code == 200:
                    name = resp.json().get("name", filename)
            except Exception as exc:
                print(f"ComfyUI base64 upload error for {addr}: {exc}")
        return name

    comfy_name = await asyncio.to_thread(push_to_backends)
    if not comfy_name:
        raise HTTPException(status_code=502, detail="上传到 ComfyUI 失败")
    return {"name": comfy_name}

_local_upload_kind_ext = local_asset_catalog.media_type
_local_upload_display_name = local_asset_catalog.display_name


def _local_upload_rel_path(value):
    checked = asset_kernel.relative_path(value)
    if checked.get("error"):
        raise HTTPException(status_code=400, detail=checked["error"])
    return checked["rel"]

def _local_upload_abs(rel):
    checked = asset_kernel.contained(LOCAL_UPLOAD_DIR, rel)
    relative = checked.get("rel")
    if checked.get("error") or (relative and not media_paths.path_under(LOCAL_UPLOAD_DIR, relative)):
        raise HTTPException(status_code=400, detail="非法路径")
    return relative, checked["path"]


def _local_upload_safe_path(name):
    filename, path = _local_upload_abs(name)
    if not filename:
        raise HTTPException(status_code=400, detail="文件名不能为空")
    return filename, path

def _local_upload_safe_folder(path_value):
    rel, path = _local_upload_abs(path_value)
    return rel, path

def _local_upload_safe_folder_name(name):
    named = asset_kernel.folder_label(name)
    if named.get("error"):
        raise HTTPException(status_code=int(named.get("status") or 400), detail=named["error"])
    return named["name"]

def _local_upload_safe_file_stem(name):
    named = asset_kernel.file_stem(name)
    if named.get("error"):
        raise HTTPException(status_code=int(named.get("status") or 400), detail=named["error"])
    return named["name"]

def _local_upload_caption_path(filename):
    return str(local_asset_catalog.annotation_path(Path(LOCAL_UPLOAD_DIR, filename), ".txt"))


def _local_upload_item(filename, *, new_asset=False):
    rel = _local_upload_rel_path(filename)
    item = local_asset_catalog.item(Path(LOCAL_UPLOAD_DIR), rel)
    record = asset_registry_register_media(
        item["url"],
        asset_id=f"asset_{uuid.uuid4().hex[:16]}" if new_asset else "",
        name=item["name"],
        kind=item["kind"],
        source="local_upload",
        created_at=item["created_at"],
    )
    if record and registry_is_asset_id(record.get("id")):
        item["asset_id"] = record["id"]
    return item

def _local_upload_folder_order_path():
    return os.path.join(DATA_DIR, "local_asset_folder_order.json")

def _local_upload_folder_orders():
    path = _local_upload_folder_order_path()
    if not os.path.isfile(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        _backup_unreadable_data_file(path, "本地素材文件夹排序")
        return {}

def _save_local_upload_folder_orders(orders):
    _atomic_write_json_file(_local_upload_folder_order_path(), orders)

def _local_upload_tree_and_items():
    with STORAGE_SETTINGS_LOCK:
        return local_asset_catalog.tree(LOCAL_UPLOAD_DIR, _local_upload_folder_orders(), _local_upload_item)


_local_upload_media_url = local_asset_catalog.media_url


def _local_upload_companion_paths(rel: str) -> List[str]:
    return [
        _local_upload_caption_path(rel),
        _local_upload_classification_path(rel),
    ]


def _local_upload_asset_record(rel: str) -> Dict[str, Any]:
    item = _local_upload_item(rel)
    asset_id = str(item.get("asset_id") or "")
    if not registry_is_asset_id(asset_id):
        raise HTTPException(status_code=500, detail="本地素材索引登记失败")
    record = ASSET_REGISTRY.get(asset_id)
    if not record:
        raise HTTPException(status_code=500, detail="本地素材索引读取失败")
    return record


def _trash_local_upload_asset(rel: str, *, reason: str = "local_asset_delete") -> str:
    record = _local_upload_asset_record(rel)
    asset_id = str(record.get("id") or "")
    asset_registry_require_unreferenced(asset_id)
    _asset_registry_trash_media(
        asset_id,
        reason=reason,
        companion_paths=_local_upload_companion_paths(rel),
    )
    return asset_id


def _register_local_upload_repair(old_name, new_name):
    old_url = _local_upload_media_url(old_name)
    new_url = _local_upload_media_url(new_name)

    def update(url, name):
        return ASSET_REGISTRY.register(
            url=url, requested_id=original["id"], source=original["source"],
            size=original["size"], mime=content_type_for_path(name),
        )

    with ASSET_REGISTRY.batch():
        original = ASSET_REGISTRY.find_by_url(old_url) or asset_registry_register_media(old_url, source="local_upload")
        if not original or original.get("deleted_at") or original.get("canonical_url") not in {old_url, new_url}:
            return None
        existing_target = ASSET_REGISTRY.find_by_url(new_url)
        if existing_target and existing_target["id"] != original["id"]:
            return None
        if not update(new_url, new_name):
            return None

    def undo():
        with ASSET_REGISTRY.batch():
            update(old_url, old_name)

    return undo


def repair_local_upload_names():
    count = local_media_repair.repair(LOCAL_UPLOAD_DIR, _register_local_upload_repair)
    if count:
        print(f"已修复 {count} 个本地素材文件名")
    return count


@app.post("/api/local-assets/upload")
async def upload_local_assets(files: List[UploadFile] = File(...), folder: str = Form("")):
    uploaded = []
    folder_rel, folder_abs = _local_upload_safe_folder(folder)
    os.makedirs(folder_abs, exist_ok=True)
    for file in files:
        content = await file.read()
        if not content:
            continue
        kind, ext = _local_upload_kind_ext(file.filename, file.content_type)
        if kind is None:
            continue
        base = asset_kernel.upload_stem(file.filename, "file")
        filename = f"up_{uuid.uuid4().hex[:12]}_{base}{ext}"
        rel_name = media_type_rel(f"{folder_rel}/{filename}".lstrip("/"))
        path = media_path_in(LOCAL_UPLOAD_DIR, rel_name)
        with open(path, "wb") as f:
            f.write(content)
        if kind == "image":
            await _classify_new_local_upload(rel_name, path)
        uploaded.append(_local_upload_item(rel_name))
    return {"files": uploaded}

@app.post("/api/local-assets/import-urls")
async def import_local_assets_from_urls(payload: LocalAssetUrlImportRequest):
    folder, directory = await asyncio.to_thread(
        local_asset_imports.destination, LOCAL_UPLOAD_DIR, payload.folder, payload.folder_parent, payload.folder_name,
    )
    files = []
    results = []
    async with local_asset_imports.http_client() as client:
        for entry in payload.items[:200]:
            url = entry.url.strip()
            result = {"url": url, "ok": False, "file": "", "error": ""}
            try:
                content, mime, source_path = await local_asset_imports.read(entry, client, output_file_from_url)
                kind, extension = _local_upload_kind_ext(source_path, mime)
                if kind not in {"image", "video"}:
                    raise ValueError(f"不是图片或视频资源：{mime or url}")
                if kind == "image":
                    detected = local_media_repair.sniff_image(content[:16])
                    if detected and not (detected == ".jpg" and extension == ".jpeg"):
                        extension = detected
                relative, path = await asyncio.to_thread(
                    local_asset_imports.save, directory, folder, content, entry.name, source_path, kind, extension,
                )
                if payload.classify and kind == "image":
                    await _classify_new_local_upload(
                        relative, str(path), payload.provider, payload.model, payload.ms_model, payload.prompt,
                    )
                item = await asyncio.to_thread(_local_upload_item, relative, new_asset=True)
                files.append(item)
                result.update(ok=True, file=relative, item=item)
            except HTTPException as exc:
                result["error"] = str(exc.detail or "导入失败")
            except Exception as exc:
                result["error"] = str(exc) or "导入失败"
            results.append(result)
    return {"ok": True, "count": len(files), "files": files, "items": results, "folder": folder}


