@app.get("/api/local-assets")
async def list_local_assets():
    tree, items = await asyncio.to_thread(_local_upload_tree_and_items)
    return {"items": items, "tree": tree}

@app.post("/api/local-assets/folders")
async def create_local_asset_folder(payload: LocalAssetFolderRequest, request: Request):
    ensure_same_origin_request(request)
    parent_rel, parent_abs = _local_upload_safe_folder(payload.parent)
    if not os.path.isdir(parent_abs):
        raise HTTPException(status_code=404, detail="父文件夹不存在")
    name = _local_upload_safe_folder_name(payload.name)
    rel = f"{parent_rel}/{name}".lstrip("/")
    _, abs_path = _local_upload_safe_folder(rel)
    if os.path.exists(abs_path):
        raise HTTPException(status_code=400, detail="同名文件夹已存在")
    os.makedirs(abs_path, exist_ok=False)
    ensure_media_type_dirs(abs_path)
    tree, items = _local_upload_tree_and_items()
    return {"ok": True, "folder": {"path": rel, "name": name}, "tree": tree, "items": items}

@app.post("/api/local-assets/folders/reorder")
async def reorder_local_asset_folders(payload: LocalAssetFolderOrderRequest, request: Request):
    ensure_same_origin_request(request)
    with STORAGE_SETTINGS_LOCK:
        parent_rel, parent_abs = _local_upload_safe_folder(payload.parent)
        if not os.path.isdir(parent_abs):
            raise HTTPException(status_code=404, detail="父文件夹不存在")
        parent = PurePosixPath(parent_rel)
        actual = {(parent / name).as_posix() for name in local_asset_catalog.child_folders(parent_abs)}
        paths = [_local_upload_safe_folder(path)[0] for path in payload.paths]
        if not asset_kernel.same_members(paths, actual):
            raise HTTPException(status_code=409, detail="文件夹列表已变化，请刷新后重试")
        orders = _local_upload_folder_orders()
        orders[parent_rel] = [PurePosixPath(path).name for path in paths]
        _save_local_upload_folder_orders(orders)
    tree, items = _local_upload_tree_and_items()
    return {"ok": True, "tree": tree, "items": items}

@app.patch("/api/local-assets/folders")
async def rename_local_asset_folder(payload: LocalAssetFolderRequest, request: Request):
    ensure_same_origin_request(request)
    with STORAGE_SETTINGS_LOCK:
        relative, source = _local_upload_safe_folder(payload.path)
        if not relative:
            raise HTTPException(status_code=400, detail="根目录不能重命名")
        if not os.path.isdir(source):
            raise HTTPException(status_code=404, detail="文件夹不存在")
        name = _local_upload_safe_folder_name(payload.name)
        new_relative = PurePosixPath(relative).with_name(name).as_posix()
        _, destination = _local_upload_safe_folder(new_relative)
        source_prefix = _local_upload_media_url(relative + "/")
        destination_prefix = _local_upload_media_url(new_relative + "/")
        try:
            with local_asset_relocation.rename_folder(source, destination):
                with _local_asset_metadata_transaction(ASSET_FAVORITES_PATH, _local_upload_folder_order_path()):
                    for record in ASSET_REGISTRY.records():
                        url = record.get("canonical_url") or ""
                        if not record.get("deleted_at") and url.startswith(source_prefix):
                            _relocate_local_asset_index(url, destination_prefix + url[len(source_prefix):])
                    _relocate_file_favorites("local", folder_change=(relative, new_relative))
                    orders = _local_upload_folder_orders()
                    if orders:
                        _save_local_upload_folder_orders(local_asset_catalog.move_folder_order(orders, relative, new_relative))
        except FileExistsError as exc:
            raise HTTPException(status_code=400, detail="同名文件夹或素材已存在") from exc
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        except OSError as exc:
            raise HTTPException(status_code=500, detail="重命名本地素材文件夹失败") from exc
    tree, items = _local_upload_tree_and_items()
    return {"ok": True, "folder": {"path": new_relative, "name": name}, "tree": tree, "items": items}


def _trash_local_asset_folder(path):
    with STORAGE_SETTINGS_LOCK:
        relative, location = _local_upload_safe_folder(path)
        if not relative:
            raise HTTPException(status_code=400, detail="根目录不能删除")
        if not os.path.isdir(location):
            return relative, [], True
        try:
            items, folders = local_asset_catalog.removable_folder(LOCAL_UPLOAD_DIR, relative)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        except OSError as exc:
            raise HTTPException(status_code=500, detail="无法读取本地素材文件夹") from exc

        entries = [(_local_upload_asset_record(item)["id"], _local_upload_companion_paths(item)) for item in items]
        asset_registry_require_unreferenced_many([asset_id for asset_id, _ in entries])
        trashed = _asset_registry_trash_media_batch(entries, reason="local_folder_delete")
        try:
            with local_asset_relocation.remove_empty_folders(folders):
                orders = local_asset_catalog.move_folder_order(_local_upload_folder_orders(), relative)
                _save_local_upload_folder_orders(orders)
        except Exception as exc:
            for asset_id in reversed(trashed):
                try:
                    _asset_registry_restore_media(asset_id)
                except Exception:
                    logging.getLogger(__name__).exception("Could not restore a local asset after a failed folder deletion")
            raise HTTPException(status_code=500, detail="删除本地素材文件夹失败") from exc
        return relative, trashed, False


@app.delete("/api/local-assets/folders")
async def delete_local_asset_folder(payload: LocalAssetFolderRequest, request: Request):
    ensure_same_origin_request(request)
    relative, trashed, already_missing = await asyncio.to_thread(_trash_local_asset_folder, payload.path)
    tree, items = _local_upload_tree_and_items()
    result = {
        "ok": True, "folder": {"path": relative, "name": PurePosixPath(relative).name},
        "tree": tree, "items": items, "trashed_asset_ids": trashed,
    }
    if already_missing:
        result["already_missing"] = True
    return result


@contextmanager
def _local_asset_metadata_transaction(*paths):
    def read(path):
        try:
            return path.read_bytes()
        except FileNotFoundError:
            return None

    snapshots = {path: read(path) for path in map(Path, paths)}
    try:
        with ASSET_REGISTRY.batch():
            yield
    except BaseException:
        for path, previous in snapshots.items():
            try:
                if read(path) != previous:
                    if previous is None:
                        path.unlink(missing_ok=True)
                    else:
                        _replace_file_durably(path, lambda handle: handle.write(previous), binary=True)
            except OSError:
                logging.getLogger(__name__).exception("Could not restore local asset metadata")
        raise


def _local_asset_address_in_use(source, destination):
    owner = ASSET_REGISTRY.find_by_url(destination)
    if not owner:
        return False
    original = ASSET_REGISTRY.find_by_url(source)
    return not original or owner["id"] != original["id"]


def _relocate_local_uploads(pairs, *, rename=False):
    def in_use(source, destination):
        return _local_asset_address_in_use(_local_upload_media_url(source), _local_upload_media_url(destination))

    with STORAGE_SETTINGS_LOCK:
        with local_asset_relocation.relocate(LOCAL_UPLOAD_DIR, pairs, in_use=in_use, rename=rename) as changes:
            if changes:
                with _local_asset_metadata_transaction(ASSET_FAVORITES_PATH):
                    for source, destination in changes:
                        _relocate_local_asset_index(_local_upload_media_url(source), _local_upload_media_url(destination))
                    _relocate_file_favorites("local", changes)
            return changes


def _relocate_local_asset_index(source, destination):
    if _local_asset_address_in_use(source, destination):
        raise FileExistsError(destination)
    record = _asset_registry_relocate_url(source, destination)
    if not record or record.get("canonical_url") != destination:
        raise OSError("Local asset index could not be updated")


@app.patch("/api/local-assets/items")
async def rename_local_asset_item(payload: LocalAssetRenameRequest, request: Request):
    ensure_same_origin_request(request)
    rel, source = _local_upload_safe_path(payload.path)
    if not os.path.isfile(source):
        raise HTTPException(status_code=404, detail="本地素材不存在")
    if not _local_upload_kind_ext(rel)[0]:
        raise HTTPException(status_code=400, detail="不支持的素材类型")
    relative = PurePosixPath(rel)
    destination = relative.with_name(_local_upload_safe_file_stem(payload.name) + relative.suffix).as_posix()
    try:
        changes = _relocate_local_uploads([(rel, destination)], rename=True)
    except FileExistsError as exc:
        raise HTTPException(status_code=400, detail="同名素材或标注文件已存在") from exc
    except FileNotFoundError as exc:
        raise HTTPException(status_code=404, detail="本地素材不存在") from exc
    except OSError as exc:
        raise HTTPException(status_code=500, detail="重命名本地素材失败") from exc
    tree, items = _local_upload_tree_and_items()
    result = {"ok": True, "item": _local_upload_item(destination), "tree": tree, "items": items}
    if changes:
        result["old_path"] = rel
    return result


@app.post("/api/local-assets/delete")
async def delete_local_assets(payload: dict, request: Request):
    ensure_same_origin_request(request)
    names = payload.get("names") if isinstance(payload, dict) else None
    if not isinstance(names, list):
        names = []
    candidates = []
    for name in names:
        try:
            rel, path = _local_upload_safe_path(name)
        except HTTPException:
            continue
        if os.path.isfile(path):
            record = _local_upload_asset_record(rel)
            candidates.append((rel, str(record.get("id") or "")))
    asset_registry_require_unreferenced_many([asset_id for _rel, asset_id in candidates])
    trashed = []
    try:
        trashed_ids = _asset_registry_trash_media_batch(
            [
                (asset_id, _local_upload_companion_paths(rel))
                for rel, asset_id in candidates
            ],
            reason="local_asset_delete",
        )
        trashed = [(rel, asset_id) for rel, asset_id in candidates if asset_id in trashed_ids]
    except Exception:
        for _rel, asset_id in reversed(trashed):
            try:
                _asset_registry_restore_media(asset_id)
            except Exception:
                pass
        raise
    return {"deleted": [rel for rel, _asset_id in trashed], "trashed_asset_ids": [asset_id for _rel, asset_id in trashed]}

@app.post("/api/local-assets/move")
async def move_local_assets(payload: dict, request: Request):
    ensure_same_origin_request(request)
    names = payload.get("names")
    if not isinstance(names, list) or not names:
        raise HTTPException(status_code=400, detail="没有选择素材")
    folder, directory = _local_upload_safe_folder(payload.get("folder"))
    if folder and not os.path.isdir(directory):
        raise HTTPException(status_code=404, detail="目标文件夹不存在")
    pairs = []
    for name in names:
        try:
            relative, _ = _local_upload_safe_path(name)
        except HTTPException:
            continue
        if _local_upload_kind_ext(relative)[0]:
            target = media_type_rel((PurePosixPath(folder) / PurePosixPath(relative).name).as_posix())
            if target != relative:
                os.makedirs(os.path.dirname(os.path.join(LOCAL_UPLOAD_DIR, target)), exist_ok=True)
                pairs.append((relative, target))
    try:
        changes = _relocate_local_uploads(pairs)
    except OSError as exc:
        raise HTTPException(status_code=500, detail="保存素材移动结果失败") from exc
    tree, items = _local_upload_tree_and_items()
    return {"ok": True, "moved": len(changes), "items": items, "tree": tree}


