async def discover_runninghub_entry(provider, kind, identifier, *, use_wallet=False):
    if kind == "app":
        data = await fetch_runninghub_app_info(provider, identifier, use_wallet=use_wallet)
        graph = {}
        fields = runninghub_entries.app_fields(data)
    else:
        graph, _ = await fetch_runninghub_workflow_graph(identifier, provider, use_wallet=use_wallet)
        fields = runninghub_entries.recovered_workflow_fields(graph)
    if not fields:
        raise HTTPException(status_code=404, detail="RunningHub 未返回可用参数。请确认应用或工作流仍可访问。")
    return {"kind": kind, "id": identifier, "fields": fields, "optionalImageMode": "keep-workflow",
            "workflowJson": graph}


