@app.get("/api/codex/status")
async def codex_status():
    exe = codex_cli_executable()
    image2_exe = gpt_image_2_skill_executable()
    capabilities = await detect_codex_image_capabilities()
    image_connection = {}
    if image2_exe:
        try:
            image_args, image_provider = gpt_image_2_skill_provider_args(gpt_image_2_skill_auth_file())
            image_connection["provider"] = image_provider
            if "--openai-api-base" in image_args:
                image_connection["api_base"] = image_args[image_args.index("--openai-api-base") + 1]
        except HTTPException as exc:
            image_connection["error"] = str(exc.detail)
    if not exe:
        return {
            "installed": False,
            "logged_in": False,
            "image2_helper_installed": bool(image2_exe),
            "image2_helper_path": image2_exe,
            "image_connection": image_connection,
            "image_models": capabilities.get("image_models") or CODEX_DEFAULT_IMAGE_MODELS,
            "image_capabilities": {
                "probe_ok": bool(capabilities.get("probe_ok")),
                "has_gpt_image_25": bool(capabilities.get("has_gpt_image_25")),
            },
            "message": "未找到 OpenAI Codex CLI，请先安装。",
        }
    try:
        proc = await asyncio.create_subprocess_exec(
            exe,
            "--version",
            cwd=BASE_DIR,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=10)
        out_text, err_text = codex_decode_output(stdout, stderr)
        ok = proc.returncode == 0
        helper_message = (
            capabilities.get("message")
            if image2_exe
            else "GPT CLI 生图组件未安装或路径已失效，请在 API 设置中点击“安装 / 更新”。"
        )
        if image_connection.get("error"):
            helper_message = f"{helper_message} {image_connection['error']}"
        elif image_connection.get("api_base"):
            helper_message = f"生图使用 API Key，请求地址：{image_connection['api_base']}。{helper_message}"
        return {
            "installed": ok,
            "logged_in": None,
            "version": out_text or err_text,
            "path": exe,
            "image2_helper_installed": bool(image2_exe),
            "image2_helper_path": image2_exe,
            "image_connection": image_connection,
            "image_models": capabilities.get("image_models") or CODEX_DEFAULT_IMAGE_MODELS,
            "image_capabilities": {
                "probe_ok": bool(capabilities.get("probe_ok")),
                "has_gpt_image_25": bool(capabilities.get("has_gpt_image_25")),
            },
            "message": f"OpenAI Codex CLI 已安装。{helper_message} 登录状态会在首次执行 codex exec 时由 CLI 校验。" if ok else (err_text or out_text or "Codex CLI 检测失败"),
            "raw": {"stdout": out_text, "stderr": err_text, "returncode": proc.returncode},
        }
    except Exception as exc:
        return {
            "installed": False,
            "logged_in": False,
            "path": exe,
            "image2_helper_installed": bool(image2_exe),
            "image2_helper_path": image2_exe,
            "image_connection": image_connection,
            "image_models": capabilities.get("image_models") or CODEX_DEFAULT_IMAGE_MODELS,
            "image_capabilities": {
                "probe_ok": bool(capabilities.get("probe_ok")),
                "has_gpt_image_25": bool(capabilities.get("has_gpt_image_25")),
            },
            "message": f"Codex CLI 检测失败：{exc}",
        }

@app.post("/api/codex/help")
async def codex_help(payload: CodexHelpRequest):
    exe = codex_cli_executable()
    if not exe:
        raise HTTPException(status_code=400, detail="未找到 OpenAI Codex CLI。")
    allowed = {"", "exec", "login", "logout", "doctor", "mcp", "app", "update"}
    command = str(payload.command or "").strip()
    if command not in allowed:
        raise HTTPException(status_code=400, detail="不允许的 Codex CLI 命令")
    args = [exe]
    if command:
        args.append(command)
    args.append("--help")
    proc = await asyncio.create_subprocess_exec(
        *args,
        cwd=BASE_DIR,
        stdout=asyncio.subprocess.PIPE,
        stderr=asyncio.subprocess.PIPE,
    )
    stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=20)
    out_text, err_text = codex_decode_output(stdout, stderr)
    if proc.returncode != 0:
        raise HTTPException(status_code=502, detail=(err_text or out_text or f"exit={proc.returncode}")[:1000])
    return {"text": out_text or err_text, "raw": {"stdout": out_text, "stderr": err_text}}

