@app.post("/api/jimeng/query-media")
async def jimeng_query_media(payload: JimengQueryMediaRequest):
    """按 submit_id 续查即梦任务：出图返回 succeeded+urls；仍排队返回 pending+queue_info；失败返回 failed。
    供画布「排队中」卡片自动轮询与手动查询复用。"""
    submit_id = str(payload.submit_id or "").strip()
    if not submit_id:
        raise HTTPException(status_code=400, detail="缺少 submit_id")
    kind = str(payload.kind or "image").strip().lower()
    if kind not in ("image", "video", "audio"):
        kind = "image"
    queried = await jimeng_query_result(submit_id, kind)
    try:
        urls = await jimeng_store_outputs(queried, kind, allow_query=False, queried_id=submit_id)
        if kind == "image":
            with CANVAS_TASK_LOCK:
                output_size = next((task.get("request", {}).get("output_size")
                                    for task in CANVAS_TASKS.values()
                                    if task.get("submit_id") == submit_id), "")
            if output_size:
                result = await asyncio.to_thread(fit_image_result_to_size, {"images": urls}, output_size)
                urls = result["images"]
        return {"status": "succeeded", "submit_id": submit_id, "kind": kind, "urls": urls}
    except JimengPendingError as exc:
        return {"status": "pending", "submit_id": submit_id, "kind": kind, "queue_info": exc.queue_info, "message": jimeng_pending_payload(exc)["message"]}
    except HTTPException as exc:
        return {"status": "failed", "submit_id": submit_id, "kind": kind, "error": str(getattr(exc, "detail", "") or exc)}

def canvas_reference_image_limits(providers):
    limits = {}
    for provider in providers:
        model_limits = {}
        for model in provider.get("image_models") or []:
            caps = product_fidelity_capabilities(provider, model)
            maximum = caps.get("maxReferenceImages") or ONLINE_IMAGE_REFERENCE_MAX
            protocol = effective_protocol(provider, model)
            if protocol == "gemini-cli" and is_antigravity_cli(gemini_cli_executable()):
                maximum = min(maximum, 3)
            elif protocol == "volcengine":
                maximum = volcengine_images.reference_limit(model, maximum)
            model_limits[model] = min(ONLINE_IMAGE_REFERENCE_MAX, maximum)
        limits[provider["id"]] = model_limits
    return {"default": ONLINE_IMAGE_REFERENCE_MAX, "models": limits}


