def _canvas_harness_trim(value, max_chars=12000, depth=0):
    if depth > 4:
        return str(value)[:500]
    if isinstance(value, dict):
        result = {}
        for key, item in list(value.items())[:100]:
            result[str(key)] = _canvas_harness_trim(item, max_chars, depth + 1)
        return result
    if isinstance(value, list):
        return [_canvas_harness_trim(item, max_chars, depth + 1) for item in value[:100]]
    if isinstance(value, str):
        return value[:max_chars]
    return value


def _canvas_harness_context(run_id):
    return CANVAS_AGENT_RUN_CONTEXT.get(str(run_id)) or {}


def _canvas_harness_asset_matches(args):
    query = str((args or {}).get("query") or "").strip().lower()
    try:
        library = load_asset_library()
    except Exception:
        library = {}
    items = []
    for category in library.get("categories") or []:
        category_name = str(category.get("name") or category.get("id") or "")
        for item in category.get("items") or []:
            if not isinstance(item, dict):
                continue
            haystack = " ".join(str(item.get(key) or "") for key in ("name", "title", "tags", "description", "url")).lower()
            if query and query not in haystack and query not in category_name.lower():
                continue
            items.append({
                "id": str(item.get("id") or ""),
                "name": str(item.get("name") or item.get("title") or "未命名素材")[:120],
                "url": str(item.get("url") or "")[:2000],
                "kind": str(item.get("kind") or item.get("type") or "image"),
                "category": category_name[:80],
            })
    limit = max(1, min(30, int((args or {}).get("limit") or 20)))
    return {"items": items[:limit], "count": len(items)}


def _canvas_harness_product_snapshots(args, context):
    requested = (args or {}).get("job_ids") or context.get("payload", {}).get("link_job_ids") or []
    result = []
    for job_id in [str(item).strip() for item in requested[:3] if str(item).strip()]:
        try:
            job = _commerce_analysis_get_job(job_id)
        except Exception:
            job = None
        if not job:
            result.append({"job_id": job_id, "status": "not_found"})
            continue
        snapshot = {
            "job_id": job_id,
            "status": job.get("status") or "",
            "url": job.get("url") or job.get("source_url") or "",
            "title": job.get("title") or "",
            "result": _canvas_harness_trim(job.get("result") or {}, 8000),
        }
        result.append(snapshot)
    return {"snapshots": result}


def _canvas_harness_task_snapshots(args):
    ids = {str(item).strip() for item in ((args or {}).get("task_ids") or []) if str(item).strip()}
    with CANVAS_TASK_LOCK:
        values = list(CANVAS_TASKS.values())
    tasks = []
    for item in values:
        if ids and str(item.get("id") or item.get("task_id") or "") not in ids:
            continue
        tasks.append({
            "id": str(item.get("id") or item.get("task_id") or ""),
            "status": item.get("status") or "",
            "provider": item.get("provider") or "",
            "model": item.get("model") or "",
            "error": item.get("error") or item.get("detail") or "",
            "updated_at": item.get("updated_at") or 0,
        })
    return {"tasks": tasks[:30]}


def _canvas_harness_risk(tool: str, args: Dict[str, Any]):
    tool = str(tool or "")
    args = args if isinstance(args, dict) else {}
    if tool == "xiaomei_delete_nodes":
        return "删除画布节点"
    if tool == "xiaomei_generate_images":
        count = int(args.get("count") or 1)
        if count > 1 or len(args.get("node_ids") or []) > 1:
            return f"批量生图（{count} 张或多个节点）"
    if tool == "xiaomei_browser_action":
        action = str(args.get("action") or "").lower()
        text = str(args.get("text") or "").lower()
        if action in {"submit", "publish", "buy", "checkout", "confirm"} or re.search(
            r"提交|发布|购买|下单|支付|确认|保存|同意", text,
        ):
            return "网页提交/发布动作"
    if tool == "xiaomei_apply_workflow":
        workflow = args.get("workflow") if isinstance(args.get("workflow"), dict) else {}
        count = 1
        for node in workflow.get("nodes") or []:
            settings = node.get("settings") if isinstance(node, dict) else {}
            count = max(count, int((settings or {}).get("count") or 1))
        if count > 1:
            return f"批量生图（{count} 张）"
    return ""


async def _canvas_harness_wait_for_approval(run_id: str, tool: str, args: Dict[str, Any], reason: str):
    loop = asyncio.get_running_loop()
    future = loop.create_future()
    approval_id = f"approval_{uuid.uuid4().hex[:16]}"
    CANVAS_AGENT_RUN_APPROVALS[str(run_id)] = future
    _canvas_agent_run_update(
        run_id,
        status="awaiting_approval",
        stage="approval",
        pending_approval={
            "id": approval_id,
            "tool": tool,
            "reason": reason,
            "arguments": _canvas_harness_trim(args, 4000),
        },
        event={
            "type": "approval_required",
            "stage": "approval",
            "message": f"需要确认：{reason}",
            "approval_id": approval_id,
        },
    )
    try:
        approved = await asyncio.wait_for(future, timeout=CANVAS_AGENT_RUN_APPROVAL_TIMEOUT_SECONDS)
    except asyncio.TimeoutError:
        approved = False
        _canvas_agent_run_add_event(run_id, f"确认超时，已拒绝：{reason}", "approval", "error")
    finally:
        CANVAS_AGENT_RUN_APPROVALS.pop(str(run_id), None)
    _canvas_agent_run_update(
        run_id,
        status="running",
        stage="executing",
        pending_approval=None,
        event={
            "type": "approval_resolved",
            "stage": "executing",
            "message": f"用户已{'确认' if approved else '拒绝'}：{reason}",
            "approved": bool(approved),
        },
    )
    return bool(approved)


async def _canvas_harness_dispatch_tool(run_id: str, namespace: str, tool: str, arguments: Any):
    context = _canvas_harness_context(run_id)
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except Exception:
            arguments = {}
    args = arguments if isinstance(arguments, dict) else {}
    if CANVAS_AGENT_RUN_INTERRUPTS.get(str(run_id), asyncio.Event()).is_set():
        return {"ok": False, "error": "任务已被用户停止"}
    _canvas_agent_run_add_event(run_id, f"Harness 调用工具：{tool}", "tool", "tool_call", tool=tool)
    if tool == "xiaomei_read_canvas_context":
        payload = context.get("payload") or {}
        return {
            "ok": True,
            "task_scope": _canvas_harness_trim(payload.get("task_scope") or {}, 6000),
            "canvas_context": _canvas_harness_trim(payload.get("canvas_context") or {}, 10000),
        }
    if tool == "xiaomei_search_assets":
        return {"ok": True, **_canvas_harness_asset_matches(args)}
    if tool == "xiaomei_read_product_snapshot":
        return {"ok": True, **_canvas_harness_product_snapshots(args, context)}
    if tool == "xiaomei_query_tasks":
        return {"ok": True, **_canvas_harness_task_snapshots(args)}

    risk = _canvas_harness_risk(tool, args)
    if risk:
        approved = await _canvas_harness_wait_for_approval(run_id, tool, args, risk)
        if not approved:
            return {"ok": False, "approved": False, "error": f"用户未确认：{risk}"}

    operation = None
    if tool == "xiaomei_create_nodes":
        nodes = [item for item in (args.get("nodes") or []) if isinstance(item, dict)][:8]
        operation = {"kind": "create_nodes", "nodes": _canvas_harness_trim(nodes, 8000)}
        result = {"ok": True, "accepted": True, "operation": operation, "message": f"已登记 {len(nodes)} 个节点，等待画布执行器落图"}
    elif tool == "xiaomei_connect_nodes":
        connections = [item for item in (args.get("connections") or []) if isinstance(item, dict)][:20]
        operation = {"kind": "connect_nodes", "connections": _canvas_harness_trim(connections, 8000)}
        result = {"ok": True, "accepted": True, "operation": operation, "message": f"已登记 {len(connections)} 条连线，等待画布执行器校验"}
    elif tool == "xiaomei_generate_images":
        operation = {
            "kind": "generate_images",
            "node_ids": [str(item)[:100] for item in (args.get("node_ids") or [])[:8]],
            "prompt": str(args.get("prompt") or "")[:6000],
            "settings": _canvas_harness_trim(args.get("settings") or {}, 2000),
            "count": max(1, min(8, int(args.get("count") or 1))),
        }
        result = {"ok": True, "accepted": True, "operation": operation, "message": "生成请求已登记，等待画布任务执行器提交"}
    elif tool == "xiaomei_delete_nodes":
        operation = {"kind": "delete_nodes", "node_ids": [str(item)[:100] for item in (args.get("node_ids") or [])[:30]], "reason": str(args.get("reason") or "")[:1000]}
        result = {"ok": True, "approved": True, "accepted": True, "operation": operation, "message": "删除动作已确认，等待浏览器画布执行"}
    elif tool == "xiaomei_browser_action":
        operation = {"kind": "browser_action", **{key: str(args.get(key) or "")[:2000] for key in ("action", "url", "text")}}
        result = {"ok": True, "approved": True, "accepted": True, "operation": operation, "message": "网页动作已确认，等待宿主执行"}
    elif tool == "xiaomei_apply_workflow":
        workflow = args.get("workflow") if isinstance(args.get("workflow"), dict) else {}
        option_id = str(args.get("option_id") or "1")[:8]
        context["selected_option_id"] = option_id
        operation = {"kind": "apply_workflow", "workflow": _canvas_harness_trim(workflow, 16000), "option_id": option_id}
        result = {"ok": True, "accepted": True, "operation": operation, "message": "完整工作流已登记，浏览器将复用现有计划执行器"}
    elif tool == "xiaomei_finish":
        summary = str(args.get("summary") or "Harness 已完成编排")[:2000]
        context["final_summary"] = summary
        result = {"ok": True, "message": summary}
    else:
        return {"ok": False, "error": f"未注册的画布工具：{tool}"}
    if operation:
        context.setdefault("operations", []).append(operation)
        _canvas_agent_run_update(
            run_id,
            operations=_canvas_harness_trim(context["operations"], 30000),
            selected_option_id=str(context.get("selected_option_id") or "1"),
        )
    _canvas_agent_run_add_event(run_id, result.get("message") or "工具已完成", "tool", "tool_result", tool=tool)
    return result


async def _canvas_harness_send(proc, message):
    if proc.stdin is None:
        raise RuntimeError("Codex App Server 输入通道不可用")
    proc.stdin.write((json.dumps(message, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8"))
    await proc.stdin.drain()


async def _canvas_harness_read(proc, timeout):
    if proc.stdout is None:
        raise RuntimeError("Codex App Server 输出通道不可用")
    line = await asyncio.wait_for(proc.stdout.readline(), timeout=max(1.0, float(timeout)))
    if not line:
        code = proc.returncode
        raise RuntimeError(f"Codex App Server 已退出（{code if code is not None else '未知'}）")
    try:
        return json.loads(line.decode("utf-8", errors="replace"))
    except Exception:
        return {"method": "app-server/invalid-output", "params": {"text": line.decode("utf-8", errors="replace")[:1000]}}


def _canvas_harness_agent_delta(context, params):
    value = params.get("delta") if isinstance(params, dict) else ""
    if isinstance(value, dict):
        value = value.get("text") or value.get("delta") or ""
    text = str(value or "")
    if text:
        context["agent_text"] = (str(context.get("agent_text") or "") + text)[-12000:]
    return text


async def _canvas_harness_handle_message(proc, run_id: str, message: Dict[str, Any]):
    method = str(message.get("method") or "")
    params = message.get("params") if isinstance(message.get("params"), dict) else {}
    if method == "item/tool/call":
        call = await _canvas_harness_dispatch_tool(
            run_id,
            str(params.get("namespace") or ""),
            str(params.get("tool") or ""),
            params.get("arguments"),
        )
        content = {"type": "inputText", "text": json.dumps(_canvas_harness_trim(call, 12000), ensure_ascii=False)}
        await _canvas_harness_send(proc, {
            "id": message.get("id"),
            "result": {"contentItems": [content], "success": bool(call.get("ok", False))},
        })
        return
    if method in {"item/commandExecution/requestApproval", "item/fileChange/requestApproval", "execCommandApproval", "applyPatchApproval"}:
        _canvas_agent_run_add_event(run_id, "Harness 请求了代码/文件权限，已按画布安全策略拒绝", "approval", "error")
        await _canvas_harness_send(proc, {"id": message.get("id"), "result": {"decision": "decline"}})
        return
    if method == "item/permissions/requestApproval":
        _canvas_agent_run_add_event(run_id, "Harness 请求了额外权限，已按画布安全策略拒绝", "approval", "error")
        await _canvas_harness_send(proc, {"id": message.get("id"), "result": {"permissions": []}})
        return
    if method == "item/tool/requestUserInput":
        _canvas_agent_run_add_event(run_id, "Harness 请求交互式输入，画布暂不自动代填", "approval", "error")
        await _canvas_harness_send(proc, {"id": message.get("id"), "result": {"answers": []}})
        return
    if method == "item/agentMessage/delta":
        context = _canvas_harness_context(run_id)
        _canvas_harness_agent_delta(context, params)
        return
    if method == "item/started":
        item = params.get("item") or {}
        item_type = str(item.get("type") or "") if isinstance(item, dict) else ""
        if item_type:
            _canvas_agent_run_add_event(run_id, f"Harness 开始：{item_type}", "executing", "item_started")
        return
    if method == "item/completed":
        item = params.get("item") or {}
        item_type = str(item.get("type") or "") if isinstance(item, dict) else ""
        if item_type == "dynamicToolCall":
            _canvas_agent_run_add_event(run_id, "工具调用已完成", "tool", "item_completed")
        return
    if method == "thread/status/changed":
        return
    if method == "turn/started":
        turn = params.get("turn") or {}
        _canvas_agent_run_update(run_id, turn_id=str(turn.get("id") or ""))
        return
    if method == "turn/completed":
        turn = params.get("turn") or {}
        status = str(turn.get("status") or "completed")
        if status in {"failed", "interrupted"}:
            detail = ((turn.get("error") or {}).get("message") if isinstance(turn.get("error"), dict) else "") or f"Harness turn {status}"
            raise RuntimeError(str(detail))
        return


async def _canvas_harness_request(proc, run_id: str, request_id: int, method: str, params: Dict[str, Any], timeout: float):
    await _canvas_harness_send(proc, {"method": method, "id": request_id, "params": params})
    while True:
        message = await _canvas_harness_read(proc, timeout)
        if message.get("id") == request_id:
            if message.get("error"):
                error = message.get("error") or {}
                raise RuntimeError(str(error.get("message") or f"App Server 请求失败：{method}"))
            return message.get("result") or {}
        await _canvas_harness_handle_message(proc, run_id, message)


def _canvas_harness_turn_input(context):
    payload = context.get("payload") or {}
    plan = context.get("plan") or {}
    safe = {
        "user_task": str(payload.get("message") or "")[:12000],
        "recommended_plan": _canvas_harness_trim(plan, 26000),
        "task_scope": _canvas_harness_trim(payload.get("task_scope") or {}, 6000),
        "canvas_context": _canvas_harness_trim(payload.get("canvas_context") or {}, 12000),
        "generation_preferences": _canvas_harness_trim(payload.get("generation_preferences") or {}, 2000),
        "link_job_ids": [str(item) for item in (payload.get("link_job_ids") or [])[:3]],
    }
    return (
        "请编排并执行这次小美画布任务。你必须使用 xiaomei_* 工具完成读取、登记工作流和状态查询；"
        "不得使用 shell、文件修改、代码修改或外部网页指令。先读取画布上下文；然后选择 recommended_plan 的一个方案，"
        "调用 xiaomei_create_nodes / xiaomei_connect_nodes / xiaomei_generate_images 或直接调用 xiaomei_apply_workflow；"
        "最后调用 xiaomei_finish。删除、网页提交/发布/购买、批量生图会自动暂停等待用户确认。"
        "工具返回的是待浏览器执行的操作，不要声称图片已经完成，除非 xiaomei_query_tasks 明确返回完成。\n\n"
        f"任务上下文 JSON：{json.dumps(safe, ensure_ascii=False, separators=(',', ':'))}"
    )


async def _run_canvas_agent_orchestration(run_id: str):
    context = _canvas_harness_context(run_id)
    payload = context.get("payload") or {}
    proc = None
    try:
        _canvas_agent_run_update(run_id, status="running", stage="analyzing")
        _canvas_agent_run_add_event(run_id, "保留现有 canvas-llm，开始分析图片、商品快照和当前任务范围", "analyzing")
        plan_result = await canvas_plan(CanvasPlanRequest(
            message=str(payload.get("message") or ""),
            system_prompt=str(payload.get("system_prompt") or ""),
            model=str(payload.get("model") or ""),
            messages=list(payload.get("messages") or [])[-12:],
            provider=str(payload.get("provider") or "comfly"),
            ms_model=str(payload.get("ms_model") or ""),
            images=list(payload.get("images") or [])[:8],
            skill_id=str(payload.get("skill_id") or ""),
            current_node_id=str(payload.get("current_node_id") or ""),
            canvas_context=dict(payload.get("canvas_context") or {}),
            generation_preferences=dict(payload.get("generation_preferences") or {}),
            link_job_ids=list(payload.get("link_job_ids") or [])[:3],
            allow_persistent_agent=False,
        ))
        context["plan"] = plan_result.get("plan") if isinstance(plan_result, dict) else None
        _canvas_agent_run_update(
            run_id,
            plan=_canvas_harness_trim(context.get("plan") or {}, 30000),
            stage="planned",
            event={"type": "plan_ready", "stage": "planned", "message": "canvas-llm 已生成结构化任务计划"},
        )
        command = _canvas_harness_command()
        if not command:
            raise RuntimeError("未找到 Codex CLI，无法启动 App Server")
        _canvas_agent_run_add_event(run_id, "Codex App Server 已接管计划执行", "harness")
        harness_cwd = os.path.abspath(tempfile.gettempdir())
        creation_kwargs = {
            "stdin": asyncio.subprocess.PIPE,
            "stdout": asyncio.subprocess.PIPE,
            "stderr": asyncio.subprocess.DEVNULL,
            "cwd": harness_cwd,
        }
        if os.name == "nt":
            creation_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = await asyncio.create_subprocess_exec(*command, **creation_kwargs)
        initialize = {
            "clientInfo": {"name": "xiaomei_canvas", "title": "小美画布", "version": APP_VERSION},
            "capabilities": {"experimentalApi": True},
        }
        await _canvas_harness_request(proc, run_id, 1, "initialize", initialize, 45)
        await _canvas_harness_send(proc, {"method": "initialized", "params": {}})
        start_params = {
            "cwd": harness_cwd,
            "approvalPolicy": "never",
            "sandbox": "read-only",
            "ephemeral": True,
            "serviceName": "xiaomei_canvas_agent",
            "developerInstructions": (
                "你是小美画布的执行 Harness。只允许调用 xiaomei_* 动态工具；"
                "不要使用 shell、文件系统、代码修改或任何未列出的工具。"
            ),
            "dynamicTools": _canvas_harness_tool_definitions(),
        }
        configured_model = str(codex_env_value("CODEX_HARNESS_MODEL") or "").strip()
        if configured_model:
            start_params["model"] = configured_model
        thread_result = await _canvas_harness_request(proc, run_id, 2, "thread/start", start_params, 60)
        thread = thread_result.get("thread") if isinstance(thread_result, dict) else {}
        thread_id = str((thread or {}).get("id") or thread_result.get("threadId") or "")
        if not thread_id:
            raise RuntimeError("Codex App Server 没有返回 thread id")
        _canvas_agent_run_update(run_id, thread_id=thread_id, stage="executing")
        await _canvas_harness_send(proc, {
            "method": "turn/start",
            "id": 3,
            "params": {
                "threadId": thread_id,
                "effort": str(os.getenv("CODEX_HARNESS_REASONING_EFFORT", "low") or "low").strip() or "low",
                "input": [{"type": "text", "text": _canvas_harness_turn_input(context)}],
            },
        })
        while True:
            if CANVAS_AGENT_RUN_INTERRUPTS.get(run_id, asyncio.Event()).is_set():
                try:
                    await _canvas_harness_request(proc, run_id, 4, "turn/interrupt", {"threadId": thread_id}, 20)
                except Exception:
                    pass
                raise asyncio.CancelledError()
            message = await _canvas_harness_read(proc, 90)
            if message.get("id") == 3:
                if message.get("error"):
                    error = message.get("error") or {}
                    raise RuntimeError(str(error.get("message") or "Harness turn 启动失败"))
                continue
            await _canvas_harness_handle_message(proc, run_id, message)
            if message.get("method") == "turn/completed":
                break
        final_text = str(context.get("final_summary") or context.get("agent_text") or "Harness 已完成编排").strip()
        operations = list(context.get("operations") or [])
        # If the model only narrated and did not call an apply tool, the first
        # structured plan remains a safe, deterministic hand-off to the client.
        if (
            not any(item.get("kind") == "apply_workflow" for item in operations if isinstance(item, dict))
            and not any(item.get("kind") == "delete_nodes" for item in operations if isinstance(item, dict))
        ):
            plan = context.get("plan") or {}
            option = (plan.get("options") or [{}])[0] if isinstance(plan, dict) else {}
            workflow = option.get("workflow") if isinstance(option, dict) else {}
            if isinstance(workflow, dict):
                operations.append({"kind": "apply_workflow", "workflow": _canvas_harness_trim(workflow, 16000), "option_id": "1", "source": "plan_fallback"})
                context["operations"] = operations
        _canvas_agent_run_update(
            run_id,
            status="completed",
            stage="ready_to_apply",
            final_text=final_text[:4000],
            operations=_canvas_harness_trim(operations, 30000),
            pending_approval=None,
            event={"type": "completed", "stage": "ready_to_apply", "message": "Harness 已完成工具编排，等待画布执行器应用"},
        )
    except asyncio.CancelledError:
        _canvas_agent_run_update(run_id, status="cancelled", stage="cancelled", error="用户已停止 Harness 任务", pending_approval=None, event={"type": "cancelled", "stage": "cancelled", "message": "用户已停止 Harness 任务"})
    except Exception as exc:
        detail = str(exc) or "Harness 执行失败"
        _canvas_agent_run_update(run_id, status="error", stage="error", error=detail[:4000], pending_approval=None, event={"type": "error", "stage": "error", "message": detail[:1000]})
    finally:
        if proc is not None:
            try:
                if proc.stdin:
                    proc.stdin.close()
            except Exception:
                pass
            try:
                await asyncio.wait_for(proc.wait(), timeout=3)
            except Exception:
                try:
                    proc.kill()
                except Exception:
                    pass
        CANVAS_AGENT_RUN_TASKS.pop(str(run_id), None)
        CANVAS_AGENT_RUN_APPROVALS.pop(str(run_id), None)
        CANVAS_AGENT_RUN_INTERRUPTS.pop(str(run_id), None)
        CANVAS_AGENT_RUN_CONTEXT.pop(str(run_id), None)


async def _canvas_agent_orchestration_worker(run_id: str):
    try:
        await asyncio.wait_for(_run_canvas_agent_orchestration(run_id), timeout=_canvas_harness_total_timeout())
    except asyncio.TimeoutError:
        _canvas_agent_run_update(run_id, status="error", stage="error", error="Harness 执行超过时间上限，已自动停止", pending_approval=None, event={"type": "error", "stage": "error", "message": "Harness 执行超过时间上限，已自动停止"})


async def stop_canvas_agent_harness():
    tasks = list(CANVAS_AGENT_RUN_TASKS.values())
    for task in tasks:
        if task and not task.done():
            task.cancel()
    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)


@app.post("/api/canvas-agent/orchestrate")
async def canvas_agent_orchestrate(payload: CanvasAgentOrchestrateRequest):
    if not _canvas_harness_enabled():
        return {"status": "fallback", "reason": "已通过 XIAOMEI_CODEX_HARNESS 关闭 Harness"}
    if not _canvas_harness_command():
        return {"status": "fallback", "reason": "未找到 Codex CLI，请先完成 codex 登录或关闭 Harness 模式"}
    item = _canvas_agent_run_create(payload.model_dump() if hasattr(payload, "model_dump") else payload.dict())
    run_id = str(item["id"])
    task = asyncio.create_task(_canvas_agent_orchestration_worker(run_id))
    CANVAS_AGENT_RUN_TASKS[run_id] = task
    return {"status": "queued", "run_id": run_id, "run": _canvas_agent_run_public(run_id)}


@app.get("/api/canvas-agent/runs/{run_id}")
async def canvas_agent_run_status(run_id: str):
    item = _canvas_agent_run_public(run_id)
    if not item:
        raise HTTPException(status_code=404, detail="Harness 任务不存在")
    return {"run": item}


@app.post("/api/canvas-agent/runs/{run_id}/approve")
async def canvas_agent_run_approve(run_id: str, payload: CanvasAgentApprovalRequest):
    item = _canvas_agent_run_public(run_id)
    if not item:
        raise HTTPException(status_code=404, detail="Harness 任务不存在")
    if item.get("status") != "awaiting_approval" or str(run_id) not in CANVAS_AGENT_RUN_APPROVALS:
        raise HTTPException(status_code=409, detail="当前没有等待确认的 Harness 动作")
    future = CANVAS_AGENT_RUN_APPROVALS.get(str(run_id))
    if future and not future.done():
        future.set_result(bool(payload.approved))
    _canvas_agent_run_add_event(run_id, f"已收到用户{'确认' if payload.approved else '拒绝'}", "approval")
    return {"ok": True, "approved": bool(payload.approved)}


@app.post("/api/canvas-agent/runs/{run_id}/interrupt")
async def canvas_agent_run_interrupt(run_id: str):
    item = _canvas_agent_run_public(run_id)
    if not item:
        raise HTTPException(status_code=404, detail="Harness 任务不存在")
    signal = CANVAS_AGENT_RUN_INTERRUPTS.get(str(run_id))
    if signal:
        signal.set()
    future = CANVAS_AGENT_RUN_APPROVALS.get(str(run_id))
    if future and not future.done():
        future.set_result(False)
    _canvas_agent_run_add_event(run_id, "已请求停止 Harness 任务", "cancelled")
    return {"ok": True}

