@app.get("/api/agent-skills")
async def get_agent_skills(response: Response):
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        records = list_agent_skill_records()
        facts = agent_skill_capability_facts()
        skills = []
        for item in records:
            record = _agent_skill_public_record(item)
            if not record:
                continue
            record["capability_status"] = shared_evaluate_capabilities(record.get("capability_ids") or [], facts)
            skills.append(record)
        return {
            "skills": skills,
            "categories": _agent_skill_public_categories(registry, records),
            "capability_catalog": shared_capability_catalog(),
            "capability_contract_version": CAPABILITY_CONTRACT_VERSION,
        }


@app.get("/api/agent-skills/capabilities")
async def get_agent_skill_capabilities(response: Response):
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    with AGENT_SKILLS_LOCK:
        records = list_agent_skill_records()
        facts = agent_skill_capability_facts()
        return {
            "contract_version": CAPABILITY_CONTRACT_VERSION,
            "catalog": shared_capability_catalog(),
            "skills": {
                str(item.get("id")): shared_evaluate_capabilities(item.get("capability_ids") or [], facts)
                for item in records
                if item.get("id")
            },
        }


@app.get("/api/agent-skills/categories")
async def get_agent_skill_categories(response: Response):
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        records = list_agent_skill_records()
        return {"categories": _agent_skill_public_categories(registry, records)}


@app.post("/api/agent-skills/categories")
async def create_agent_skill_category(payload: AgentSkillCategoryCreateRequest):
    name = str(payload.name or "").strip()
    try:
        category_id = _agent_skill_category_id(name)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        categories = registry.setdefault("categories", [])
        if not isinstance(categories, list):
            categories = []
            registry["categories"] = categories
        known = _agent_skill_category_records(registry)
        if any(item["id"] == category_id or str(item["name"]).casefold() == name.casefold() for item in known):
            raise HTTPException(status_code=409, detail="这个 Skill 分类已经存在")
        category = {"id": category_id, "name": name[:60], "builtin": False}
        categories.append(category)
        save_agent_skill_package_registry(registry)
        public = {**category, "skill_count": 0}
    return {"category": public}


@app.patch("/api/agent-skills/categories/{category_id}")
async def update_agent_skill_category(category_id: str, payload: AgentSkillCategoryUpdateRequest):
    try:
        cleaned_id = _agent_skill_category_id(category_id)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    name = str(payload.name or "").strip()
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        category_records = _agent_skill_category_records(registry)
        target = next((item for item in category_records if item["id"] == cleaned_id), None)
        if not target:
            raise HTTPException(status_code=404, detail="Skill 分类不存在")
        if target.get("builtin"):
            raise HTTPException(status_code=400, detail="内置 Skill 分类不能重命名")
        if not name:
            raise HTTPException(status_code=400, detail="Skill 分类名称不能为空")
        if any(item["id"] != cleaned_id and str(item["name"]).casefold() == name.casefold() for item in category_records):
            raise HTTPException(status_code=409, detail="这个 Skill 分类名称已经存在")
        categories = registry.setdefault("categories", [])
        stored = next((item for item in categories if isinstance(item, dict) and item.get("id") == cleaned_id), None)
        if not stored:
            raise HTTPException(status_code=404, detail="Skill 分类不存在")
        stored["name"] = name[:60]
        save_agent_skill_package_registry(registry)
        records = list_agent_skill_records()
        public = next(item for item in _agent_skill_public_categories(registry, records) if item["id"] == cleaned_id)
    return {"category": public}


@app.delete("/api/agent-skills/categories/{category_id}")
async def delete_agent_skill_category(category_id: str, payload: AgentSkillCategoryDeleteRequest):
    try:
        cleaned_id = _agent_skill_category_id(category_id)
        fallback_id = _agent_skill_category_id(payload.fallback_category_id or "custom")
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        category_records = _agent_skill_category_records(registry)
        target = next((item for item in category_records if item["id"] == cleaned_id), None)
        if not target:
            raise HTTPException(status_code=404, detail="Skill 分类不存在")
        if target.get("builtin"):
            raise HTTPException(status_code=400, detail="内置 Skill 分类不能删除")
        fallback = next((item for item in category_records if item["id"] == fallback_id), None)
        if not fallback or fallback_id == cleaned_id:
            raise HTTPException(status_code=400, detail="请选择有效的目标分类")
        categories = registry.setdefault("categories", [])
        registry["categories"] = [
            item for item in categories
            if not (isinstance(item, dict) and item.get("id") == cleaned_id)
        ]
        reassigned = 0
        for skill_id, record in (registry.get("packages", {}) or {}).items():
            if not isinstance(record, dict) or str(record.get("category") or "other") != cleaned_id:
                continue
            record["category"] = fallback_id
            record["category_label"] = fallback["name"]
            registry["packages"][skill_id] = record
            reassigned += 1
        save_agent_skill_package_registry(registry)
    return {
        "ok": True,
        "category_id": cleaned_id,
        "fallback_category_id": fallback_id,
        "reassigned": reassigned,
    }

@app.post("/api/agent-skills/inspect-upload")
async def inspect_agent_skill_upload(
    files: List[UploadFile] = File(...),
    relative_paths: str = Form(default=""),
):
    """Scan a folder selected in the browser without exposing its source path."""
    if not files:
        raise HTTPException(status_code=400, detail="请选择包含 SKILL.md 的文件夹")
    if len(files) > 500:
        raise HTTPException(status_code=400, detail="一次最多选择 500 个 Skill 文件")
    try:
        raw_paths = json.loads(relative_paths) if relative_paths else []
    except Exception as exc:
        raise HTTPException(status_code=400, detail="文件夹相对路径无法解析") from exc
    if not isinstance(raw_paths, list):
        raw_paths = []
    os.makedirs(AGENT_SKILL_UPLOAD_DIR, exist_ok=True)
    source_dir = tempfile.mkdtemp(prefix="skill-", dir=AGENT_SKILL_UPLOAD_DIR)
    total_bytes = 0
    try:
        for index, upload in enumerate(files):
            fallback = os.path.basename(str(upload.filename or f"file-{index}"))
            relative = _agent_skill_upload_relative_path(
                raw_paths[index] if index < len(raw_paths) else "",
                fallback,
            )
            target = _agent_skill_safe_join(source_dir, relative)
            raw = await upload.read()
            total_bytes += len(raw)
            if total_bytes > 100 * 1024 * 1024:
                raise ValueError("所选 Skill 文件总大小不能超过 100 MB")
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, "wb") as handle:
                handle.write(raw)
        scan = _agent_skill_scan_package(source_dir)
    except (OSError, ValueError) as exc:
        _agent_skill_cleanup_upload_source(source_dir)
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {
        "source_dir": scan["source_dir"],
        "package": scan["manifest"],
        "skills": [_agent_skill_scan_public(item) for item in scan["skills"]],
        "valid_count": scan["valid_count"],
        "warnings": scan["warnings"],
        "errors": scan["errors"],
    }

@app.post("/api/agent-skills/inspect-package")
async def inspect_agent_skill_package(payload: AgentSkillPackageInspectRequest):
    try:
        scan = _agent_skill_scan_package(payload.source_dir)
    except (OSError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    return {
        "source_dir": scan["source_dir"],
        "package": scan["manifest"],
        "skills": [_agent_skill_scan_public(item) for item in scan["skills"]],
        "valid_count": scan["valid_count"],
        "warnings": scan["warnings"],
        "errors": scan["errors"],
    }

@app.post("/api/agent-skills/import-package")
async def import_agent_skill_package(payload: AgentSkillPackageImportRequest):
    try:
        scan = _agent_skill_scan_package(payload.source_dir)
    except (OSError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    requested = set()
    for value in payload.skill_ids or []:
        try:
            requested.add(agent_skill_id(value))
        except HTTPException as exc:
            raise HTTPException(status_code=400, detail=exc.detail)
    available = {str(item.get("id")): item for item in scan["skills"]}
    if requested:
        missing = sorted(requested - set(available))
        if missing:
            raise HTTPException(status_code=400, detail=f"清单中不存在指定 Skill：{', '.join(missing)}")
        candidates = [available[item] for item in sorted(requested)]
    else:
        candidates = scan["skills"]
    imported, skipped, conflicts, errors, warnings = [], [], [], [], list(scan.get("warnings") or [])
    registry_changed = False
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        packages = registry.setdefault("packages", {})
        for item in candidates:
            slug = str(item.get("id") or "")
            warnings.extend([f"{slug}：{message}" for message in (item.get("warnings") or [])])
            if not item.get("valid"):
                skipped.append({"id": slug, "reason": "invalid", "detail": item.get("error") or "包校验未通过"})
                continue
            existing = packages.get(slug) if isinstance(packages.get(slug), dict) else None
            existing_zip = (existing or {}).get("zip_validation") or {}
            current_zip = item.get("zip_validation") or {}
            same_version = existing and str(existing.get("version") or "") == str(item.get("version") or "")
            same_hash = existing and str(existing_zip.get("sha256") or "") == str(current_zip.get("sha256") or "")
            destination_exists = os.path.isdir(agent_skill_package_path(slug))
            if existing and same_version and same_hash and destination_exists:
                skipped.append({"id": slug, "reason": "already_installed", "version": existing.get("version", "")})
                continue
            if (existing or destination_exists) and not payload.replace:
                conflicts.append({
                    "id": slug,
                    "reason": "version_conflict" if existing else "installed_without_registry",
                    "installed_version": existing.get("version", "") if existing else "",
                    "incoming_version": item.get("version", ""),
                })
                continue
            try:
                _agent_skill_copy_package(item, scan["source_dir"], replace=bool(destination_exists and payload.replace))
                stored = _agent_skill_registry_record(item)
                stored["enabled"] = bool(existing.get("enabled", True)) if existing else True
                packages[slug] = stored
                imported.append(_agent_skill_public_record(_agent_skill_load_package_record(slug)) or stored)
                registry_changed = True
            except Exception as exc:
                errors.append(f"{slug}：导入失败：{exc}")
        if registry_changed:
            save_agent_skill_package_registry(registry)
    result = {
        "source_dir": scan["source_dir"],
        "package": scan["manifest"],
        "imported": imported,
        "skipped": skipped,
        "conflicts": conflicts,
        "warnings": warnings,
        "errors": errors,
    }
    _agent_skill_cleanup_upload_source(scan["source_dir"])
    return result

@app.patch("/api/agent-skills/{skill_id}")
async def update_agent_skill_state(skill_id: str, payload: AgentSkillStateRequest):
    try:
        cleaned_id = agent_skill_id(skill_id)
    except HTTPException:
        raise
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        record = registry.get("packages", {}).get(cleaned_id)
        is_package = isinstance(record, dict)
        if not is_package and not os.path.isfile(agent_skill_path(cleaned_id)):
            raise HTTPException(status_code=404, detail="Skill 不存在")
        if not is_package and (payload.enabled is not None or payload.category_id is not None):
            raise HTTPException(status_code=400, detail="单文件 Skill 只支持重命名")
        if payload.enabled is None and payload.category_id is None and payload.display_name is None:
            raise HTTPException(status_code=400, detail="没有需要更新的 Skill 状态")
        if payload.enabled is True:
            # 设计大脑草稿 Skill 必须先显式发布，防止未审核经验通过草稿直接生效。
            try:
                draft_blocked = DESIGN_BRAIN_SKILL_LINKS.is_draft(cleaned_id)
            except DesignBrainError as error:
                raise HTTPException(status_code=error.status, detail=error.message)
            if draft_blocked:
                raise HTTPException(status_code=409, detail="该 Skill 是设计大脑草稿，请先在设计大脑中发布后再启用")
        if payload.enabled is not None:
            record["enabled"] = bool(payload.enabled)
        if payload.category_id is not None:
            try:
                category_id = _agent_skill_category_id(payload.category_id)
            except ValueError as exc:
                raise HTTPException(status_code=400, detail=str(exc)) from exc
            category_map = _agent_skill_category_map(registry)
            if category_id not in category_map:
                raise HTTPException(status_code=404, detail="Skill 分类不存在")
            record["category"] = category_id
            record["category_label"] = category_map[category_id]
        if payload.display_name is not None:
            display_name = payload.display_name.strip()
            names = registry.setdefault("display_names", {})
            if display_name:
                names[cleaned_id] = display_name
            else:
                names.pop(cleaned_id, None)
        if is_package:
            registry["packages"][cleaned_id] = record
        save_agent_skill_package_registry(registry)
        skill = load_agent_skill_record(cleaned_id)
    return {"skill": _agent_skill_public_record(skill)}

@app.get("/api/agent-skills/{skill_id}/resource")
async def get_agent_skill_resource(skill_id: str, path: str = ""):
    with AGENT_SKILLS_LOCK:
        skill = load_agent_skill_record(skill_id)
    if not skill:
        raise HTTPException(status_code=404, detail="Skill 不存在")
    relative_path = str(path or "").replace("\\", "/").strip()
    allowed = set(skill.get("package_files") or [])
    for extra in (skill.get("tutorial_path"), skill.get("example_path")):
        if extra:
            allowed.add(extra)
    if relative_path not in allowed:
        raise HTTPException(status_code=404, detail="Skill 资源不存在")
    content, truncated = _agent_skill_resource_text(skill, relative_path, AGENT_SKILL_RESOURCE_MAX_CHARS)
    if not content and relative_path not in {"", "SKILL.md"}:
        raise HTTPException(status_code=404, detail="Skill 资源无法读取")
    return {"skill_id": skill.get("id"), "path": relative_path, "content": content, "truncated": truncated}

@app.get("/api/agent-skills/{skill_id}")
async def get_agent_skill(skill_id: str):
    with AGENT_SKILLS_LOCK:
        skill = load_agent_skill_record(skill_id)
    if not skill:
        raise HTTPException(status_code=404, detail="Skill 不存在")
    resources = _agent_skill_detail_resources(skill)
    return {
        "skill": _agent_skill_public_record(skill),
        "instructions": build_agent_skill_context(skill),
        "resources": {
            "reference_files": skill.get("reference_files") or [],
            "script_files": skill.get("script_files") or [],
            "tutorial": resources.get("tutorial", ""),
            "example": resources.get("example", ""),
        },
    }

@app.put("/api/agent-skills/{skill_id}")
async def update_agent_skill_legacy(skill_id: str, payload: AgentSkillLegacyRequest):
    """Keep the legacy editor contract while writing through the canonical store."""

    cleaned_id = agent_skill_id(skill_id)
    path = agent_skill_path(cleaned_id)
    with AGENT_SKILLS_LOCK:
        if not os.path.isfile(path):
            raise HTTPException(status_code=404, detail="Skill 不存在")
        existing, _ = read_skill_text(path)
        has_frontmatter = bool(re.match(r"^\s*---\s*\r?\n", existing.lstrip("\ufeff")))
        document = render_skill_document(
            str(payload.name or "").strip() or cleaned_id,
            payload.description,
            payload.instructions,
            frontmatter=has_frontmatter,
        )
        write_skill_text(path, document)
        if str(payload.name or "").strip():
            registry = load_agent_skill_package_registry()
            names = registry.get("display_names") or {}
            if cleaned_id in names:
                names.pop(cleaned_id)
                save_agent_skill_package_registry(registry)
        skill = load_agent_skill_record(cleaned_id)
    return {"skill": _agent_skill_public_record(skill)}

@app.delete("/api/agent-skills/{skill_id}")
async def delete_agent_skill_legacy(skill_id: str):
    cleaned_id = agent_skill_id(skill_id)
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
        packages = registry.get("packages", {})
        if not isinstance(packages, dict):
            packages = {}
            registry["packages"] = packages
        if cleaned_id in packages:
            package_path = agent_skill_package_path(cleaned_id)
            if os.path.islink(package_path):
                raise HTTPException(status_code=400, detail="Skill 安装目录是符号链接，无法删除")
            if os.path.lexists(package_path) and not os.path.isdir(package_path):
                raise HTTPException(status_code=409, detail="Skill 安装目录不是文件夹，无法删除")
            backup_path = ""
            if os.path.isdir(package_path):
                os.makedirs(AGENT_SKILL_PACKAGE_BACKUPS_DIR, exist_ok=True)
                backup_path = os.path.join(AGENT_SKILL_PACKAGE_BACKUPS_DIR, f"{cleaned_id}-delete-{uuid.uuid4().hex}")
                os.replace(package_path, backup_path)
            removed = packages.pop(cleaned_id)
            names = registry.setdefault("display_names", {})
            old_display_name = names.pop(cleaned_id, None)
            try:
                save_agent_skill_package_registry(registry)
            except Exception:
                packages[cleaned_id] = removed
                if old_display_name is not None:
                    names[cleaned_id] = old_display_name
                if backup_path:
                    os.replace(backup_path, package_path)
                raise
            if backup_path:
                shutil.rmtree(backup_path, ignore_errors=True)
        else:
            path = agent_skill_path(cleaned_id)
            if not os.path.isfile(path):
                raise HTTPException(status_code=404, detail="Skill 不存在")
            os.remove(path)
            names = registry.get("display_names") or {}
            if cleaned_id in names:
                names.pop(cleaned_id)
                save_agent_skill_package_registry(registry)
    return {"ok": True}

@app.post("/api/agent-skills/upload")
async def upload_agent_skill_legacy(file: UploadFile = File(...)):
    raw = await file.read()
    if len(raw) > 1024 * 1024:
        raise HTTPException(status_code=400, detail="Skill 文件不能超过 1 MB")
    try:
        content = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise HTTPException(status_code=400, detail="Skill 文件必须为 UTF-8 Markdown") from exc

    with AGENT_SKILLS_LOCK:
        os.makedirs(AGENT_SKILLS_DIR, exist_ok=True)
        base_id = agent_skill_slug(os.path.splitext(str(file.filename or "skill"))[0])
        skill_id = base_id
        suffix = 2
        packages = load_agent_skill_package_registry().get("packages", {})
        while os.path.exists(agent_skill_path(skill_id)) or skill_id in packages:
            skill_id = f"{base_id}-{suffix}"
            suffix += 1
        path = agent_skill_path(skill_id)
        write_skill_text(path, content)
        skill = load_agent_skill_record(skill_id)
    return {"skill": _agent_skill_public_record(skill)}

@app.post("/api/agent-skills/create")
async def create_agent_skill(payload: AgentSkillCreateRequest):
    name = str(payload.name or "").strip()
    description = str(payload.description or "").strip().replace("\r", " ").replace("\n", " ")
    instructions = str(payload.instructions or "").strip()
    if not name or not instructions:
        raise HTTPException(status_code=400, detail="Skill 名称和指令不能为空")
    with AGENT_SKILLS_LOCK:
        os.makedirs(AGENT_SKILLS_DIR, exist_ok=True)
        base_id = agent_skill_slug(name)
        skill_id = base_id
        suffix = 2
        while os.path.exists(agent_skill_path(skill_id)) or skill_id in load_agent_skill_package_registry().get("packages", {}):
            skill_id = f"{base_id}-{suffix}"
            suffix += 1
        path = agent_skill_path(skill_id)
        write_skill_text(
            path,
            render_skill_document(
                name,
                description,
                instructions,
                frontmatter=True,
            ),
        )
        skill = load_agent_skill_record(skill_id)
    return {"skill": _agent_skill_public_record(skill)}

# --- 设计大脑 Skill：生成 / 编辑 / 发布 / 版本回退 ---
# 物理文件复用 agent_skills 包目录与注册表；版本快照与生命周期记录在
# data/design_brain/skill_links.json。所有写入都要求显式用户动作，
# 未审核经验没有触碰这些端点的通路。

class DesignBrainSkillCreateRequest(BaseModel):
    name: str = ""
    description: str = ""
    instructions: str = ""

class DesignBrainSkillUpdateRequest(BaseModel):
    name: str = ""
    description: str = ""
    instructions: str = ""

class DesignBrainSkillRollbackRequest(BaseModel):
    version: int

DESIGN_BRAIN_SKILL_CONTENT_MAX = 200 * 1024

def _design_brain_skill_document(name, description, instructions, version_label):
    return (
        "---\n"
        f"name: {json.dumps(name, ensure_ascii=False)}\n"
        f"description: {json.dumps(description, ensure_ascii=False)}\n"
        f"version: {json.dumps(version_label, ensure_ascii=False)}\n"
        "---\n\n"
        f"{str(instructions or '').strip()}\n"
    )

def _design_brain_default_instructions(experience):
    lines = ["# 使用场景", f"（来自设计大脑经验：{experience.get('title') or ''}）", "", "# 经验规则"]
    observations = [text for text in (experience.get("observations") or []) if str(text).strip()]
    lines.extend(f"- {text}" for text in observations) if observations else lines.append("- （待补充观察）")
    lines.extend(["", "# 说明", "- 本 Skill 由设计大脑经验生成，默认停用；请在设计大脑中确认效果后发布再启用。"])
    return "\n".join(lines)

def _design_brain_unique_skill_id(name):
    base_id = agent_skill_slug(name or "设计经验 Skill")
    skill_id = base_id
    suffix = 2
    linked = DESIGN_BRAIN_SKILL_LINKS.list()
    while (
        os.path.exists(agent_skill_path(skill_id))
        or os.path.isdir(agent_skill_package_path(skill_id))
        or skill_id in load_agent_skill_package_registry().get("packages", {})
        or skill_id in linked
    ):
        skill_id = f"{base_id}-{suffix}"
        suffix += 1
    return skill_id

def _install_design_brain_skill_package(skill_id, name, description, instructions):
    """构造暂存目录并复用包扫描/复制/注册安装；调用方需持有 AGENT_SKILLS_LOCK。

    返回 (注册表记录, 完整文档文本)。草稿一律 enabled=False。
    """
    version_label = "1.0.1"
    document = _design_brain_skill_document(name, description, instructions, version_label)
    staging = os.path.join(AGENT_SKILL_UPLOAD_DIR, f"design-brain-{uuid.uuid4().hex}")
    os.makedirs(staging, exist_ok=True)
    write_skill_text(os.path.join(staging, "SKILL.md"), document)
    with open(os.path.join(staging, "manifest.json"), "w", encoding="utf-8", newline="\n") as handle:
        json.dump({
            "name": name, "version": version_label, "total": 1, "format": "single-skill",
            "skills": [{
                "slug": skill_id, "displayName": name, "summary": description,
                "category": "custom", "version": version_label, "packagePath": ".", "singleSkill": True,
            }],
        }, handle, ensure_ascii=False, indent=2)
    try:
        scan = _agent_skill_scan_package(staging)
        record = next((item for item in scan.get("skills", []) if item.get("id") == skill_id), None)
        if not record or not record.get("valid"):
            raise HTTPException(status_code=400, detail="Skill 文档校验未通过，请调整名称与内容后重试")
        _agent_skill_copy_package(record, scan["source_dir"], replace=False)
        stored = _agent_skill_registry_record(record)
        stored["enabled"] = False
        registry = load_agent_skill_package_registry()
        registry.setdefault("packages", {})[skill_id] = stored
        save_agent_skill_package_registry(registry)
    finally:
        shutil.rmtree(staging, ignore_errors=True)
    return stored, document

def _write_design_brain_skill_version(skill_id, entry, name, description, instructions, note):
    """写入新版本 SKILL.md 并登记版本快照；调用方需持有 AGENT_SKILLS_LOCK。"""
    next_version = int(entry.get("current_version") or 0) + 1
    document = _design_brain_skill_document(name, description, instructions, f"1.0.{next_version}")
    skill_path = os.path.join(agent_skill_package_path(skill_id), "SKILL.md")
    if not os.path.isfile(skill_path):
        raise HTTPException(status_code=409, detail="Skill 安装目录不存在，请重新生成或导入")
    write_skill_text(skill_path, document)
    registry = load_agent_skill_package_registry()
    record = registry.get("packages", {}).get(skill_id)
    if isinstance(record, dict):
        record["version"] = f"1.0.{next_version}"
        if str(name or "").strip():
            record["name"] = str(name).strip()[:120]
            record["display_name"] = str(name).strip()[:120]
        save_agent_skill_package_registry(registry)
    return DESIGN_BRAIN_SKILL_LINKS.snapshot(skill_id, document, note)

@app.post("/api/design-brain/experiences/{experience_id}/skill")
async def create_design_brain_skill_from_experience(experience_id: str, payload: DesignBrainSkillCreateRequest):
    try:
        experience = DESIGN_BRAIN_EXPERIENCES.get(experience_id)
    except DesignBrainError as error:
        raise HTTPException(status_code=error.status, detail=error.message)
    if experience.get("status") != "published":
        raise HTTPException(status_code=409, detail="只有已发布的经验可以生成 Skill；请先完成审核发布")
    name = str(payload.name or "").strip() or str(experience.get("title") or "").strip() or "设计经验 Skill"
    description = str(payload.description or "").strip() or f"来自设计大脑经验：{experience.get('title') or ''}"
    instructions = str(payload.instructions or "").strip() or _design_brain_default_instructions(experience)
    if len(instructions) > DESIGN_BRAIN_SKILL_CONTENT_MAX:
        raise HTTPException(status_code=400, detail="Skill 指令内容过长，请精简后重试")
    with AGENT_SKILLS_LOCK:
        skill_id = _design_brain_unique_skill_id(name)
        _stored, document = _install_design_brain_skill_package(skill_id, name, description, instructions)
        try:
            link = DESIGN_BRAIN_SKILL_LINKS.link(skill_id, experience_id, document, note=f"从经验生成：{experience.get('title') or ''}")
            DESIGN_BRAIN_EXPERIENCES.attach_skill(experience_id, skill_id)
        except Exception:
            shutil.rmtree(agent_skill_package_path(skill_id), ignore_errors=True)
            registry = load_agent_skill_package_registry()
            registry.get("packages", {}).pop(skill_id, None)
            save_agent_skill_package_registry(registry)
            raise
        skill = _agent_skill_load_package_record(skill_id)
    return {"skill": _agent_skill_public_record(skill), "link": link}

@app.patch("/api/design-brain/skills/{skill_id}")
async def update_design_brain_skill(skill_id: str, payload: DesignBrainSkillUpdateRequest):
    try:
        cleaned_id = agent_skill_id(skill_id)
    except HTTPException:
        raise
    try:
        entry = DESIGN_BRAIN_SKILL_LINKS.get(cleaned_id)
    except DesignBrainError as error:
        raise HTTPException(status_code=error.status, detail=error.message)
    instructions = str(payload.instructions or "").strip()
    if not instructions:
        raise HTTPException(status_code=400, detail="Skill 指令不能为空")
    if len(instructions) > DESIGN_BRAIN_SKILL_CONTENT_MAX:
        raise HTTPException(status_code=400, detail="Skill 指令内容过长，请精简后重试")
    name = str(payload.name or "").strip()
    description = str(payload.description or "").strip()
    with AGENT_SKILLS_LOCK:
        link = _write_design_brain_skill_version(cleaned_id, entry, name, description, instructions, note="编辑内容")
        skill = _agent_skill_load_package_record(cleaned_id)
    return {"skill": _agent_skill_public_record(skill), "link": link}

@app.post("/api/design-brain/skills/{skill_id}/publish")
async def publish_design_brain_skill(skill_id: str):
    try:
        cleaned_id = agent_skill_id(skill_id)
    except HTTPException:
        raise
    with AGENT_SKILLS_LOCK:
        try:
            link = DESIGN_BRAIN_SKILL_LINKS.set_lifecycle(cleaned_id, "published")
        except DesignBrainError as error:
            raise HTTPException(status_code=error.status, detail=error.message)
        if not os.path.isfile(os.path.join(agent_skill_package_path(cleaned_id), "SKILL.md")):
            raise HTTPException(status_code=409, detail="Skill 安装目录不存在，请重新生成或导入")
        skill = _agent_skill_load_package_record(cleaned_id)
    return {"skill": _agent_skill_public_record(skill), "link": link}

@app.post("/api/design-brain/skills/{skill_id}/rollback")
async def rollback_design_brain_skill(skill_id: str, payload: DesignBrainSkillRollbackRequest):
    try:
        cleaned_id = agent_skill_id(skill_id)
    except HTTPException:
        raise
    with AGENT_SKILLS_LOCK:
        try:
            entry = DESIGN_BRAIN_SKILL_LINKS.get(cleaned_id)
        except DesignBrainError as error:
            raise HTTPException(status_code=error.status, detail=error.message)
        target = next((item for item in entry.get("versions", []) if int(item.get("version") or 0) == int(payload.version)), None)
        if not target:
            raise HTTPException(status_code=404, detail="找不到该版本")
        next_version = int(entry.get("current_version") or 0) + 1
        content = str(target.get("content") or "")
        document = re.sub(r'(?m)^version:.*$', f'version: {json.dumps(f"1.0.{next_version}", ensure_ascii=False)}', content, count=1)
        if document == content:
            document = _design_brain_skill_document(target.get("note") or cleaned_id, "", content, f"1.0.{next_version}")
        skill_path = os.path.join(agent_skill_package_path(cleaned_id), "SKILL.md")
        if not os.path.isfile(skill_path):
            raise HTTPException(status_code=409, detail="Skill 安装目录不存在，请重新生成或导入")
        write_skill_text(skill_path, document)
        registry = load_agent_skill_package_registry()
        record = registry.get("packages", {}).get(cleaned_id)
        if isinstance(record, dict):
            record["version"] = f"1.0.{next_version}"
            save_agent_skill_package_registry(registry)
        link = DESIGN_BRAIN_SKILL_LINKS.snapshot(cleaned_id, document, note=f"回退自 v{payload.version}")
        skill = _agent_skill_load_package_record(cleaned_id)
    return {"skill": _agent_skill_public_record(skill), "link": link}

class DesignBrainReviewRequest(BaseModel):
    history_timestamp: float = 0
    image_url: str = ""
    rating: int = 0
    comment: str = Field(default="", max_length=600)
    issue_tag: str = ""
    selected_as_final: bool = False


def _design_brain_short_digest(value) -> str:
    return "sha256:" + hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()[:16]


def _design_brain_resolve_skill_version(skill_id: str) -> str:
    """评价时刻固化 Skill 版本：设计大脑版本号优先，其次包注册表版本。"""
    skill_id = str(skill_id or "").strip()
    if not skill_id:
        return ""
    try:
        link = DESIGN_BRAIN_SKILL_LINKS.get(skill_id)
        if link and link.get("current_version"):
            return f"v{link['current_version']}"
    except DesignBrainError:
        pass
    record = load_agent_skill_package_registry().get("packages", {}).get(skill_id)
    if isinstance(record, dict) and str(record.get("version") or "").strip():
        return str(record["version"]).strip()
    return ""


def _design_brain_local_image_checks(url: str) -> Dict[str, Any]:
    """本地只读检查：文件存在、可解码尺寸、最短边。失败不阻塞评价。"""
    checks = {"file_ok": False, "width": 0, "height": 0, "min_edge_ok": False, "note": ""}
    path = output_file_from_url(url) if url else None
    if not path or not os.path.isfile(path):
        checks["note"] = "原图不在本机，跳过本地检查"
        return checks
    try:
        with Image.open(path) as image:
            checks["width"], checks["height"] = image.size
        checks["file_ok"] = True
        checks["min_edge_ok"] = min(checks["width"], checks["height"]) >= 512
        if not checks["min_edge_ok"]:
            checks["note"] = f"最短边 {min(checks['width'], checks['height'])}px，低于 512px"
    except Exception as exc:
        checks["note"] = f"本地检查失败：{str(exc)[:120]}"
    return checks


@app.post("/api/design-brain/reviews")
async def create_design_brain_review(payload: DesignBrainReviewRequest):
    """创建质量评价：回读完整历史记录固化生成条件，供对照测试判定可比性。"""
    rating = int(payload.rating or 0)
    if rating < 1 or rating > 5:
        raise HTTPException(status_code=400, detail="评分需在 1-5 星之间")
    record = None
    if payload.history_timestamp:
        try:
            with HISTORY_LOCK:
                with open(HISTORY_FILE, "r", encoding="utf-8-sig") as handle:
                    history = json.load(handle)
            record = next((item for item in (history if isinstance(history, list) else [])
                           if isinstance(item, dict)
                           and abs(float(item.get("timestamp") or 0) - float(payload.history_timestamp)) < 0.001), None)
        except (OSError, ValueError):
            record = None
    params = record.get("params") if isinstance(record and record.get("params"), dict) else {}
    image_url = str(payload.image_url or "").strip() or next((url for url in (record or {}).get("images") or [] if url), "")
    if not image_url and not record:
        raise HTTPException(status_code=400, detail="评价必须关联一张图片或一条历史记录")
    reference_urls = sorted({
        str(ref.get("url") or "").strip()
        for ref in (params.get("reference_images") or [])
        if isinstance(ref, dict) and ref.get("url")
    })
    asset_ref_id = ""
    for item in (record or {}).get("image_items") or []:
        if isinstance(item, dict) and item.get("url") == image_url:
            candidate = str(item.get("asset_ref_id") or "").strip()
            if candidate:
                asset_ref_id = candidate
            break
    skill_id = str((record or {}).get("skill_id") or "").strip()
    review = DESIGN_BRAIN_REVIEWS.create({
        "target": {
            "url": image_url,
            "asset_ref_id": asset_ref_id,
            "history_timestamp": float((record or {}).get("timestamp") or payload.history_timestamp or 0),
            "run_id": str((record or {}).get("design_run_id") or "").strip(),
            "canvas_id": "",
        },
        "context": {
            "skill_id": skill_id,
            "skill_name": str((record or {}).get("skill_name") or "").strip(),
            "skill_version": _design_brain_resolve_skill_version(skill_id),
            "model": str((record or {}).get("model") or params.get("model") or "").strip(),
            "provider_id": str((record or {}).get("provider_id") or params.get("provider_id") or "").strip(),
            "size": str(params.get("size") or "").strip(),
            "quality": str(params.get("quality") or "").strip(),
            "reference_digest": _design_brain_short_digest("|".join(reference_urls)),
            "reference_count": len(reference_urls),
            "prompt_digest": _design_brain_short_digest(str((record or {}).get("prompt") or "").strip()),
        },
        "user_feedback": {
            "rating": rating,
            "comment": str(payload.comment or "").strip(),
            "selected_as_final": bool(payload.selected_as_final),
        },
        "issue_tag": str(payload.issue_tag or "").strip(),
        "auto_checks": _design_brain_local_image_checks(image_url),
    })
    return {"review": review}


