@app.delete("/api/projects/{project_id}")
async def delete_project(project_id: str):
    """软删除项目：项目进入回收站，项目内画布保留原归属以便恢复。"""
    if project_id == DEFAULT_PROJECT_ID:
        raise HTTPException(status_code=400, detail="默认项目不可删除")
    cleanup_expired_project_trash()
    projects = ensure_default_project()
    target = next((p for p in projects if p.get("id") == project_id and not p.get("deleted_at")), None)
    if not target:
        raise HTTPException(status_code=404, detail="项目不存在")
    target["deleted_at"] = now_ms()
    target["updated_at"] = target["deleted_at"]
    save_projects(projects)
    return {"ok": True, "project": project_record(target)}

@app.post("/api/projects/{project_id}/restore")
async def restore_project(project_id: str):
    cleanup_expired_project_trash()
    projects = ensure_default_project()
    target = next((p for p in projects if p.get("id") == project_id and p.get("deleted_at")), None)
    if not target:
        raise HTTPException(status_code=404, detail="回收站中没有这个项目")
    target.pop("deleted_at", None)
    target["updated_at"] = now_ms()
    save_projects(projects)
    return {"project": project_record(target)}

@app.delete("/api/projects/{project_id}/purge")
async def purge_project(project_id: str):
    cleanup_expired_project_trash()
    with CANVAS_LOCK:
        projects = load_projects()
        if not any(p.get("id") == project_id and p.get("deleted_at") for p in projects):
            raise HTTPException(status_code=404, detail="回收站中没有这个项目")
        try:
            trashed = _soft_delete_project_canvases_unlocked(project_id)
            _write_projects_unlocked([p for p in projects if p.get("id") != project_id])
        except OSError as exc:
            logging.getLogger(__name__).warning("无法清理项目 %s: %s", project_id, exc)
            raise HTTPException(
                status_code=503, detail="暂时无法清理项目，项目仍在回收站，请重试",
            ) from exc
    PROJECT_AGENT_STORE.purge(project_id)
    return {"ok": True, "trashed": trashed}


