@app.post("/api/commerce-analysis/reports/capture")
async def commerce_analysis_capture_merchant_report(payload: CommerceMerchantReportCaptureRequest):
    """接收用户在官方千牛/生意参谋页面看到或导出的报表。

    这里不访问第三方分析服务，也不接收浏览器凭据；后端只对用户主动提交的
    CSV/可见表格做字段归一化，并把结果挂到当前商品分析任务。
    """
    kind = str(payload.kind or "operations").strip().lower()
    if kind in {"audience", "people", "population", "人群", "人群结构"}:
        kind = "audience"
    elif kind not in {"operations", "operation", "运营", "运营数据"}:
        raise HTTPException(status_code=400, detail="报表类型不在允许范围内")
    source = str(payload.source or "seller").strip().lower()
    if source not in {"seller", "qianniu", "sycm", "operations", "official", "official-export", "authorized", "authorized-api"}:
        raise HTTPException(status_code=400, detail="报表来源不在允许范围内")
    url = str(payload.url or "").strip()
    if url:
        host = (urllib.parse.urlsplit(url).hostname or "").lower().rstrip(".")
        allowed_hosts = ("taobao.com", "1688.com", "tmall.com")
        if not any(host == suffix or host.endswith(f".{suffix}") for suffix in allowed_hosts):
            raise HTTPException(status_code=400, detail="报表页面域名不在白名单内")
    payload_data = payload.model_dump() if hasattr(payload, "model_dump") else payload.dict()
    payload_data["kind"] = kind
    record = await asyncio.to_thread(_commerce_analysis_create_report, payload_data)
    job_id = str(record.get("job_id") or "")
    updated_result = None
    if job_id:
        job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
        if job and isinstance(job.get("result"), dict):
            result = dict(job["result"])
            report = record.get("report") if isinstance(record.get("report"), dict) else {}
            if kind == "operations":
                item = {
                    "id": record.get("id"),
                    "title": record.get("title") or report.get("productName") or "官方运营报表",
                    "text": record.get("text") or "",
                    "metrics": payload_data.get("metrics") if isinstance(payload_data.get("metrics"), dict) else {},
                    "report": report,
                    "fileName": record.get("file_name") or "",
                    "capturedAt": record.get("created_at") or "",
                }
                result["operations"] = {
                    "status": "captured",
                    "items": [item],
                    "capturedAt": record.get("created_at") or "",
                    "source": record.get("source") or source,
                    "message": record.get("message") or "已捕获运营数据",
                }
            else:
                result["peopleStructure"] = report
            result = _commerce_analysis_attach_contract(
                result,
                job_id=job_id,
                mode=str(result.get("collection", {}).get("mode") or "import"),
            )
            updated_result = result
            await asyncio.to_thread(
                _commerce_analysis_update_job,
                job_id,
                result_json=_commerce_analysis_json(result),
                message=("已补充运营报表，可继续进行联合分析" if kind == "operations" else "已补充人群结构数据，可继续进行联合分析"),
            )
    return {"ok": True, "kind": kind, "record": record, "result": updated_result}


