@app.post("/api/commerce-analysis/agent/sessions/{session_id}/turn")
async def commerce_analysis_agent_turn(session_id: str, payload: CommerceAnalysisAgentTurnRequest):
    session = await asyncio.to_thread(_commerce_agent_get_session, session_id, True)
    if not session:
        raise HTTPException(status_code=404, detail="网页智能体会话不存在")
    if session.get("status") in {"cancelled", "completed"}:
        return {"session": session, "actions": [], "done": True, "message": "网页智能体会话已结束"}
    if payload.skill_id:
        await asyncio.to_thread(_commerce_agent_update_session, session_id, skill_id=str(payload.skill_id)[:120])
        session["skill_id"] = str(payload.skill_id)[:120]
    for raw_event in (payload.events or [])[:20]:
        event_payload = dict(raw_event) if isinstance(raw_event, dict) else {}
        event_payload.setdefault("job_id", session.get("job_id") or "")
        event = await asyncio.to_thread(_commerce_agent_record_event, session_id, event_payload)
        if event.get("status") != "rejected":
            session["step"] = min(int(session.get("max_steps") or 24), int(session.get("step") or 0) + 1)
        if event.get("action") == "finish" and event.get("status") != "rejected":
            session["status"] = "completed"
    if session.get("status") == "completed":
        updated = await asyncio.to_thread(_commerce_agent_update_session, session_id, status="completed", step=session.get("step"), finished_at=_commerce_analysis_now())
        return {"session": updated, "actions": [], "done": True, "message": "商品分析动作已完成"}
    await asyncio.to_thread(_commerce_agent_update_session, session_id, step=session.get("step"), error="")
    refreshed = await asyncio.to_thread(_commerce_agent_get_session, session_id, True)
    actions = await _commerce_agent_next_actions(
        refreshed or session,
        payload.message,
        payload.page_context,
        (refreshed or session).get("events") or [],
        payload,
    )
    if not actions:
        updated = await asyncio.to_thread(_commerce_agent_update_session, session_id, status="completed", finished_at=_commerce_analysis_now())
        return {"session": updated, "actions": [], "done": True, "message": "没有更多安全分析动作"}
    return {
        "session": refreshed or session,
        "actions": actions,
        "done": False,
        "message": "请在可见商品页面执行这些安全分析动作后回传事件",
    }


@app.post("/api/commerce-analysis/agent/sessions/{session_id}/events")
async def commerce_analysis_agent_event(session_id: str, payload: CommerceAnalysisAgentEventRequest):
    session = await asyncio.to_thread(_commerce_agent_get_session, session_id, False)
    if not session:
        raise HTTPException(status_code=404, detail="网页智能体会话不存在")
    if session.get("status") in {"cancelled", "completed"}:
        raise HTTPException(status_code=409, detail="网页智能体会话已结束")
    event_payload = payload.dict()
    event_payload["job_id"] = payload.job_id or session.get("job_id") or ""
    event = await asyncio.to_thread(_commerce_agent_record_event, session_id, event_payload)
    current_step = int(session.get("step") or 0)
    if event.get("status") != "rejected":
        current_step = min(int(session.get("max_steps") or 24), current_step + 1)
    changes = {"step": current_step}
    if event.get("action") == "finish" and event.get("status") != "rejected":
        changes.update({"status": "completed", "finished_at": _commerce_analysis_now()})
    elif event.get("status") == "rejected":
        changes["error"] = str(event.get("error") or "动作未通过安全校验")[:320]
    updated = await asyncio.to_thread(_commerce_agent_update_session, session_id, **changes)
    return {"event": event, "session": updated}


