@app.get("/api/commerce-analysis/jobs/{job_id}/resources/{resource_id}")
async def commerce_analysis_download_resource(job_id: str, resource_id: str):
    resource_id = str(resource_id or "").strip().lower()
    allowed_resources = {"product", "images", "detail", "detail_more", "sku", "sku_images", "sku_list", "reviews", "questions", "videos", "operations", "people"}
    if resource_id not in allowed_resources:
        raise HTTPException(status_code=404, detail="商品分析资源不存在")
    job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="商品分析任务不存在")
    result = job.get("result") if isinstance(job.get("result"), dict) else {}
    if not result:
        raise HTTPException(status_code=409, detail="该资源尚未准备完成")
    result = _commerce_analysis_attach_contract(result, job_id=job_id, mode=str(result.get("source") or "import"))
    resource = next((item for item in result.get("resources") or [] if item.get("id") == resource_id), None)
    report_filename = ""
    if resource_id == "operations":
        matrix, report_filename = _commerce_analysis_operations_report_matrix(result)
        headers, rows = [], matrix
    elif resource_id == "people":
        matrix, report_filename = _commerce_analysis_people_report_matrix(result)
        headers, rows = [], matrix
    else:
        headers, rows = _commerce_analysis_resource_rows(result, resource_id)
    if not resource or not resource.get("downloadable") or not rows:
        raise HTTPException(status_code=409, detail=(resource or {}).get("reason") or "该数据模块当前没有可下载内容")
    buffer = StringIO()
    writer = csv.writer(buffer, lineterminator="\r\n")
    if headers:
        writer.writerow(headers)
    writer.writerows(rows)
    label = str(resource.get("title") or resource_id).replace("/", "-")
    filename = report_filename or f"商品分析-{job_id[:12]}-{label}.csv"
    return Response(
        content=("\ufeff" + buffer.getvalue()).encode("utf-8"),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{urllib.parse.quote(filename)}"},
    )


