@app.post("/api/commerce-analysis/jobs/{job_id}/pause")
async def commerce_analysis_pause_job(job_id: str):
    job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="商品分析任务不存在")
    if job.get("status") in {"ready", "partial", "failed", "login_required", "paused"}:
        return job
    current = COMMERCE_ANALYSIS_RUNTIME_TASKS.get(job_id)
    await asyncio.to_thread(
        _commerce_analysis_update_job,
        job_id,
        status="paused",
        stage="paused",
        progress=job.get("progress") or 0,
        message="任务已暂停，可以点击重试继续",
        error="",
    )
    if current and not current.done():
        current.cancel()
        await asyncio.sleep(0)
    return await asyncio.to_thread(_commerce_analysis_get_job, job_id)


@app.post("/api/commerce-analysis/jobs/{job_id}/retry", status_code=202)
async def commerce_analysis_retry_job(job_id: str, module: str = ""):
    job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="商品分析任务不存在")
    if not job.get("url"):
        raise HTTPException(status_code=400, detail="任务缺少商品链接，无法重试")
    module = str(module or "").strip().lower()
    if module and module not in COMMERCE_ANALYSIS_COLLECTION_MODULE_KEYS:
        raise HTTPException(status_code=400, detail="不支持的分析模块")
    current = COMMERCE_ANALYSIS_RUNTIME_TASKS.get(job_id)
    if current and not current.done():
        return job
    previous_result_json = _commerce_analysis_json(job.get("result")) if module and isinstance(job.get("result"), dict) else None
    await asyncio.to_thread(
        _commerce_analysis_update_job,
        job_id,
        status="queued",
        stage="queued",
        progress=0,
        message="任务已重新排队",
        finished_at=None,
        result_json=previous_result_json,
        error="",
    )
    _commerce_analysis_schedule_job(
        job_id,
        job["url"],
        bool(job.get("browser", True)),
        module,
        backend=str(job.get("backend") or "edge"),
        session_id=str(job.get("session_id") or ""),
        tab_id=str(job.get("tab_id") or ""),
    )
    return await asyncio.to_thread(_commerce_analysis_get_job, job_id)


@app.post("/api/commerce-analysis/import")
async def commerce_analysis_import_result(payload: CommerceAnalysisImportRequest):
    data = payload.data if isinstance(payload.data, dict) else {}
    url = str(payload.url or data.get("originalUrl") or data.get("sourceUrl") or data.get("url") or "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="导入结果缺少原始商品链接")
    try:
        _commerce_analysis_require_marketplace_url(url)
        # Electron 已经从用户可见的商品 WebContentsView 读取到页面，
        # 此时不再额外请求公开页面，避免淘宝风控导致桌面端的可见快照无法导入。
        if str(data.get("backend") or "").strip().lower() != "electron":
            await _ensure_public_link_url(url)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=_clean_link_text(exc, 320)) from exc
    data_backend = str(data.get("backend") or "").strip().lower()
    import_backend = data_backend if data_backend in {"edge", "electron", "cdp"} else "edge"
    session_id = str(data.get("session_id") or data.get("sessionId") or "")[:120]
    tab_id = str(data.get("tab_id") or data.get("tabId") or "")[:120]
    collection_meta = data.get("collection") if isinstance(data.get("collection"), dict) else {}
    data_status = str(data.get("status") or collection_meta.get("status") or "").strip().lower()
    data_message = " ".join(str(data.get(key) or "") for key in ("message", "error"))
    auth_snapshot = data_status in {"login_required", "verification_required", "needs_login"}
    auth_snapshot = auth_snapshot or (
        import_backend == "electron"
        and data.get("ok") is False
        and bool(re.search(r"登录|验证|验证码|风控|captcha|verify", data_message, re.IGNORECASE))
    )
    if auth_snapshot:
        recent_job = await asyncio.to_thread(
            _commerce_analysis_recent_auth_import,
            url,
            import_backend,
            session_id,
            tab_id,
        )
        if recent_job and isinstance(recent_job.get("result"), dict):
            return recent_job["result"]
    job = _commerce_analysis_create_job(
        url,
        False,
        "import",
        backend=import_backend,
        session_id=session_id,
        tab_id=tab_id,
    )
    import_mode = "electron" if import_backend == "electron" else "import"
    result = _commerce_analysis_build_result(data, url, import_mode)
    if not _commerce_analysis_identity_matches_request(result, url):
        observed_id, observed_url = _commerce_analysis_result_identity(result, url)
        result = _commerce_analysis_build_result(
            {
                "ok": False,
                "status": "failed",
                "source": import_mode,
                "originalUrl": url,
                "finalUrl": url,
                "message": "导入页面的商品身份与请求链接不一致，已丢弃结果，禁止串到其他商品。",
                "collection": {
                    "mode": import_mode,
                    "source": "import-identity-check",
                    "identityCheck": {
                        "status": "mismatch",
                        "requestedProductId": _commerce_analysis_product_id(None, url),
                        "observedProductId": observed_id,
                        "observedNormalizedUrl": observed_url,
                    },
                },
            },
            url,
            import_mode,
        )
    # 桌面端按资源卡分模块采集时，每次采集都会回传一份“当前模块”快照。
    # 将它与同一商品的上一份结果合并，避免采完评价后再采问大家时，
    # 后一次导入把评价样本清空，导致界面再次提示“采集评价”。
    requested_module = str(
        collection_meta.get("requestedModule")
        or collection_meta.get("moduleRetry")
        or ""
    ).strip().lower()
    previous_job_id = str(payload.previous_job_id or data.get("previousJobId") or "").strip()[:120]
    if previous_job_id and requested_module in COMMERCE_ANALYSIS_RETRY_MODULE_KEYS:
        previous_job = await asyncio.to_thread(_commerce_analysis_get_job, previous_job_id)
        previous_url = str(previous_job.get("url") or "") if isinstance(previous_job, dict) else ""
        previous_result = previous_job.get("result") if isinstance(previous_job, dict) else None
        if (
            isinstance(previous_result, dict)
            and previous_url
            and _commerce_agent_safe_url(previous_url) == _commerce_agent_safe_url(url)
        ):
            result = _commerce_analysis_merge_module_retry(previous_result, result, requested_module, url, import_mode)
    result = _commerce_analysis_attach_contract(result, job_id=job["id"], mode=import_mode)
    result["collection"] = dict(result.get("collection") or {})
    result["collection"]["filename"] = str(payload.filename or "")[:240]
    snapshot_path = await asyncio.to_thread(
        _commerce_analysis_write_snapshot,
        job["id"],
        result,
        {"import": _commerce_analysis_public_item_for_storage(data)},
    )
    result["collection"]["snapshotPath"] = snapshot_path
    await asyncio.to_thread(
        _commerce_analysis_update_job,
        job["id"],
        status=result.get("status") if result.get("status") in {"ready", "partial"} else "failed",
        stage="completed",
        progress=100,
        message=result.get("message") or "已导入商品分析结果",
        source="import",
        finished_at=_commerce_analysis_now(),
        result_json=_commerce_analysis_json(result),
        error="" if result.get("status") in {"ready", "partial"} else result.get("message") or "导入结果不可用",
    )
    if result.get("status") in {"ready", "partial"}:
        _commerce_analysis_schedule_detail_cache_prewarm(result, job["id"])
    return result


