def _compose_vertical_canvas(images, target_width, scaled_heights):
    canvas = Image.new("RGB", (target_width, sum(scaled_heights)), "white")
    resampling = getattr(Image, "Resampling", Image).LANCZOS
    try:
        y = 0
        for source, height in zip(images, scaled_heights):
            oriented = ImageOps.exif_transpose(source)
            rgb = None
            resized = None
            try:
                if image_has_alpha(oriented):
                    rgba = oriented.convert("RGBA")
                    white = Image.new("RGBA", rgba.size, "white")
                    try:
                        white.alpha_composite(rgba)
                        rgb = white.convert("RGB")
                    finally:
                        rgba.close()
                        white.close()
                else:
                    rgb = oriented.convert("RGB")
                resized = rgb if rgb.size == (target_width, height) else rgb.resize((target_width, height), resampling)
                canvas.paste(resized, (0, y))
                y += height
            finally:
                if resized is not None and resized is not rgb:
                    resized.close()
                if rgb is not None:
                    rgb.close()
                if oriented is not source:
                    oriented.close()
        return canvas
    except Exception:
        canvas.close()
        raise


def _detail_stitch_dimensions(sizes, max_width=4096, max_height=50_000, max_pixels=120_000_000):
    def scaled_heights(width):
        return [max(1, round(height * width / source_width)) for source_width, height in sizes]

    low, high = 1, min(max_width, *(width for width, _ in sizes))
    best = None
    while low <= high:
        width = (low + high) // 2
        heights = scaled_heights(width)
        total_height = sum(heights)
        if total_height <= max_height and width * total_height <= max_pixels:
            best = (width, heights, total_height)
            low = width + 1
        else:
            high = width - 1
    if best is None:
        raise ValueError("这些详情图即使缩至最小宽度仍超过单图上限；请减少屏数")
    return best


@app.post("/api/canvas-detail-stitch")
async def canvas_detail_stitch(payload: CanvasDetailStitchRequest, request: Request):
    for url in payload.urls:
        share = _share_request_media_access(request, url)
        if share and not _share_editor_asset_mutation_allowed(share):
            raise HTTPException(status_code=403, detail="当前分享链接不能拼接详情页图片")
    def _build_detail_stitch():
        urls = [str(url or "").strip() for url in payload.urls]
        if not 2 <= len(urls) <= 100:
            raise ValueError("请选择 2–100 张已完成的 9:16 详情图")
        sources = []
        sizes = []
        try:
            for index, url in enumerate(urls, 1):
                path = output_file_from_url(url)
                if not path or not os.path.isfile(path):
                    raise ValueError(f"第 {index} 屏不是可读取的本地图片，请先保存到小美画布素材")
                source = None
                try:
                    source = Image.open(path)
                    width, height = source.size
                    orientation = source.getexif().get(274, 1)
                    if orientation in (5, 6, 7, 8):
                        width, height = height, width
                    if width < 1 or height < 1 or width * height > 50_000_000:
                        raise ValueError("图片尺寸无效或超过 5000 万像素")
                    if width >= height and payload.allow_compatible_portrait:
                        raise ValueError(f"实际比例为 {width}:{height}，详情页分屏需要竖图")
                    if not payload.allow_compatible_portrait and abs(width / height - 9 / 16) > (9 / 16) * 0.03:
                        raise ValueError(f"实际比例为 {width}:{height}，仅支持 9:16；请重新生成该屏")
                except Exception as exc:
                    if source is not None:
                        source.close()
                    raise ValueError(f"第 {index} 屏无法拼接：{exc}") from exc
                sources.append(source)
                sizes.append((width, height))
            if payload.allow_compatible_portrait:
                first_width, first_height = sizes[0]
                first_ratio = first_width / first_height
                for index, (width, height) in enumerate(sizes[1:], 2):
                    if abs(width / height - first_ratio) > first_ratio * 0.03:
                        raise ValueError(
                            f"第 {index} 屏实际比例为 {width}:{height}，与第 1 屏的 {first_width}:{first_height} 不一致；请统一分屏比例"
                        )
            target_width, heights, total_height = _detail_stitch_dimensions(sizes)
            try:
                canvas = _compose_vertical_canvas(sources, target_width, heights)
            except Exception as exc:
                raise ValueError("图片解码或拼接失败，请检查源图后重试") from exc
            try:
                filename = generated_output_filename("detail_page_", ".png")
                path = output_path_for(filename, "output")
                os.makedirs(os.path.dirname(path), exist_ok=True)
                temporary = f"{path}.tmp"
                try:
                    canvas.save(temporary, format="PNG", compress_level=3)
                    os.replace(temporary, path)
                finally:
                    if os.path.exists(temporary):
                        os.remove(temporary)
            finally:
                canvas.close()
            result_url = output_url_for(filename, "output")
            first_width, first_height = sizes[0]
            divisor = math.gcd(first_width, first_height)
            actual_ratio = "9:16" if abs(first_width / first_height - 9 / 16) <= (9 / 16) * 0.03 else f"{first_width // divisor}:{first_height // divisor}"
            record = asset_registry_register_media(
                result_url, name="详情页长图.png", kind="image", source="generated",
                derived_from=urls, metadata={"operation": "detail-stitch", "screens": len(urls),
                                             "source_ratio": actual_ratio},
            )
            return {"url": result_url, "name": "详情页长图.png", "width": target_width,
                    "height": total_height, "actual_ratio": actual_ratio,
                    "scaled_down": target_width < min(width for width, _ in sizes),
                    "asset_ref_id": (record or {}).get("id", "")}
        finally:
            for source in sources:
                source.close()

    try:
        return await asyncio.to_thread(_build_detail_stitch)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc


@app.post("/api/commerce/long-preview")
async def commerce_long_preview(payload: CanvasAssetDownloadRequest):
    """按任务顺序把成功图片纵向拼接成一张长图，兼容本地和远程 API 图片。"""
    def _build_long_image():
        images = []
        raw_items = payload.items or [{"url": url} for url in payload.urls]
        for raw in raw_items[:80]:
            text = str((raw.get("url") if isinstance(raw, dict) else raw) or "").strip()
            if not text:
                continue
            path = output_file_from_url(text)
            source = None
            try:
                if path and os.path.isfile(path):
                    source = Image.open(path)
                else:
                    local_by_name = local_media_file_by_basename(filename_from_media_url(text, ""))
                    if local_by_name and os.path.isfile(local_by_name):
                        source = Image.open(local_by_name)
                    else:
                        remote = fetch_remote_media_bytes(text)
                        if remote:
                            source = Image.open(BytesIO(remote[0]))
                if source is None:
                    continue
                image = ImageOps.exif_transpose(source)
                image.load()
                if image.mode in ("RGBA", "LA") or (image.mode == "P" and "transparency" in image.info):
                    rgba = image.convert("RGBA")
                    white = Image.new("RGBA", rgba.size, "white")
                    white.alpha_composite(rgba)
                    image = white.convert("RGB")
                else:
                    image = image.convert("RGB")
                images.append(image)
            except Exception as exc:
                print(f"[commerce-preview] 跳过无法读取的图片 {text}: {exc}")
            finally:
                try:
                    if source is not None:
                        source.close()
                except Exception:
                    pass
        if not images:
            raise ValueError("没有可拼接的成功图片")
        target_width = min(1200, max(image.width for image in images))
        target_width = max(320, target_width)
        scaled_heights = [max(1, round(image.height * target_width / image.width)) for image in images]
        total_height = sum(scaled_heights)
        if total_height > 50000:
            target_width = max(240, round(target_width * 50000 / total_height))
            scaled_heights = [max(1, round(image.height * target_width / image.width)) for image in images]
            total_height = sum(scaled_heights)
        try:
            canvas = _compose_vertical_canvas(images, target_width, scaled_heights)
            try:
                output = BytesIO()
                canvas.save(output, format="PNG", optimize=True)
                return output.getvalue()
            finally:
                canvas.close()
        finally:
            for image in images:
                image.close()

    try:
        content = await asyncio.to_thread(_build_long_image)
    except Exception as exc:
        raise HTTPException(status_code=422, detail=f"长图拼接失败：{exc}") from exc
    filename = sanitize_export_filename(payload.filename or "小美画布-长图预览.png", "小美画布-长图预览.png")
    if not filename.lower().endswith(".png"):
        filename += ".png"
    encoded = urllib.parse.quote(filename)
    return Response(content, media_type="image/png", headers={"Content-Disposition": f"inline; filename*=UTF-8''{encoded}"})

def sanitize_export_filename(name: str, fallback: str) -> str:
    base = os.path.basename(str(name or "").strip()) or fallback
    base = re.sub(r'[\\/:*?"<>|]+', "_", base)
    return base or fallback

