@app.post("/api/asset-library/workflows/upload")
async def upload_asset_library_workflows(
    files: List[UploadFile] = File(...),
    library_id: str = Form(""),
    category_id: str = Form(""),
    names: str = Form("[]"),
    description: str = Form(""),
):
    library, category = asset_library_workflows.destination(load_asset_library(), library_id, category_id, strict=bool(library_id))
    target_library = library["id"]
    target_category = (category or {}).get("id") or category_id
    try:
        display_names = json.loads(names)
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail="工作流名称格式无效")
    if not isinstance(display_names, list) or any(not isinstance(name, str) for name in display_names):
        raise HTTPException(status_code=400, detail="工作流名称必须是文字列表")
    added = []
    description = description.strip()[:2000]
    with ExitStack() as batch:
        for index, file in enumerate(files[:100]):
            raw = await file.read()
            filename = file.filename or "canvas-workflow.zip"
            if not (filename.lower().endswith(asset_library_workflows.WORKFLOW_EXTENSIONS) or raw.startswith(b"PK")):
                continue
            label = display_names[index] if index < len(display_names) else Path(filename).stem
            item = batch.enter_context(asset_library_workflows.store(
                ASSET_LIBRARY_DIR, raw, filename, label, now_ms(), output_file_from_url,
            ))
            item["description"] = description
            added.append(item)
        if not added:
            raise HTTPException(status_code=400, detail="没有可上传的工作流文件")
        catalog = _publish_asset_library_workflows(added, target_library, target_category, strict=True)
    return {"library": catalog, "items": added}


