def image_space_prepare_library(lib):
    for library in lib.get("libraries", []):
        for category in library.get("categories", []):
            for item in category.get("items", []):
                if item.get("classification"):
                    item["classification"] = asset_annotations.normalize(item["classification"])
                url = item.get("url") or ""
                path = output_file_from_url(url)
                if path is None and category.get("type") == "workflow":
                    repaired = asset_library_workflows.legacy_file_url(ASSET_LIBRARY_DIR, url)
                    if repaired:
                        item["url"] = repaired
                image_space_dimensions(item, path)
    return lib


