_IMAGE_SPACE_DIMENSIONS = {}


def image_space_dimensions(item, path):
    if not path or asset_library_media_kind(path) != "image":
        return
    try:
        stat = os.stat(path)
        key = (path, stat.st_mtime_ns, stat.st_size)
        size = _IMAGE_SPACE_DIMENSIONS.get(key)
        if size is None:
            if os.path.splitext(path)[1].lower() == ".svg":
                from svg_media import generated_svg_meta
                with open(path, "rb") as stream:
                    meta = generated_svg_meta(stream.read())
                if not meta:
                    return
                size = meta["natural_w"], meta["natural_h"]
            else:
                with Image.open(path) as img:
                    size = img.size
            if len(_IMAGE_SPACE_DIMENSIONS) > 10000:
                _IMAGE_SPACE_DIMENSIONS.clear()
            _IMAGE_SPACE_DIMENSIONS[key] = size
        item["width"], item["height"] = size
    except (OSError, ValueError, Image.DecompressionBombError):
        pass


def image_space_read_generated_classification(path):
    return asset_annotations.read_classification(path + ".classification.json")


def image_space_collections():
    path = os.path.join(DATA_DIR, "image_space_collections.json")
    if not os.path.isfile(path):
        return []
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


