async def update_image_space_collection(collection_id: str, payload: ImageSpaceCollectionRequest):
    items = image_space_collections()
    item = next((entry for entry in items if entry["id"] == collection_id), None)
    if item is None:
        raise HTTPException(status_code=404, detail="合集不存在")
    if not payload.name.strip():
        raise HTTPException(status_code=400, detail="请输入合集名称")
    item.update(payload.model_dump() if hasattr(payload, "model_dump") else payload.dict(), name=payload.name.strip())
    _atomic_write_json_locked(os.path.join(DATA_DIR, "image_space_collections.json"), items)
    return {"collections": items, "item": item}


