@app.get("/api/shared-folders/{folder_id}/file")
async def get_shared_folder_file(folder_id: str, path: str = ""):
    entry = shared_folder_by_id(folder_id)
    if not entry:
        raise HTTPException(status_code=404, detail="共享文件夹不存在")
    folder_abs = shared_folder_abs(entry)
    abs_path = shared_child_abs(folder_abs, path)
    if not os.path.isfile(abs_path):
        raise HTTPException(status_code=404, detail="文件不存在")
    ext = os.path.splitext(abs_path)[1].lower()
    if ext not in shared_media.EXTENSIONS:
        raise HTTPException(status_code=400, detail="不支持的文件类型")
    return FileResponse(abs_path, media_type=content_type_for_path(abs_path))

@app.post("/api/shared-folders/import")
async def import_shared_folder_files(payload: SharedFolderImport):
    entry = shared_folder_by_id(payload.folder_id)
    if not entry:
        raise HTTPException(status_code=404, detail="共享文件夹不存在")
    folder_abs = shared_folder_abs(entry)
    lib = load_asset_library()
    cat = find_asset_category_in_library(lib, payload.category_id, payload.library_id)
    if not cat:
        raise HTTPException(status_code=404, detail="分类不存在")
    if cat.get("type") != "image":
        raise HTTPException(status_code=400, detail="该分类暂不支持添加媒体")
    added = []
    for rel in (payload.paths or [])[:200]:
        abs_path = shared_child_abs(folder_abs, rel)
        if not os.path.isfile(abs_path):
            continue
        ext = os.path.splitext(abs_path)[1].lower()
        if ext not in shared_media.EXTENSIONS:
            continue
        _, item = make_asset_library_item(abs_path, os.path.basename(abs_path), subdir=cat.get("dir") or "")
        if item.get("kind") == "image":
            classification = await classify_asset_image_best_effort(output_file_from_url(item.get("url") or "") or abs_path)
            if classification:
                item["classification"] = classification
        cat.setdefault("items", []).append(item)
        added.append(item)
    save_asset_library(lib, merge_items=added)
    return {"library": lib, "items": added}

async def caption_image_with_provider(abs_path, prompt, provider_id, model, ms_model=""):
    provider = get_api_provider(provider_id)
    prompt_text = str(prompt or "").strip() or "描述图片"
    cli = None
    if is_codex_provider(provider):
        cli = ("codex", CODEX_DEFAULT_CHAT_MODELS, codex_chat_text)
    elif is_gemini_cli_provider(provider):
        cli = ("gemini-cli", GEMINI_CLI_DEFAULT_CHAT_MODELS, gemini_cli_chat_text)
    if cli is not None:
        identifier, fallback, request_caption = cli
        resolved = selected_model(model, (provider.get("chat_models") or fallback)[0])
        payload = CanvasLLMRequest(message=prompt_text, provider=provider_id or identifier, model=resolved, images=[abs_path])
        text, _ = await request_caption(payload, [])
        return text, resolved

    root, headers, resolved = resolve_chat_provider(provider_id, model, ms_model)
    try:
        raw = await asset_annotations.request_caption(
            abs_path, prompt_text, root + "/chat/completions", headers, resolved,
            timeout=AI_REQUEST_TIMEOUT, non_streaming=is_apimart_provider(provider),
        )
    except httpx.HTTPStatusError as exc:
        message = exc.response.text
        detail = friendly_chat_error_detail(message, resolved, provider)
        raise HTTPException(exc.response.status_code, detail or f"上游接口错误。{message}") from exc
    except httpx.HTTPError as exc:
        log_net_error(f"素材识图 provider={provider.get('id')} model={resolved}", exc)
        raise HTTPException(502, f"请求上游识图接口失败。{exc}") from exc
    except (ValueError, OSError) as exc:
        raise HTTPException(502, f"无法读取图片或解析上游识图结果。{exc}") from exc
    text = text_from_chat_response(raw).strip() if isinstance(raw, dict) else ""
    return text or "接口返回了空回复。", resolved


