def load_asset_favorites():
    if not os.path.exists(ASSET_FAVORITES_PATH):
        return {"version": 1, "items": []}
    try:
        with open(ASSET_FAVORITES_PATH, "r", encoding="utf-8-sig") as fh:
            data = json.load(fh)
    except Exception:
        data = {}
    items = data.get("items") if isinstance(data, dict) else None
    if not isinstance(items, list):
        items = []
    cleaned = []
    seen = set()
    for item in items:
        if not isinstance(item, dict):
            continue
        key = str(item.get("key") or "").strip()
        if not key or key in seen:
            continue
        seen.add(key)
        cleaned.append({
            "key": key[:300],
            "name": str(item.get("name") or "").strip()[:200],
            "kind": str(item.get("kind") or "generated").strip()[:40],
            "url": str(item.get("url") or "").strip()[:600],
            "media_type": str(item.get("media_type") or "").strip()[:20],
            "folder": str(item.get("folder") or "").strip()[:300],
            "added_at": int(item.get("added_at") or 0),
        })
    cleaned.sort(key=lambda item: item.get("added_at") or 0, reverse=True)
    return {"version": 1, "items": cleaned}

def save_asset_favorites(data):
    os.makedirs(DATA_DIR, exist_ok=True)
    temp_path = f"{ASSET_FAVORITES_PATH}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as fh:
            json.dump(data, fh, ensure_ascii=False, indent=2)
        os.replace(temp_path, ASSET_FAVORITES_PATH)
    finally:
        if os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass
    return data


def _relocate_file_favorites(kind, changes=(), folder_change=None):
    """Keep path-based favorites attached to files when a managed folder changes."""
    if kind not in {"upload", "generated", "local"}:
        return
    mapping = dict(changes)
    old_folder, new_folder = folder_change or (None, None)
    data = load_asset_favorites()
    dirty = False
    for item in data["items"]:
        if item.get("kind") != kind or not str(item.get("key") or "").startswith(kind + ":"):
            continue
        old_rel = item["key"][len(kind) + 1:]
        new_rel = mapping.get(old_rel)
        if new_rel is None and old_folder and old_rel.startswith(old_folder + "/"):
            new_rel = new_folder + old_rel[len(old_folder):]
        if not new_rel or new_rel == old_rel:
            continue
        item["key"] = f"{kind}:{new_rel}"
        item["url"] = (f"/api/storage-files/{kind}/{urllib.parse.quote(new_rel, safe='/')}")
        item["name"] = os.path.basename(new_rel)
        item["folder"] = os.path.dirname(new_rel).replace("\\", "/")
        dirty = True
    if dirty:
        save_asset_favorites(data)

@app.get("/api/asset-favorites")
async def list_asset_favorites():
    data = load_asset_favorites()
    return {"items": data["items"], "keys": [item["key"] for item in data["items"]]}

@app.post("/api/asset-favorites/toggle")
async def toggle_asset_favorite(payload: AssetFavoriteToggleRequest):
    key = str(payload.key or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="缺少收藏标识")
    data = load_asset_favorites()
    existed = any(item.get("key") == key for item in data["items"])
    if existed:
        data["items"] = [item for item in data["items"] if item.get("key") != key]
        favorite = False
    else:
        data["items"].insert(0, {
            "key": key[:300],
            "name": str(payload.name or "").strip()[:200] or key,
            "kind": str(payload.kind or "generated").strip()[:40] or "generated",
            "url": str(payload.url or "").strip()[:600],
            "media_type": str(payload.media_type or "").strip()[:20],
            "folder": str(payload.folder or "").strip()[:300],
            "added_at": now_ms(),
        })
        favorite = True
    save_asset_favorites(data)
    return {"favorite": favorite, "keys": [item["key"] for item in data["items"]], "items": data["items"]}

def find_asset_item_in_library(lib, item_id, library_id=""):
    for library in lib.get("libraries", []):
        if library_id and library.get("id") != library_id:
            continue
        for cat in library.get("categories", []):
            for item in cat.get("items", []):
                if item.get("id") == item_id:
                    return item
    return None


def find_asset_item_location_in_library(lib, item_id, library_id="", category_id="", source_url=None):
    locations = asset_kernel.locate_items(lib, [item_id], library_id, category_id)
    if source_url is not None:
        locations = [location for location in locations if location[2].get("url") == source_url]
        if not locations:
            raise HTTPException(409, "源素材已变化，请刷新后重试")
        if len(locations) != 1:
            raise HTTPException(409, "存在多条匹配素材，请指定来源分组")
    return locations[0] if locations else (None, None, None)

async def _ready_background_removal_model(model_id=BACKGROUND_REMOVAL_MODEL_ID, backend=""):
    model_id = _background_removal_requested_model_id(model_id, backend)
    engine = background_removal_engine_info()
    if not engine.get("available"):
        raise HTTPException(status_code=503, detail=engine.get("message") or "本地抠图运行环境不可用")
    try:
        model = await background_removal_model_definition(model_id)
    except Exception as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    model_path = await asyncio.to_thread(_background_removal_local_model_path, model)
    if not model_path:
        raise HTTPException(status_code=409, detail=f"{model.get('name') or model_id} 尚未下载，请先在抠图入口完成模型下载")
    return model, model_path


def _background_removal_name(source_path, requested_name=""):
    raw = str(requested_name or os.path.splitext(os.path.basename(source_path))[0] or "image").strip()
    raw = os.path.splitext(raw)[0]
    return sanitize_asset_name(raw, "image")


@app.get("/api/background-removal/status")
async def get_background_removal_status():
    engine = background_removal_engine_info()
    try:
        models = await background_removal_model_catalog()
    except Exception as exc:
        return {"engine": engine, "models": [], "catalog_error": str(exc)[:500]}
    states = []
    for model in models:
        downloaded = bool(await asyncio.to_thread(_background_removal_local_model_path, model))
        states.append(_background_removal_public_state(model, downloaded))
    return {"engine": engine, "models": states, "catalog_error": ""}


@app.post("/api/background-removal/models/{model_id}/download")
async def start_background_removal_model_download(model_id: str):
    engine = background_removal_engine_info()
    if not engine.get("available"):
        raise HTTPException(status_code=503, detail=engine.get("message") or "本地抠图运行环境不可用")
    try:
        model = await background_removal_model_definition(model_id, force=True)
    except Exception as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    downloaded = bool(await asyncio.to_thread(_background_removal_local_model_path, model))
    if downloaded:
        state = BACKGROUND_REMOVAL_DOWNLOADS.setdefault(model.get("id"), {"status": "downloaded"})
        state.update({"status": "downloaded", "downloaded_bytes": model.get("size", 0), "total_bytes": model.get("size", 0), "error": ""})
        return _background_removal_public_state(model, True)
    state = BACKGROUND_REMOVAL_DOWNLOADS.get(model.get("id"))
    task = state.get("task") if isinstance(state, dict) else None
    if task is not None and not task.done():
        return _background_removal_public_state(model, False)
    state = {
        "status": "downloading",
        "downloaded_bytes": 0,
        "total_bytes": int(model.get("size") or 0),
        "error": "",
        "task": None,
    }
    state["task"] = asyncio.create_task(_download_background_removal_model(model, state))
    BACKGROUND_REMOVAL_DOWNLOADS[model.get("id")] = state
    return _background_removal_public_state(model, False)


@app.get("/api/background-removal/models/{model_id}/download")
async def get_background_removal_model_download(model_id: str):
    try:
        model = await background_removal_model_definition(model_id)
    except Exception as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    downloaded = bool(await asyncio.to_thread(_background_removal_local_model_path, model))
    return _background_removal_public_state(model, downloaded)


def _local_upscale_require_local_request(request):
    host = getattr(getattr(request, "client", None), "host", "")
    if not _request_host_is_loopback(host) or _request_is_share_gateway(request):
        raise HTTPException(
            status_code=403,
            detail="本地高清模型只能在运行小美画布的电脑上使用，分享页不能调用主机 GPU",
        )


