@app.post("/api/local-upscale/models/{model_id}/download")
async def start_local_upscale_model_download(model_id: str, request: Request):
    _local_upscale_require_local_request(request)
    if str(model_id or "").strip().lower() != LOCAL_UPSCALE_REAL_ESRGAN_ID:
        raise HTTPException(status_code=400, detail="该模型由 ComfyUI 管理，不能在这里下载")
    model = _local_upscale_realesrgan_state()
    if not model.get("available"):
        raise HTTPException(status_code=503, detail=model.get("message") or "当前系统不能运行 Real-ESRGAN")
    if model.get("downloaded"):
        state = LOCAL_UPSCALE_DOWNLOADS.setdefault(model_id, {"status": "downloaded"})
        state.update({
            "status": "downloaded",
            "phase": "ready",
            "downloaded_bytes": LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE["size"],
            "total_bytes": LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE["size"],
            "error": "",
        })
        return _local_upscale_realesrgan_state()
    state = LOCAL_UPSCALE_DOWNLOADS.get(LOCAL_UPSCALE_REAL_ESRGAN_ID)
    task = state.get("task") if isinstance(state, dict) else None
    if task is not None and not task.done():
        return _local_upscale_realesrgan_state()
    state = {
        "status": "downloading",
        "phase": "downloading",
        "downloaded_bytes": 0,
        "total_bytes": LOCAL_UPSCALE_REAL_ESRGAN_PACKAGE["size"],
        "error": "",
        "task": None,
    }
    state["task"] = asyncio.create_task(_download_local_upscale_realesrgan(state))
    LOCAL_UPSCALE_DOWNLOADS[LOCAL_UPSCALE_REAL_ESRGAN_ID] = state
    return _local_upscale_realesrgan_state()


