@app.post("/api/image/local-upscale")
async def upscale_local_image(payload: LocalImageUpscaleRequest, request: Request):
    _local_upscale_require_local_request(request)
    source_url = str(payload.source_url or "").strip()
    _share_request_media_access(request, source_url)
    source_path = local_media_path_from_url(source_url)
    if not source_path or not os.path.isfile(source_path):
        raise HTTPException(status_code=400, detail="只支持处理当前小美画布中的本地图片")
    try:
        return await asyncio.to_thread(
            _local_upscale_process,
            source_path,
            source_url,
            payload.name,
            payload,
        )
    except FileNotFoundError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except subprocess.TimeoutExpired as exc:
        raise HTTPException(status_code=504, detail="本地高清处理超时，请降低倍率后重试") from exc
    except Exception as exc:
        raise HTTPException(status_code=422, detail=f"本地高清放大失败：{str(exc)[:900]}") from exc


