@app.post("/api/image/background-removal")
async def remove_background_image(payload: BackgroundRemovalRequest, request: Request):
    # 共享编辑者只能处理当前分享画布已经引用的图片；本机窗口仍由
    # _share_request_media_access 的回环豁免保持原有行为。
    source_url = str(payload.source_url or "").strip()
    _share_request_media_access(request, source_url)
    if _background_removal_backend(payload.backend, payload.model_id) == "aiarty":
        _aiarty_require_local_request(request)
        source_path = local_media_path_from_url(source_url)
        if not source_path or not os.path.isfile(source_path):
            raise HTTPException(status_code=400, detail="只支持处理当前小美画布中的本地图片")
        try:
            job = await _aiarty_start_job([{
                "source_path": source_path,
                "source_url": source_url,
                "source_name": payload.name or os.path.basename(source_path),
            }], "single", bool(payload.auto_center))
        except HTTPException:
            raise
        except Exception as exc:
            raise HTTPException(status_code=503, detail=str(exc)[:500]) from exc
        return {
            "pending": True,
            "job_id": job.get("id") or "",
            "job": job,
            "backend": "aiarty",
            "message": job.get("message") or "Aiarty 已启动，等待导出透明 PNG",
        }
    model, model_path = await _ready_background_removal_model(payload.model_id, payload.backend)
    source_path = local_media_path_from_url(source_url)
    if not source_path or not os.path.isfile(source_path):
        raise HTTPException(status_code=400, detail="只支持处理当前小美画布中的本地图片")
    output_image = None
    try:
        output_image, meta = await asyncio.to_thread(
            _remove_background_image_from_path,
            source_path,
            model,
            model_path,
            bool(payload.auto_center),
        )
        base = _background_removal_name(source_path, payload.name)
        display_name = f"{base}_透明底.png"
        display_stem, display_ext = os.path.splitext(display_name)
        filename = generated_output_filename(
            "bgremove_",
            display_ext or ".png",
            suffix=f"_{display_stem}",
        )
        output_path = output_path_for(filename, "output")
        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        await asyncio.to_thread(output_image.save, output_path, "PNG", optimize=True)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=422, detail=f"本地抠图失败：{exc}") from exc
    finally:
        if output_image is not None:
            output_image.close()
    return {
        "url": output_url_for(filename, "output"),
        "name": display_name,
        "kind": "image",
        "width": meta.get("width"),
        "height": meta.get("height"),
        "backend": "onnx",
        "model_id": model.get("id"),
        "model_name": model.get("name"),
        "device": background_removal_engine_info().get("device") or "",
        "auto_center": bool(payload.auto_center),
        "background_removal": {
            "backend": "onnx",
            "model_id": model.get("id"),
            "model_name": model.get("name"),
            "device": background_removal_engine_info().get("device") or "",
            "device_is_gpu": bool(background_removal_engine_info().get("device_is_gpu")),
            "auto_center": bool(payload.auto_center),
            **meta,
        },
        "derived_from": {"url": source_url, "operation": "background-removal"},
    }


@app.post("/api/asset-library/items/background-removal")
async def remove_background_asset_library_items(payload: AssetLibraryBackgroundRemovalRequest, request: Request):
    ordered_ids = []
    seen_ids = set()
    for value in (payload.ids or [])[:100]:
        item_id = str(value or "").strip()
        if item_id and item_id not in seen_ids:
            seen_ids.add(item_id)
            ordered_ids.append(item_id)
    if not ordered_ids:
        raise HTTPException(status_code=400, detail="没有选择图片素材")
    if _background_removal_backend(payload.backend, payload.model_id) == "aiarty":
        _aiarty_require_local_request(request)
        lib = load_asset_library()
        source_specs = []
        for item_id in ordered_ids:
            source_library, source_cat, item = find_asset_item_location_in_library(lib, item_id, payload.library_id)
            if not item:
                continue
            if item.get("kind") != "image" and asset_library_media_kind(item.get("url") or "") != "image":
                continue
            source_path = output_file_from_url(item.get("url") or "")
            if not source_path or not os.path.isfile(source_path):
                continue
            source_specs.append({
                "asset_id": item.get("id") or item_id,
                "source_url": item.get("url") or "",
                "source_path": source_path,
                "source_name": item.get("name") or os.path.basename(source_path),
                "source_library_id": source_library.get("id") if source_library else payload.library_id,
                "source_category_id": source_cat.get("id") if source_cat else "",
                "target_library_id": payload.target_library_id or (source_library.get("id") if source_library else payload.library_id),
                "target_category_id": payload.target_category_id or (source_cat.get("id") if source_cat else ""),
            })
        if not source_specs:
            raise HTTPException(status_code=400, detail="没有找到可交给 Aiarty 处理的本地图片")
        try:
            job = await _aiarty_start_job(source_specs, "asset_batch", bool(payload.auto_center))
        except HTTPException:
            raise
        except Exception as exc:
            raise HTTPException(status_code=503, detail=str(exc)[:500]) from exc
        return {
            "pending": True,
            "job_id": job.get("id") or "",
            "job": job,
            "backend": "aiarty",
            "message": job.get("message") or "Aiarty 已启动，等待导出透明 PNG",
        }
    model, model_path = await _ready_background_removal_model(payload.model_id, payload.backend)
    lib = load_asset_library()
    target_cat = None
    if payload.target_category_id:
        target_cat = find_asset_category_in_library(lib, payload.target_category_id, payload.target_library_id)
        if not target_cat:
            raise HTTPException(status_code=404, detail="目标分组不存在")
        if target_cat.get("type") != "image":
            raise HTTPException(status_code=400, detail="目标分组不支持图片")

    added = []
    results = []
    for item_id in ordered_ids:
        source_library, source_cat, item = find_asset_item_location_in_library(lib, item_id, payload.library_id)
        result = {"id": item_id, "ok": False, "item": None, "error": ""}
        if not item:
            result["error"] = "素材不存在"
            results.append(result)
            continue
        if item.get("kind") != "image" and asset_library_media_kind(item.get("url") or "") != "image":
            result["error"] = "仅支持图片素材去背景"
            results.append(result)
            continue
        source_path = output_file_from_url(item.get("url") or "")
        if not source_path or not os.path.isfile(source_path):
            result["error"] = "原图文件不存在"
            results.append(result)
            continue
        output_image = None
        temp_path = ""
        try:
            output_image, meta = await asyncio.to_thread(
                _remove_background_image_from_path,
                source_path,
                model,
                model_path,
                bool(payload.auto_center),
            )
            temp_file = tempfile.NamedTemporaryFile(prefix="bgremove_", suffix=".png", delete=False)
            temp_path = temp_file.name
            temp_file.close()
            await asyncio.to_thread(output_image.save, temp_path, "PNG", optimize=True)
            dest_cat = target_cat or source_cat
            base = _background_removal_name(source_path, item.get("name") or "")
            _, next_item = make_asset_library_item(temp_path, f"{base}_透明底.png", subdir=dest_cat.get("dir") or "")
            next_item["derived_from"] = {
                "asset_id": item.get("id"),
                "url": item.get("url"),
                "operation": "background-removal",
            }
            next_item["background_removal"] = {
                "backend": "onnx",
                "model_id": model.get("id"),
                "model_name": model.get("name"),
                "device": background_removal_engine_info().get("device") or "",
                "device_is_gpu": bool(background_removal_engine_info().get("device_is_gpu")),
                "auto_center": bool(payload.auto_center),
                **meta,
            }
            dest_cat.setdefault("items", []).append(next_item)
            added.append(next_item)
            result.update({"ok": True, "item": next_item})
        except Exception as exc:
            result["error"] = str(exc)[:500]
        finally:
            if output_image is not None:
                output_image.close()
            if temp_path and os.path.exists(temp_path):
                try:
                    os.remove(temp_path)
                except OSError:
                    pass
        results.append(result)
    if added:
        save_asset_library(lib, merge_items=added)
    return {
        "library": lib,
        "count": len(added),
        "items": added,
        "results": results,
        "failed": [item for item in results if not item.get("ok")],
    }

@app.post("/api/asset-library/items/classify")
async def classify_asset_library_items(payload: AssetLibraryClassifyRequest):
    async def annotate(item_id):
        library = load_asset_library()
        item = find_asset_item_in_library(library, item_id, payload.library_id)
        if item is None:
            raise HTTPException(404, "资产不存在")
        url = item.get("url") or ""
        if item.get("kind") != "image" and asset_library_media_kind(url) != "image":
            raise HTTPException(400, "仅支持图片素材智能分类")
        path = output_file_from_url(url)
        if not path or not os.path.isfile(path):
            raise HTTPException(404, "文件不存在")
        value = await classify_image_with_provider(path, payload.provider, payload.model, payload.ms_model, payload.prompt)
        with ASSET_LIBRARY_IO_LOCK:
            latest = load_asset_library()
            current = find_asset_item_in_library(latest, item_id, payload.library_id)
            if current is None:
                raise HTTPException(404, "素材已被移除")
            if current.get("url") != url:
                raise HTTPException(409, "分析期间素材地址已变更。请刷新后重试。")
            saved = asset_annotations.replace_ai(current.get("classification"), value)
            current["classification"] = saved
            save_asset_library(latest)
        return {"classification": saved}

    result = await asset_annotations.batch(
        payload.ids[:80], "id", annotate, defaults={"classification": None, "error": ""},
    )
    return {"library": load_asset_library(), **result}


AVATAR_REVIEWS = AvatarReviews(
    lambda: load_asset_library(), lambda library: save_asset_library(library),
    find_asset_item_location_in_library, ASSET_LIBRARY_IO_LOCK, now_ms,
)


@app.post("/api/asset-library/items/{item_id}/register-avatar")
async def register_asset_library_avatar(item_id: str, payload: AssetAvatarRegisterRequest):
    provider = get_api_provider(payload.provider_id)
    platform = avatar_platform_for_provider(provider)
    if platform not in AVATAR_SUPPORTED_PLATFORMS:
        name = (provider or {}).get("name") or (provider or {}).get("id") or "该平台"
        raise HTTPException(status_code=400, detail=f"「{name}」暂不支持素材认证。")
    requested_project = provider.get("volcengine_project_name") if platform == "volcengine" else payload.project_name
    project = str(requested_project or "default").strip() or "default"
    return await AVATAR_REVIEWS.submit(
        payload.library_id, item_id, platform, provider["id"], project,
        lambda media: _submit_avatar_review(platform, provider, media, project, payload.group_name),
        category_id=payload.category_id, source_url=payload.source_url,
    )


@app.post("/api/asset-library/items/{item_id}/avatar-status")
async def check_asset_library_avatar(item_id: str, payload: AssetAvatarRegisterRequest):
    provider = get_api_provider(payload.provider_id or "")
    platform = avatar_platform_for_provider(provider)
    if platform not in AVATAR_SUPPORTED_PLATFORMS:
        raise HTTPException(status_code=400, detail="该平台暂不支持数字人/真人认证审核。")
    return await AVATAR_REVIEWS.status(
        payload.library_id, item_id, platform,
        lambda task_id, stored_provider, project: _query_avatar_review(platform, provider, task_id, stored_provider, project),
        category_id=payload.category_id, source_url=payload.source_url,
    )


@app.delete("/api/asset-library/items/{item_id}")
async def delete_asset_library_item(item_id: str):
    lib = load_asset_library()
    matches = asset_kernel.locate_items(lib, [item_id])
    if not matches:
        raise HTTPException(status_code=404, detail="资产不存在")
    for _library, _cat, item in matches:
        record = _asset_library_item_registry_record(item)
        asset_registry_require_unreferenced(str(record.get("id") or ""))
    trashed_asset_ids = []
    try:
        for library, cat, item in matches:
            trashed_asset_ids.append(_trash_asset_library_item(library, cat, item, reason="asset_library_delete"))
        asset_kernel.detach_objects(lib, [item for _library, _cat, item in matches])
        save_asset_library(lib)
    except Exception:
        for asset_id in reversed(trashed_asset_ids):
            try:
                _asset_registry_restore_media(asset_id)
            except Exception:
                pass
        raise
    return {"library": lib, "trashed_asset_ids": trashed_asset_ids}

@app.post("/api/asset-library/items/delete")
async def batch_delete_asset_library_items(payload: AssetLibraryBatchDeleteRequest):
    ids = {str(item) for item in (payload.ids or []) if str(item)}
    empty_category_id = str(payload.remove_empty_category_id or "").strip()
    if not ids and not empty_category_id:
        raise HTTPException(status_code=400, detail="没有选择资产")
    if empty_category_id and not payload.library_id:
        raise HTTPException(status_code=400, detail="请指定要移除空分组的资产库")
    lib = load_asset_library()
    if payload.sources is None:
        matches = asset_kernel.locate_items(lib, ids, payload.library_id, empty_category_id)
    else:
        if not payload.library_id or empty_category_id:
            raise HTTPException(status_code=400, detail="请指定源素材库")
        matches = asset_kernel.scoped_item_locations(lib, ids, payload.library_id, [entry.model_dump() for entry in payload.sources])
        if matches is None:
            raise HTTPException(status_code=409, detail="源素材已变化，请刷新后重试")
    records = []
    preserved_asset_ids = []
    reference_scan_cache = {}
    if payload.sources is not None:
        removing = {id(item) for _, _, item in matches}
        retained_paths = {
            path
            for library in lib.get("libraries", [])
            for category in library.get("categories", [])
            for item in category.get("items", [])
            if id(item) not in removing
            if (path := registry_url_key(_asset_registry_trackable_url(item.get("url"))))
        }
    else:
        retained_paths = set()
    if retained_paths and any(
        registry_url_key(_asset_registry_trackable_url(item.get("url"))) in retained_paths
        for _, _, item in matches
    ):
        raise HTTPException(status_code=409, detail="该文件仍由其他分组使用，无法移入回收站")
    for _library, _cat, item in matches:
        record = _asset_library_item_registry_record(item)
        asset_id = str(record.get("id") or "")
        records.append((item, asset_id))
        if payload.preserve_referenced and asset_registry_reference_summary(asset_id, reference_scan_cache)["total"]:
            preserved_asset_ids.append(asset_id)
        else:
            asset_registry_require_unreferenced(asset_id, reference_scan_cache)
    trashed_asset_ids = []
    removed_category_id = ""
    try:
        preserved = set(preserved_asset_ids)
        asset_ids = {id(item): asset_id for item, asset_id in records}
        for library, cat, item in matches:
            asset_id = asset_ids.get(id(item))
            if asset_id in preserved:
                continue
            try:
                trashed_asset_ids.append(_trash_asset_library_item(
                    library, cat, item, reason="asset_library_batch_delete", reference_scan_cache=reference_scan_cache,
                ))
            except HTTPException as exc:
                if not payload.preserve_referenced or exc.status_code != 409:
                    raise
                preserved_asset_ids.append(asset_id)
                preserved.add(asset_id)
        asset_kernel.detach_objects(lib, [item for _library, _cat, item in matches])
        removed_category_id = asset_kernel.drop_empty_image_group(lib, payload.library_id, empty_category_id)
        save_asset_library(lib)
    except Exception:
        for asset_id in reversed(trashed_asset_ids):
            try:
                _asset_registry_restore_media(asset_id)
            except Exception:
                pass
        raise
    return {
        "library": lib,
        "removed": len(matches),
        "trashed_asset_ids": trashed_asset_ids,
        "preserved_referenced": len(preserved_asset_ids),
        "removed_category_id": removed_category_id,
    }

@app.post("/api/asset-library/items/move")
async def batch_move_asset_library_items(payload: AssetLibraryBatchMoveRequest):
    ids = {str(item) for item in (payload.ids or []) if str(item)}
    if not ids:
        raise HTTPException(status_code=400, detail="没有选择资产")
    if payload.sources is not None and not payload.library_id:
        raise HTTPException(status_code=400, detail="请指定源素材库")
    sources = None if payload.sources is None else [entry.model_dump() for entry in payload.sources]
    with ASSET_LIBRARY_IO_LOCK:
        lib = load_asset_library()
        outcome = asset_kernel.move_items(lib, ids, payload.library_id, payload.target_library_id, payload.target_category_id, sources)
        if outcome.get("error"):
            raise HTTPException(status_code=int(outcome.get("status") or 400), detail=outcome["error"])
        if outcome["moved"]:
            save_asset_library(lib)
    return {"library": lib, "moved": outcome["moved"]}

@app.post("/api/asset-library/items/crop")
async def batch_crop_asset_library_items(payload: AssetLibraryBatchCropRequest):
    ids = {str(item) for item in (payload.ids or []) if str(item)}
    if not ids:
        raise HTTPException(status_code=400, detail="没有选择资产")
    lib = load_asset_library()
    target_cat = None
    if payload.target_category_id:
        target_cat = find_asset_category_in_library(lib, payload.target_category_id, payload.target_library_id)
        if not target_cat:
            raise HTTPException(status_code=404, detail="目标分组不存在")
        if target_cat.get("type") != "image":
            raise HTTPException(status_code=400, detail="目标分组不支持媒体")
    added = []

    def center_crop_to_temp(src):
        """解码 + 居中裁剪 + 落临时 PNG；图像 IO 必须离开事件循环。"""
        with Image.open(src) as img:
            img = img.convert("RGBA")
            w, h = img.size
            box = asset_kernel.center_box(w, h)
            if not box:
                return None
            cropped = img.crop(box)
            tmp = tempfile.NamedTemporaryFile(delete=False, suffix=".png")
            tmp_path = tmp.name
            tmp.close()
            cropped.save(tmp_path, "PNG")
            return tmp_path

    for library in lib.get("libraries", []):
        if payload.library_id and library.get("id") != payload.library_id:
            continue
        for cat in library.get("categories", []):
            if cat.get("type") != "image":
                continue
            source_items = [item for item in (cat.get("items", []) or []) if item.get("id") in ids]
            for item in source_items:
                src = output_file_from_url(item.get("url") or "")
                if not src or not os.path.isfile(src):
                    continue
                try:
                    # 批量裁剪是 N 张大图的解码与编码，留在事件循环里会让整个应用卡住。
                    tmp_path = await asyncio.to_thread(center_crop_to_temp, src)
                    if not tmp_path:
                        continue
                    try:
                        base_name = os.path.splitext(item.get("name") or "asset")[0] + "_crop.png"
                        dest_cat = target_cat or cat
                        _, next_item = make_asset_library_item(tmp_path, base_name, subdir=dest_cat.get("dir") or "")
                        next_item["derived_from"] = {
                            "asset_id": item.get("asset_ref_id") or item.get("id") or "",
                            "url": item.get("url") or "",
                            "operation": "center-crop",
                        }
                        dest_cat.setdefault("items", []).append(next_item)
                        added.append(next_item)
                    finally:
                        try:
                            os.remove(tmp_path)
                        except Exception:
                            pass
                except Exception:
                    continue
    save_asset_library(lib)
    return {"library": lib, "added": len(added), "items": added}

@app.put("/api/canvases/{canvas_id}")
async def update_canvas(canvas_id: str, payload: CanvasSaveRequest, request: Request):
    _share_request_canvas_access(request, canvas_id, write=True)
    lock_conflicts = manager.collab_lock_conflicts(
        _share_clean_canvas_id(canvas_id),
        _collab_clean_id(payload.client_id),
        [str(item.get("id") or "") for item in (payload.nodes or []) if isinstance(item, dict)],
    )
    if lock_conflicts:
        raise HTTPException(status_code=423, detail={"message": "有其他成员正在编辑这些节点，请稍后重试。", "locks": lock_conflicts})
    def mutate_canvas():
        with CANVAS_LOCK:
            canvas = load_canvas(canvas_id)
            current_updated_at = int(canvas.get("updated_at") or 0)
            if payload.base_updated_at and current_updated_at and int(payload.base_updated_at) < current_updated_at:
                raise HTTPException(status_code=409, detail={
                    "message": "画布已被其他页面更新，已拒绝旧版本覆盖。",
                    "canvas": canvas,
                    "updated_at": current_updated_at,
                })
            canvas["title"] = (payload.title or canvas.get("title") or "未命名画布")[:80]
            canvas["icon"] = (payload.icon or canvas.get("icon") or "layers")[:32]
            canvas["kind"] = normalize_canvas_kind(canvas.get("kind"))
            old_nodes = [item for item in (canvas.get("nodes") or []) if isinstance(item, dict)]
            old_by_id = {str(item.get("id") or ""): item for item in old_nodes if item.get("id")}
            revision = now_ms()
            prepared_nodes = []
            for incoming in (payload.nodes or []):
                node = dict(incoming or {})
                node_id = str(node.get("id") or "")
                previous = old_by_id.get(node_id)
                comparable = dict(node)
                comparable.pop("_collab_updated_at", None)
                previous_comparable = dict(previous or {})
                previous_comparable.pop("_collab_updated_at", None)
                try:
                    unchanged = bool(previous) and json.dumps(comparable, ensure_ascii=False, sort_keys=True) == json.dumps(previous_comparable, ensure_ascii=False, sort_keys=True)
                except Exception:
                    unchanged = False
                node["_collab_updated_at"] = int(previous.get("_collab_updated_at") or current_updated_at or revision) if unchanged else revision
                prepared_nodes.append(node)
            canvas["nodes"] = prepared_nodes
            canvas["connections"] = payload.connections
            if canvas["kind"] == "smart":
                canvas["viewport"] = payload.viewport
            else:
                canvas["viewport"] = canvas.get("viewport") or {"x": 0, "y": 0, "scale": 1}
            canvas["logs"] = payload.logs[-500:]
            canvas["settings"] = payload.settings or {}
            _write_canvas_file_locked(canvas)
            return canvas

    canvas = await asyncio.to_thread(mutate_canvas)
    updated_at = int(canvas.get("updated_at") or now_ms())
    await workspace_events.broadcast_canvas_updated(canvas_id, updated_at, payload.client_id)
    await manager.broadcast_collab(canvas_id, {
        "type": "collab_canvas_changed",
        "client_id": _collab_clean_id(payload.client_id),
        "updated_at": updated_at,
        "changed_ids": [str(item.get("id") or "") for item in (payload.nodes or []) if isinstance(item, dict) and item.get("id")],
    })
    return {"canvas": canvas}


@app.patch("/api/canvases/{canvas_id}/nodes")
async def patch_canvas_nodes(canvas_id: str, payload: CanvasNodeChangesRequest, request: Request):
    """Apply only changed nodes and return explicit per-node conflicts.

    The desktop canvas still supports the legacy full PUT path.  Collaboration
    clients use this endpoint so two people editing unrelated nodes do not
    overwrite one another's work.
    """
    _share_request_canvas_access(request, canvas_id, write=True)
    canvas_id = _share_clean_canvas_id(canvas_id)
    if not canvas_id:
        raise HTTPException(status_code=400, detail="无效的画布 ID")
    client_id = _collab_clean_id(payload.client_id)
    changes = [item for item in (payload.changes or []) if isinstance(item, dict)]
    deleted_ids = list(dict.fromkeys(_share_clean_canvas_id(item) for item in (payload.deleted_ids or []) if _share_clean_canvas_id(item)))
    changed_ids = []
    for item in changes:
        candidate = item.get("node") if isinstance(item.get("node"), dict) else item
        node_id = _share_clean_canvas_id(item.get("id") or candidate.get("id"))
        if node_id:
            changed_ids.append(node_id)
    changed_ids = list(dict.fromkeys(changed_ids + deleted_ids))
    lock_conflicts = manager.collab_lock_conflicts(canvas_id, client_id, changed_ids)
    if lock_conflicts:
        raise HTTPException(status_code=423, detail={
            "message": "有其他成员正在编辑这些节点，请稍后重试。",
            "locks": lock_conflicts,
        })

    def mutate_canvas():
        with CANVAS_LOCK:
            current = load_canvas(canvas_id)
            current_nodes = [item for item in (current.get("nodes") or []) if isinstance(item, dict)]
            by_id = {str(item.get("id") or ""): item for item in current_nodes if item.get("id")}
            conflicts = []
            for item in changes:
                incoming = item.get("node") if isinstance(item.get("node"), dict) else item
                node_id = _share_clean_canvas_id(item.get("id") or incoming.get("id"))
                if not node_id:
                    continue
                base_revision = int(item.get("base_updated_at") or payload.base_updated_at or 0)
                existing = by_id.get(node_id)
                # 历史画布没有逐节点版本号；把缺失值视为“尚未参与协作”，
                # 否则一次无关节点更新会错误地阻塞本次增量保存。
                remote_revision = int((existing or {}).get("_collab_updated_at") or 0)
                if existing is not None and base_revision and remote_revision > base_revision:
                    conflicts.append({
                        "node_id": node_id,
                        "local": incoming,
                        "remote": existing,
                        "remote_revision": remote_revision,
                    })
            for node_id in deleted_ids:
                existing = by_id.get(node_id)
                base_revision = int(payload.base_updated_at or 0)
                remote_revision = int((existing or {}).get("_collab_updated_at") or 0)
                if existing is not None and base_revision and remote_revision > base_revision:
                    conflicts.append({
                        "node_id": node_id,
                        "local": None,
                        "remote": existing,
                        "remote_revision": remote_revision,
                        "deleted": True,
                    })
            if conflicts:
                raise HTTPException(status_code=409, detail={
                    "message": "部分节点已被其他成员更新。",
                    "canvas": current,
                    "conflicts": conflicts,
                })
            revision = now_ms()
            for item in changes:
                incoming = item.get("node") if isinstance(item.get("node"), dict) else item
                node_id = _share_clean_canvas_id(item.get("id") or incoming.get("id"))
                if not node_id:
                    continue
                node = dict(incoming)
                node["id"] = node_id
                node["_collab_updated_at"] = revision
                by_id[node_id] = node
            for node_id in deleted_ids:
                by_id.pop(node_id, None)
            # Preserve the client's existing order where possible, then append
            # genuinely new nodes in the order received.
            ordered = []
            seen = set()
            for item in current_nodes:
                node_id = str(item.get("id") or "")
                if node_id in by_id and node_id not in seen:
                    ordered.append(by_id[node_id])
                    seen.add(node_id)
            for item in changes:
                incoming = item.get("node") if isinstance(item.get("node"), dict) else item
                node_id = _share_clean_canvas_id(item.get("id") or incoming.get("id"))
                if node_id in by_id and node_id not in seen:
                    ordered.append(by_id[node_id])
                    seen.add(node_id)
            current["nodes"] = ordered
            if deleted_ids:
                deleted_set = set(deleted_ids)
                current["connections"] = [
                    conn for conn in (current.get("connections") or [])
                    if not (isinstance(conn, dict) and (str(conn.get("from") or "") in deleted_set or str(conn.get("to") or "") in deleted_set))
                ]
                for node in current["nodes"]:
                    if isinstance(node, dict):
                        if isinstance(node.get("inputNodeIds"), list):
                            node["inputNodeIds"] = [item for item in node["inputNodeIds"] if str(item or "") not in deleted_set]
                        if isinstance(node.get("items"), list):
                            node["items"] = [item for item in node["items"] if str(item or "") not in deleted_set]
            if payload.connections is not None:
                valid_ids = set(by_id)
                current["connections"] = [
                    conn for conn in (payload.connections or [])
                    if not isinstance(conn, dict) or (str(conn.get("from") or "") in valid_ids and str(conn.get("to") or "") in valid_ids)
                ]
            if payload.viewport is not None and normalize_canvas_kind(current.get("kind")) == "smart":
                current["viewport"] = payload.viewport
            if payload.title is not None:
                current["title"] = (str(payload.title).strip() or current.get("title") or "未命名画布")[:80]
            if payload.icon is not None:
                current["icon"] = (str(payload.icon).strip() or current.get("icon") or "layers")[:32]
            if payload.logs is not None:
                current["logs"] = payload.logs[-500:]
            if payload.settings is not None:
                current["settings"] = payload.settings or {}
            _write_canvas_file_locked(current)
            return current

    canvas = await asyncio.to_thread(mutate_canvas)
    updated_at = int(canvas.get("updated_at") or now_ms())
    await workspace_events.broadcast_canvas_updated(canvas_id, updated_at, payload.client_id)
    await manager.broadcast_collab(canvas_id, {
        "type": "collab_canvas_changed",
        "client_id": client_id,
        "updated_at": updated_at,
        "changed_ids": changed_ids,
    }, exclude=None)
    return {"canvas": canvas, "changed_ids": changed_ids}

@app.post("/api/canvases/{canvas_id}/logs/delete")
async def delete_canvas_log(canvas_id: str, payload: DeleteCanvasLogRequest, request: Request):
    _share_request_canvas_access(request, canvas_id, write=True)
    log_id = str(payload.log_id or "").strip()
    if not log_id:
        raise HTTPException(status_code=400, detail="缺少日志 ID")

    def remove_log_record():
        with CANVAS_LOCK:
            canvas = load_canvas(canvas_id)
            current_updated_at = int(canvas.get("updated_at") or 0)
            if payload.base_updated_at and current_updated_at and int(payload.base_updated_at) < current_updated_at:
                raise HTTPException(status_code=409, detail={
                    "message": "画布已被其他页面更新，请刷新后重试。",
                    "canvas": canvas,
                    "updated_at": current_updated_at,
                })
            logs = list(canvas.get("logs") or [])
            target = next((item for item in logs if str(item.get("id") or "") == log_id), None)
            if not target:
                raise HTTPException(status_code=404, detail="生成日志不存在")
            candidate_media = []
            seen_candidate_paths = set()
            if payload.delete_unreferenced_media:
                for url in collect_local_media_urls(target.get("outputs") or []):
                    path = generated_media_path_from_url(url)
                    if not path:
                        continue
                    path_key = os.path.normcase(os.path.realpath(path))
                    if path_key in seen_candidate_paths:
                        continue
                    seen_candidate_paths.add(path_key)
                    candidate_media.append({"url": url, "path": path})
            canvas["logs"] = [item for item in logs if str(item.get("id") or "") != log_id]
            _write_canvas_file_locked(canvas)
            return canvas, candidate_media

    canvas, candidate_media = await asyncio.to_thread(remove_log_record)
    removed_files = []
    trashed_asset_ids = []
    skipped_referenced = []
    removed_previews = 0
    if payload.delete_unreferenced_media:
        def cleanup_unreferenced_media():
            nonlocal removed_previews
            for candidate in candidate_media:
                path = str(candidate.get("path") or "")
                url = str(candidate.get("url") or "")
                filename = os.path.basename(path)
                if persisted_json_references_media_path(path):
                    skipped_referenced.append(filename)
                    continue
                try:
                    record = asset_registry_register_media(
                        url,
                        name=filename,
                        kind=asset_library_media_kind(path),
                        source="generated",
                        created_at=os.path.getmtime(path),
                    )
                    asset_id = str((record or {}).get("id") or "")
                    if not registry_is_asset_id(asset_id):
                        skipped_referenced.append(filename)
                        continue
                    asset_registry_require_unreferenced(asset_id)
                    removed_previews += delete_media_preview_cache(path)
                    _asset_registry_trash_media(asset_id, reason="canvas_log_delete")
                    removed_files.append(filename)
                    trashed_asset_ids.append(asset_id)
                except (HTTPException, OSError):
                    skipped_referenced.append(filename)

        def locked_cleanup():
            with CANVAS_LOCK:
                cleanup_unreferenced_media()
        await asyncio.to_thread(locked_cleanup)

    await workspace_events.broadcast_canvas_updated(canvas_id, int(canvas.get("updated_at") or now_ms()), payload.client_id)
    return {
        "ok": True,
        "canvas": canvas,
        "removed_files": removed_files,
        "trashed_files": removed_files,
        "trashed_asset_ids": trashed_asset_ids,
        "removed_previews": removed_previews,
        "skipped_referenced": skipped_referenced,
    }

@app.delete("/api/canvases/{canvas_id}")
async def delete_canvas(canvas_id: str):
    def soft_delete():
        with CANVAS_LOCK:
            path = canvas_path(canvas_id)
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    canvas = json.load(f)
            except FileNotFoundError as exc:
                raise HTTPException(status_code=404, detail="画布不存在") from exc
            except OSError as exc:
                raise HTTPException(status_code=503, detail="暂时无法读取画布，请重试") from exc
            except ValueError:
                canvas = None
            if not isinstance(canvas, dict):
                backup = f"{path}.corrupt-{uuid.uuid4().hex[:12]}"
                try:
                    os.rename(path, backup)
                except OSError as exc:
                    raise HTTPException(status_code=503, detail="暂时无法备份损坏的画布，请重试") from exc
                return {"ok": True, "purged": True, "backup_file": os.path.basename(backup)}
            if not canvas.get("deleted_at"):
                canvas["deleted_at"] = now_ms()
                _write_canvas_file_locked(canvas)
            return {"ok": True, "purged": False}

    return await asyncio.to_thread(soft_delete)

@app.post("/api/canvases/{canvas_id}/restore")
async def restore_canvas(canvas_id: str):
    def restore():
        with CANVAS_LOCK:
            canvas = load_canvas_any(canvas_id)
            if canvas.get("deleted_at"):
                canvas.pop("deleted_at", None)
                # 原项目可能已被彻底删除：恢复时归入默认项目，避免画布恢复后无处可见。
                project_id = str(canvas.get("project") or "").strip()
                if project_id and not any(
                    str(p.get("id") or "") == project_id and not p.get("deleted_at")
                    for p in load_projects()
                ):
                    canvas["project"] = DEFAULT_PROJECT_ID
                _write_canvas_file_locked(canvas)
            return canvas

    canvas = await asyncio.to_thread(restore)
    return {"canvas": canvas}

@app.delete("/api/canvases/{canvas_id}/purge")
async def purge_canvas(canvas_id: str):
    def purge():
        with CANVAS_LOCK:
            path = canvas_path(canvas_id)
            if os.path.exists(path):
                os.remove(path)

    await asyncio.to_thread(purge)
    return {"ok": True}

