# --- GPT 对话 ---

@app.post("/api/harness/design", response_model=HarnessDesignResponse)
async def harness_design_bridge(payload: HarnessDesignRequest, request: Request, x_user_id: str = Header(default="")):
    """Classify an official Harness design request and return the existing chat payload shape.

    The endpoint deliberately does not create a generation job. Harness Skills use the returned
    payload to ask for confirmation, then submit the same payload to ``/api/chat/agent``.
    """
    text = str(payload.message or "").strip()
    lowered = text.lower()
    rules = (
        ("ecommerce", "ecommerce-visual", ("电商", "主图", "详情页", "sku", "卖点", "淘宝", "天猫", "商品"), "800x800"),
        ("poster", "poster-design", ("海报", "展会", "宣传", "发布会"), "1080x1440"),
        ("brand", "brand-visual", ("品牌", "vi", "logo", "标志", "视觉规范"), "1600x900"),
        ("social", "social-visual", ("社媒", "社交媒体", "小红书", "抖音", "微博", "公众号", "instagram", "封面"), "1080x1440"),
    )
    category, skill_id, needles, default_size = next((row for row in rules if any(needle in lowered for needle in row[2])), ("general", "", (), "1024x1024"))
    size = str(payload.size or "").strip() or default_size
    normalized = f"设计类别：{category}\n画布尺寸：{size}\n设计任务：{text}"
    api_request = {
        "conversation_id": str(payload.conversation_id or ""),
        "message": text,
        "mode": "agent",
        "size": size,
        "provider": "comfly",
        "skill_id": skill_id,
        "reference_images": [item.model_dump() if hasattr(item, "model_dump") else item.dict() for item in payload.reference_images],
        "confirm_image_generation": False,
    }
    return HarnessDesignResponse(category=category, skill_id=skill_id, normalized_message=normalized, suggested_size=size, api_request=api_request)


def _chat_user_message(payload, references, context, *, skill, mode=None, merchant=False):
    return chat_conversations.prompt_message(
        payload.message, payload.mode if mode is None else mode, references, context, now_ms(),
        link_image_limit=CHAT_ATTACHMENT_MAX, skill=skill, merchant=merchant,
    )


@app.post("/api/chat")
async def chat(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    link_context = await _prepare_link_context(payload.message, [], payload.link_job_ids, payload.link_resource_ids, payload.page_context)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    user_message = _chat_user_message(payload, refs, link_context, skill=public_agent_skill(payload))
    conversation = _save_chat_prompt(user_id, conversation, user_message, payload)

    history_record = None
    if payload.mode == "image":
        link_images = (
            {"url": address, "name": f"商品链接参考图 {number}", "kind": "image", "role": "link"}
            for number, address in enumerate(link_context.get("images") or (), 1)
            if _commerce_analysis_is_chat_image_reference(address)
        )
        image_refs = [*image_references(refs), *link_images][:CHAT_ATTACHMENT_MAX]
        image_provider_id = payload.provider
        provider = get_api_provider(image_provider_id)
        default_model = (provider.get("image_models") or [IMAGE_MODEL])[0]
        model = selected_model(payload.image_model or payload.model, default_model)
        image_size = chat_prompt_size_override(payload.message, payload.size) or payload.size
        try:
            image_data, raw = await generate_ai_image(payload.message, image_size, payload.quality, model, image_refs, provider["id"], "", payload.background)
            local_url = await save_ai_image_to_output(image_data, prefix="chat_")
        except httpx.HTTPStatusError as exc:
            text = exc.response.text or ""
            detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
            raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
        except httpx.HTTPError as exc:
            log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
            detail = friendly_image_network_error_detail(exc, provider.get("name") or provider.get("id") or "", model)
            raise HTTPException(status_code=502, detail=detail) from exc
        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "type": "image",
            "content": payload.message,
            "image_url": local_url,
            "created_at": now_ms(),
            "model": model,
            "size": image_size,
            "background": payload.background,
            "raw_usage": raw.get("usage") if isinstance(raw, dict) else None,
        }
        history_record = chat_image_history_record(
            payload.message,
            [local_url],
            model,
            provider,
            image_size,
            payload.quality,
            image_refs,
            "generate_image",
            raw,
            payload.background,
        )
    else:
        assistant_message = await build_chat_text_reply(payload, conversation, allow_retry=False)

    conversation = _complete_chat_reply(user_id, conversation, user_message, assistant_message, history_record)
    return {"conversation": conversation, "message": assistant_message}

@app.post("/api/chat/agent")
async def chat_agent(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    link_context = await _prepare_link_context(payload.message, [], payload.link_job_ids, payload.link_resource_ids, payload.page_context)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )

    requested_confirmation = bool(payload.confirm_image_generation) or chat_agent_confirmation_message(payload.message)
    confirmed_draft = latest_chat_image_draft(conversation, payload.generation_draft_id) if requested_confirmation else None
    if payload.confirm_image_generation and not confirmed_draft:
        raise HTTPException(status_code=404, detail="待确认的生图文案不存在或已被清理，请重新整理")
    if confirmed_draft and confirmed_draft.get("draft_status") == "generated":
        raise HTTPException(status_code=409, detail="这份文案已经确认并生成过图片；如需再次生成，请发起新的生图请求")
    draft_id = str((confirmed_draft or {}).get("id") or "")
    with CHAT_CONVERSATIONS.confirm_draft(user_id, conversation["id"], draft_id):
        return await _run_chat_agent_turn(payload, user_id, conversation, link_context, confirmed_draft)


async def _run_chat_agent_turn(payload, user_id, conversation, link_context, confirmed_draft):
    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    link_image_refs = [
        {"url": url, "name": f"商品链接参考图 {index + 1}", "kind": "image", "role": "link"}
        for index, url in enumerate(link_context.get("images") or [])
        if _commerce_analysis_is_chat_image_reference(url)
    ]
    if confirmed_draft:
        draft_refs = [item for item in (confirmed_draft.get("used_references") or []) if isinstance(item, dict) and item.get("url")]
        image_refs = image_references(draft_refs)[:CHAT_ATTACHMENT_MAX]
    else:
        image_refs = (image_references(refs) + link_image_refs)[:CHAT_ATTACHMENT_MAX]
    skill_meta = public_agent_skill(payload)
    user_message = _chat_user_message(payload, refs, link_context, skill=skill_meta, mode="agent")
    if confirmed_draft:
        user_message.update({
            "generation_draft_id": str(confirmed_draft.get("id") or ""),
            "generation_confirmed": True,
            "generation_prompt": str(payload.generation_prompt or confirmed_draft.get("draft_prompt") or payload.message).strip(),
        })
    if payload.confirm_design_plan:
        user_message.update({
            "design_plan_id": str(payload.design_plan_id or "").strip(),
            "design_plan_confirmed": True,
        })
    conversation = _save_chat_prompt(user_id, conversation, user_message, payload)

    if not confirmed_draft and not payload.confirm_design_plan:
        design_plan = await build_chat_design_plan(payload, conversation, image_refs)
        if design_plan:
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "design_plan",
                "content": "我先把这次视觉需求整理成设计方案。你可以修改提示词，确认后再进入生图草稿。",
                "created_at": now_ms(),
                "design_plan": design_plan,
                "design_category": design_plan.get("category", "ecommerce"),
                "agent_action": "design_plan",
                "model": "DeepSeek Harness" if design_plan.get("harness_status") == "ready" else "设计策划回退",
            }
            if skill_meta:
                assistant_message.update({"skill_id": skill_meta["id"], "skill_name": skill_meta["name"]})
            conversation = CHAT_CONVERSATIONS.append_reply(user_id, conversation["id"], user_message["id"], assistant_message)
            return {
                "conversation": conversation,
                "message": assistant_message,
                "agent": {"action": "design_plan", "decision": design_plan},
            }

    if payload.confirm_design_plan and not confirmed_draft:
        decision = {
            "action": "edit_image" if image_refs else "generate_image",
            "prompt": str(payload.generation_prompt or payload.message).strip(),
            "reply": "已按确认的设计方案整理生图草稿。",
            "design_plan_id": str(payload.design_plan_id or ""),
        }
        action = decision["action"]
    elif confirmed_draft:
        action = str(confirmed_draft.get("draft_action") or "generate_image")
        if action not in {"generate_image", "edit_image"}:
            action = "edit_image" if image_refs else "generate_image"
        confirmed_prompt = str(payload.generation_prompt or confirmed_draft.get("draft_prompt") or payload.message or "").strip()
        if not confirmed_prompt:
            raise HTTPException(status_code=400, detail="生图文案不能为空，请修改后再确认")
        decision = {
            "action": action,
            "prompt": confirmed_prompt,
            "reply": "已按你确认的文案生成。",
            "confirmed_draft_id": str(confirmed_draft.get("id") or ""),
        }
    else:
        decision = await decide_chat_agent_action(payload, conversation, image_refs)
        action = decision.get("action") or "chat"
    tool_refs = image_refs[:]
    inherited_size = ""
    if action == "edit_image" and not tool_refs:
        previous = chat_image_requests.previous_image(conversation.get("messages"))
        if previous:
            tool_refs.append(previous)
            inherited_size = chat_image_requests.reference_dimensions(output_file_from_url(previous))
    if action == "edit_image" and not tool_refs:
        action = "generate_image"

    history_record = None
    if action in {"generate_image", "edit_image"}:
        draft_provider_id = str(confirmed_draft.get("image_provider") or "") if confirmed_draft else ""
        preferred_provider = draft_provider_id or payload.image_provider or payload.provider
        image_provider = chat_image_requests.image_provider(load_api_providers(), preferred_provider, payload.provider)
        if image_provider is None:
            image_provider = get_api_provider(preferred_provider or "comfly")
        default_model = (image_provider.get("image_models") or [IMAGE_MODEL])[0]
        draft_model = str(confirmed_draft.get("image_model") or confirmed_draft.get("model") or "") if confirmed_draft else ""
        model = selected_model(draft_model or payload.image_model or default_model, default_model)
        prompt = decision.get("prompt") or payload.message
        base_size = str(confirmed_draft.get("size") or payload.size) if confirmed_draft else payload.size
        prompt_size = chat_prompt_size_override(payload.message, base_size) or chat_prompt_size_override(prompt, base_size)
        image_size = snap_size_to_multiple(prompt_size or inherited_size or payload.size, 16)
        if confirmed_draft:
            requested_count = max(1, min(4, int(confirmed_draft.get("image_count") or 1)))
        else:
            requested_count = 1 if action == "edit_image" else chat_image_requests.image_count(payload.message)
        if not confirmed_draft:
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "image_draft",
                "content": "我先把生图文案整理成可编辑草稿。请修改下面的内容；只有点击“确认生图”后才会调用图片模型。",
                "draft_prompt": prompt,
                "draft_action": action,
                "draft_status": "pending",
                "created_at": now_ms(),
                "model": model,
                "image_model": model,
                "image_provider": image_provider["id"],
                "size": image_size,
                "quality": payload.quality,
                "background": payload.background,
                "image_count": requested_count,
                "used_references": tool_refs,
                "agent_action": "image_draft",
            }
            if skill_meta:
                assistant_message.update({"skill_id": skill_meta["id"], "skill_name": skill_meta["name"]})
        else:
            prompts = chat_image_requests.batch_prompts(prompt, requested_count)
            local_urls = []
            raw_items = []
            try:
                for item_prompt in prompts:
                    image_data, raw = await generate_ai_image(item_prompt, image_size, payload.quality, model, tool_refs, image_provider["id"], "", payload.background)
                    local_urls.append(await save_ai_image_to_output(image_data, prefix="chat_"))
                    raw_items.append(raw)
            except httpx.HTTPStatusError as exc:
                text = exc.response.text or ""
                detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
                raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
            except httpx.HTTPError as exc:
                log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
                detail = friendly_image_network_error_detail(exc, image_provider.get("name") or image_provider.get("id") or "", model)
                raise HTTPException(status_code=502, detail=detail) from exc
            local_url = local_urls[0] if local_urls else ""
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "image",
                "content": prompt,
                "image_url": local_url,
                "image_urls": local_urls,
                "created_at": now_ms(),
                "model": model,
                "provider": image_provider["id"],
                "size": image_size,
                "background": payload.background,
                "image_count": len(local_urls),
                "prompts": prompts,
                "agent_action": action,
                "agent_reply": decision.get("reply") or "已按你确认的文案生成。",
                "used_references": tool_refs,
                "generation_draft_id": str(confirmed_draft.get("id") or ""),
                "raw_usage": raw_items[0].get("usage") if raw_items and isinstance(raw_items[0], dict) else None,
            }
            history_record = chat_image_history_record(
                prompt,
                local_urls,
                model,
                image_provider,
                image_size,
                payload.quality,
                tool_refs,
                action,
                raw_items,
                payload.background,
            )
    else:
        assistant_message = await build_chat_text_reply(payload, conversation)
        assistant_message["agent_action"] = "chat"

    conversation = _complete_chat_reply(user_id, conversation, user_message, assistant_message, history_record)
    return {"conversation": conversation, "message": assistant_message, "agent": {"action": action, "decision": decision}}

def _merchant_require_change_conversation(change: Dict[str, Any], user_id: str) -> None:
    conversation_id = _merchant_clean_text(change.get("conversation_id"), 120)
    if not conversation_id:
        raise HTTPException(status_code=409, detail="变更缺少对话归属，无法继续操作")
    # Conversations are stored under the browser user directory.  This check
    # prevents a guessed change ID from being approved by another local user.
    load_conversation(user_id, conversation_id)


def _merchant_check_change_source(change: Dict[str, Any]) -> Tuple[bool, str]:
    job_id = str(change.get("job_id") or "").strip()
    job = _commerce_analysis_get_job(job_id) if job_id else None
    if not job or not isinstance(job.get("result"), dict):
        return False, "关联的商品快照不存在或已清理"
    current_digest = _merchant_source_digest_for_job(job)
    if not hmac.compare_digest(str(change.get("source_digest") or ""), current_digest):
        return False, "商品快照已更新，原批准已失效；请重新生成方案"
    return True, ""


def _merchant_invalidate_change(change: Dict[str, Any], reason: str) -> Dict[str, Any]:
    guardrail = dict(change.get("guardrail") if isinstance(change.get("guardrail"), dict) else {})
    guardrail["invalidated_at"] = _commerce_analysis_now()
    guardrail["invalidated_reason"] = _merchant_clean_text(reason, 300)
    return _merchant_update_change(
        change.get("id"),
        status="pending",
        approved_at=None,
        guardrail_json=_commerce_analysis_json(guardrail),
        error=_merchant_clean_text(reason, 500),
    ) or change


def _merchant_invalidate_approved_changes_for_job(job_id: str) -> int:
    """Invalidate approvals as soon as a persisted product snapshot changes."""
    safe_job_id = _merchant_job_id(job_id)
    invalidated = 0
    for change in _merchant_list_changes(job_id=safe_job_id, status="approved", limit=100):
        fresh, reason = _merchant_check_change_source(change)
        if fresh:
            continue
        _merchant_invalidate_change(change, reason)
        invalidated += 1
    return invalidated


def _merchant_apply_change(change: Dict[str, Any]) -> Dict[str, Any]:
    # Never trust a caller-held row: a recapture may have invalidated approval
    # after the caller loaded the card but before it pressed “apply”.
    stored = _merchant_get_change(change.get("id")) if isinstance(change, dict) and change.get("id") else None
    if stored:
        change = stored
    if str(change.get("status") or "") != "approved":
        raise HTTPException(status_code=409, detail="请先通过界面按钮批准该变更")
    fresh, reason = _merchant_check_change_source(change)
    if not fresh:
        _merchant_invalidate_change(change, reason)
        raise HTTPException(status_code=409, detail=reason)
    kind = str(change.get("kind") or "")
    if kind not in MERCHANT_CHANGE_KINDS:
        raise HTTPException(status_code=409, detail="变更类型不支持应用")
    updated = _merchant_update_change(change.get("id"), status="applied", applied_at=_commerce_analysis_now(), error="")
    if not updated:
        raise HTTPException(status_code=404, detail="变更不存在")
    after = updated.get("after") if isinstance(updated.get("after"), dict) else {}
    if kind == "listing_copy":
        return {"change": updated, "export": {"file_name": "小美经营助手-商品文案.md", "content": after}}
    # No platform operation is performed here.  The browser only receives a
    # small change ID and the destination fetches the approved ledger row.
    target = "commerce"
    return {"change": updated, "handoff": {"target": target, "change_id": updated.get("id"), "kind": kind}}


@app.get("/api/merchant-agent/changes")
async def merchant_agent_changes(
    request: Request,
    conversation_id: str = "",
    job_id: str = "",
    status: str = "",
    limit: int = 50,
    x_user_id: str = Header(default=""),
):
    user_id = safe_user_id(x_user_id, request)
    safe_conversation = _merchant_clean_text(conversation_id, 120)
    if safe_conversation:
        load_conversation(user_id, safe_conversation)
    changes = await asyncio.to_thread(_merchant_list_changes, safe_conversation, job_id, status, limit)
    # A list without a conversation filter is retained for the single-local-user
    # history view; mutation endpoints always verify the conversation owner.
    return {"changes": changes}


@app.get("/api/merchant-agent/changes/{change_id}")
async def merchant_agent_change(change_id: str, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    return {"change": change}


@app.post("/api/merchant-agent/changes/{change_id}/approve")
async def merchant_agent_approve_change(
    change_id: str,
    payload: MerchantChangeApprovalRequest,
    request: Request,
    x_user_id: str = Header(default=""),
):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    if change.get("status") == "approved":
        return {"change": change}
    if change.get("status") != "pending":
        raise HTTPException(status_code=409, detail="只有待确认变更可以批准")
    fresh, reason = await asyncio.to_thread(_merchant_check_change_source, change)
    if not fresh:
        await asyncio.to_thread(_merchant_invalidate_change, change, reason)
        raise HTTPException(status_code=409, detail=reason)
    guardrail = dict(change.get("guardrail") if isinstance(change.get("guardrail"), dict) else {})
    note = _merchant_clean_text(payload.note, 1000)
    if note:
        guardrail["approval_note"] = note
    guardrail["approved_via"] = "ui_button"
    updated = await asyncio.to_thread(
        _merchant_update_change,
        change.get("id"),
        status="approved",
        approved_at=_commerce_analysis_now(),
        guardrail_json=_commerce_analysis_json(guardrail),
        error="",
    )
    return {"change": updated}


@app.post("/api/merchant-agent/changes/{change_id}/apply")
async def merchant_agent_apply_change(change_id: str, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    return await asyncio.to_thread(_merchant_apply_change, change)


@app.post("/api/merchant-agent/changes/{change_id}/discard")
async def merchant_agent_discard_change(
    change_id: str,
    payload: MerchantChangeDiscardRequest,
    request: Request,
    x_user_id: str = Header(default=""),
):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    if change.get("status") not in {"pending", "approved"}:
        raise HTTPException(status_code=409, detail="当前变更不能丢弃")
    reason = _merchant_clean_text(payload.reason, 1000)
    updated = await asyncio.to_thread(
        _merchant_update_change,
        change.get("id"),
        status="discarded",
        error=reason,
    )
    return {"change": updated}


@app.post("/api/chat/stream")
async def chat_stream(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    if payload.mode == "image":
        raise HTTPException(status_code=400, detail="图片模式请使用 /api/chat")

    user_id = safe_user_id(x_user_id, request)
    merchant_mode = str(payload.mode or "").strip().lower() == "merchant-agent"
    if merchant_mode:
        # Accept the human-facing aliases in the Merchant contract while
        # preserving the existing product-analysis resource IDs internally.
        payload.link_resource_ids = sorted(_merchant_resource_ids(payload.link_resource_ids))
    # Merchant Agent is intentionally local-snapshot only.  Do not let a URL
    # pasted into chat trigger the generic public-web reader on this route.
    context_message = re.sub(r"https?://[^\s<>]+", "", payload.message) if merchant_mode else payload.message
    link_context = await _prepare_link_context(
        context_message,
        [],
        payload.link_job_ids,
        payload.link_resource_ids,
        {} if merchant_mode else payload.page_context,
    )
    if merchant_mode and not link_context.get("job_ids"):
        raise HTTPException(status_code=409, detail="经营助手需要先完成并关联一个商品分析任务")
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    user_message = _chat_user_message(payload, refs, link_context, skill=public_agent_skill(payload), merchant=merchant_mode)
    conversation = _save_chat_prompt(user_id, conversation, user_message, payload)

    if merchant_mode:
        async def merchant_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                result = await _run_merchant_agent_turn(payload, conversation, link_context)
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            except httpx.HTTPStatusError as exc:
                body = exc.response.text or ""
                provider_cfg = get_api_provider(payload.provider)
                yield sse_event({"type": "error", "detail": friendly_chat_error_detail(body, payload.model, provider_cfg, exc.response.status_code) or f"上游接口错误：{body[:500]}"})
                return
            except httpx.TimeoutException:
                yield sse_event({"type": "error", "detail": "经营助手的模型响应超时，请重试或切换聊天模型"})
                return
            except httpx.HTTPError as exc:
                yield sse_event({"type": "error", "detail": f"经营助手请求上游接口失败：{str(exc)[:300]}"})
                return
            for event in result.get("events") if isinstance(result.get("events"), list) else []:
                yield sse_event(event)
            content = str(result.get("content") or "已完成本次经营分析。")
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "merchant_agent",
                "content": content,
                "created_at": now_ms(),
                "model": result.get("model") or payload.model,
                "raw_usage": result.get("raw_usage"),
                "merchant_changes": result.get("changes") if isinstance(result.get("changes"), list) else [],
            }
            for event in _chat_reply_events(user_id, conversation, user_message, assistant_message, send_delta=True):
                yield event

        return StreamingResponse(merchant_stream(), media_type="text/event-stream")

    provider = get_api_provider(payload.provider)
    if provider_protocol(provider) in {"codex", "gemini-cli"}:
        async def local_stream():
            yield sse_event(dict(type="meta", conversation=conversation))
            try:
                reply = await _cli_chat_message(payload, conversation, provider)
            except HTTPException as error:
                yield sse_event(dict(type="error", detail=error.detail))
                return
            for event in _chat_reply_events(user_id, conversation, user_message, reply, send_delta=True):
                yield event

        return StreamingResponse(local_stream(), media_type="text/event-stream")

    base, headers, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    body = dict(model=model, messages=_upstream_chat_messages(payload, conversation), stream=True)
    timeout = chat_stream_timeout_for_payload(payload)
    first_text_timeout = (
        COMMERCE_CHAT_FIRST_TOKEN_TIMEOUT if str(payload.mode or "").strip().lower() == "commerce-analysis" else None
    )

    def status_detail(text, status):
        return friendly_chat_error_detail(text, model, provider, status) or f"上游接口错误：{text}"

    def notice(attempt, retries, delay):
        print(f"[chat-stream] retry provider={payload.provider} model={model} attempt={attempt}/{retries} delay={delay:g}s", flush=True)

    async def stream():
        yield sse_event(dict(type="meta", conversation=conversation))
        async with httpx.AsyncClient(timeout=chat_agent_http_timeout(timeout)) as client:
            events = chat_streaming.events(
                client, f"{base}/chat/completions", headers, body,
                timeout=timeout, first_text_timeout=first_text_timeout, retries=CHAT_AGENT_RETRIES,
                retry_delay=CHAT_AGENT_RETRY_DELAY, transient=is_transient_chat_error,
                status_detail=status_detail, notice=notice,
            )
            async with aclosing(events):
                async for event in events:
                    if event["type"] != "complete":
                        yield sse_event(event)
                        continue
                    reply = chat_replies.assistant_message(
                        event["content"] or "接口返回了空回复。", model, now_ms(), usage=event["usage"],
                    )
                    for saved in _chat_reply_events(user_id, conversation, user_message, reply):
                        yield saved

    return StreamingResponse(stream(), media_type="text/event-stream")


# --- 历史记录 ---

def _history_values(value):
    if isinstance(value, list):
        return value
    return [value] if value else []


def _history_media_url(value):
    if isinstance(value, dict):
        return str(value.get("url") or value.get("src") or value.get("path") or value.get("uri") or "").strip()
    return str(value or "").strip()


def history_record_has_display_media(record):
    if not isinstance(record, dict):
        return False
    for key in ("images", "videos", "outputs"):
        if any(_history_media_url(value) for value in _history_values(record.get(key))):
            return True
    for key in ("image_items", "video_items", "items", "media_items"):
        for item in _history_values(record.get(key)):
            if _history_media_url(item):
                return True
    return False


def history_record_media_urls(record):
    if not isinstance(record, dict):
        return []
    urls = []
    seen = set()

    def add(value):
        url = _history_media_url(value)
        if url and url not in seen:
            seen.add(url)
            urls.append(url)

    for key in ("images", "videos", "outputs"):
        for value in _history_values(record.get(key)):
            add(value)
    for key in ("image_items", "video_items", "items", "media_items"):
        for value in _history_values(record.get(key)):
            if isinstance(value, dict):
                add(value)
    return urls


def _history_media_key(value):
    """Normalize a media URL enough to match history rows to canvas nodes."""
    text = _history_media_url(value).replace("\\", "/")
    if not text:
        return ""
    try:
        parsed = urllib.parse.urlsplit(text)
        # A local browser may persist an absolute loopback URL while the canvas
        # stores the same file as a relative route.  Keep external URLs
        # host-qualified so two providers cannot collide on a path alone.
        if parsed.scheme and parsed.netloc and parsed.hostname in {"127.0.0.1", "localhost", "::1"}:
            text = parsed.path or "/"
        else:
            text = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path, "", ""))
    except Exception:
        text = text.split("?", 1)[0].split("#", 1)[0]
    return text.rstrip("/") or "/"


def _history_project_ids_from_value(value):
    if isinstance(value, (list, tuple, set)):
        values = value
    else:
        values = [value]
    result = set()
    for item in values:
        project_id = str(item or "").strip()
        if project_id:
            result.add(project_id)
    return result


def _history_project_ids(record, canvas_media_index=None):
    """Return explicit and legacy-inferred project IDs for one history row."""
    if not isinstance(record, dict):
        return set()
    params = record.get("params") if isinstance(record.get("params"), dict) else {}
    project_ids = set()
    for value in (
        record.get("project_id"),
        record.get("project"),
        params.get("project_id"),
        params.get("project"),
    ):
        project_ids.update(_history_project_ids_from_value(value))
    if isinstance(canvas_media_index, dict):
        for url in history_record_media_urls(record):
            project_ids.update(canvas_media_index.get(_history_media_key(url), set()))
    return project_ids


def _history_canvas_project_media_index():
    """Build a read-only URL -> project index for history rows from old builds."""
    index = {}
    if not os.path.isdir(CANVAS_DIR):
        return index
    try:
        filenames = os.listdir(CANVAS_DIR)
    except OSError:
        return index
    for filename in filenames:
        if not str(filename).endswith(".json"):
            continue
        try:
            with open(os.path.join(CANVAS_DIR, filename), "r", encoding="utf-8") as f:
                canvas = json.load(f)
        except Exception:
            continue
        if not isinstance(canvas, dict) or canvas.get("deleted_at"):
            continue
        project_id = str(canvas.get("project") or DEFAULT_PROJECT_ID).strip() or DEFAULT_PROJECT_ID
        values = (
            canvas.get("nodes"),
            canvas.get("logs"),
            canvas.get("history"),
            canvas.get("assets"),
            canvas.get("outputs"),
        )
        for value in values:
            for _path, _raw, url in canvas_media.walk(value):
                key = _history_media_key(url)
                if key:
                    index.setdefault(key, set()).add(project_id)
    return index


def _history_listing_media(record):
    """Return the small, normalized media shape used by the history manager.

    The persisted history rows also contain provider payloads, usage details and
    compatibility fields.  The manager only needs a URL, media kind and an
    optional filename; keeping that boundary here prevents the large history
    file from being sent to the browser just to render thumbnails.
    """
    if not isinstance(record, dict):
        return []
    entries = []
    seen = set()
    video_exts = {ext.lower() for ext in STORAGE_VIDEO_EXTS}

    def add(value, fallback="image"):
        if isinstance(value, list):
            for item in value:
                add(item, fallback)
            return
        if isinstance(value, dict):
            url = _history_media_url(value)
            hinted = str(value.get("kind") or value.get("mediaKind") or value.get("type") or "").strip().lower()
            name = str(value.get("name") or value.get("filename") or "").strip()
        else:
            url = _history_media_url(value)
            hinted = ""
            name = ""
        if not url or url in seen:
            return
        seen.add(url)
        is_video = "video" in hinted or os.path.splitext(url.split("?", 1)[0])[1].lower() in video_exts
        entries.append({"url": url, "kind": "video" if is_video else (fallback or "image"), **({"name": name} if name else {})})

    # Keep the same ordering as history.html so old and compact responses are
    # interchangeable while duplicate URL fields collapse to one entry.
    add(record.get("video_items"), "video")
    add(record.get("videos"), "video")
    add(record.get("items"), "")
    add(record.get("media_items"), "")
    add(record.get("image_items"), "image")
    add(record.get("images"), "image")
    add(record.get("outputs"), "")
    return entries


def _history_listing_group(record, media):
    if not isinstance(record, dict):
        return "other"
    if any(item.get("kind") == "video" for item in media):
        return "video"
    raw_type = str(record.get("type") or "").strip().lower()
    params = record.get("params") if isinstance(record.get("params"), dict) else {}
    source = normalize_history_source(
        record.get("history_source")
        or record.get("source")
        or params.get("history_source")
        or params.get("source")
        or ""
    )
    # Older canvas callers submitted local ComfyUI work through the shared
    # endpoint with ``history_source=canvas``.  Use the workflow metadata
    # before the generic canvas branch so those rows remain discoverable in
    # the ComfyUI history channel.
    if (
        source in {"", "canvas", "smart_canvas"}
        and raw_type not in {"online", "chat", "commerce"}
        and (
            record.get("workflow_json")
            or record.get("prompt_id")
            or record.get("backend")
        )
    ):
        return "comfyui"
    if source in {"comfyui", "comfy_ui", "comfy_app", "comfyui_workbench"} or raw_type in {
        "comfyui", "comfy_ui", "comfy_app", "comfy-app"
    }:
        return "comfyui"
    # The shared image API writes type=online for several UI entry points.
    # The saved entry point takes precedence over that transport type.
    if source:
        return source
    if raw_type == "online":
        return "online"
    if raw_type in {"chat", "gpt-chat", "gpt_chat"}:
        return "chat"
    if raw_type == "canvas" or "canvas" in raw_type:
        return "canvas"
    if raw_type == "commerce" or "commerce" in raw_type:
        return "commerce"
    return "other"


def _history_listing_item(record, canvas_media_index=None):
    media = _history_listing_media(record)
    params = record.get("params") if isinstance(record.get("params"), dict) else {}
    source = normalize_history_source(
        record.get("history_source")
        or record.get("source")
        or params.get("history_source")
        or params.get("source")
    )
    project_ids = sorted(_history_project_ids(record, canvas_media_index))
    history_group = _history_listing_group(record, media)
    if history_group == "comfyui":
        source = "comfyui"
    compact = {
        "prompt": str(record.get("prompt") or ""),
        "timestamp": record.get("timestamp", 0),
        "type": str(record.get("type") or ""),
        "history_source": source,
        "model": str(record.get("model") or params.get("model") or ""),
        "provider_name": str(record.get("provider_name") or ""),
        "status": str(record.get("status") or ""),
        "state": str(record.get("state") or ""),
        "result": str(record.get("result") or ""),
        "error": str(record.get("error") or ""),
        "error_message": str(record.get("error_message") or ""),
        "message": str(record.get("message") or ""),
        "media_items": media,
        "media_count": len(media),
        "has_video": any(item.get("kind") == "video" for item in media),
        "project_id": project_ids[0] if len(project_ids) == 1 else "",
        "project_ids": project_ids,
        "skill_id": str(record.get("skill_id") or "").strip(),
        "skill_name": str(record.get("skill_name") or "").strip(),
        "design_run_id": str(record.get("design_run_id") or "").strip(),
        "provider_id": str(record.get("provider_id") or params.get("provider_id") or "").strip(),
    }
    compact["history_group"] = history_group
    compact["params"] = {
        "source": str(params.get("source") or params.get("history_source") or "").strip(),
        "model": str(params.get("model") or "").strip(),
        "project_id": project_ids[0] if len(project_ids) == 1 else "",
    }
    return compact


HISTORY_API_CACHE_LOCK = Lock()
HISTORY_API_CACHE = {"signature": None, "rows": []}


def _read_history_api_rows():
    if not os.path.exists(HISTORY_FILE):
        return []
    try:
        stat = os.stat(HISTORY_FILE)
        signature = (os.path.abspath(HISTORY_FILE), int(stat.st_mtime_ns), int(stat.st_size))
        with HISTORY_API_CACHE_LOCK:
            if HISTORY_API_CACHE.get("signature") == signature:
                return list(HISTORY_API_CACHE.get("rows") or [])
        with open(HISTORY_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        rows = [item for item in data if isinstance(item, dict)] if isinstance(data, list) else []
        with HISTORY_API_CACHE_LOCK:
            HISTORY_API_CACHE.update({"signature": signature, "rows": rows})
        return list(rows)
    except Exception as exc:
        print(f"读取历史文件失败: {exc}")
        return []


@app.get("/api/history")
async def get_history_api(type: str = None, view: str = "", project_id: str = ""):
    requested_project_id = str(project_id or "").strip()
    data = await asyncio.to_thread(_read_history_api_rows)
    if data:
        try:
            if type:
                data = [item for item in data if item.get("type", "zimage") == type]
            data = [item for item in data if history_record_has_display_media(item)]
            manager_view = str(view or "").strip().lower() == "manager"
            canvas_media_index = (
                await asyncio.to_thread(_history_canvas_project_media_index)
                if (manager_view or requested_project_id)
                else None
            )
            if requested_project_id:
                data = [
                    item for item in data
                    if requested_project_id in _history_project_ids(item, canvas_media_index)
                ]

            def sort_key(item):
                ts = item.get("timestamp", 0)
                if isinstance(ts, (int, float)):
                    return float(ts)
                return 0

            data.sort(key=sort_key, reverse=True)
            if manager_view:
                return [_history_listing_item(item, canvas_media_index) for item in data]
            return data
        except Exception as e:
            print(f"读取历史记录失败: {e}")
            return []
    return []

@app.get("/api/queue_status")
async def get_queue_status(client_id: str):
    with QUEUE_LOCK:
        total = len(QUEUE)
        positions = [i + 1 for i, t in enumerate(QUEUE) if t["client_id"] == client_id]
        position = positions[0] if positions else 0
    return {"total": total, "position": position}

@app.post("/api/history/delete")
async def delete_history(req: DeleteHistoryRequest):
    if not os.path.exists(HISTORY_FILE):
        return {"success": False, "message": "历史记录文件不存在"}
    try:
        with HISTORY_LOCK:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                history = json.load(f)
            target_record = None
            new_history = []
            for item in history:
                is_match = False
                item_ts = item.get("timestamp", 0)
                if isinstance(req.timestamp, (int, float)) and isinstance(item_ts, (int, float)):
                    if abs(float(item_ts) - float(req.timestamp)) < 0.001:
                        is_match = True
                elif str(item_ts) == str(req.timestamp):
                    is_match = True
                if is_match:
                    target_record = item
                else:
                    new_history.append(item)
            if target_record:
                # Register legacy media before removing its only history row.
                # The reference check below then sees the remaining canvases
                # and history records rather than deleting a shared file.
                asset_registry_register_history_record(target_record)
                _write_history_file_locked(new_history)

        if target_record:
            trashed_asset_ids = []
            retained_asset_ids = []
            seen_asset_ids = set()
            for ref in target_record.get("asset_refs") if isinstance(target_record.get("asset_refs"), list) else []:
                if not isinstance(ref, dict):
                    continue
                asset_id = str(ref.get("asset_id") or "")
                if not registry_is_asset_id(asset_id) or asset_id in seen_asset_ids:
                    continue
                seen_asset_ids.add(asset_id)
                try:
                    if asset_registry_reference_summary(asset_id)["total"]:
                        retained_asset_ids.append(asset_id)
                    else:
                        _asset_registry_trash_media(asset_id, reason="history_delete")
                        trashed_asset_ids.append(asset_id)
                except Exception as exc:
                    # The history entry is already gone.  Keep the source file
                    # if its registry transition fails so deletion remains
                    # recoverable instead of becoming an accidental purge.
                    print(f"历史素材回收处理失败 ({asset_id}): {exc}")
                    retained_asset_ids.append(asset_id)
            return {
                "success": True,
                "trashed_asset_ids": trashed_asset_ids,
                "retained_asset_ids": retained_asset_ids,
                "message": "历史记录已删除；仍被引用的素材已保留" if retained_asset_ids else "历史记录及未引用素材已移入回收站",
            }
        else:
            return {"success": False, "message": "未找到对应的历史记录"}
    except Exception as e:
        print(f"Delete history error: {e}")
        return {"success": False, "message": str(e)}


def _delete_history_batch_sync(raw_timestamps):
    """Delete selected history rows with one history-file rewrite.

    The manager can select thousands of rows.  Sending one request per row
    would make every request parse and rewrite the same multi-megabyte JSON
    file, so batch the file mutation while preserving the existing asset
    reference/recycle-bin checks for each removed row.
    """
    raw_timestamps = list(raw_timestamps or [])
    if not raw_timestamps:
        return {"success": False, "message": "未选择历史记录"}
    if len(raw_timestamps) > 5000:
        raise HTTPException(status_code=400, detail="一次最多删除 5000 条历史记录")
    targets = {float(value) for value in raw_timestamps}
    if not os.path.exists(HISTORY_FILE):
        return {"success": False, "message": "历史记录文件不存在"}
    try:
        target_records = []
        with HISTORY_LOCK:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                history = json.load(f)
            new_history = []
            for item in history if isinstance(history, list) else []:
                item_ts = item.get("timestamp", 0) if isinstance(item, dict) else 0
                matched = False
                try:
                    matched = any(abs(float(item_ts) - timestamp) < 0.001 for timestamp in targets)
                except (TypeError, ValueError):
                    matched = False
                if matched:
                    target_records.append(item)
                else:
                    new_history.append(item)
            if not target_records:
                return {"success": False, "message": "未找到对应的历史记录"}
            for target_record in target_records:
                asset_registry_register_history_record(target_record)
            _write_history_file_locked(new_history)

        trashed_asset_ids = []
        retained_asset_ids = []
        seen_asset_ids = set()
        for target_record in target_records:
            refs = target_record.get("asset_refs") if isinstance(target_record, dict) else []
            for ref in refs if isinstance(refs, list) else []:
                if not isinstance(ref, dict):
                    continue
                asset_id = str(ref.get("asset_id") or "")
                if not registry_is_asset_id(asset_id) or asset_id in seen_asset_ids:
                    continue
                seen_asset_ids.add(asset_id)
                try:
                    if asset_registry_reference_summary(asset_id)["total"]:
                        retained_asset_ids.append(asset_id)
                    else:
                        _asset_registry_trash_media(asset_id, reason="history_delete")
                        trashed_asset_ids.append(asset_id)
                except Exception as exc:
                    print(f"历史素材回收处理失败 ({asset_id}): {exc}")
                    retained_asset_ids.append(asset_id)
        return {
            "success": True,
            "deleted": len(target_records),
            "trashed_asset_ids": trashed_asset_ids,
            "retained_asset_ids": retained_asset_ids,
            "message": f"已删除 {len(target_records)} 条历史记录",
        }
    except HTTPException:
        raise
    except Exception as e:
        print(f"Batch delete history error: {e}")
        return {"success": False, "message": str(e)}


@app.post("/api/history/delete-batch")
async def delete_history_batch(req: DeleteHistoryBatchRequest):
    # File and asset-registry operations are synchronous. Keep large batches
    # off the event loop so the rest of the local app can still load and respond.
    return await asyncio.to_thread(_delete_history_batch_sync, req.timestamps)


def _storage_cleanup_note_url(url: Any, referenced: set) -> None:
    path = output_file_from_url(url)
    if not path:
        return
    try:
        referenced.add(os.path.normcase(os.path.realpath(path)))
    except OSError:
        referenced.add(os.path.normcase(os.path.abspath(path)))


# 引用核对必须走完全部列表与嵌套层：这里任何“跳过”都会让仍然在用的图片
# 变成“未引用”并被删除。历史记录加上画布目前约 52 万个节点、最深 9 层，
# 所以预算只用来挡住病态数据；一旦超限就整条清理失败，绝不静默少算。
STORAGE_CLEANUP_WALK_BUDGET = 2_000_000
STORAGE_CLEANUP_MAX_DEPTH = 64


def _storage_cleanup_walk_urls(value: Any, referenced: set, depth: int = 0, budget: Optional[list] = None) -> None:
    """Collect local media file paths referenced anywhere inside app data."""
    if budget is None:
        budget = [STORAGE_CLEANUP_WALK_BUDGET]
    budget[0] -= 1
    if budget[0] <= 0:
        raise HTTPException(
            status_code=409,
            detail="运行数据体量超出引用核对预算，已停止清理。请先减少历史记录或手动整理素材后重试。",
        )
    if depth > STORAGE_CLEANUP_MAX_DEPTH:
        raise HTTPException(
            status_code=409,
            detail="运行数据嵌套层级异常，已停止清理，以免把仍在使用的图片当成未引用删除。",
        )
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).strip().lower() in {"base64", "image_base64", "mask_base64", "image_data", "databytes"}:
                continue
            _storage_cleanup_walk_urls(child, referenced, depth + 1, budget)
    elif isinstance(value, list):
        for child in value:
            _storage_cleanup_walk_urls(child, referenced, depth + 1, budget)
    elif isinstance(value, str):
        url = _asset_registry_trackable_url(value)
        if url and not url.startswith(("http://", "https://")):
            _storage_cleanup_note_url(url, referenced)


def _storage_cleanup_referenced_paths():
    """文件路径集合：仍被历史、画布、素材收藏或工作台数据引用的本地媒体。

    用本地路径（realpath）而不是 URL 字符串比对，避免编码差异造成漏配。
    画布回收站里的画布也算引用：恢复画布时文件必须还在。

    返回 (引用路径集合, 软问题列表)。画布或历史文件读不出来时直接拒绝清理：
    读不到就等于引用核对不完整，此时把文件当“未引用”清掉，会让还引用着它的
    画布或历史失效。data 顶层 json 这类辅助数据读不出来只上报不阻断，避免
    一个次要文件让整条清理链路不可用。
    """
    referenced = set()
    scan_cache: Dict[str, Any] = {}
    # 整条扫描共用一个预算，保证总工作量有界；超限直接抛错中止清理。
    budget = [STORAGE_CLEANUP_WALK_BUDGET]

    # 历史：输出媒体 + params 输入图 + workflow 内部引用。
    history_records, _history_problems = _asset_scan_history_records(scan_cache)
    for record in history_records:
        _storage_cleanup_walk_urls(record, referenced, 0, budget)
        workflow = record.get("workflow_json")
        if isinstance(workflow, str) and workflow.lstrip().startswith("{"):
            try:
                _storage_cleanup_walk_urls(json.loads(workflow), referenced, 0, budget)
            except json.JSONDecodeError:
                pass

    # 画布（含回收站中的画布，恢复时需要文件仍在）。
    canvas_entries, _canvas_problems = _asset_scan_canvas_entries(scan_cache)
    for _filename, canvas in canvas_entries:
        if isinstance(canvas, dict):
            _storage_cleanup_walk_urls(canvas, referenced, 0, budget)

    # 画布或历史读不出来就停止：引用集合不完整，不能据此清理。
    _asset_scan_require_readable(_asset_scan_problems(scan_cache))

    # 其他工作台/收藏数据：data 顶层 json、设计大脑、对话、电商分析。
    soft_problems = []
    scan_files = []
    try:
        for filename in os.listdir(DATA_DIR):
            if filename.endswith(".json") and filename != "asset_registry.json":
                scan_files.append(os.path.join(DATA_DIR, filename))
        design_brain_dir = os.path.join(DATA_DIR, "design_brain")
        if os.path.isdir(design_brain_dir):
            for filename in os.listdir(design_brain_dir):
                if filename.endswith(".json"):
                    scan_files.append(os.path.join(design_brain_dir, filename))
        for sub in ("conversations", "commerce_analysis"):
            directory = os.path.join(DATA_DIR, sub)
            if os.path.isdir(directory):
                for filename in os.listdir(directory):
                    if filename.endswith(".json"):
                        scan_files.append(os.path.join(directory, filename))
    except OSError:
        pass
    for path in scan_files:
        try:
            with open(path, "r", encoding="utf-8-sig") as handle:
                _storage_cleanup_walk_urls(json.load(handle), referenced, 0, budget)
        except (OSError, json.JSONDecodeError, UnicodeDecodeError):
            # 辅助数据读不出来只上报：它可能引用了媒体，但不该让整条清理链路停摆。
            soft_problems.append({
                "file": os.path.basename(path),
                "error": "文件无法读取或解析，其中引用的媒体可能未被计入",
            })
    return referenced, soft_problems


def _storage_cleanup_unreferenced_sync() -> Dict[str, Any]:
    referenced, soft_problems = _storage_cleanup_referenced_paths()
    cleaned_ids = []
    errors = list(soft_problems)
    freed_bytes = 0
    for kind in ("upload", "generated", "local"):
        try:
            roots = storage_kind_roots(kind)
        except Exception:
            continue
        for root in roots:
            if not os.path.isdir(root):
                continue
            for current, dirs, files in os.walk(root):
                dirs[:] = [name for name in dirs if not name.startswith((".", "_"))]
                for filename in files:
                    if os.path.splitext(filename)[1].lower() not in STORAGE_MEDIA_EXTS:
                        continue
                    path = os.path.join(current, filename)
                    try:
                        path_key = os.path.normcase(os.path.realpath(path))
                    except OSError:
                        continue
                    if path_key in referenced:
                        continue
                    try:
                        size = os.path.getsize(path)
                        url = _asset_registry_storage_url(kind, root, path)
                        record = ASSET_REGISTRY.find_by_url(url) or asset_registry_register_media(
                            url,
                            name=filename,
                            source="history",
                            created_at=os.path.getmtime(path),
                        )
                        asset_id = str((record or {}).get("id") or "")
                        if not registry_is_asset_id(asset_id):
                            errors.append({"file": filename, "error": "素材登记失败"})
                            continue
                        _asset_registry_trash_media(asset_id, reason="storage_cleanup")
                        cleaned_ids.append(asset_id)
                        freed_bytes += int(size)
                    except Exception as exc:
                        message = exc.detail if isinstance(exc, HTTPException) else str(exc)
                        errors.append({"file": filename, "error": str(message)})
    return {
        "success": True,
        "cleaned": len(cleaned_ids),
        "freed_bytes": int(freed_bytes),
        "trash_asset_ids": cleaned_ids[:500],
        "errors": errors[:50],
    }


@app.post("/api/storage/cleanup-unreferenced")
async def storage_cleanup_unreferenced():
    """把图片空间中不再被任何数据引用的文件移入应用回收站（可恢复）。"""
    return await asyncio.to_thread(_storage_cleanup_unreferenced_sync)








# --- 本地 ComfyUI 生图 ---

@app.post("/api/generate")
def generate(req: GenerateRequest):
    return _generate_comfy(req)


def _generate_comfy(req: GenerateRequest, progress_callback=None, cancel_event=None):
    from ComfyUI.integration import comfy_execution, comfy_outputs

    def check_cancel():
        if cancel_event is not None and cancel_event.is_set():
            raise RuntimeError("本地生图已取消")

    global NEXT_TASK_ID
    current_task = None
    target_backend = None
    progress_stop = None
    progress_thread = None
    with QUEUE_LOCK:
        task_id = NEXT_TASK_ID
        NEXT_TASK_ID += 1
        current_task = {"task_id": task_id, "client_id": req.client_id}
        QUEUE.append(current_task)

    try:
        check_cancel()
        workflow_name = workflow_invocations.name(req.workflow_json)
        workflow_path = workflow_path_from_name(workflow_name)
        snapshot = req.workflow_snapshot if req.local_only else None
        if snapshot is None and not os.path.isfile(workflow_path):
            if workflow_name != "Z-Image.json" or not os.path.isfile(WORKFLOW_PATH):
                raise FileNotFoundError(f"Workflow file not found: {req.workflow_json}")
            workflow_path = WORKFLOW_PATH
        required_images = collect_required_comfy_media(req.params)

        addresses = tuple(COMFYUI_INSTANCES)
        requested_backend = str(req.preferred_backend or "").strip()
        managed_runtime = getattr(globals().get("COMFY_APPS"), "runtime", None)
        managed_backend = managed_runtime is not None and requested_backend == managed_runtime.address
        if req.local_only and ((requested_backend not in addresses and not managed_backend) or not re.fullmatch(r"(?:127\.0\.0\.1|localhost):\d+", requested_backend)):
            raise ValueError("本地应用只能提交到已配置的本机 ComfyUI，不会转交云端")
        if requested_backend in addresses or (req.local_only and managed_backend):
            target_backend = requested_backend
            with LOAD_LOCK:
                BACKEND_LOCAL_LOAD[target_backend] = BACKEND_LOCAL_LOAD.get(target_backend, 0) + 1
        else:
            target_backend = reserve_best_backend(required_images)

        comfy_execution.sync_inputs(
            target_backend, () if req.local_only else tuple(COMFYUI_INSTANCES), required_images,
            check_cancel=check_cancel,
        )

        seed = random.randint(1, 4294967295)
        workflow = comfy_execution.prepare_workflow(
            workflow_path, snapshot=snapshot, preserve=req.preserve_workflow,
            prompt=req.prompt, width=req.width, height=req.height, seed=seed,
        )
        app_item = _canvas_comfy_app_for_workflow(workflow_name, req.app_id)
        if app_item:
            apply_dlss5_preset(workflow, app_item, req.params)
        comfy_execution.apply_workflow_inputs(workflow, req.params)

        comfy_client_id = CLIENT_ID
        if req.local_only and req.client_id:
            comfy_client_id = req.client_id
        elif callable(progress_callback):
            comfy_client_id = f"xiaomei_canvas_{uuid.uuid4().hex}"

        runtime_matches = managed_runtime is not None and target_backend == managed_runtime.address
        process = managed_runtime.process if runtime_matches else None
        if process is not None and process.poll() is not None:
            process = None
        check_cancel()
        prompt_id = comfy_execution.submit_workflow(target_backend, workflow, comfy_client_id)

        def report_wait(message=None):
            if callable(progress_callback):
                update = {
                    "status": "running", "prompt_id": prompt_id,
                    "comfy_backend": target_backend, "progress_source": "comfyui",
                }
                if message:
                    update["message"] = message
                progress_callback(update)

        if callable(progress_callback):
            report_wait("ComfyUI 已接收，等待节点实时进度")
            progress_stop = threading.Event()
            progress_thread = threading.Thread(
                target=_watch_comfy_progress,
                args=(target_backend, comfy_client_id, prompt_id, workflow, progress_callback, progress_stop),
                name=f"comfy-progress-{prompt_id[:8]}",
                daemon=True,
            )
            progress_thread.start()

        workflow_timeout = max(30, min(COMFYUI_HISTORY_TIMEOUT, req.timeout_seconds or COMFYUI_HISTORY_TIMEOUT))
        history_data = comfy_execution.wait_for_result(
            target_backend, prompt_id, workflow_timeout, managed=runtime_matches, process=process,
            on_wait=report_wait, check_cancel=check_cancel,
            pause=time.sleep if cancel_event is None else cancel_event.wait,
        )
        check_cancel()

        current_timestamp = time.time()
        prefix = f"{req.type}_{int(current_timestamp)}_"
        outputs = comfy_outputs.collect_result(
            history_data, workflow,
            download=lambda item: download_comfy_output(target_backend, item, prefix=prefix),
            save_text=lambda value, name: save_comfy_text_output(value, prefix=prefix, name=name),
            check_cancel=check_cancel,
        )

        history_params = dict(req.params) if isinstance(req.params, dict) else {}
        project_id = str(req.project_id or "").strip()
        if project_id:
            history_params["project_id"] = project_id
        result = {
            "prompt": req.prompt if req.prompt else "Detail Enhance",
            **outputs,
            "seed": seed,
            "timestamp": current_timestamp,
            "type": req.type,
            "history_source": normalize_history_source(req.history_source, "canvas"),
            "project_id": project_id,
            "workflow_json": req.workflow_json,
            "task_id": task_id,
            "prompt_id": prompt_id,
            "backend": target_backend,
            "params": history_params
        }
        check_cancel()
        if req.record_history:
            save_to_history(result)
            if GLOBAL_LOOP:
                asyncio.run_coroutine_threadsafe(workspace_events.broadcast_new_image(result), GLOBAL_LOOP)
        return result

    except Exception as e:
        return {"images": [], "error": str(e)}
    finally:
        if progress_stop is not None:
            progress_stop.set()
        if progress_thread is not None and progress_thread.is_alive():
            progress_thread.join(timeout=1.2)
        if target_backend:
            with LOAD_LOCK:
                if BACKEND_LOCAL_LOAD.get(target_backend, 0) > 0:
                    BACKEND_LOCAL_LOAD[target_backend] -= 1
                    if not BACKEND_LOCAL_LOAD[target_backend] and target_backend not in COMFYUI_INSTANCES:
                        del BACKEND_LOCAL_LOAD[target_backend]
        if current_task:
            with QUEUE_LOCK:
                if current_task in QUEUE:
                    QUEUE.remove(current_task)

# --- ComfyUI 工作流管理 ---

BUILTIN_WORKFLOWS = {"Z-Image.json", "Z-Image-Enhance.json", "2511.json", "klein-enhance.json", "Flux2-Klein.json", "upscale.json", "seedvr2-official-upscale.json", "swinir-upscale.json"}
_BUILTIN_WORKFLOW_KEYS = {os.path.normcase(name) for name in BUILTIN_WORKFLOWS}
CUSTOM_WORKFLOW_FOLDER = "custom"
LEGACY_CUSTOM_WORKFLOW_FOLDER = "自定义"

class WorkflowField(BaseModel):
    id: str
    node: str = ""
    input: str = ""
    name: str = ""
    type: str = "text"
    default: Any = None
    min: Optional[float] = None
    max: Optional[float] = None
    step: Optional[float] = None
    options: List[str] = []
    random_enabled: bool = False
    advanced: bool = False

class WorkflowConfig(BaseModel):
    title: str = ""
    fields: List[WorkflowField] = []
    mini_cards: Dict[str, Any] = {}

class WorkflowUploadRequest(BaseModel):
    name: str
    workflow: Dict[str, Any]
    folder: str = ""

class WorkflowRunRequest(BaseModel):
    fields: Dict[str, Any] = {}
    config: WorkflowConfig
    client_id: str = ""

def workflow_path_from_name(name: str) -> str:
    path = workflow_invocations.file_path(WORKFLOW_DIR, name)
    if path is None:
        raise HTTPException(400, "Invalid workflow name")
    return path


def is_valid_workflow_name(name: str) -> bool:
    return bool(workflow_invocations.name(name))


is_valid_workflow_folder = workflow_invocations.valid_folder


def workflow_config_path(name: str) -> str:
    graph_path = workflow_path_from_name(name)
    relative = os.path.relpath(graph_path, WORKFLOW_DIR)
    path = media_paths.path_under(WORKFLOW_DIR, relative[:-5] + ".config.json")
    if path is None:
        raise HTTPException(400, "Invalid workflow name")
    return path


def is_builtin_workflow(name: str) -> bool:
    return os.path.normcase(workflow_invocations.name(name)) in _BUILTIN_WORKFLOW_KEYS

def is_app_mirror_workflow(name: str) -> bool:
    """是否是应用镜像工作流（custom/app_<id>.json）。

    这类文件由 comfy_apps/<id>/app.json 派生而来，工作台已经把它们作为
    应用展示；如果再当作普通工作流列出来，同一个图会出现两次。
    """
    from ComfyUI.integration.comfy_apps import is_app_mirror_workflow as check
    return check(name)

def runninghub_workflow_store_key(workflow_id: str) -> str:
    return normalize_runninghub_reference_id(workflow_id, "workflow")


def require_runninghub_workflow_id(value):
    key = runninghub_workflow_store_key(value)
    if not key:
        raise HTTPException(status_code=400, detail="workflowId 必填")
    return key


def runninghub_workflow_catalog(provider=None, *, strict=False):
    if provider is None:
        provider = next((item for item in load_api_providers() if item["id"] == "runninghub"), {})
    return runninghub_workflows.WorkflowCatalog(
        RUNNINGHUB_WORKFLOW_STORE_FILE, runninghub_workflow_store_key, _atomic_write_json_file,
        provider.get("rh_workflows") or [], strict=strict,
    )


def runninghub_provider_with_workflow_store(provider):
    cards = runninghub_workflow_catalog(provider).cards()
    return {**provider, "rh_workflows": normalize_runninghub_entries(cards, "workflow")}


class ComfyInstancesPayload(BaseModel):
    instances: List[str] = []

COMFY_INSTANCE_SAVE_LOCK = Lock()


def normalize_comfy_instances(values):
    addresses = {}
    for value in values:
        address = re.sub(r"^https?://", "", value.strip(), flags=re.I).rstrip("/")
        if not address:
            continue
        host, colon, port = address.rpartition(":")
        if not colon:
            raise HTTPException(status_code=400, detail=f"地址缺少端口号：{value}（例如 127.0.0.1:8188）")
        bracketed = host.startswith("[") and host.endswith("]")
        valid_host = bool(host) and not re.search(r"[\s/@?#,]", host) and (bracketed or ":" not in host)
        if not valid_host or not re.fullmatch(r"[0-9]{1,5}", port) or not 1 <= int(port) <= 65535:
            raise HTTPException(status_code=400, detail=f"地址不合法：{value}（例如 127.0.0.1:8188）")
        addresses[address] = None
    if not addresses:
        raise HTTPException(status_code=400, detail="至少保留一个 ComfyUI 后端地址")
    return list(addresses)


@app.get("/api/comfyui/instances")
def get_comfyui_instances():
    with LOAD_LOCK:
        return {"instances": list(COMFYUI_INSTANCES)}


@app.put("/api/comfyui/instances")
def save_comfyui_instances(payload: ComfyInstancesPayload):
    global COMFYUI_INSTANCES, COMFYUI_ADDRESS
    addresses = normalize_comfy_instances(payload.instances)
    with COMFY_INSTANCE_SAVE_LOCK:
        try:
            update_env_values({"COMFYUI_INSTANCES": ",".join(addresses)})
        except OSError as error:
            raise HTTPException(status_code=500, detail=f"写入 env 失败：{error}") from error
        with LOAD_LOCK:
            for address in list(BACKEND_LOCAL_LOAD):
                if address not in addresses and BACKEND_LOCAL_LOAD[address] <= 0:
                    del BACKEND_LOCAL_LOAD[address]
            for address in addresses:
                BACKEND_LOCAL_LOAD.setdefault(address, 0)
            COMFYUI_INSTANCES = addresses
            COMFYUI_ADDRESS = addresses[0]
    return {"instances": addresses}


@app.get("/api/workflows")
def list_workflows():
    if not os.path.isdir(WORKFLOW_DIR):
        return {"workflows": []}
    items = []
    for root, dirs, files in os.walk(WORKFLOW_DIR):
        # 工作流目录可以按项目自由分层。只跳过隐藏/缓存目录，不能再把
        # 根目录限制为 custom/自定义，否则其它项目的工作流永远不会出现在
        # 设置页和画布节点的切换列表里。
        dirs[:] = [
            d for d in dirs
            if d not in {".", "..", "__pycache__"} and not d.startswith(".")
        ]
        for fn in sorted(files):
            if not fn.endswith(".json") or fn.endswith(".config.json"):
                continue
            rel = os.path.relpath(os.path.join(root, fn), WORKFLOW_DIR).replace("\\", "/")
            if not is_valid_workflow_name(rel):
                continue
            if is_builtin_workflow(rel):
                continue
            # 应用镜像（custom/app_<id>.json）由工作台应用派生，不单独成条。
            if is_app_mirror_workflow(rel):
                continue
            cfg = {}
            cfg_path = workflow_config_path(rel)
            if os.path.exists(cfg_path):
                try:
                    with open(cfg_path, "r", encoding="utf-8") as f:
                        cfg = json.load(f) or {}
                except Exception:
                    cfg = {}
            folder = os.path.dirname(rel).replace("\\", "/")
            items.append({
                "name": rel,
                "title": cfg.get("title") or fn.replace(".json", ""),
                "builtin": False,
                "field_count": len(cfg.get("fields") or []),
                "folder": folder,
                "project": folder or "根目录",
            })
    items.sort(key=lambda item: (
        0 if item.get("folder") in {CUSTOM_WORKFLOW_FOLDER, LEGACY_CUSTOM_WORKFLOW_FOLDER} else 1,
        str(item.get("folder") or "").casefold(),
        str(item.get("title") or item.get("name") or "").casefold(),
    ))
    return {"workflows": items}

@app.get("/api/workflows/{name:path}")
def get_workflow(name: str):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    workflow_path = workflow_path_from_name(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    with open(workflow_path, "r", encoding="utf-8") as f:
        workflow = json.load(f)
    cfg = {"title": name.replace(".json", ""), "fields": []}
    cfg_path = workflow_config_path(name)
    if os.path.exists(cfg_path):
        try:
            with open(cfg_path, "r", encoding="utf-8") as f:
                cfg = json.load(f) or cfg
        except Exception:
            pass
    app_item = _canvas_comfy_app_for_workflow(name)
    preset = dlss5_preset_field(app_item) if app_item else None
    if preset:
        app_library = globals().get("COMFY_APPS")
        info = app_library._catalog_info() if app_library else {}
        preset = dlss5_preset_field(app_item, info) or preset
    if preset:
        fields = cfg.setdefault("fields", [])
        existing = next((field for field in fields if field.get("id") == preset["id"]), None)
        if existing:
            existing.update({key: value for key, value in preset.items() if key != "name"})
        else:
            fields.append(preset)
    return {"name": name, "workflow": workflow, "config": cfg, "builtin": is_builtin_workflow(name)}

@app.post("/api/workflows")
def upload_workflow(payload: WorkflowUploadRequest):
    name = os.path.basename(payload.name.strip())
    if not name.endswith(".json"):
        name = name + ".json"
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="工作流名称不合法，请使用中文/英文/数字/_-.")
    folder = str(payload.folder or "").strip().replace("\\", "/").strip("/")
    if not is_valid_workflow_folder(folder):
        raise HTTPException(status_code=400, detail="工作流项目目录不合法")
    if not isinstance(payload.workflow, dict) or not payload.workflow:
        raise HTTPException(status_code=400, detail="工作流 JSON 为空")
    # 简单校验：是 API 格式（节点 id 为 key，含 class_type）
    sample = next(iter(payload.workflow.values()), None)
    if not isinstance(sample, dict) or "class_type" not in sample:
        raise HTTPException(status_code=400, detail="不是有效的 ComfyUI API 工作流 JSON（需包含 class_type）")
    folder = folder or CUSTOM_WORKFLOW_FOLDER
    stored_name = f"{folder}/{name}" if folder else name
    path = workflow_path_from_name(stored_name)
    _atomic_write_json_file(path, payload.workflow)
    return {"name": stored_name}

@app.put("/api/workflows/{name:path}/config")
def save_workflow_config(name: str, payload: WorkflowConfig):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    workflow_path = workflow_path_from_name(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    config = payload.model_dump()
    _atomic_write_json_file(workflow_config_path(name), config)
    return {"config": config}

@app.delete("/api/workflows/{name:path}")
def delete_workflow(name: str):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    if is_builtin_workflow(name):
        raise HTTPException(status_code=400, detail="内置工作流不可删除")
    workflow_path = workflow_path_from_name(name)
    cfg_path = workflow_config_path(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    os.remove(workflow_path)
    if os.path.exists(cfg_path):
        os.remove(cfg_path)
    removed_apps = []
    app_library = globals().get('COMFY_APPS')
    if app_library and hasattr(app_library, 'sync_deleted_workflow'):
        removed_apps = app_library.sync_deleted_workflow(name)
    return {"ok": True, "removed_apps": removed_apps}

@app.post("/api/workflows/{name:path}/run")
def run_workflow(name: str, payload: WorkflowRunRequest):
    reference = workflow_invocations.name(name)
    if not os.path.isfile(workflow_path_from_name(reference)):
        raise HTTPException(404, "Workflow not found")
    request = GenerateRequest(
        workflow_json=reference, type="workflow-test",
        params=workflow_invocations.node_inputs(payload.config.fields, payload.fields),
        client_id=payload.client_id or str(uuid.uuid4()),
    )
    return generate(request)


