if __name__ == "__main__":
    import uvicorn
    # 关闭服务端协议级 WebSocket ping：部分客户端（如 PS UXP 面板）不会自动回 pong，
    # 默认 20s ping/20s 超时会把这些连接每隔一会儿就踢掉造成"频繁断连"。
    # 客户端有自己的应用层心跳 + 断线重连兜底，这里禁用协议 ping 更稳。
    preferred_port = int(os.getenv("XIAOMEI_CANVAS_PORT", "3000"))
    # Windows may reserve a port range for Hyper-V/WSL or another local
    # service. Probe the preferred port first, then select the next available
    # port so the desktop launcher can still start without manual repair.
    port = None
    for candidate in range(preferred_port, min(preferred_port + 201, 65536)):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
                probe.bind(("127.0.0.1", candidate))
            port = candidate
            break
        except OSError:
            continue
    if port is None:
        raise RuntimeError(
            f"No available local port in range {preferred_port}-{preferred_port + 200}"
        )
    if port != preferred_port:
        print(f"Preferred port {preferred_port} is unavailable; using {port}.")

    uvicorn.run(app, host="127.0.0.1", port=port,
                ws_ping_interval=None, ws_ping_timeout=None)
